COPY public.groupinformation_homeinfo (id, title, description, video) FROM stdin;
1	\N	Smart Data Analysis Systems Group (SDAS Group) was founded by Prof. Diego Peluffo in 2018. It is supported by expert and young researchers from several academic institutions from Ecuador, Colombia, Brasil, Argentina, and Spain. SDAS research group deals with data-anaylsis-related problems by providing software- and embedded-systems-driven solutions. The scope of its applications of interest encompasses: Time-varying, complex data analysis, formal methods for machine learning, sensor network, low-computational cost approaches for data analysis, and data visualization, among others. Also, SDAS Group offers services on scientific and technical counseling on data analysis, sensor networks and embedded systems design, programming, software development, and applied mathematics.	media/V3_Sdas_Group_Video.mp4
\.


