--
-- Data for Name: groupinformation_projectinfo; Type: TABLE DATA; Schema: public; Owner: roadhouse_user
--

COPY public.groupinformation_projectinfo (id, project, description, image, url_project, type_project) FROM stdin;
5	Methodology of information visual analysis in Big Data	This project aims to to design a methodology of visual analysis of information in Big Data using principles of visualization and interactivity in conjunction with techniques of dimensionality reduction. The premise of this research is the possibility of performing the interaction with the user to select and combine methods of reduction of dimension. Then, this project involves not only the design of an interaction model and interface, but also the formulation of a generalized method of dimensionility reduction that allows for an intuitive selection and combination of methods. A transversal aspect of all the stages of the design of the visual analysis methodology is the computational cost that hinders the goal of the methodology being really interactive, that is, in real time. That said, in this project, it is mandatory to carry out all the designs and test implementations in low-computational-cost environments.		https://sites.google.com/view/metodologiabigdata/inicio	400
6	Dimensionality reduction and data visualization	The objective of this emergent research area is to link the field of dimensionality reduction (DR) with that of information visualization (IV), in order to harness the special properties of the latter within DR frameworks. In particular, the properties of controllability and interactivity are of interest, which should make the DR outcomes significantly more understandable and tractable for the (no-necessarily-expert) user. These two properties allow the user to have freedom to select the best way for representing data.		https://sites.uclouvain.be/DRedVis/	400
7	Low-cost prototype for biofeedback applications	This work project is about the design of a low-cost biofeedback devices. Device desing involves mainly two building blocks: The first one is concerned on the signal acquisition and analog filtering. Meanwhile, the second one is the estimation of physiological variable indicators and visual feedback implemented in a circuit platform. The goal is reaching great usability and portability while involving low design costs.		https://sites.google.com/site/alejocastroworks/dispositivo-biofeedback	410
8	Modular design methodology for production plants	The aim of this research is to propose a modular design methodology for planning and assembly of industrial installations and production systems by using computer simulation as a decision making tool. Particularly, methodology is to be tested over a special coffee production plant, located in Nariño-Colombia. Design and simulation results validate the suitability of the proposed methodology.		https://sites.google.com/site/factorydesigncad3d/Planta-Torrefactora-de-Cafe	410
\.


