COPY public.members_publication (id, title, event_of_publication, author, abstract, year, member_id, url_publication) FROM stdin;
26	Herramientas de Análisis de Grandes volúmenes de datos para la toma de decisiones empresariales y fidelización de los clientes	Revista de Estrategias del Desarrollo Empresarial ISSN: 2444-4960	Ana Umaquinga, Tatiana Saltos, Diego Peluffo	El crecimiento acelerado de la competencia entre las empresas a nivel global es innegable. Los nuevos retos para generar valor, descubrir tendencias y preferencias de consumo de clientes exigen a las empresas contar con herramientas tecnológicas de mayor alcance y eficiencia que permitan ser apoyo en la toma de decisiones en tiempo real o en el menor tiempo posible con el fin de crear ventaja competitiva y mantenerse en el mercado. Herramientas tecnológicas como Big data, Data mining entre otras, pretenden obtener nuevo conocimiento, patrones, predicciones para una mejor comprensión y precisión de las necesidades del cliente, que no sería posible con el uso de herramientas convencionales. De ahí el trabajo en equipo del área tecnológica y del negocio requiere de este conocimiento de valor para la definición de estrategias encaminadas a capitalizar dicho conocimiento originado de manera interna y externa especialmente de las redes sociales. El presente artículo es de tipo descriptivo, exploratorio, y documental, se realiza un análisis de Big data y minería de datos a nivel empresarial, sus tópicos de uso en la toma de decisiones y búsqueda de la fidelización de sus clientes, así como sus aspectos de valor y retos. En consecuencia, los resultados evidencian la relación favorable y eficiente de la aplicación de estas tecnologías en la toma de decisiones empresariales, por lo que, surge la necesidad de un mayor número de investigaciones de este tipo. Abstract The accelerated growth of competition among companies globally is undeniable. The new challenges to generate value, discover trends and preferences of customers demand companies to have technological tools of greater reach and efficiency that allow to be support in the decision making in real time or in the shortest possible time in order to create competitive advantage and stay in the market. Technological tools like Data mining, Big data, among others, aim to obtain new knowledge, patterns, predictions for a better understanding and precision of costumer needs, which would not be possible with the use of conventional tools. Hence teamwork in the area of technology and business requires this knowledge of value for the definition of strategies aimed at capitalizing on this knowledge originated in an internal and external way especially of social networks. The present article is descriptive, exploratory, and documentary, perform an analysis of the technological tools used at the business level and topics of use in the decision making and search of the loyalty of its clients, as well as its value aspects and challenges. Consequently, the results show the favorable and efficient relationship of the application of these technologies in business decisionmaking, therefore, the need arises for a greater number of future research of this type.	2017	2	https://www.researchgate.net/publication/322302894_Herramientas_de_analisis_de_grandes_volumenes_de_datos_para_la_toma_de_decisiones_empresariales_y_fidelizacion_de_los_clientes
28	Automatic Motion Segmentation via a Cumulative Kernel Representation and Spectral Clustering	International Conference on Intelligent Data Engineering and Automated Learning	OR Oña-Rocha, OT Sánchez-Manosalvas, AC Umaquinga-Criollo, PD Rosero-Montalvo, LE Suárez-Zambrano, JL Rodríguez-Sotelo, DH Peluffo-Ordóñez	Dynamic or time-varying data analysis is of great interest in emerging and challenging research on automation and machine learning topics. In particular, motion segmentation is a key stage in the design of dynamic data analysis systems. Despite several studies have addressed this issue, there still does not exist a final solution highly compatible with subsequent clustering/classification tasks. In this work, we propose a motion segmentation compatible with kernel spectral clustering (KSC), here termed KSC-MS, which is based on multiple kernel learning and variable ranking approaches. Proposed KSC-MS is able to automatically segment movements within a dynamic framework while providing robustness to noisy environments.	2017	2	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_44
32	Data Visualization Using Interactive Dimensionality Reduction and Improved Color-Based Interaction Model	International Work-Conference on the Interplay Between Natural and Artificial Computation	PD Rosero-Montalvo, DF Peña-Unigarro, DH Peluffo, JA Castro-Silva, A Umaquinga, EA Rosero-Rosero	This work presents an improved interactive data visualization inteface based on a mixture of the outcomes of dimensionality reduction (DR) methods. Broadly, it works as follows: The user can input the mixture weighting factors through a visual and intuitive interface with a primary-light-colors-basemodel (Red, Green, and Blue). By design, such a mixture is a weighted sum othe color tone. Additionally, the low-dimensional representation space produceby DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculateand employed to deﬁne the graph to simultaneously be drawn over the scatteplot. Our interface enables the user to interactively combine DR methods by thhuman perception of color, while providing information about the structure ooriginal data. Then, it makes the selection of a DR scheme more intuitive -evefor non-expert users.	2017	2	\N
29	Impacto de la Usabilidad de los Drones en la Agregación del Valor en la Producción. Impact of Usability Drones in the Aggregation of Value in Production	III JORNADAS ACADÉMICAS INTERNACIONALES CISIC 2017	Diego Hernán Peluffo Ordoñez, Sandra Karina Narváez Pupiales, Ana Cristina Umaquinga Criollo	The Ecuadorian economy has been based mainly on the exploitation of raw materials and imports of goods and services, this ecosystem not encouraging development as a result in certain periods of time and according to the variability of the international market has caused to this day swings, as a result of changes in the prices of these resources compared to prices of products with higher added value and high technology. One of the main objectives of the Change of the Productive Matrix is to evolve this pattern of primary exporting specialization to a pattern of diversified production highlighting especially the capacities and knowledge of human talent involved in these processes. In order to frame the economic and social development of the population around this change, the incorporation of technology has become one of the main axes to improve and achieve the proposed objectives, being in this way a vital tool to improve production. Of the many technological possibilities that exist, this research highlights, analyzes and evaluates the incorporation of unmanned Aerial Systems or Vehicles commonly known as DRONES to the agricultural sector with special emphasis on the advantages, disadvantages, risks, acceptance levels, components of hardware and software, statistics related to production cost savings and how the current Regulation by the Civil Aviation Directorate in Ecuador contributes to the development and usability of these systems. Finally, the conclusions point to the great possibilities of growth and transformation of agriculture to effective methods of precision where the aid of DRONES and automation can provide a large amount of information such as reports, images, videos, maps and others where human intervention becomes minimal. Resumen: La economía ecuatoriana se ha basado fundamentalmente en la explotación de materias primas e importación de bienes y servicios, este ecosistema poco alentador de desarrollo como resultado en ciertos periodos de tiempo y de acuerdo a la variabilidad del mercado internacional ha provocado hasta el día de hoy vaivenes, a consecuencia de las variaciones de los precios de estos recursos frente a precios de productos de mayor valor agregado y alta tecnología. Uno de los objetivos principales del Cambio de la Matriz Productiva es evolucionar este patrón de especialización primario exportador a un patrón de producción diversificado resaltando especialmente las capacidades y conocimientos del talento humano interviniente en estos procesos. Para enmarcar el desarrollo económico y social de la población alrededor de este cambio, la incorporación de la tecnología se ha convertido en uno de los principales ejes para mejorar y conseguir los objetivos propuestos, siendo de esta forma una herramienta vital para mejorar la producción. De las muchas posibilidades tecnológicas existentes, en esta investigación se resalta, analiza y evalúa la incorporación de los Sistemas o Vehículos Aéreos no tripulados conocidos comúnmente como DRONES al sector agrícola con especial énfasis en las ventajas, desventajas, riesgos, niveles de aceptación, componentes de hardware y software, estadísticas relacionadas a los ahorros de costos de producción y cómo la Regulación vigente por parte de la Dirección General de Aviación Civil en el Ecuador contribuye al desarrollo y usabilidad de estos sistemas. Finalmente las conclusiones exponen las grandes posibilidades de crecimiento y transformación de la agricultura a métodos efectivos de precisión en dónde la ayuda de los vehículos aéreos no tripulados (DRONES) y automatización pueden facilitar gran cantidad de información tales como informes, imágenes, videos, mapas y otros en donde la intervención humana llega a ser mínima.	2017	2	http://diegopeluffo.com/publicaciones/2017_UsabilidadDrones_CISCIC.pdf
34	Sistema Informático Basado en Estándares Darwin Core Para Presentar la Información de las Colecciones de Historia Natural: Distribución Geográfica de Especies y Jerarquización Sistémica de Especímenes	REDU Red Ecuatoriana de Universidades y Escuelas Politécnicas para Investigación y Postgrados	Hugo Navarrete Francisco Rodríguez, Luis Cárdenas, Juan Calle, Andrés Jiménez, Daniel Vargas, Ana Umaquinga-Criollo	In 2013 the Pontifical Catholic University of Ecuador (PUCE) as part of its multidisciplinary research work between the School of Biological Sciences and Systems Engineering project called was performed: Development of a computer system for disseminating information generated by research projects at the School of Biological Sciences at the Antisana Ecological Reserve (REA), in order to promote the dissemination of the results of such investigations. In this collaborative work it allowed the scope to propose a project: Expand the computer system developed and release some of the biodiversity information stored in the database of the Herbarium QCA. A computer system of base rate taxonomic scientific data was developed using the Darwin Core standards biodiversity additionally features modular design, users multi-level which use the management different modules or use them together, the development of a geographical display optimized for kml download files and georeferenced information presentation botanical applying Extreme programming Methodology (XP), Model View Controller (MVC), class diagram, use case testing and verification of results. The result is a computer system, a database of scientific type with information regarding species Pteridophytes deposited in the QCA herbarium with distribution in the REA and other areas of the country for analysis of diversity, conservation and management of plant resources It includes taxonomic information, collection sites and correct location geographical coordinates determines the spatial distribution of species through geographic displays online, photographic documentation of the species identified as types, paratypes, holotypes performing migration of 8,000 of these registry, additional permits information export, which seeks to contribute to knowledge researchers and the general public.	2016	2	\N
35	Estudio Descriptivo de Técnicas Aplicadas en Herramientas Open Source y Comerciales para Visualización de Información de Big Data.	Generando Ciencia: Memorias de las I Jornadas Internacionales de Investigación Científica UTN	Ana C. Umaquinga C. , Diego H. Peluffo O. ,Juan C. Alvarado P., Milton V. Cabrera A.	En el campo de visualización de la información (VI) en Big Data (también denominado DataVis, InfoVis, Analítica Visual, VA), se han realizado innumerables esfuerzos, a nivel empresarial, educación e investigación, entre otros, que han dado como resultado diversas propuestas de herramientas de software que usan interfaces y técnicas de VI. En la actualidad, existen decenas de herramientas que potencializan y se especializan en determinadas técnicas de visualización. Por tanto, para un usuario, la elección de una herramienta en particular no es una tarea trivial. En este trabajo, se presenta un estudio descriptivo de técnicas de visualización de información abarcando diferentes grupos o tipos de técnicas, tales como: Geometric Projection, Interactive, Icon-based, y Hierarchical, entre otros. Para este fin, se realiza una tabulación de información, presentando las herramientas de software y técnicas de visualización consideradas en este estudio, de forma que pueda realizarse la identificación de las técnicas más comúnmente utilizadas y recomendadas para uso en entornos de tipo Open Source y Soluciones Empresariales. Para ello, se parte de la revisión de análisis de literatura de VI, Analítica Visual y artículos científicos sobre herramientas de análisis de Big Data enfocados en establecer herramientas de software y técnicas de visualización. Dichos análisis y revisiones se realizan sobre un total de 58 técnicas de visualización y 31 herramientas de software. Como resultado, se obtiene una valoración de técnicas de visualización y se establece aspectos clave y recomendaciones para realizar la selección de técnicas de visualización de acuerdo con los requerimientos del usuario. Palabras clave: Data Vis, Herramientas de Visualización de Big Data, Técnicas de visualización, Software Comercial, Software Open Source. Abstract In the field of information visualization (IV) in Big Data (also called DataVis, InfoVis, Visual Analytics, VA), there have been countless efforts, in enterprise, education and research spheres, among others. Such efforts have led to different proposals for software tools using IV interfaces and techniques. Currently, there are dozens of tools that enhance and specialize in certain visualization techniques. Therefore, the choice of a particular tool is not a trivial task for users. In this work, we present a descriptive study on IV techniques encompassing several groups or types of techniques, such as: geometric projection, IV hierarchical, IV interactive, and icon-based IV, among others. To this end, a tabulation of information is performed, presenting software tools and visualization techniques considered in this study, so that the identification of the techniques most commonly used and recommended for use in environments such Open Source Solutions and business software can be readily performed. To do this, we start by a review of literature on IV, Visual Analytics, as well as scientific articles about Big Data analysis tools focused on establishing software tools and visualization techniques. Such a review is conducted on a total of 58 visualization techniques and 21 software tools. As a result, an assessment of visualization techniques is obtained and key issues and recommendations for the selection of visualization techniques according to user’s requirements are established. Key words: Big Data Visualization tools, Commercial Software, DataVis, Open Source Software Tools, Visualization Techniques.	2016	2	\N
33	Propuesta de Análisis Visual de Datos en Big Data Usando Reducción de Dimensión Interactiva	Tecnologías aplicadas a la Ingeniería FICA-UTN 2016	A. C. Umaquinga-Criollo,D. H. Peluffo-Ordóñez,P. D. Rosero-Montalvo,M. V. Cabrera-Álvarez,J. C. Alvarado-Pérez, A. J. Anaya-Isaza	Today, the volume of available data is experiencing an \r\nexponential growing, introducing an emergent are so-called Big Data. \r\nAlong with the data growing, the demand of tools, techniques and \r\ndevices to store, transmit and process high-dimensional data (HD) is \r\nincreased. Most available methodologies to process HD output abstract \r\noutcomes and user is not involved in the selection or parameter tuning \r\nprocesses of data analysis techniques. In this work, we propose a visual \r\nanalysis  methodology  following  principles  of  interactivity  and \r\ncontrollability. Doing so, users (even non-expert ones) can intuitively \r\nselect  a  dimensionality  reduction  method  to  generate  intelligible \r\nrepresentations for human beings.	2017	2	https://www.researchgate.net/publication/311457198_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva
36	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA	INCISCOS 2016 International Conference on Information Systems and Computer Science	Juan A. Castro-Silva Andrés J. Anaya-Isaza, Diego H. Peluffo-Ordoñez, Juan C. Alvarado-Pérez,Jorge Ivan-Rios, Paul D. Rosero-Montalvo, Diego F. Peña-Unigarro Jose A. Salazar-CastroJuan C. ,Ana C. Umaquinga-Criollo	Este trabajo presenta un estudio comparativo con métodos de reducción de la dimensión lineal, tales como: Análisis de Componentes Principales & Análisis Discriminante Lineal. El estudio pretende determinar, bajo criterios de objetividad, cuál de estas técnicas obtiene el mejor resultado de separabilidad entre clases. Para la validación experimental se utilizan dos bases de datos, del repositorio científico (UC Irvine Machine Learning Repository), para dar tratamiento a los atributos del data-set en función de confirmar visualmente la calidad de los resultados obtenidos. Las inmersiones obtenidas son analizadas, para realizar una comparación de resultados del embedimiento representados con RNX(K), que permite evaluar el área bajo la curva, del cual asume una mejor representación en una topología global o local que posteriormente genera los gráficos de visualización en un espacio de menor dimensión, para observar la separabilidad entre clases conservando la estructura global de los datos. Palabras clave— Análisis de componentes principales, Análisis discriminante lineal, Aprendizaje de máquina, Clasificación lineal, Clasificación supervisada, Métodos de reducción de la dimensión. Abstract— This paper presents a comparative study with methods of reducing the linear dimension, such as Principal Component Analysis & linear discriminant analysis. The study aims to determine, based on criteria of objectivity, which of these techniques get the best result of separability between classes. For experimental validation two databases, scientific repository (UC Irvine Machine Learning Repository) are used to provide treatment to the attributes of the data-set according to visually confirm the quality of the results. The dives obtained are analyzed, for comparison of results embedimiento represented with RNX (K), which evaluates the area under the curve, which assumes better representation in a local global topology or subsequently generates graphics display a space of smaller dimension, to observe the class separability preserving the overall structure of the data.	2016	2	\N
37	Propuesta de Análisis visual de Datos en Big Data Usando Reducción de Dimensión Interactiva	3ras Jornadas Internacionales FICA	A. J. Anaya-Isaza A. C. Umaquinga-Criollo, D. H. Peluffo-Ordóñez, M. V. Cabrera-Álvarez,J. C. Alvarado-Pérez	Today, the volumen of available data is experiencing \r\nan exponential  growing, introducing an emergent are so-called Big \r\nData. Along with the data growing, the demand of tools, techniques \r\nand devices to store, transmit and process high-dimensional data (HD) \r\nis  increased.  Most  available  methodologies  to  process  HD  output \r\nabstract outcomes and user is not involved in the selection or parameter \r\ntuning processes of data analysis techniques. In this work, we propose \r\na visual analysis methodology following principles of interactivity and \r\ncontrolability. Doing so, users (even non-expert ones) can inuitively \r\nselect  a  dimensionality  reduction  method  to  generate  inteligible \r\nrepresentations for human beings.	2016	2	\N
38	Theoretical Developments for Interpreting Kernel Spectral Clus-tering From Alternative Viewpoints	Advances in Science, Technology and Engineering Systems Journal	Diego Peluffo-Ordónez, Paul Rosero-Montalvo, Ana Umaquinga-Criollo, Luis Suárez-Zambrano, Hernan Domınguez-Limaico, Omar Ona-Rocha, Stefany Flores-Armas, Edgar Maya-Olalla	To perform an exploration process over complex structured data within \r\nunsupervised settings, the so-called kernel spectral clustering (KSC) is \r\none of the most recommended and appealing approaches, given its \r\nversatility and elegant formulation. In this work, we explore the \r\nrelationship between (KSC) and other well-known approaches, namely \r\nnormalized cut clustering and kernel k-means. To do so, we ﬁrst deduce \r\na generic KSC model from a primal-dual formulation based on\r\nleast-squares support-vector machines (LS-SVM). For experiments, \r\nKSC as well as other consider methods are assessed on image \r\nsegmentation tasks to prove their usability.	2017	2	\N
39	Reflexión Sobre el Trastorno por Déficit de Atención/Hiperactividad en Niños: Perspectiva Psicopedagógica, Neuropsicológica y Neurofisiológica	Congreso Internacional Psicología en la Educación 2017	Gabriela Narváez Olmedo, Stefany Cristina Flores Armas, Ana Cristina Umaquinga Criollo, Diego Hernán Peluffo-Ordóñez, Paola Alexandra Castro-Cabrera	Attention-deficit/hyperactivity  disorder  (ADHD)  is  primarily  characterized  by \r\ndistraction,  motor  restlessness, and  impulsive behaviors.  Its diagnosis  is typically  in \r\nchildren, however, in most cases this disorder may persist into adulthood and may cause \r\nvarious negative impacts on the social and emotional dynamics of individuals. Since it is \r\ntransversal  issue,  ADHD  in  children  has  been  approached  from  different  fields  of \r\nneuroscience, psychology and pedagogy. On one hand, some experts claim that there is a \r\nlink between the symptoms of ADHD with dysfunction of certain areas of the brain. On \r\nthe other hand, other specialists define ADHD as a behavioral syndrome. This conceptual \r\ndichotomy has been the subject of scientific controversy during the last decade. Another \r\nequally  controversial  aspect  of  ADHD  is  its  diagnosis,  because  it  includes  a \r\ncomprehensive analysis of the child, which requires the training of parents and teachers \r\nto  identify  symptoms,  as  well  as  the  presence  of  specialists  with  several  hours  of \r\ndedication. In practice, having a harmonic criterion between the three parts is not entirely \r\nfeasible. Within this multidisciplinary and controversial scenario, this article presents a \r\nreflexive and critical  dissertation –by way of  essay- on  the definition, diagnosis  and \r\ntreatment  of  ADHD in  children  from  a  psychopedagogical,  neuropsychological  and \r\nneurophysiological perspective.	2017	2	\N
27	Morfologías Visuales de Representación de Datos Como Aumento de Capacidades Analíticas Humanas: Una Revisión de Literatura	I Congreso Internacional de Ingenierías 2017, 375- 381	AJA Isaza, ACU Criollo, GN Olmedo, PDR Montalvo, DHP Ordóñez	La representación visual de datos es una técnica de extracción de conocimiento que permite tener una percepción de toda la información disponible dentro de Big Data. Para lograr el objetivo de captación de la atención humana, es necesario representar el conjunto de datos de una manera intuitiva. De esta forma, el usuario pueda tomar decisiones adecuadas. Consecuentemente, el mejoramiento de la experiencia humano computador se basa en el uso de técnicas de análisis de datos, donde los recursos computacionales deben ser optimizados. En este trabajo, se desarrolla una metodología con una investigación de tipo descriptivo, exploratorio y documental con los diferentes enfoques de visualización de datos orientados al análisis exploratorio para el descubrimiento científico y aumento de las capacidades humanas como apoyo a las decisiones automáticas. Palabras Claves: Big data, minería de datos, morfología visual, visualización. Abstract Visual representation is an approach to extract knowledge, which enables users to perceive the information whitin a context of Big Data. To involve the human perception into the data analysis, an inuitive data representation is needed. Consequently, any user will be able to make more adequate decisions. Indeed, the enhancement of human-computer interaction is based on the use of data anaylisis techniques while computational broad is optimized. In this work, a descriptive, exploratory and documental methodology is presented aimed at highlighting the benefit of involving the human skills within the process of automatic decision making.	2017	2	https://www.researchgate.net/publication/322509217_Morfologias_visuales_de_representacion_de_datos_como_aumento_de_capacidades_analiticas_humanas_Una_revision_de_literatura
40	Análisis Descriptivo de la Aplicabilidad de las Herramientas de Descubrimiento de Conocimiento en Ámbitos Académicos y Sociales, para Determinar Aplicaciones Futuras	ORNADAS ACADÉMICAS INTERNACIONALES CISIC 2017	Lilian Dayana Cruz Cruz	La Minería de Datos es un campo de gran acogida en el mundo académico, y tiene muchas aplicaciones en los modelos de almacenamiento masivo. Para llevar a cabo el Descubrimiento de Conocimiento en Bases de Datos (DCBD), típicamente es utilizado el proceso KDD (Knowledge Discovery in Databases); definiéndose éste como un proceso automático de identificación y análisis robusto de los datos; consistente en extraer patrones en forma de reglas o funciones, a partir de los datos, para que el usuario los interprete. Una herramienta DCBD debe integrar una variedad de componentes (técnicas de minería de datos, consultas, métodos de visualización, interfaces, etc.), los cuales, en conjunto, se encargarían de extraer información y reconocer patrones interesantes y útiles de los datos almacenados. Existen muchos tipos de herramientas que permiten extraer conocimiento basadas en el proceso KDD, sin embargo y debido a su variedad y aplicación, se hace necesario describir de manera concreta los diferentes ámbitos en los que pueden aplicarse de acuerdo a las funcionalidades específicas que cada una tiene. El presente artículo es de tipo exploratorio - descriptivo y pretende ser un referente para el análisis y selección de las diferentes herramientas de descubrimiento de conocimiento, de acuerdo a sus características particulares y su aplicación en contextos académicos y problemáticas sociales, que requieren una exploración robusta de los datos.	2017	4	https://www.researchgate.net/publication/320336384_Analisis_descriptivo_de_la_aplicabilidad_de_las_herramientas_de_descubrimiento_de_conocimiento_en_ambitos_academicos_y_sociales_para_determinar_aplicaciones_futuras
41	Theoretical developments for interpreting kernel spectral clustering from alternative viewpoints.	ASTESJ: Advances in Science, Technology and Engineering Systems Journal.	D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo, A. C. Umaquinga-Criollo, L. Suárez-Zambrano, H. Domínguez-Limaico, O. Oña-Rocha, S. Flores-Armas, E. Maya-Olalla.	To perform an exploration process over complex structured data within unsupervised settings, the so-called kernel spectral clustering (KSC) is one of the most recommended and appealing approaches, given its versatility and elegant formulation. In this work, we explore the relationship between (KSC) and other well-known approaches, namely normalized cut clustering and kernel k-means. To do so, we first deduce a generic KSC model from a primal-dual formulation based on least-squares support-vector machines (LS-SVM). For experiments, KSC as well as other consider methods are assessed on image segmentation tasks to prove their usability.	2017	1	https://astesj.com/v02/i03/p208/
42	Human Sit Down Position Detection Using Data Classification and Dimensionality Reduction.	ASTESJ: Advances in Science, Technology and Engineering Systems Journal.	P. D. Rosero-Montalvo, D. Jaramillo, S. Flores-Armas, D. H. Peluffo-Ordóñez, V. Alvear-Puertas, M. López.	The analysis of human sit down position is a research area allows for preventing health physical problems in the back. Many works have proposed systems that detect the sitting position, some open issues are still to be dealt with, such as: Cost, computational load, accuracy, portability, and among others. In this work, we present an alternative approach based on an embedded system to acquire the position-related variables and machine learning techniques, namely dimensionality reduction (DR) and classification. Since the information acquired by sensors is high-dimensional and therefore it might not be saved into embedded system memory, for this reason the system has a DR stage based on principal component analysis (PCA) is performed. Subsequently, the posed detection is carried out by the k-nearest neighbors (KNN) classifier between the matrix stored in the system and new data acquired by pressure and distance sensors. Thus, regarding using the whole data set, the computational cost is decreased by 33 % as well as the data reading is reduced by 10 ms. Then, sitting-pose detection task takes 26 ms, and reaches 75% of accuracy in a 4-trial experiment.	2017	1	https://astesj.com/v02/i03/p95/
43	Bridging the gap between human knowledge and machine learning	ADCAIJ: Advances in distributed computing and artificial intelligence Journal.	J. C. Alvarado-Pérez, D. H. Peluffo-Ordóñez, R. Therón	Nowadays, great amount of data is being created by several sources from academic, scientific, business and industrial activities. Such data intrinsically contains meaningful information allowing for developing techniques, and have scientific validity to explore the information thereof. In this connection, the aim of artificial intelligence (AI) is getting new knowledge to make decisions properly. AI has taken an important place in scientific and technology development communities, and recently develops computer-based processing devices for modern machines. Under the premise, the premise that the feedback provided by human reasoning -which is holistic, flexible and parallel- may enhance the data analysis, the need for the integration of natural and artificial intelligence has emerged. Such an integration makes the process of knowledge discovery more effective, providing the ability to easily find hidden trends and patterns belonging to the database predictive model. As well, allowing for new observations and considerations from beforehand known data by using both data analysis methods and knowledge and skills from human reasoning. In this work, we review main basics and recent works on artificial and natural intelligence integration in order to introduce users and researchers on this emergent field. As well, key aspects to conceptually compare them are provided.	2015	1	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2015415464
44	Multi-scale similarities in stochastic neighbour embedding: Reducing dimensionality while preserving both local and global structure	Neurocomputing Journal.	D. H. Peluffo-Ordóñez, J. A. Lee, M. Verleysen	Stochastic neighbour embedding (SNE) and its variants are methods of nonlinear dimensionality reduction that involve soft Gaussian neighbourhoods to measure similarities for all pairs of data. In order to build a suitable embedding, these methods try to reproduce in a low-dimensional space the neighbourhoods that are observed in the high-dimensional data space. Previous works have investigated the immunity of such similarities to norm concentration, as well as enhanced cost functions, like sums of Jensen–Shannon divergences. This paper proposes an additional refinement, namely multi-scale similarities, which are averages of soft Gaussian neighbourhoods with exponentially growing bandwidths. Such multi-scale similarities can replace the regular, single-scale neighbourhoods in SNE-like methods. Their objective is then to maximise the embedding quality on all scales, with the best preservation of both local and global neighbourhoods, and also to exempt the user from having to fix a scale arbitrarily. Experiments with several data sets show that the proposed multi-scale approach captures better the structure of data and improves significantly the quality of dimensionality reduction.	2015	1	http://www.sciencedirect.com/science/article/pii/S0925231215003641
45	Automatic Sleep Stages Classification Using EEG Entropy Features and Unsupervised Pattern Analysis Techniques	Entropy — Open Access Journal	J. L. Rodríguez-Sotelo, A. Osorio-Forero, A. Jiménez-Rodríguez, D. Cuesta-Frau, E. Cirugeda-Roldán and D. H. Peluffo-Ordóñez	Sleep is a growing area of research interest in medicine and neuroscience. Actually, one major concern is to find a correlation between several physiologic variables and sleep stages. There is a scientific agreement on the characteristics of the five stages of human sleep, based on EEG analysis. Nevertheless, manual stage classification is still the most widely used approach. This work proposes a new automatic sleep classification method based on unsupervised feature classification algorithms recently developed, and on EEG entropy measures. This scheme extracts entropy metrics from EEG records to obtain a feature vector. Then, these features are optimized in terms of relevance using the Q-α algorithm. Finally, the resulting set of features is entered into a clustering procedure to obtain a final segmentation of the sleep stages. The proposed method reached up to an average of 80% correctly classified stages for each patient separately while keeping the computational cost low.	2014	1	http://www.mdpi.com/1099-4300/16/12/6573
46	Unsupervised feature relevance analysis applied to improve ECG heartbeat clustering	Computer Methods and Programs in Biomedicine	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, D. Cuesta-Frau, G. Castellanos-Domínguez	The computer-assisted analysis of biomedical records has become an essential tool in clinical settings. However, current devices provide a growing amount of data that often exceeds the processing capacity of normal computers. As this amount of information rises, new demands for more efficient data extracting methods appear.\r\nThis paper addresses the task of data mining in physiological records using a feature selection scheme. An unsupervised method based on relevance analysis is described. This scheme uses a least-squares optimization of the input feature matrix in a single iteration. The output of the algorithm\r\nis a feature weighting vector.\r\nThe performance of the method was assessed using a heartbeat clustering test on real ECG records. The quantitative cluster validity measures yielded a correctly classified heartbeat rate of 98.69% \r\n(specificity), 85.88% (sensitivity) and 95.04% (general clustering performance), which is even higher than the performance achieved by other similar ECG clustering studies. The number of features was\r\nreduced on average from 100 to 18, and the temporal cost was a 43% lower than in previous ECG clustering schemes.	2012	1	http://diegopeluffo.com/publicaciones/Computer_Methods_Biomedicine2012.pdf
47	Weighted time series analysis for electroencephalographic source localization	DYNA	D. H. Peluffo-Ordóñez,E. Giraldo, G. Castellanos-Domínguez	This paper presents a new method to estimate neural activity from electroencephalographic signals using a weighted time series analysis. The method considers a physiologically based linear model that takes both spatial and temporal dynamics into account and a weighting stage to modify the assumptions of the model from observations. The calculated weighting matrix is included in the cost function used to solve the dynamic inverse problem, and therefore in the Kalman filter formulation. In this way, a weighted Kalman filtering approach is proposed including a preponderance matrix. The filter's performance (in terms of localization error) is analyzed for several SNRs. The optimal performance is achieved using the linear model with a weighting matrix computed by an inner product method.	2012	1	http://www.revistas.unal.edu.co/index.php/dyna/article/view/28126/43545
48	Comparative study of feature selection methods for supervised and unsupervised inference	Revista Tecnológicas	D. H. Peluffo-Ordóñez, J. L. Rodríguez, G. Castellanos	In this work, a comparative study of feature selection methods \r\nfor supervised and unsupervised inference obtained from classical \r\nPCA is presented.  We deduce an expression for the cost function of \r\nPCA based on the mean square error of data and its orthonormal \r\nprojection, and then this concept is extended to obtain an expression \r\nfor  general  WPCA.    Additionally,  we  study  the  supervised  and \r\nunsupervised Q – α algorithm and its relation with PCA. At the \r\nend, we present results employing two data sets: A low-dimensional \r\ndata set to analyze the effects of orthonormal rotation, and a high-\r\ndimensional data set to assess the classification performance. The \r\nfeature selection methods were assessed taking into account the \r\nnumber of relevant features, computational cost and classification \r\nperformance. The classification was carried out using a partitional \r\nclustering algorithm.	2009	1	http://diegopeluffo.com/publicaciones/TecnoLogicas2009.pdf
49	Kernel-based framework for spectral dimensionality reduction and clustering formulation: A theoretical study	Advances in Distributed Computing and Artificial Intelligence Journal 2016 (ADCAIJ).	X. Blanco-Valencia, M. A. Becerra, A. E. Castro-Ospina, M. Ortega-Adarme, D. Viveros-Melo, J. C. Alvarado-Pérez, D. H. Peluffo-Ordóñez.	This work outlines a unified formulation to represent spectral approaches for both dimensionality reduction and clustering. Proposed formulation starts with a generic latent variable model in terms of the projected input data matrix.\r\nParticularly, such a projection maps data onto a unknown high-dimensional space. Regarding this model, a generalized optimization problem is stated using quadratic formulations and a least-squares support vector machine.\r\nThe solution of the optimization is addressed through a primal-dual scheme.\r\nOnce latent variables and parameters are determined, the resultant model outputs a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Particularly, proposed\r\nformulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2017	1	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2017613140
50	Case based reasoning applied to medical diagnosis using multi-class classifier: A preliminary study.	ENFOQUE UTE.	D. Viveros Melo, M. Ortega Adarme, X. Blanco Valencia, A.E. Castro Ospina, S. Murillo Rendón, D. H. Peluffo-Ordóñez.	Case-based reasoning (CBR) is a process used for computer processing that tries to mimic the behavior of a human expert in making decisions regarding a subject and learn from the experience \r\nof past cases. CBR has demonstrated to be appropriate for working with unstructured domains \r\ndata or difficult knowledge acquisition situations, such as medical diagnosis, where it is possible \r\nto  identify  diseases  such  as: cancer  diagnosis,  epilepsy  prediction  and  appendicitis  diagnosis. \r\nSome of the trends that may be developed for CBR in the health science are oriented to reduce \r\nthe  number  of  features  in  highly dimensional  data. An  important  contribution  may  be  the \r\nestimation  of  probabilities  of  belonging  to  each  class  for  new  cases. In  this  paper,  in  order  to \r\nadequately  represent  the  database  and  to avoid  the  inconveniences  caused  by  the  high \r\ndimensionality,  noise  and  redundancy,  a  number  of  algorithms  are  used  in  the  preprocessing \r\nstage  for  performing  both  variable  selection  and  dimension  reduction  procedures. \r\nAlso, a comparison  of  the  performance  of some representative multiclass classifiers  is  carried  out  to identify  the  most effective  one to  include within  a  CBR  scheme. Particularly,  four  classification \r\ntechniques and  two reduction  techniques are  employed to make a comparative study  of multi-class\r\nclassifiers on CBR.	2017	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/141/148
51	Unsupervised analysis applied to the detection cardiac arrhythmias.	ENFOQUE UTE.	M. Moreno-Revelo, S. Patascoy-Botina, A. Pantoja-Bucheli, J. Revelo-Fuelagán, J. Rodriguez-Sotelo, S. Murillo-Rendón, D. H. Peluffo-Ordóñez.	An  arrhythmia  is  a  pathology  that  consists  on  altering  the  heartbeat.  Although,  the  12-lead \r\nelectrocardiogram  allows  evaluation  of  the  electrical  behavior  from  heart  to  determine  certain \r\npathologies,   there   are   some   arrhythmias   that   are   difficult   to   detect with   this   type   of \r\nelectrocardiography.  In  this  sense,  it  is  necessary  the  use  of  the  Holter  monitor  because  it \r\nfacilitates the records of the heart electrical activity for long periods of time, it is usually 24 up to \r\n48  hours.  Due  to  the  extension  of  the  records  provided  by  the  monitor,  it  is  common  to  use \r\ncomputational systems to evaluate diagnostic and morphological features of the beats in order to \r\ndetermine  if  there  is  any  type  of  abnormality.These  computational  systems  can  be  based  on \r\nsupervised  or  unsupervised  pattern  recognition  techniques,  however  considering  that  the  first \r\noption requires a visual inspection about the large number of beats present in a Holter record, it \r\nis an arduous task, as well as it involves monetary costs. Consequently, throughout this paper we \r\npresent  the  design  of  a  complete  system  for  the  identification  of  arrhythmias  in  Holter  records \r\nusing unsupervised pattern recognition techniques. The proposed system involves stages of pre-processing of the signal, segmentation and characterization of beats, as well as feature selection \r\nand clustering. In this case, the technique k-means is used.\r\nThese steps are applied within the framework  of  a  segment-based  methodology  that  improves  the  detection  of  minority  classes. Additionally,  init\r\nialization  criteria  are  considered,  which  allow  to  enhance  quality  measures, \r\nespecially  sensitivity.  As  a  result,  it  is  determined  that  using  k-means  with  the  max-min initialization  and  a  number  of  groups  equal  to  12,  it  is  possible  to  obtain  the  best  resu\r\nlts,  with values of: 99.36%, 91.31% and 99.16% for accuracy, sensitivity and specificity, respectively.	2017	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/125/131
52	Mejoramiento de las Capacidades Tecnológicas en los Sectores Rurales de la Provincia de Imbabura.	Revista CIENCIA.	S. Flores-Armas, P. Rosero-Montalvo, E. Maya-Olalla, D. H. Peluffo-Ordóñez.	The   engineering   degree   program   in   Electronics   and   Communication \r\nNetworks  from  Universidad  Técnica  del  Norte,  with  the  aim  of  str\r\nengthening  the society service processes, has created a project that benefits the population of the \r\nrural  areas  of  the  province  of  Imbabura. Such  a  project  has  as  a  main  goal  to \r\nreduce  the  digital  divide  in  high  schools  by  providing  access  to  information  and \r\ncommunication  technologies  to  Imabura’s  rural  population.  To  execute  the improving  technological  capabilities  project,  it  is  considered  as  a  population  of interest,  individuals  (men  and  women)  older  than  12  from  different  social  levels, cultures  and  ethnic  backgrounds.  Methodologically,  training  programs  based  on  a needs' assessment are formulated, which are subsequently evaluated with the aim of reducing the digital illiteracy level in the population of interest. In turn, improving its  technological  deficiencies  and its  quality  of  life.  Strategically,  the  Community Infocentros  and  school  labs  are  considered,  since  they  are  reference  points  for \r\nreaching  communities.  Along  with  them,  project  executors  are  able  to  making \r\ntraining   on   basic   office   tools,   basics   on   communication   networks,   Internet, \r\ncomputer   maintenance,   and   men   and   women   management   of   web   pages. \r\nFollowing the training, it was observed that, in the fields of action, participants met \r\ntheir expectations, abilities and skills acquired technology issues. In this paper, the \r\nmethodological aspects and main results of the project are presented.	2017	1	https://ia601608.us.archive.org/0/items/Articulo11_201705/Arti%CC%81culo%2011.pdf
53	Empleo del estropajo común (Luffa cylindrica) en la remoción de contaminantes.	RIAA: Revista de Investigación Agraria y Ambiental.	R. I. Pereira-Martínez, J. F. Muñoz-Paredes, D. H. Peluffo-Ordóñez.	Interesa a la ingeniería, el desarrollo biotecnológico de técnicas de tratamiento de agua para la remoción de contaminantes, aprovechando las propiedades de las fibras de Luffa cylindrica (FLc). Así lo exponen los argumentos explicados en varias investigaciones realizadas en todo el mundo en las que se describe un sugestivo escenario de razones válidas para considerar a la fibra del estropajo, como un material industrialmente promisorio y sostenible, apto para la realización de tratamientos de remoción de contaminantes y en la separación de sustancias inmersas en matrices fluidas. También explican la utilización de las fibras como matriz inmovilizadora para sostener comunidades microbianas activas implantadas con fines específicos; incluso, al comprender la arquitectura y las propiedades mecánicas de las FLc, se explora su utilización como agregado en la obtención de materiales compuestos, en la producción de nuevas sustancias y su capacidad para retener humedad. El presente artículo se refiere a la descripción de los procesos de adsorción e inmovilización en los que se ha involucrado a las FLc haciendo una revisión de experiencias investigativas. A la vez se estudian, los razonamientos que han permitido describir las técnicas y que posibilitan el aporte de soluciones al problema de la remoción de contaminantes y del tratamiento de agua.	2017	1	http://hemeroteca.unad.edu.co/index.php/riaa/article/view/1850
54	Internet de las Cosas y Visión Artificial, Funcionamiento y Aplicaciones: Revisión de Literatura.	ENFOQUE UTE.	V. Alvear-Puertas, P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, J. Pijal-Rojas.	Internet of Things (or also known as IoT) is one of the technologies most named today because \r\nof the ability it envisages to connect all kinds of devices to the Internet. If to the potentialities of \r\nIoT we add another technology of high impact as It is the Artificial Vision we have a wide field of \r\ninnovative  applications,  where  the  processing  of  images  and  video in  real  time  allow  the \r\nvisualization of large amounts of data on the Internet. The main applications developed with IoT \r\nand Artificial Vision can be implemented in education, medicine, intelligent buildings, surveillance \r\nsystems of people and vehicles, among others.This type of applications improves the quality of \r\nlife  of  users,  however,  for  their  development an  infrastructure  is  required that  allows  the \r\nconvergence of different protocols and devices, but in a special way that can handle the different \r\nphases  of  the  acquisition  of  images. In  this  work,  a  review  of  the  beginnings,  concepts, \r\ntechnologies and applications related to the Artificial Vision with the Internet of Things has been \r\ncarried out to be able to understand in a precise way the impact of its application in daily life.	2017	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/121/127
55	Agrupamiento espectral multi-clase basado en particiones normalizadas (Multi-way spectral clustering based on normalized partitions)	Cuaderno ACTIVA	D. H. Peluffo-Ordóñez	A comprehensive methodology for classification-oriented non-supervised analysis through the use of spectral techniques is presented here. This methodology includes a non-supervised clustering stage developed under the multiway criterion of normalized partitions. This technique is preferred because it does not require an additional clustering algorithm. Additionally, it results in a suitable partition, since it considers the information obtained from a solution of one’s own. Besides, adequate affinity measurements are applied, and the number of clusters is automatically estimated in order to reduce processing time and improve algorithm convergence. Experimental results are obtained on an image database. The quality of the cluster is measured by means of segmentation results. Also, a non-supervised performance measurement was introduced.	2013	1	http://ojs.tdea.edu.co/index.php/cuadernoactiva/article/view/112
56	Red Inalámbrica de Sensores basados en IPv6 para el monitoreo remoto de cultivos en la granja La Pradera de la Universidad Técnica	El diario FICAYA emprende	E. Tambaco-Suárez, E. Maya-Olalla, D. H. Peluffo-Ordóñez, H. Domínguez-Limaico, J. Michilena-Calderon	La  implementación  de  una  red inalámbrica de  sensores  (WSN) a  través del Protocolo   de   internet   versión   6   (IPv6), permite el monitoreo remoto y en tiempo real de factores  ambientales \r\nde los cultivos  de ciclo  corto  en  la  granja  La  Praderade  la Universidad Técnica del Norte. Al contar con redes inalámbricas de sensores es beneficioso debido a sus costos asequibles, mantenimiento económico y bajo consumo de potencia,  siendo  este último  la  característica \r\nque permite tener una red escalable, dado que los  nodos  sensores  pueden  ser  alimentados \r\ncon   energías   verdes como   es   el   caso   de paneles   solares y   así   monitorear   mayores \r\náreas, distancias y en tiempo real. Contar con un  monitoreo  en tiempo  real  de  los  factores \r\nambientales  permite  al  administrador  de  los cultivos   tener   información   confiable   como \r\nbase para la toma de decisiones, posiblemente para   programar   un   riego   controlado;   el \r\nbeneficio  crece  aún  más  si  se  aprovecha  la existencia de plataformas como servicio en la \r\nnube  (PAAS) que  permiten visualizar  estos datos  desde  cualquier  dispositivo  inteligente \r\ncon  acceso  a Internet  mediante un  navegador web.	2016	1	http://diegopeluffo.com/publicaciones/2016_FicayaEmprende_Red_de_monitore_granja.pdf
57	Aplicación de Técnicas de Fuerza Bruta con Diccionario de Datos, para vulnerar servicios con métodos de autenticación simple “Contraseñas”, pruebas de concepto con software libre y su remediación.	Revista MASKANA.	H. M. Domínguez-Limaico, E. Maya-Olalla, D. H. Peluffo-Ordóñez, C. M. Crisanto-Ñ.	This paper illustrates the increased security risks in recent years of attacks on authentication controls, specifically passwords. Methods and techniques for violating such controls using more and more brute force attack approaches, including data dictionaries. Furthermore, the manuscript presents a proof concept using the free distribution of Linux "Kali Linux" and the penetration tool "Metaexploits Framework" to mitigate attacks; to finally present a more detailed approach for the secure management of passwords, an important issue in times of crisis.\r\nKeywords: Security informatics, controls, passwords, brute force, data dictionary, penetration, attacks.	2017	1	https://www.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1079
58	Sistema de Monitoreo de Monóxido de Carbono a través de una Red de sensores Inalámbrica y una Plataforma como servicio en la nube para una residencia.	Revista MASKANA.	E. M. Carrión, E. Maya-Olalla, H. M. Domínguez-Limaico, D. H. Peluffo-Ordóñez.	This paper presents a system of monitoring carbon monoxide as basis for the securization of environmental safety in a residence, based on a wireless sensor network and platform as a service in the cloud with the objective of caring for human lives and preventing gas poisoning.\r\nKeywords: WSN, platform as a service, IoT, IEEE 802.15.4, zigbee, wireless sensor network, arduino.	2017	1	https://www.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1080
59	Diseño de telefonía IP a través del Cloud Computing bajo una plataforma de software libre OpenNebula	Revista MASKANA.	G. C. Ruiz-García, E. Maya-Olalla, C. A. Vásquez, H. M. Domínguez-Limaico, D. H. Peluffo-Ordóñez.	The present study implicates a new solution of telecommunication for IP telephony service, which is based on cloud computing, providing an option for communications at the “Universidad Técnica del Norte”. The analysis was performed, based on the IEEE 29148 standard for selecting a virtualization platform and IP telephony software. Subsequently, the IP telephony was designed through cloud computing. In the IP telephony design, the dimensioning of IP telephony was developed through the cloud, considering the instance capacity, bandwidth, traffic flow and the number of trunks. For the analysis of these parameters the updated information of the University’s IP telephony was used. Thereafter, the cloud platform was configured. Following, the service performance was tested as to observe the behavior after the incorporation of this infrastructure.\r\nKeywords: VoIP, PBX, softphone, PSTN, SIP, cloud computing, Elastix, OpenNebula.	2017	1	https://www.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1084
60	Herramientas de análisis de grandes volúmenes de datos para la toma de decisiones empresariales y fidelización de los clientes	Revista de Estrategias del Desarrollo Empresarial. Junio 2017 Vol.3 No.8 31-39	A. Umaquinga, T. Saltos, D. H. Peluffo-Ordóñez.	The    accelerated    growth    of    competition    among companies  globally  is  undeniable.  The  new  challenges to  generate  value,  discover  trends  and  preferences  of customers  demand  companies  to  have  technological tools  of  greater  reach  and  efficiency  that  allow  to  be support  in  the  decision  making  in  real  time  or  in  the shortest  possible  time  in  order to  create  competitive \r\nadvantage  and  stay  in  the  market.  Technological  tools like Data mining, Big data, among others, aim to obtain new   knowledge,   patterns,   predictions   for   a   better understanding  and  precision  of  costumer  needs,  which would  not  be  possible  with  the  use  of  conventional tools.  Hence  teamwork  in  the  area  of  technology  and business   requires   this   knowledge   of   value   for   the \r\ndefinition  of  strategies  aimed  at  capitalizing  on  this knowledge  originated  in  an  internal  and  external  way especially  of  social  networks.  The  present  article  is descriptive,  exploratory,  and  documentary,  perform  an analysis of the  technological  tools used at  the  business level  and  topics  of  use  in  the  decision  making  and search  of  the  loyalty  of  its  clients,  as  well  as  its  value \r\naspects and challenges. Consequently, the results show the    favorable    and    efficient    relationship    of    the application  of  these  technologies  in  business  decision-making, therefore, the need arises for a greater number of future research of this type.	2017	1	http://www.ecorfan.org/spain/researchjournals/Estrategias_del_Desarrollo_Empresarial/vol3num8/Revista_de_Estrategias_del_Desarrollo_Empresarial_V3_N8_4.pdf
63	Low Data Fusion Framework Oriented to Information Quality for BCI Systems	International Conference on Bioinformatics and Biomedical Engineering 2018	Miguel Alberto Becerra, Karla C. Alvarez-Uribe, Diego Hernán Peluffo Ordoñez.	The evaluation of the data/information fusion systems does not have standard quality criteria making the reuse and optimization of these systems a complex task. In this work, we propose a complete low data fusion (DF) framework based on the Joint Director of Laboratories (JDL) model, which considers contextual information alongside information quality (IQ) and performance evaluation system to optimize the DF process according to the user requirements. A set of IQ criteria was proposed by level. The model was tested with a brain-computer interface (BCI) system multi-environment to prove its functionality. The first level makes the selection and preprocessing of electroencephalographic signals. In level one feature extraction is carried out using discrete wavelet transform (DWT), nonlinear and linear statistical measures, and Fuzzy Rough Set – FRS algorithm for selecting the relevant features; finally, in the same level a classification process was conducted using support vector machine – SVM. A Fuzzy Inference system is used for controlling different processes based on the results given by an IQ evaluation system, which applies quality measures that can be weighted by the users of the system according to their requirements. Besides, the system is optimized based on the results given by the cuckoo search algorithm, which uses the IQ traceability for maximizing the IQ criteria according to user requirements. The test was carried out with different type and levels of noise applied to the signals. The results showed the capability and functionality of the model.	2018	1	https://link.springer.com/chapter/10.1007%2F978-3-319-78759-6_27
93	Different perspectives for kernel spectral clustering: A theoretical study	2016 IEEE Ecuador Technical Chapters Meeting (ETCM).	D. H. Peluffo-Ordóñez, P. D. Rosero, C. H. Pupiales, L. E. Suárez, E. D. Jaramillo, E. A. Maya, \r\nJ. R. Michilena, C. A. Vásquez	Spectral clustering is a suitable technique to deal with problems involving unlabeled clusters and having a complex structure, being kernel-based approaches the most recommended ones. This work aims at demonstrating the relationship between a widely-recommended method, so-named kernel spectral clustering (KSC) and other well-known approaches, namely normalized cut clustering and kernel k-means. Such demonstrations are done by following a primal-dual scheme. Also, we mathematically and experimentally prove the usability of using LS-SVM formulations with a model. Experiments are conducted to assess the clustering performance of KSC and the other considered methods on image segmentation tasks.	2016	1	https://ieeexplore.ieee.org/document/7750849/
64	Case-Based Reasoning Systems for Medical Applications with Improved Adaptation and Recovery Stages	International Conference on Bioinformatics and Biomedical Engineering 2018	X. Blanco Valencia, D. Bastidas Torres, C. Piñeros Rodriguez, D. H. Peluffo-Ordóñez, M. A. Becerra, A. E. Castro-Ospina.	Case-Based Reasoning Systems (CBR) are in constant evolution, as a result, this article proposes improving the retrieve and adaption stages through a different approach. A series of experiments were made, divided in three sections: a proper pre-processing technique, a cascade classification, and a probability estimation procedure. Every stage offers an improvement, a better data representation, a more efficient classification, and a more precise probability estimation provided by a Support Vector Machine (SVM) estimator regarding more common approaches. Concluding, more complex techniques for classification and probability estimation are possible, improving CBR systems performance due to lower classification error in general cases.	2018	1	https://link.springer.com/chapter/10.1007%2F978-3-319-78723-7_3
65	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering 2018	J.A. Salazar-Castro, A.C. Umaquinga-Criollo, L.D. Cruz-Cruz, L.O. Alpala-Alpala, C. González-Castaño, M.A. Becerra-Botero, D.H. Peluffo-Ordóñez, C.G. Castellanos-Domínguez.	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	1	https://link.springer.com/chapter/10.1007%2F978-3-319-78759-6_22
66	Cardiac Pulse Modeling Using a Modified van der Pol Oscillator and Genetic Algorithms	International Conference on Bioinformatics and Biomedical Engineering 2018	F.M. Lopez-Chamorro, A.F. Arciniegas-Mejia, D.E. Imbajoa-Ruiz, P.D. Rosero-Montalvo, P.García, A.E. Castro-Ospina, A. Acosta, D.H. Peluffo-Ordóñez.	This paper proposes an approach for modeling cardiac pulses from electrocardiographic signals (ECG). A modified van der Pol oscillator model (mvP) is analyzed, which, under a proper configuration, is capable of describing action potentials, and, therefore, it can be adapted for modeling a normal cardiac pulse. Adequate parameters of the mvP system response are estimated using non-linear dynamics methods, like dynamic time warping (DTW). In order to represent an adaptive response for each individual heartbeat, a parameter tuning optimization method is applied which is based on a genetic algorithm that generates responses that morphologically resemble real ECG. This feature is particularly relevant since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are performed over real ECG from MIT-BIH arrhythmias database. The application of the optimization process shows that the mvP oscillator can be used properly to model the ideal cardiac rate pulse.	2018	1	https://link.springer.com/chapter/10.1007%2F978-3-319-78723-7_8
68	Face Detection and Classification Using Eigenfaces and Principal Component Analysis: Preliminary Results	Information Systems and Computer Science (INCISCOS), 2017	Richard Mejía-Campos ; Diego Néjer-Haro ; Santiago Recalde-Avincho ; Paul Rosero-Montalvo ; Diego Peluffo-Ordóñez.	This work is a Scientific Track paper corresponding to the area of Intelligent Systems. This paper presents a facial recognition approach based on the Eigenfaces method as well as Principal Component Analysis (PCA) as algorithm of processing and cleaning images, respectively. The classification was performed by using the Euclidean distance between the facial characters stored in a database and new images captured in an interface with similarly coded developed in MatLab. As main results, we obtained: (i) 68.9% of classification accuracy when using different components of stored faces, (ii) 91.43% of classification performance when storing 3 components for each face and evaluating more users for training model in seven controlled experiments. \r\n\r\nFace Detection and Classification Using Eigenfaces and.... Available from: https://www.researchgate.net/publication/324165158_Face_Detection_and_Classification_Using_Eigenfaces_and_Principal_Component_Analysis_Preliminary_Results [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/324165158_Face_Detection_and_Classification_Using_Eigenfaces_and_Principal_Component_Analysis_Preliminary_Results
74	Automatic Motion Segmentation via a Cumulative Kernel Representation and Spectral Clustering	Intelligent Data Engineering and Automated Learning – IDEAL 2017.  IDEAL 2017.	O. R. Oña-Rocha, O. T. Sánchez-Manosalvas, A. C. Umaquinga-Criollo, P. Rosero-Montalvo, L. E. Suárez-Zambrano, J. L. Rodriguez-Sotelo, D. H. Peluffo-Ordóñez.	Dynamic or time-varying data analysis is of great interest in emerging and challenging research on automation and machine learning topics. In particular, motion segmentation is a key stage in the design of dynamic data analysis systems. Despite several studies have addressed this issue, there still does not exist a final solution highly compatible with subsequent clustering/classification tasks. In this work, we propose a motion segmentation compatible with kernel spectral clustering (KSC), here termed KSC-MS, which is based on multiple kernel learning and variable ranking approaches. Proposed KSC-MS is able to automatically segment movements within a dynamic framework while providing robustness to noisy environments.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_44
69	GreenFarm-DM: A tool for analyzing vegetable crops data from a greenhouse using data mining techniques (First trial).	Ecuador Technical Chapters Meeting (ETCM), 2017 IEEE.	K. L. Ponce, J. A. Palacion, E. Maya-Olalla, H. M. Dominguez-Limaico, L. E. Suaréz, P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, J. C. Alvarado-Perez.	This work shows the use of Big Data and Data Mining techniques on vegetable crops data from a greenhouse by implementing the first version of a software tool, so called GreenFarm-DM. Such a tool is aimed at analyzing the factors that influence the growth of the crops, and determine a predictive model of soil moisture. Within a greenhouse, the variables that affect crop growth are: relative humidity, soil moisture, ambient temperature, and levels of illumination and CO2. These parameters are essential for photosynthesis, i.e. during processes where plants acquire the most nutrients, and therefore, if performing a good control on these parameters, plants might grow healthier and produce better fruits. The process of analysis of such factors in a data mining context requires designing an analysis system and establishing an objective variable to be predicted by the system. In this case, in order to optimize water resource expenditure, soil moisture has been chosen as the target variable. The proposed analysis system is developed in a user interface implemented in Java and NetBeans IDE 8.2, and consists mainly of two stages. One of them is the classification through algorithm C4.5 (chosen for the first trial), which uses a decision tree based on the data entropy, and allows to visualize the results graphically. The second main stage is the prediction, in which, from the classification results obtained in the previous stage, the target variable is predicted from information of a new set of data. In other words, the interface builds a predictive model to determine the behavior of soil moisture.	2017	1	http://ieeexplore.ieee.org/document/8247519/
70	Elderly fall detection using data classification on a portable embedded system.	Ecuador Technical Chapters Meeting (ETCM), 2017 IEEE.	P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, P. Godoy, k. Ponce, E. Rosero, C. Vásquez, F. Cuzme, S. C Flores, Z. A. Mera.	The area of research on the detection of falls in the elderly allows to prevent major ailments to a person and not receiving timely medical attention. Although different systems have been proposed for the detection of falls, there are some open problems such as: cost, computational load, precision, portability, among others. This paper presents an alternative approach based on the acquisition of speed variation of the person on the X, Y and Z axes using an accelerometer and machine learning techniques. Since the information acquired by the sensor is very variant, with noise and high volume of data, a prototype selection stage is carried out using confidence intervals and techniques of Leaving-One-Out. Subsequently, automatic detection is performed using the K-nearest neighbors (K-NN) classifier. As a result of fall detection 95% accuracy is achieved in experiments from 5 trials and already used in reality by an older adult, the system has a time of 30 ms for position selection and the detection of drop is maintained in a 92% right.	2017	1	http://ieeexplore.ieee.org/document/8247529/
71	Prototype reduction algorithms comparison in nearest neighbor classification for sensor data: Empirical study.	Ecuador Technical Chapters Meeting (ETCM), 2017 IEEE.	P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, A. Umaquinga, A. Anaya, J. Serrano, E. Rosero, C. Vásquez, L. Suaréz.	This work presents a comparative study of prototype selection (PS) algorithms. Such a study is done over data-from-sensor acquired by an embedded system. Particularly, five flexometers are used as sensors, which are located inside a glove aimed to read sign language. Measures were taken to quantify the balance between classification performance and reduction training set data (QCR) with k neighbors equal to 3 and 1 to force the classifier (kNN) to the maximum. Two tests were used: (a)the QCR performance and (b) the embedded system decision in real proves. As result the Random Mutation Hill Climbing (RMHC) algorithm is considered the best option to choose in this data type with removed instances at 87% and classification performance at 82% in software tests, also the classifier kNN must be with k=3 to improve the classification performance. In a real situation, with the algorithm implemented. The system makes correct decisions at 81% with 5 persons doing sign language in real time.	2017	1	http://ieeexplore.ieee.org/document/8247530/?reload=true
72	Forecasting of Energy Consumption Based on Gaussian Mixture Model and Classification Techniques.	Simposio Internacional sobre Calidad de la Energia Electrica SICEL 2017.	D. Imbajoa-R, A. Arciniegas-M, J. Revelo-Fuelagan, D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo.	The estimation of energy demand is not always straightforward or reliable, as one or several classes may fail in the prediction. In this study, a novel methodology of load forecasting is proposed.Three different configurations of Artificial Neural Networks perform a supervised classification of energy consumption data, each one providing an  output  vector of unreliable predicted  data.  Under  the  clustering  method  k-means, multiple patterns  are identified, and then processed by the Gaussian Mixture Model in order to provide higher relevance to the more accurate  predicted samples  of \r\ndata.  The  accuracy  of  the  prediction  is  evaluated  with  the  several  error  rate measurements. Finally, a mixture of the generated forecasts by the methods is performed, showing a lower error rate \r\ncompared to the inputs predictions, therefore, a more reliable forecast.	2017	1	https://www.researchgate.net/profile/David_Imbajoa/publication/320853691_Forecasting_of_Energy_Consumption_Based_on_Gaussian_Mixture_Model_and_Classification_Techniques/links/59fe4a400f7e9b9968c3cfe6/Forecasting-of-Energy-Consumption-Based-on-Gaussian-Mixture-Model-and-Classification-Techniques.pdf
73	Comparison Among Physiological Signals for Biometric Identification	Intelligent Data Engineering and Automated Learning – IDEAL 2017.  IDEAL 2017.	M. Moreno-Revelo, M. Ortega-Adarme, D. H. Peluffo-Ordóñez, K. C. Alvarez-Uribe. M. A. Becerra.	The biometric is an open research field that requires analysis of new techniques to increase its accuracy. Although there are active biometric systems for subject identification, some of them are considered vulnerable to be fake such as a fingerprint, face or palm-print. Different biometric studies based on physiological signals have been carried out. However, these can be regarded as limited. So, it is important to consider that there is a need to perform an analysis among them and determine the effectivity of each one and proposed new multimodal biometric systems. In this work is presented a comparative study of 40 physiological signals from a multimodal analysis. First, a preprocessing and feature extraction was carried out using Hermite coefficients, discrete wavelet transform, and statistical measures of them. Then, feature selection was applied using two selectors based on Rough Set algorithms, and finally, classifiers and a mixture of five classifiers were used for classification. The more relevant results shown an accuracy of 97.7% from 3 distinct EEG signals, and an accuracy of 100% using 40 different physiological signals (32 EEG, and eight peripheral signals).	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_47
75	Interactive Data Visualization Using Dimensionality Reduction and Dissimilarity-Based Representations	Intelligent Data Engineering and Automated Learning – IDEAL 2017.  IDEAL 2017.	D. F. Peña-Unigarro, P. Rosero-Montalvo, J. Revelo-Fuelagán, J. A. Castro-Silva, J. C. Alvarado-Pérez, R. Therón, C. M. Ortega-Bustamante, D. H. Peluffo-Ordóñez.	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
76	Analysis of Motor Imaginary BCI Within Multi-environment Scenarios Using a Mixture of Classifiers	The 12th Colombian Conference on Computing.  CCC 2017.	M. Ortega-Adarme, M. Moreno-Revelo, D. H. Peluffo-Ordóñez, D. Marín-Castrillon, \r\nA. E. Castro-Ospina, M. A. Becerra.	Brain-computer interface (BCI) is a system that provides communication between human beings and machines through an analysis of human brain neural activity. Several studies on BCI systems have been carried out in controlled environments, however, a functional BCI should be able to achieve an adequate performance in real environments. This paper presents a comparative study on alternative classification options to analyze motor imaginary BCI within multi-environment real scenarios based on mixtures of classifiers. The proposed methodology is as follows: The imaginary movement detection is carried out by means of feature extraction and classification, in the first stage; feature set is obtained from wavelet transform, empirical mode decomposition, entropy, variance and rates between minimum and maximum, in the second stage, where several classifier combinations are applied. The system is validated using a database, which was constructed using the Emotiv Epoc+ with 14 channels of electroencephalography (EEG) signals. These were acquired from three subject in 3 different environments with the presence and absence of disturbances. According to the different effects of the disturbances analyzed in the three environments, the performance of the mixture of classifiers presented better results when compared to the individual classifiers, making it possible to provide guidelines for choosing the appropriate classification algorithm to incorporate into a BCI system.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_37
77	Two Novel Clustering Performance Measures Based on Coherence and Relative Assignments of Clusters	The 12th Colombian Conference on Computing.  CCC 2017.	H. J. Areiza-Laverde, A. E. Castro-Ospina, P. D. Rosero-Montalvo, D. H. Peluffo-Ordóñez, \r\nJ. L. Rodriguez-Sotelo, M. A. Becerra-Botero.	This work proposes two novel alternatives for dealing with the highly important issue of the clustering performance estimation. One of the measures is the cluster coherence aimed to quantifying the normalized ratio of cuts within a graph-partitioning framework, and therefore it uses a graph-driven approach to explore the nature of data regarding the cluster assignment. The another one is the probability-based-performance quantifier, which calculates a probability value for each cluster through relative frequencies. Proposed measures are tested on some clustering representative techniques applied to real and artificial data sets. Experimental results probe the readability and robustness to noisy labels of our measures.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_56
78	Data Visualization Using Interactive Dimensionality Reduction and Improved Color-Based Interaction Model	International Work-Conference on the Interplay Between Natural and Artificial Computation.	P. D. Rosero-Montalvo, D. F. Peña-Unigarro, D. H. Peluffo-Ordóñez, J. A. Castro-Silva, \r\nA. C. Umaquinga-Criollo, E. A. Rosero-Rosero.	This work presents an improved interactive data visualization interface based on a mixture of the outcomes of dimensionality reduction (DR) methods. Broadly, it works as follows: The user can input the mixture weighting factors through a visual and intuitive interface with a primary-light-colors-based model (Red, Green, and Blue). By design, such a mixture is a weighted sum of the color tone. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to simultaneously be drawn over the scatter plot. Our interface enables the user to interactively combine DR methods by the human perception of color, while providing information about the structure of original data. Then, it makes the selection of a DR scheme more intuitive -even for non-expert users.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-59773-7_30
79	Sleep Stages Clustering Using Time and Spectral Features of EEG Signals.	International Work-Conference on the Interplay Between Natural and Artificial Computation.  IWINAC 2017.	J. L. Rodriguez-Sotelo, A. Osorio-Forero, A. Jiménez-Rodríguez, F. Restrepo-de-Mejía, \r\nD. H. Peluffo-Ordóñez, J. Serrano.	Sleep stage classification is a highly addressed issue in polysomnography; It is considered a tedious and time-consuming task if done manually by the specialist; therefore, from the engineering point of view, several methods have been proposed to perform an automatic sleep stage classification. In this paper an unsupervised approach to automatic sleep stage clustering of EEG signals is proposed which uses spectral features related to signal power, coherences, asymmetries, and Wavelet coefficients; the set of features is classified using a clustering algorithm that optimizes a cost function of minimum sum of squares. Accuracy and kappa coefficients are comparable to those of the current literature as well as individual stage classification results. Methods and results are discussed in the light of the current literature, as well as the utility of the groups of features to differentiate the states of sleep. Finally, clustering techniques are recommended for implementation in support systems for sleep stage scoring.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-59740-9_44
81	Estudio comparativo de técnicas supervisadas de machine learning aplicadas en problemas médicos.	III Jornadas Académicas Internacionales CISIC 2017	C. Basante, C. Ortega, D. H. Peluffo-Ordóñez, X. Blanco.	Currently,  information  overload  has  caused  human  analysis  capabilities \r\nbecome insufficient in  comparison  with  the  imminent  growth  of  technological  capabilities  to \r\ncollect,  communicate  and  store  large  volumes  of  information.  In  hospitals  or  health entities,\r\nmillions of data, diagnostic tests, and other information are collected every day. The  medicine  has  used  the  technological  revolution  in  many  ways  to  facilitate  the handling,  processing,  visualization and  analysis  of  data,  a  specific  task associated  with the diagnosis of diseases is the pathology classification, where in the machine trained in conjunction with an expert can improve\r\nand facilitate the diagnosis. Currently there are many  disciplines  which  aim  is  developed  techniques  that  allow  computers  to  learn, however  one  of  the  most  explored  is  machine  learning  in  which  classifiers  have  been developed, they  allow  the assignment of  new  objects  represented  in  features in to beforehand known categories. As part of artificial intelligence, t\r\nhe classification of pathologies is not a trivial task -there is a great variety of classification techniques. In this connection, this research work performs a comparison   of   multi-class   classification   techniques recommended by scientific literature, such as: SVM (Support Vector Machine), KNN (K-nearest neighbors algorithm),  ANN  (Artificial  neural  network),  PC  (Parzen ́s  Classifier),  Random  Forest and  Adaboost  (Adaptative  Boosting).  The  experiments  are  performed  on heart  disease (Cleveland), cardiotocography and hypothyroidism databases. As a result, it is demonstrated that Cleveland and hypothyroid databases are challenging for the ANN, PC and Adaboost classifiers because of their scarcity of data, causing that classification procedures reach greater error values. On the contrary, when dealing with databases having proper balance in their number of samples for each class (for instance, cardiotocography),  better  results  are  obtained  when classification  training  is  done  with Adaboost.	2017	1	http://diegopeluffo.com/publicaciones/2017_EstudioComparativo_CISIC.pdf
83	Big Data Analytics BDA) en la toma de decisiones empresariales.	III Jornadas Académicas Internacionales CISIC 2017	A. C. Umaquinga-Criollo, S. K. Narvaez-Pupiales, D. H. Peluffo-Ordóñez, M. C. Ortega-Bustamante.	Ante el crecimiento exponencial y vertiginoso del volumen de los datos de diferente tipo: estructurados, semiestructurados y no estructurados provenientes de una variedad de fuentes entre ellas: la web, redes sociales, bases de datos, archivos de audio/video, datos transaccionales, sensores, comunicación máquina a máquina (denominado M2M). El área de Big Data pretende dar respuesta a los desafíos del tratamiento de la información. Es por ello, que el proceso de análisis de grandes volúmenes de datos Big Data Analytics (denominado BDA) facilita el descubrimiento de patrones, predicciones, fraudes, tendencias de mercado, comportamientos y preferencias de los clientes e información de utilidad, que no sería posible con las herramientas convencionales. BDA se convierte en una de las herramientas de soporte para la toma de decisiones empresariales y ventaja competitiva en tiempo real o en el menor tiempo posible frente a sus competidores, ofreciendo nuevos niveles de competitividad, procesos, modelos de negocio basados en datos y reducción del riesgo para conservar, fidelizar y captar una mayor cantidad de clientes generando un aumento en las fuentes de ingreso de las empresas. El presente artículo es de tipo exploratorio, descriptivo y documental. Se realiza un estudio descriptivo del impacto de Big Data Analytics (BDA) en el campo empresarial, así como un breve recorrido por sus tendencias, oportunidades, dificultades y retos. Este estudio pretende contribuir a la comunidad de investigadores, así como al personal de las empresas y a quienes se inician en el conocimiento de Big Data Analytics para una mejor comprensión en este campo. Abstract: By the exponential and vertiginous growth of the volume of data of different types: structured, semi-structured and unstructured from a variety of sources including: the web, social networks, databases, audio / video files, transactional data, sensors, machine-to-machine communication (denominated M2M). The Big-Data-area is intended to address the challenges of information processing. Therefore, the Big Data Analytics (BDA) process of large volumes of data facilitates the discovery of patterns, predictions, fraud, market trends, customer behaviours and preferences and useful information that would not be possible with conventional tools. BDA becomes one of the tools to support business decision-making and competitive advantage in real time or in the shortest possible time in relation its competitors, offering new levels of competitiveness, processes, business models based in data and risk reduction, to conserve, retain and attract a greater number of customers generating an increase in the sources of income of companies. This article is exploratory, descriptive and documentary. A descriptive study of the impact of Big Data Analytics (BDA) in the business field, as well as a brief tour of its tendencies, opportunities, difficulties and challenges. This study aims to contribute to the research community, as well as the staff of the companies and those who are introduced to the knowledge of Big Data Analytics for a better understanding in this field. \r\n\r\nBIG DATA ANALYTICS (BDA) EN LA TOMA DE... (PDF Download Available). Available from: https://www.researchgate.net/publication/318586255_BIG_DATA_ANALYTICS_BDA_EN_LA_TOMA_DE_DECISIONES_EMPRESARIALES_BIG_DATA_ANALYTICS_BDA_IN_BUSINESS_DECISION_MAKING [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/318586255_BIG_DATA_ANALYTICS_BDA_EN_LA_TOMA_DE_DECISIONES_EMPRESARIALES_BIG_DATA_ANALYTICS_BDA_IN_BUSINESS_DECISION_MAKING
84	Impacto de la usabilidad de los drones en la agragación del valor en la producción.	III Jornadas Académicas Internacionales CISIC 2017	S. K. Narvaez-Pupiales, A. C. Umaquinga-Criollo, D. H. Peluffo-Ordóñez.	The Ecuadorian economy has been based mainly on the exploitation of raw materials \r\nand  imports  of goods  and  services,  this  ecosystem  not  encouraging  development  as  a \r\nresult in certain periods of time and according to the variability of the international market \r\nhas  caused  to  this  day  swings,  as  a  result  of  changes  in  the  prices  of  these  resources \r\ncompared to prices of products with higher added value and high technology. One of the \r\nmain objectives of the Change of the Productive Matrix is to evolve this pattern of primary \r\nexporting specialization to a pattern of diversified production highlighting especially the \r\ncapacities and knowledge of human talent involved in these processes.\r\nIn order to frame the economic and social development of the population around this \r\nchange, the incorporation of technology has become one of the main axes to improve and\r\nachieve the proposed objectives, being in this way a vital tool to improve production. Of \r\nthe  many  technological  possibilities  that  exist,  this  research  highlights,  analyzes  and \r\nevaluates the incorporation of unmanned Aerial Systems or Vehicles commonly known \r\nas  DRONES  to  the  agricultural  sector  with  special  emphasis  on  the  advantages, \r\ndisadvantages, risks, acceptance levels, components of hardware and software, statistics \r\nrelated to production cost savings and how the current Regulation by the Civil Aviation \r\nDirectorate in Ecuador contributes to the development and usability of these systems.\r\nFinally, the conclusions point to the great possibilities of growth and transformation of\r\nagriculture to effective methods of precision where the aid of DRONES and automation \r\ncan  provide  a  large  amount  of  information  such  as  reports,  images,  videos,  maps  and\r\nothers where human intervention becomes minimal.	2017	1	http://diegopeluffo.com/publicaciones/2017_UsabilidadDrones_CISCIC.pdf
85	La importancia de la informática en la ingeniería mecatrónica: Una experiencia reflexiva.	III Jornadas Académicas Internacionales CISIC 2017	P. Benavides, W. Mosquera, D. H. Peluffo-Ordóñez, D. Terán.	La ingeniería mecatrónica es una especialidad relativamente nueva, la cual se conforma por la sinergia y aprovechamiento de características y fortalezas de otras especialidades que ya tienen un largo trayecto a nivel profesional. Particularmente, la formación de un estudiante de mecatrónica involucra técnicas de programación que constituye el cerebro o parte inteligente para el desarrollo de cualquier sistema automático. Por tanto, el área de programación es de uso transversal y debe ser adecuadamente enseñada a los estudiantes de mecatrónica. No obstante, hay evidencia de que algunos educadores en mecatrónica han tomado la errada posición de que los futuros profesionales, al no ser desarrolladores de software, no deberían recibir enseñanza de la programación a profundidad, sino por el contrario, solamente una formación en conceptos básicos. El método aplicado para la realización de este artículo es el experimental, aplicado a partir de experiencia en la práctica profesional y como docentes de las asignaturas de programación básica, avanzada y sistemas de control, en la carrera de ingeniería en mecatrónica en la Universidad Técnica del Norte, lo cual ha permitido presentar una reflexión sobre la importancia y pertinencia del área de programación informática en la enseñanza de mecatrónica. Como conclusión de este trabajo se presenta elementos de discusión y aspectos técnicos para tomar una posición ante la necesidad y pertinencia de la enseñanza de la programación informática para mecatrónica de forma adecuada, es decir, en contexto y a nivel requerido por un profesional en ingeniería, abarcando en partes iguales la sinergia de los saberes que conforman la carrera de Ingeniería en Mecatrónica. \r\n\r\n(PDF) La importancia de la Informática en la Ingeniería mecatrónica: una experiencia reflexiva. Available from: https://www.researchgate.net/publication/318724551_La_importancia_de_la_Informatica_en_la_Ingenieria_mecatronica_una_experiencia_reflexiva [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/318724551_La_importancia_de_la_Informatica_en_la_Ingenieria_mecatronica_una_experiencia_reflexiva
86	Implementación de un sistema de control para rehabilitador pasivo de dedos de la mano.	Congreso Internacionalde bioingenieria y sistemas inteligentes de rehabilitación. 2017	W. Mosquera, P. Benavides, D. Ojeda, D. Ortiz, D. H. Peluffo-Ordóñez.	Mediante este documento se hace referencia a un proyecto de investigación en el área médica y fisioterapéutica, enmarcada en tratamientos para recuperación de la movilidad funcional de los dedos de la mano que se han generado por traumatismo ocasionados en accidentes de tránsito, de trabajo o problemas neurológicos y congénitos. El diseño de este rehabilitador pasivo involucra utilizar un software adecuado tanto para la simulación del prototipo como para el sistema de control que se tendrá a partir de procesos fisioterapéuticos ya establecidos, estos procesos permitirán la rehabilitación de los dedos de mano. Se hace uso de nuevas tecnologías para la construcción y control del dispositivo tomando en cuenta las condiciones ambientales y hospitalarias, de esta manera la persona afectada pueda volver a desempeñar sus funciones cotidianas mejorando su calidad de vida. \r\n\r\nImplementación de un sistema de control... (PDF Download Available). Available from: https://www.researchgate.net/publication/321589503_Implementacion_de_un_sistema_de_control_para_rehabilitador_pasivo_de_dedos_de_la_mano [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/321589503_Implementacion_de_un_sistema_de_control_para_rehabilitador_pasivo_de_dedos_de_la_mano
87	Reflexión sobre el trastorno por déficit de atención/hiperactividad en niños: Perspectiva psicopedagógica, neuropsicológica y neurofisiológica	Congreso Internacional Psicología en la Educación. 2017	G. Narváez-Olmedo, S. C. Flores-Armas, A. C. Umaquinga-Criollo, D. H. Peluffo-Ordóñez,\r\nP. A. Castro-Cabrera.	Attention-deficit/hyperactivity    disorder    (ADHD)    is    primarily    characterized    by \r\ndistraction,  motor  restlessness,  and  impulsive  behaviors.  Its  diagnosis  is  typically  in \r\nchildren, however, in most cases this disorder may persist into adulthood and may cause \r\nvarious negative impacts on the social and emotional dynamics of individuals. Since it is \r\ntransversal  issue,  ADHD  in  children  has  been  approached  from  different  fields  of \r\nneuroscience, psychology and pedagogy. On one hand, some experts claim that there is a \r\nlink between the symptoms of ADHD with dysfunction of certain areas of the brain. On \r\nthe other hand, other specialists define ADHD as a behavioral syndrome. This conceptual \r\ndichotomy has been the subject of scientific controversy during the last decade. Another \r\nequally   controversial   aspect   of   ADHD   is   its   diagnosis,   because   it   includes   a \r\ncomprehensive analysis of the child, which requires the training of parents and teachers \r\nto  identify  symptoms,  as  well  as  the  presence  of  specialists  with  several  hours  of \r\ndedication. In practice, having a harmonic criterion between the three parts is not entirely \r\nfeasible. Within this multidisciplinary and controversial scenario, this article presents a \r\nreflexive  and  critical  dissertation –by  way  of  essay-on  the  definition,  diagnosis  and \r\ntreatment  of  ADHD  in  children  from  a  psychopedagogical,  neuropsychological  and \r\nneurophysiological perspective.	2017	1	http://diegopeluffo.com/publicaciones/2017_TDAH.pdf
88	Herramientas de análisis de grandes volúmenes de datos para la toma de decisiones empresariales y fidelización de los clientes	Revista de Estrategias del Desarrollo Empresarial Junio 2017 Vol.3 No.8 31-39	D. H. Peluffo-Ordóñez,Umaquinga, Ana & Tatiana, Saltos, Diego. (2017).	Resumen El crecimiento acelerado de la competencia entre las empresas a nivel global es innegable. Los nuevos retos para generar valor, descubrir tendencias y preferencias de consumo de clientes exigen a las empresas contar con herramientas tecnológicas de mayor alcance y eficiencia que permitan ser apoyo en la toma de decisiones en tiempo real o en el menor tiempo posible con el fin de crear ventaja competitiva y mantenerse en el mercado. Herramientas tecnológicas como Big data, Data mining entre otras, pretenden obtener nuevo conocimiento, patrones, predicciones para una mejor comprensión y precisión de las necesidades del cliente, que no sería posible con el uso de herramientas convencionales. De ahí el trabajo en equipo del área tecnológica y del negocio requiere de este conocimiento de valor para la definición de estrategias encaminadas a capitalizar dicho conocimiento originado de manera interna y externa especialmente de las redes sociales. El presente artículo es de tipo descriptivo, exploratorio, y documental, se realiza un análisis de Big data y minería de datos a nivel empresarial, sus tópicos de uso en la toma de decisiones y búsqueda de la fidelización de sus clientes, así como sus aspectos de valor y retos. En consecuencia, los resultados evidencian la relación favorable y eficiente de la aplicación de estas tecnologías en la toma de decisiones empresariales, por lo que, surge la necesidad de un mayor número de investigaciones de este tipo. Abstract The accelerated growth of competition among companies globally is undeniable. The new challenges to generate value, discover trends and preferences of customers demand companies to have technological tools of greater reach and efficiency that allow to be support in the decision making in real time or in the shortest possible time in order to create competitive advantage and stay in the market. Technological tools like Data mining, Big data, among others, aim to obtain new knowledge, patterns, predictions for a better understanding and precision of costumer needs, which would not be possible with the use of conventional tools. Hence teamwork in the area of technology and business requires this knowledge of value for the definition of strategies aimed at capitalizing on this knowledge originated in an internal and external way especially of social networks. The present article is descriptive, exploratory, and documentary, perform an analysis of the technological tools used at the business level and topics of use in the decision making and search of the loyalty of its clients, as well as its value aspects and challenges. Consequently, the results show the favorable and efficient relationship of the application of these technologies in business decisionmaking, therefore, the need arises for a greater number of future research of this type. \r\n\r\nHerramientas de análisis de grandes... (PDF Download Available). Available from: https://www.researchgate.net/publication/322302894_Herramientas_de_analisis_de_grandes_volumenes_de_datos_para_la_toma_de_decisiones_empresariales_y_fidelizacion_de_los_clientes [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/322302894_Herramientas_de_analisis_de_grandes_volumenes_de_datos_para_la_toma_de_decisiones_empresariales_y_fidelizacion_de_los_clientes
89	Morfologías visuales de representación de datos como aumento de capacidades analíticas humanas: Una revisión de literatura	Conference: Conference: I Congreso Internacional de Ingenierías 2017, At Universidad Técnica del Norte , Ibarra ,Ecuador	D. H. Peluffo-Ordóñez,Andrés Javier Anaya Isaza1, Ana Cristina Umaquinga Criollo, Gabriela Narváez Olmedo, Paúl David Rosero Montalvo	Visual representation is an approach to extract knowledge, which enables users to perceive the information within a context of Big Data. To involve the human perception into the data analysis, an inuitive data representation is needed. Consequently, any user will be able to make more adequate decisions. Indeed, the enhancement of human-computer interactions is based o the use of data analysis techniques while computational broad is optimized. In this work, a descriptive, exploratory and documental methodology is presented aimed at highlighting the benefit of involving the human skills within the process of automatic decisions making.	2017	1	https://issuu.com/utnuniversity/docs/ebook_aportes_de_la_ingenieria_2017/374
90	AUDITORÍA DE SEGURIDAD INFORMÁTICA SIGUIENDO LA METODOLOGÍA OSSTMMV3: CASO DE ESTUDIO	QUINTO CONGRESO ECUATORIANO DE TECNOLOGÍAS DE LA INFORMACIÓN Y COMUNICACIÓN - TIC.EC 2017, Edition: Especial, Publisher: Universidad de Cuenca, Editors: Universidad de Cuenca, pp.307-319	D. H. Peluffo-Ordóñez, Cristian Bracho-Ortega, Fabián Cuzme-Rodríguez, Carlos Pupiales-Yepez, Luis Suárez-Zambrano, César Moreira-Zambrano	This article explains the methodology followed in computing auditing in terms of security where OSSTMM version 3 was taken as reference methodology and implemented in GAD-Mira. The current methodology allows to measure the security aspects of five different channels such as human, physical, wireless communications, telecommunications, and networking. At the same time, it includes porosity (OpSec), controls, and limitations as three important measures in each channel which allow to calculate and get the numerical values that explain the importance and influence of each item in the computing audit. Additionally, results obtained after the application of the described methodology allowed to understand deficiencies or excesses in terms of security controls that exist in a company or organization in each channel, being an important point to analyze the internal vulnerabilities that need to be solved. \r\n\r\nAUDITORÍA DE SEGURIDAD INFORMÁTICA... (PDF Download Available). Available from: https://www.researchgate.net/publication/321532783_AUDITORIA_DE_SEGURIDAD_INFORMATICA_SIGUIENDO_LA_METODOLOGIA_OSSTMMV3_CASO_DE_ESTUDIO [accessed Jun 03 2018].	2017	1	https://www.researchgate.net/publication/321532783_AUDITORIA_DE_SEGURIDAD_INFORMATICA_SIGUIENDO_LA_METODOLOGIA_OSSTMMV3_CASO_DE_ESTUDIO
91	On the Relationship Between Dimensionality Reduction and Spectral Clustering from a Kernel Viewpoint	13th International Conference on Distributed Computing and Artificial Intelligence, Advances in Intelligent Systems and Computing. DCAI 2016	D. H. Peluffo-Ordóñez, M. A. Becerra, A. E. Castro-Ospina, X. Blanco-Valencia, J. C. Alvarado-Pérez, R. Therón, A. Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	1	http://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
92	Interactive visualization methodology of high-dimensional data with a color-based model for dimensionality reduction	2016 XXI Symposium on Signal Processing, Images and Artificial Vision (STSIVA).	D. F. Peña-ünigarro, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo, \r\nO. R. Oña-Rocha, A. A. Isaza, J. C. Alvarado-Perez, R. Theron	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	1	https://ieeexplore.ieee.org/document/7743318/
94	Human-sitting-pose detection using data classification and dimensionality reduction	2016 IEEE Ecuador Technical Chapters Meeting (ETCM).	S. Nuñez-Godoy, V. Alvear-Puertas, S. Realpe-Godoy, E. Pujota-Cuascota, H. Farinango-Endara, \r\nI. Navarrete-Insuasti, F. Vaca-Chapi, P. Rosero-Montalvo, D. H. Peluffo-Ordóñez	The research area of sitting-pose analysis allows for preventing a range of physical health problems mainly physical. Despite that different systems have been proposed for sitting-pose detection, some open issues are still to be dealt with, such as: Cost, computational load, accuracy, portability, and among others. In this work, we present an alternative approach based on a sensor network to acquire the position-related variables and machine learning techniques, namely dimensionality reduction (DR) and classification. Since the information acquired by sensors is high-dimensional and therefore it might not be saved into embedded system memory, a DR stage based on principal component analysis (PCA) is performed. Subsequently, the automatic posed detection is carried out by the k-nearest neighbors (KNN) classifier. As a result, regarding using the whole data set, the computational cost is decreased by 33 % as well as the data reading is reduced by 10 ms. Then, sitting-pose detection task takes 26 ms, and reaches 75% of accuracy in a 4-trial experiment.	2016	1	http://ieeexplore.ieee.org/document/7750822/
95	Comparison Between Unipolar And Bipolar Electrograms For Detecting Rotor Tip From 2D Fibrillation Model Using Image Fusion. A Simulation Study.	Latin American Conference on Computational Intelligence 2016 (IEEE LA-CCI).	C. A. Duarte-Salazar, A. Orozco-Duque, A. Tobón, D. H. Peluffo-Ordóñez, J. A. Guzmán-Luna, \r\nM. A. Becerra.	The atrial fibrillation (AF) is the most common arrhythmia, which generates the highest costs on clinical systems. Theory of the rotor is one of the most recent approaches to explain the mechanisms that maintain AF. The most promising treatment is the ablation, whose success depends on rotor tip location. In a previous research, the approximate entropy (ApEn) calculated on simulated electrograms from atrial models has shown high capability for detecting the rotor tip, however it needed a human final adjustment. In addition, this technique involves a high computational cost, which is a problem for its effective application. In this study, multiple features maps were generated and different combinations of them were conducted using wavelet image fusion. The rotor tip location when using image fusion, was similar to the results achieved with the methodology based on ApEn, however, our methodology did not require any manual adjustment, and the computational cost was reduced to 85%. This study includes a comparative analysis between unipolar and bipolar electrograms obtained from a simulated 2D model of a human atrial tissue under chronic AF.	2016	1	http://ieeexplore.ieee.org/document/7885712/
96	Comparison Between Unipolar And Bipolar Electrograms For Detecting Rotor Tip From 2D Fibrillation Model Using Image Fusion. A Simulation Study.	Latin American Conference on Computational Intelligence 2016 (IEEE LA-CCI).	C. A. Duarte-Salazar, A. Orozco-Duque, A. Tobón, D. H. Peluffo-Ordóñez, J. A. Guzmán-Luna, \r\nM. A. Becerra.	The atrial fibrillation (AF) is the most common arrhythmia, which generates the highest costs on clinical systems. Theory of the rotor is one of the most recent approaches to explain the mechanisms that maintain AF. The most promising treatment is the ablation, whose success depends on rotor tip location. In a previous research, the approximate entropy (ApEn) calculated on simulated electrograms from atrial models has shown high capability for detecting the rotor tip, however it needed a human final adjustment. In addition, this technique involves a high computational cost, which is a problem for its effective application. In this study, multiple features maps were generated and different combinations of them were conducted using wavelet image fusion. The rotor tip location when using image fusion, was similar to the results achieved with the methodology based on ApEn, however, our methodology did not require any manual adjustment, and the computational cost was reduced to 85%. This study includes a comparative analysis between unipolar and bipolar electrograms obtained from a simulated 2D model of a human atrial tissue under chronic AF.	2016	1	http://ieeexplore.ieee.org/document/7885712/
97	Dimensionality reduction for interactive data visualization via a Geo-Desic approach.	Latin American Conference on Computational Intelligence 2016 (IEEE LA-CCI).	J. A. Salazar-Castro, D. Peña-Unigarro, D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo,\r\nH. M. Domínguez-Limaico, J. C. Alvarado-Pérez, R. Therón,	This work presents a dimensionality reduction (DR) framework that enables users to perform either the selection or mixture of DR methods by means of an interactive model, here named Geo-Desic approach. Such a model consists of linear combination of kernel-based representations of DR methods, wherein the corresponding coefficients are related to coordinated latitude and longitude inside of the world map. By incorporating the Geo-Desic approach within an interface, the combination may be made easily and intuitively by users -even non-expert ones- fulfilling their criteria and needs, by just picking up points from the map. Experimental results demonstrates the usability and ability of DR methods representation of proposed approach.	2016	1	https://ieeexplore.ieee.org/document/7885740/
98	Interactive data visualization using dimensionality reduction and similarity-based representations.	XXI IberoAmerican Congress on Pattern Recognition 2016 (CIARP).	P. D. Rosero-Montalvo, P. Diaz, J. A. Salazar-Castro, D. F. Peña-Unigarro, A. J. Anaya-Isaza,\r\nJ. C. Alvarado-Pérez, R. Therón, D. H. Peluffo-Ordóñez.	This work presents a new interactive data visualization approach based on mixture of the outcomes of dimensionality reduction (DR) methods. Such a mixture is a weighted sum, whose weighting factors are defined by the user through a visual and intuitive interface. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to be drawn on the scatter plot. Our visualization approach enables the user to interactively combine DR methods while provided information about the structure of original data, making then the selection of a DR scheme more intuitive.	2016	1	http://link.springer.com/chapter/10.1007/978-3-319-52277-7_41
99	Multi-labeler classification using kernel representations and mixture of classifiers .	XXI IberoAmerican Congress on Pattern Recognition 2016 (CIARP).	D. E. Imbajoa-R, I. Gustin, M. Bolaños-Ledezma, A. F. Arciniegas-M, F. A. Guasmayán-G, \r\nM. J. Bravo-Montenegro, A. E. Castro-Ospina, D. H. Peluffo-Ordóñez.	This work introduces a multi-labeler kernel novel approach for data classification learning from multiple labelers. The learning process is done by training support-vector machine classifiers using the set of labelers (one labeler per classifier). The objective functions representing the boundary decision of each classifier are mixed by means of a linear combination. Followed from a variable relevance, the weighting factors are calculated regarding kernel matrices representing each labeler. To do so, a so-called supervised kernel function is also introduced, which is used to construct kernel matrices. Our multi-labeler method reaches very good results being a suitable alternative to conventional approaches.	2016	1	http://link.springer.com/chapter/10.1007/978-3-319-52277-7_42
100	Data Fusion from Multiple Stations for Estimation of PM2.5 in Specific Geographical Location.	XXI IberoAmerican Congress on Pattern Recognition 2016 (CIARP).	M. A. Becerra, M. Bedoya-Sánchez, J. García-Carvajal, J. A. Guzmán-Luna, D. H. Peluffo-Ordóñez,\r\nC. Tobón.	Nowadays, an important decrease in the quality of the air has been observed, due to the presence of contamination levels that can change the natural composition of the air. This fact represents a problem not only for the environment, but also for the public health. Consequently, this paper presents a comparison among approaches based on Adaptive Neural Fuzzy Inference System (ANFIS) and Support Vector Regression (SVR) for the estimation level of PM2.5 (Particle Material 2.5) in specific geographic locations based on nearby stations. The systems were validated using an environmental database that belongs to air quality network of Valle de Aburrá (AMVA) of Medellin Colombia, which has the registration of 5 meteorological variables and 2 pollutants that are from 3 nearby measurement stations. Therefore, this project analyses the relevance of the characteristics obtained in every single station to estimate the levels of PM2.5 in the target station, using four different selectors based on Rough Set Feature Selection (RSFS) algorithms. Additionally, five systems to estimate the PM2.5 were compared: three based on ANFIS, and two based on SVR to obtain an aim and an efficient mechanism to estimate the levels of PM2.5 in specific geographic locations fusing data obtained from the near monitoring stations.	2016	1	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_52
101	Arquitectura, servicios y aplicaciones de Business Intelligence: Revisión de literatura	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	P. Rosero, E. Rosero, L. Beltran, D. Peluffo, C. Pupiales	Business Intelligence (BI) es el conjunto de estrategias y herramientas para analizar gran cantidad de volúmenes de datos con el fin de encontrar patrones o tendencias de consumo de las personas y establecer estrategias de negocio, para lograr este objetivo es necesario contar con servicios y aplicaciones como RealTime BI, Social BI, Cloud BI, BI 3.0, Business Analitics y Mobile BI. Todo el proceso de BI es soportado por diferentes análisis que implementan algoritmos de machine learning en grandes volúmenes y diferentes fuentes de datos, considerado como Big Data. En este trabajo se hace relación a las funcionalidades y los requerimientos necesarios de BI desde un concepto inicial hasta conceptos específicos y herramientas para su implementación. \r\n\r\n(PDF) ARQUITECTURA, SERVICIOS Y APLICACIONES DE Business Intelligence: Revisión de literatura. Available from: https://www.researchgate.net/publication/313280378_ARQUITECTURA_SERVICIOS_Y_APLICACIONES_DE_Business_Intelligence_Revision_de_literatura [accessed Jun 03 2018].	2016	1	https://www.researchgate.net/publication/313280378_ARQUITECTURA_SERVICIOS_Y_APLICACIONES_DE_Business_Intelligence_Revision_de_literatura
102	A multi-class extension for case-based reasoning applied to medical problems: A first approach.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	D. Viveros-Melo, M. Ortega-Adarme, X. Valencia, A. E. Castro-Ospina, S. Murillo-Rendón, D. H. Peluffo-Ordóñez.	Case-based reasoning (CBR) is a process used for computer processing that tries to mimic the behavior of a human expert in making decisions regarding a subject and learn from the experience \r\nof past cases. CBR has demonstrated to be appropriate for working with unstructured domains data\r\nor difficult knowledge acquisition situations, such as medical diagnosis, where it is possible to  identify  diseases  such  as: cancer  diagnosis,  epilepsy  prediction  and  appendicitis  diagnosis. \r\nSome of the trends that may be developed for CBR in the health science are oriented to reduce \r\nthe  number  of  features  in  highly dimensional  data. An  important  contribution  may  be  the estimation  of  probabilities  of  belonging  to  each  class  for  new  cases. In  this  paper,  in  order  to \r\nadequately  represent  the  database  and  to avoid  the  inconveniences  caused  by  the  high \r\ndimensionality,  noise  and  redundancy,  a  number  of  algorithms  are  used  in  the  preprocessing \r\nstage  for  performing  both  variable  selection  and  dimension  reduction  procedures. Also, a \r\ncomparison  of  the  performance  of some representative multi-class classifiers  is  carried  out  to \r\nidentify  the  most effective  one to  include within  a  CBR  scheme. Particularly,  four  classification \r\ntechniques and  two reduction  techniques are  employed to make a comparative study  of multi-\r\nclass classifiers on CBR.	2016	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/141/148
103	Internet de las Cosas y Visión Artificial, Funcionamiento y Aplicaciones: Revisión de Literatura.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	V. Alvear-Puertas, I. E. Navarrete-Insuasti, P. Rosero-Montalvo, J. Noguera, F. Cuzme, D. H. Peluffo-Ordóñez.	Internet of Things (or also known as IoT) is one of the technologies most named today because \r\nof the ability it envisages to connect all kinds of devices to the Internet. If to the potentialities of \r\nIoT we add another technology of high impact as It is the Artificial Vision we have a wide field of \r\ninnovative  applications,  where  the  processing  of  images  and  video in  real  time  allow  the \r\nvisualization of large amounts of data on the Internet. The main applications developed with IoT \r\nand Artificial Vision can be implemented in education, medicine, intelligent buildings, surveillance \r\nsystems of people and vehicles, among others.This type of applications improves the quality of \r\nlife  of  users,  however,  for  their  development an  infrastructure  is  required that  allows  the \r\nconvergence of different protocols and devices, but in a special way that can handle the different \r\nphases  of  the  acquisition  of  images. \r\nIn  this  work,  a  review  of  the  beginnings,  concepts, technologies and applications related to the Artificial Vision with the Internet of Things has been carried out to be able to understand in a precise way the impact of its application in daily life.	2016	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/121/127
116	A Low Cost Portable Prototype for Support of Bio-Feedback Therapies in Psychophysiological Disorders	Jornadas Internacionales FICA 2016.	J. A. Salazar-Castro, D. H. Peluffo-Ordóñez, S. Cano, A. Ruano, E. J. Revelo-Fuelagan, J. F. Salazar-Castro, H. Campaña, C. R. Ramírez-Saavedra.	This work project is about the design of a low-cost biofeedback devices. Device desing involves mainly two building blocks: The first one is concerned on the signal acquisition and analog filtering. Meanwhile, the second one is the estimation of physiological variable indicators and visual feedback implemented in a circuit platform. The goal is reaching great usability and portability while involving low design costs.	2016	1	https://www.researchgate.net/project/A-Low-Cost-Portable-Prototype-for-Support-of-Bio-Feedback-Therapies-in-Psychophysiological-Disorders
104	Cardiac arrhythmia identification system based on non-supervised machine learning methods.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	M. Moreno-Revelo, S. Patascoy-Botina, A. Pantoja-Bucheli, J. Revelo-Fuelagan, J. Rodríguez-Sotelo, S. Murillo-Rendón, D. H. Peluffo-Ordóñez.	An  arrhythmia  is  a  pathology  that  consists  on  altering  the  heartbeat.  Although,  the  12-\r\nlead electrocardiogram  allows  evaluation  of  the  electrical  behavior  from  heart  to  determine  certain pathologies,   there   are   some   arrhythmias   that   are   difficult   to   detect \r\nwith   this   type   of electrocardiography.  In  this  sense,  it  is  necessary  the  use  of  the  Holter  monitor  because  it facilitates the records of the heart electrical activity for long periods of time, it is usually 24 up to 48  hours.  Due  to  the  extension  of  the  records  provided  by  the  monitor,  it  is  common  to  use computational systems to evaluate diagnostic and morphological features of the beats in order to determine  if  there  is  any  type  of  abnormality. These  computational  systems  can  be  based  on supervised  or  unsupervised  pattern  recognition  techniques,  however  considering  that  the  first option requires a visual inspection about the large number of beats present in a Holter record, it is an arduous task, as well as it involves monetary costs. Consequently, throug\r\nhout this paper we present  the  design  of  a  complete  system  for  the  identification  of  arrhythmias  in  Holter  records using unsupervised pattern recognition techniques. The proposed system involves stages of pre-processing of the signal, segmentation and characterization of beats, as well as feature selection and clustering. In this case, the technique k-means is used.These steps are applied within the framework  of  a  segment-based  methodology  that  improves  the  detection  of  minority  classes. Additionally,  initialization  criteria  are  considered,  which  allow  to  enhance  quality  measures, especially  sensitivity.  As  a  result,  it  is  determined  that  using  k-means  with  the  max-\r\nmin initialization  and  a  number  of  groups  equal  to  12,  it  is  possible  to  obtain  the  best  resu\r\nlts,  with values of: 99.36%, 91.31% and 99.16% for accuracy, sensitivity and specificity, respectively.	2016	1	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/125/131
105	Estudio comparativo de NSGA-II y PSO como métodos de optimización multiobjetivo en problemas con frente óptimo de Pareto convexo.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	D. F. Dorado-Sevilla, M. J. Bravo-Montenegro, F. A. Guasmayán-G, D. H. Peluffo-Ordóñez.	En   este   estudio,   dos   algoritmos   representativos   de   la computación  evolutiva  se  aplican  a  un  problema  de  prueba multiobjetivo   simple   con   un   conjunto óptimo de   Pareto convexo  con  el  fin  de  identificar cuál de  los  dos  es más eficiente   encontrando   desde   el   espacio   de   búsqueda   un conjunto óptimo de  soluciones.  Se  describe  como  funcionan estos métodos inspirados en comportamientos de la naturaleza y  como  estos  intentan  encontrar  una  conjunto  Pareto óptimo. Los   resultados   se   analizan   utilizando   las   métricas   de rendimiento Distancia Generacional y Razón de Error.	2016	1	http://diegopeluffo.com/publicaciones/2016_INCISCOS_%20NSGA-II%20y%20PSO.pdf
106	Multi-Labeller classification Method based on Mixture of Classifiers and Genetic Algorithm Optimization.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	A. F. Arciniegas-M, D. E. Imbajoa-R, I. D. Gustin, M. Bolaños, F. Guasmayán-G, M. J. Bravo, D. H. Peluffo-Ordóñez.	This work presents a new method proposal applied to  Multi-Labelers scenarios.  This  is  a  situation  where  labelling individuals in a set of data based on certain characteristics in the process of determining labels to individuals in a set of data based on certain characteristics. Our  approach consists in  processing a Support  Vector  Machine  classifier  to  each labelers substantiated on his answers. We formulate a genetic algorithm optimization to obtain  a  set  of  weights  according  to  their  opinion,  in  order  to penalize   each   panelist.   Finally,   their  resulting   mappings  are \r\nmixed, and a final classifier is generated, showing to be better than majority  vote.  For  experiments,  the  well-known  Iris  database  is handled,  with  multiple  simulated  artificial  labels.  The  proposed \r\nmethod reaches very good results compared to conventional multi-labeler methods,  able  to  assess  the  concordance  among  panelists considering the structure data.	2016	1	https://pdfs.semanticscholar.org/a716/663d86e86e81b42de0634cff004f13b3b0be.pdf
108	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	A. J. Anaya-Isaza, D. H. Peluffo-Ordóñez, J. C. Alvarado-Pérez, J. Ivan-Rios, J. A. Castro-Silva, P. D. Rosero-Montalvo, D. F. Peña-Unigarro, J. A. Salazar-Castro, A. C. Umaquinga-Criollo.	Este trabajo presenta un estudio comparativo con métodos de reducción de la dimensión lineal, tales como: Análisis de Componentes Principales & Análisis Discriminante Lineal. El estudio pretende determinar, bajo criterios de objetividad, cuál de estas técnicas obtiene el mejor resultado de separabilidad entre clases. Para la validación experimental se utilizan dos bases de datos, del repositorio científico (UC Irvine Machine Learning Repository), para dar tratamiento a los atributos del data-set en función de confirmar visualmente la calidad de los resultados obtenidos. Las inmersiones obtenidas son analizadas, para realizar una comparación de resultados del embedimiento representados con RNX(K), que permite evaluar el área bajo la curva, del cual asume una mejor representación en una topología global o local que posteriormente genera los gráficos de visualización en un espacio de menor dimensión, para observar la separabilidad entre clases conservando la estructura global de los datos. Palabras clave— Análisis de componentes principales, Análisis discriminante lineal, Aprendizaje de máquina, Clasificación lineal, Clasificación supervisada, Métodos de reducción de la dimensión. Abstract— This paper presents a comparative study with methods of reducing the linear dimension, such as Principal Component Analysis & linear discriminant analysis. The study aims to determine, based on criteria of objectivity, which of these techniques get the best result of separability between classes. For experimental validation two databases, scientific repository (UC Irvine Machine Learning Repository) are used to provide treatment to the attributes of the data-set according to visually confirm the quality of the results. The dives obtained are analyzed, for comparison of results embedimiento represented with RNX (K), which evaluates the area under the curve, which assumes better representation in a local global topology or subsequently generates graphics display a space of smaller dimension, to observe the class separability preserving the overall structure of the data. \r\n\r\nEstudio comparativo de métodos... (PDF Download Available). Available from: https://www.researchgate.net/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA [accessed Jun 03 2018].	2016	1	https://www.researchgate.net/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA
109	Plan de continuidad de negocio aplicado al centro de datos del proyecto hidroeléctrico Coca Codo Sinclair.	Congreso Internacional de Innovación y Transferencia de Conocimiento 2016 (CIITC).	D. E. Imbaquingo-Esparza, C. P. Guevara-Vega, D. H. Peluffo-Ordóñez, J. F. Cevallos-Amaguay.	This paper presents the development of a Business Continuity Plan (BCP) to be applied t\r\no the Data Center Audit of the project “Hidroeléctrico Coca CodoSinclair”.  The aim of the proposed \r\nBCP is to guarantee the continuity of services and/or technological processes by ensuring the \r\nprotection of project resources and the primary operations. The proposed BCP is based on the \r\nnorm  ISO  22301;  2012,  Society  Security,  Management  System  of  Business  Continuity  and \r\nStandard BCLS 2000 of DRI International, which are governed by principles for appropriate \r\ndecision making when occurring a natural disaster or some unforeseen. Methodologically, the \r\ndevelopment of our BCP begins by performing a situational analysis of the organization, along \r\nwith  an  analysis  regarding  information  security  data  center.  Subsequently,  a  leadership \r\nevaluation criteria evaluation is done, considering criteria such as: Planning, support, operation \r\nand  strategic  planning.  Then,  the  natural  hazards  and  threats  are  identified.  Based  on  the \r\nanalysis  and  assessment  outcomes,  business  continuity  model  arises  accordingly  to  the  ISO \r\nstandard 22301. As well, given a prior knowledge of the context of the Association, planning, \r\nleadership,  support,  policies,  strategy  and  continuity  procedures  are  established.  Since  the \r\nimplemented design continuity plan covers all aspects considered in norm ISO 22301 as well \r\nas  the  results  of  analyzes  of  the  Association,  it can  be  considered  as  a  versatile  and  feasible \r\nimplementation model.	2016	1	http://diegopeluffo.com/publicaciones/2016_CIITC_PlanDeContinuidadCocaCodoSinclair.pdf
