110	Mejoramiento de las capacidades tecnológicas en los sectores rurales de la provincia de Imbabura.	Congreso Internacional de Innovación y Transferencia de Conocimiento 2016 (CIITC).	S. Flores-Armas, P. D. Rosero-Montalvo, E. Maya-Olalla, D. H. Peluffo-Ordóñez.	La  Universidad  Técnica  del  Norte  a  través  de  la  carrera  de  ingeniería  en \r\nElectrónica y Redes de Comunicación, fortaleciendo al proceso de vinculación con \r\nla sociedad, crea un proyecto que beneficia a la población de las zonas rurales de \r\nla  provincia  de  Imbabura,  y  que,  particularmente,  tiene  el  objetivo  de  disminuir  la \r\nbrecha  digital  en  colegios,  brindado  acceso  a  las  tecnologías  de  información  y \r\ncomunicación.   Para   poner   en   acción   el   proyecto   de   mejoramiento   de   las \r\ncapacidades tecnológicas, se consideró como población de interés a los individuos \r\nmayores de 12 años, hombres y mujeres, de diferentes niveles sociales, culturales \r\ny  étnicos.  Metodológicamente,  se  plantea  una  planificación  de  programas  de \r\ncapacitación  en  base  a  un  diagnóstico  de  las  necesidades,  que  posteriormente \r\nfueron  evaluados  con  el  propósito  de  reducir  las  deficiencias  tecnológicas  de  las \r\npersonas y así mejorar la calidad de vida con miras a reducir el analfabetismo digital. \r\nDentro  de  la  ejecución  del  proyecto,  se  toma  como  estrategia  los  Infocentros \r\nComunitarios y propios laboratorios de computación de las instituciones educativas, \r\nlos mismos que son punto de referencia para  llegar  a las comunidades,  logrando \r\ncapacitar   en   herramientas   de   ofimática   básica,   asistencias   de   redes   de \r\ncomunicación, Internet,  mantenimiento  de  computadoras,  y  administración  de \r\npáginas web. Posteriormente a la capacitación, claramente se pudo observar que, \r\nen los sectores de acción, satisficieron sus expectativas, adquirieron habilidades y \r\ndestrezas  de  temas  tecnológicos.  En  este  artículo  se  presenta  los  aspectos \r\nmetodológicos y resultados más importantes del proyecto.	2016	1	http://diegopeluffo.com/publicaciones/2016_CIITC_MejoramientoCapacidadesTecnologicas.pdf
111	Aplicación de Técnicas de Fuerza Bruta con Diccionario de Datos, para vulnerar servicios con métodos de autenticación simple “Contraseñas”, pruebas de concepto con software libre y su remediación.	Congreso Ecuatoriano de Tecnologías de la Información y Comunicación 2016 (TIC.EC).	H. M. Domínguez-Limaico, E. Maya-Olalla, D. H. Peluffo-Ordóñez, C. M. Crisanto-Ñ.	This paper illustrates the increased security risks in recent years of attacks on authentication controls, specifically passwords. Methods and techniques for violating such controls using more and more brute force attack approaches, including data dictionaries. Furthermore, the manuscript presents a proof concept using the free distribution of Linux "Kali Linux" and the penetration tool "Metaexploits Framework" to mitigate attacks; to finally present a more detailed approach for the secure management of passwords, an important issue in times of crisis.\r\nKeywords: Security informatics, controls, passwords, brute force, data dictionary, penetration, attacks.	2016	1	https://publicaciones.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1079
