113	Diseño de telefonía IP a través del Cloud Computing bajo una plataforma de software libre OpenNebula .	Congreso Ecuatoriano de Tecnologías de la Información y Comunicación 2016 (TIC.EC).	G. C. Ruiz-García, E. Maya-Olalla, C. A. Vásquez, H. M. Domínguez-Limaico, D. H. Peluffo-Ordóñez.	The present study implicates a new solution of telecommunication for IP telephony service, which is based on cloud computing, providing an option for communications at the “Universidad Técnica del Norte”. The analysis was performed, based on the IEEE 29148 standard for selecting a virtualization platform and IP telephony software. Subsequently, the IP telephony was designed through cloud computing. In the IP telephony design, the dimensioning of IP telephony was developed through the cloud, considering the instance capacity, bandwidth, traffic flow and the number of trunks. For the analysis of these parameters the updated information of the University’s IP telephony was used. Thereafter, the cloud platform was configured. Following, the service performance was tested as to observe the behavior after the incorporation of this infrastructure.	2016	1	https://publicaciones.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1084
114	Propuesta de análisis visual de datos en Big Data usando reducción de dimensión interactiva .	Jornadas Internacionales FICA 2016.	A. C. Umaquinga-Criollo, D. H. Peluffo-Ordóñez, M. V. Cabrera-Álvarez, J. C. Alvarado-Pérez, A. J. Anaya-Isaza.	Today, the volumen of available data is experiencing an exponential growing, introducing an emergent are so-called Big Data. Along with the data growing, the demand of tools, techniques and devices to store, transmit and process high-dimensional data (HD) is increased. Most available methodologies to process HD output abstract outcomes and user is not involved in the selection or parameter tuning processes of data analysis techniques. In this work, we propose a visual analysis methodology following principles of interactivity and controlability. Doing so, users (even non-expert ones) can inuitively select a dimensionality reduction method to generate inteligible representations for human beings. Palabras Clave—Big Data, reducción de dimensión, análisis visual  \r\n\r\nPropuesta de análisis visual de datos en... (PDF Download Available). Available from: https://www.researchgate.net/publication/311457198_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva [accessed Jun 03 2018].	2016	1	https://www.researchgate.net/publication/311457198_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva
118	Sistema de Riego Basado En La Internet De Las Cosas (IoT).	Jornadas Internacionales FICA 2016.	A. J. Anaya-Isaza, D. H. Peluffo-Ordóñez, J. Ivan-Rios, J. A. Castro-Silva, D. A. Carvajal-Ruiz, L. H. Espinoza-Llanos.	The application of technology in all the society’s fields has increased since the 90’s decade, and in the agriculture has brought many benefits enabling increase quality and productivity in   crops.   The   inefficiency   and   ineffectiveness   of   traditional methods  of  control  and  monitoring  used  in  agriculture,  produce extra  time  and  cost  loss  for  farmers.  This  paper  describes  the design,  elaboration  and  implementation  of  an  irrigation  system using open hardware and open software, Wireless Sensor Network (WSN),  actuators,  Wireless  Communication  Devices  and ICT \r\ntools, to create an environment where Internet of Things (IoT) and precision  agriculture  give  users  better  control  of  irrigation  over crops based on evapotranspiration.	2016	1	https://www.researchgate.net/profile/Diego_Peluffo/publication/315793360_Sistema_de_Riego_Basado_En_La_Internet_De_Las_Cosas_IoT/links/58f4dd6ba6fdcc11e569fa8a/Sistema-de-Riego-Basado-En-La-Internet-De-Las-Cosas-IoT.pdf
119	Prototipo de Arma de Fuego Para Uso Controlado En la Sociedad Como Alternativa Segura.	Jornadas Internacionales FICA 2016.	R. O. Peña-Pérez, J. C. Alvarado-Pérez, P. A. Briceño-Rivera, L. E. Arteaga-Noguera, M. V. Cabrera-Álvarez, D. H. Peluffo-Ordóñez.	This positioning system, as a help in the fight agains the crime is based  in  a  easy  use  and  low  cost  fabrication  technology,  in  an encryptation  procedure  by  cicles  configurable  by  the  user  using techniques  as  learning  machine  and  data  mining.  This  device  will give  the  chance  to  know  who  are  the  pólice  officers  assigned  in every  sector  and  will  guarantee  in  a  100%  the  supervision  of  the staff  who  Works  in  an  institution  dedicated  to  the  security  of  the \r\ncitizens.  The  plan  establish  the  creation  of  two  operational  centers that  will  work  ,  one  in  every  block  and  other  in  the  monitoring facilities, supported in information processing techniques to survey the imposed work actions.It  is  told  that  an  strict  control  process  of  materials  and  human resources  with   the help   of   the   technology   ,  which   are   global positioning  system,  data  analysis,  and  biometrical  systems  will result  in  control  and  security  in  real  time,  24  hours  a  day  of  the resources  and  staff  that  use  it.  With  this  experimentation  model  a new knowledge wi\r\nll be obtained available to improve the process.	2016	1	http://diegopeluffo.com/publicaciones/2016_JornadasFica_prototipo_pistola.pdf
120	Solución del problema de ruteo de vehículos dependientes del tiempo, usando un algoritmo genético híbrido con gerenciamiento de población.	Jornadas Internacionales FICA 2016.	F. A. Guasmayán-G, E. M. Toro-Ocampo, M.J. Bravo-Montenegro, D. H. Peluffo-Ordóñez.	In the operation of logistics service companies and distribution, traffic congestion becomes a problem to be considered, because of their effect  on  arrival  times  to  meet  to  end  users,  in  addition  to  routing  costs.  These  costs  may  decrease  making  travel  plans,  where  traffic \r\ncongestion  in  urban  centers  are  avoided.  This  paper  proposes  an  experimental  design  to  estimate  congestion  costs  as  input  to solve the vehicle  routing  problem  with  time  dependent  (TDVRP).  As  strategy  solution,  it  intends  a  genetic  algorithm  hybrid  with  population \r\nmanagement. The data validation is performed considering a Dairy company making the distribution of its products in the storechannel in Pasto, obtaining a 35% reduction in logistics costs of distribution of f\r\ninal product.	2016	1	http://diegopeluffo.com/publicaciones/2016_JornadasFica_Ruteo.pdf
121	Estrategia de asignación para el problema de ruteo de vehículos con múltiples depósitos.	Jornadas Internacionales FICA 2016.	M.J. Bravo-Montenegro, F. A. Guasmayán-G, E. M. Toro-Ocampo, D. H. Peluffo-Ordóñez.	This   project   addresses   the   solution  of   Multi   Depot Vehicle    Routing    Problem    (MDVRP)    involving    fuel consumption,  this  problem  is  considered  NP-hard,  so  it  is solved  by  a  hybrid  algorithm  that  minimizes  the  costs  of distance   and   fuel   consumption,   within   a   reasonable \r\ncomputational   time.   Client   grouping   and   allocation  to deposits made by applying two procedures in order to form the  initial  population,  the  first  procedure  is  to  assign  first \r\nand routed after using ellipses, the routes are programmed and  optimized using  genetic  algorithms.  The  performance of the algorithm is evaluated by conducting different runs and   comparing   the   results   obtained   with the   bodies designed by Cordeau, in order to apply the methodology of \r\nsolution test case distribution of dairy products a company of San Juan de Pasto, which is also considered distance fuel costs.	2016	1	http://diegopeluffo.com/publicaciones/2016_JornadasFica_Ruteo2.pdf
122	Análisis De Señales EEG Para Detección De Intenciones Motoras Aplicadas A Sistemas BCI.	Jornadas Internacionales FICA 2016.	M. A. Patiño-Noguera, C. E. Medina-Ortega, W. Castro, D. H. Peluffo-Ordóñez.	The physical limitations that many people have as a result of degenerative neuronal diseases and limb amputations, have resulted in extensive research trying to understand the intentions of the brain through the study of characteristics of EEG signals, with the purpose of use them in output commands and can perform tasks that improve the quality of life of people. Although currently exist BCI systems that somehow allow users to interact with certain devices, these still presenting significant limitations because there is no definitive methodology that allows the correct characterization and classification of EEG signals, this being a research topic still open. The main idea of this work is to present an alternative methodology for feature extraction of EEG signals a view to improving the current systems BCI and achieve a friendly user interface. Keywords: Brain computer interface (BCI), Discrete Wavelet Transform (WDT), Electroencephalography (EEG), Feature Extraction. \r\n\r\nAnálisis De Señales EEG Para Detección De... (PDF Download Available). Available from: https://www.researchgate.net/publication/311767399_Analisis_De_Senales_EEG_Para_Deteccion_De_Intenciones_Motoras_Aplicadas_A_Sistemas_BCI [accessed Jun 03 2018].	2016	1	https://www.researchgate.net/publication/311767399_Analisis_De_Senales_EEG_Para_Deteccion_De_Intenciones_Motoras_Aplicadas_A_Sistemas_BCI
133	Deforming objects via exponential homotopy: A first approach	The Twentieth Symposium on Signal Processing, Images and Computer Vision. STSIVA 2015	D. H. Peluffo-Ordóñez,Luis O. Alpala, Catalina González-Castaño, Fredy A. Guasmayan	This work presents a novel alternative to conventional linear homotopy with suboptimal settings for applications on object deformation. Proposed approach extends the linear mapping to exponential representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. As well, we introduce a quality indicator based on the ratio between the coefficients curve of resultant homotopy and those of a non-realistic, reference homotopy. Experimental results are promising and show the applicability of exponential homotopy to interpolating images with soft changes and homotopic geometric objects.	2015	1	http://ieeexplore.ieee.org/document/7330401/
123	Influencia del horario de clases en las calificaciones de matemáticas en estudiantes de educación media desde un enfoque multiobjetivo	VI Simposio Internacio nal de Evaluación de los aprendizajes 2016 .	F. A. Guasmayán-G, M. J. Bravo-Montenegro, D. F, Dorado-Sevilla, D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo.	En este trabajo se realiza un estudio estadístico para la comparación de las calificaciones \r\nobtenidas en tres periodos consecutivos de tres grupos de estudiantes de grado séptimo de \r\neducación media, para lo cual se realiza un diseño de experimentos unifactorial en el que se \r\ndetermina si el tener clases de matemáticas en las últimas horas de la jornada académica influye \r\nen el rendimiento medido con las calificaciones obtenidas en los tres grupos de estudiantes con el \r\nmismo docente.	2016	1	https://www.researchgate.net/publication/313344472_Influencia_del_horario_de_clases_en_las_calificaciones_de_matematicas_en_estudiantes_de_educacion_media_desde_un_enfoque_multiobjetivo
124	Visualización y métodos kernel: Integrando inteligencia natural y artificial .	Congreso Internacional de Ingenierías UPEC 2016.	J. X. Alvarado-Pérez, D. H. Peluffo-Ordóñez, R.Therón.	The large amount of data generated by different activities -academic, scientific, business and industrial activities, among others-contains meaningful information that allows developing \r\nprocesses   and   techniques,   which   have   scientific   validity   to   optimally   explore   such \r\ninformation. Doing so, we get new knowledge to properly make decisions. The robustness \r\nand high computational processing capabilities of modern machines are used by areas such \r\nas artificial intelligence, if holistically integrates with the natural intelligence, in other words, if is synergistically combines sophisticated data analysis methods as well as the knowledge, skills  and  flexibility of  human  reasoning,  it  is  possible  to  discover  knowledge  in  a  more effective way. "Information Visualization" is an efficient way to bring the results generated by  the  algorithms  to  human  understanding in  order  to  find  hidden  trends  and  patterns belonging visually to the predictive model, that allow analysts to produce new observations and  considerations  from  existing  data,  improving  the  performance  of  machine  learning systems,  making  it  more  intelligible  results  and  improving  interactivity  and  controllability by the user. Nonetheless, the task of presenting and/or represent data in an understandable, intuitive and dynamic way, is not a trivial task, one of the biggest problems that visualization faces  is  the  high  dimension -being dimension the  number  of  variables  or  attributes  that characterize an object. An effective solution is the dimension\r\nality reduction methods (RD) that  can  represent  the  original, high-dimensional  data as  a  space  whose  dimensionis intelligible to humans (2D or 3D). Currently, the kernel methods represent a good alternative because of  their versatility  and ability to  make RD algorithms  easily  implementable\r\nin programming environments. This paper presents a brief description and method of use of a \r\ngeneralized method, so-calledkernel principal component analysis (KPCA).	2016	1	https://www.researchgate.net/profile/Diego_Peluffo/publication/313244494_Visualizacion_y_metodos_kernel_Integrando_inteligencia_natural_y_artificial/links/5893e4a745851563f828f0fc/Visualizacion-y-metodos-kernel-Integrando-inteligencia-natural-y-artificial.pdf
125	Low-cost prototype for biofeedback applications	Segundo encuentro nacional de semilleros de investigación en Ingeniería Electrónica 2015	S. Cano, A. Ruano, J. Revelo, D. Peluffo	This work project is about the design of a low-cost biofeedback devices. Device desing involves mainly two building blocks: The first one is concerned on the signal acquisition and analog filtering. Meanwhile, the second one is the estimation of physiological variable indicators	2015	1	https://www.researchgate.net/project/A-Low-Cost-Portable-Prototype-for-Support-of-Bio-Feedback-Therapies-in-Psychophysiological-Disorders
126	Generalized Bonhoeffer-van der Pol oscillator for modelling cardiac pulse: Preliminary results	IEEE 2nd Colombian Conference on Automatic Control. CCAC 2015	Peluffo-Ordonez, D.H.; Rodriguez-Sotelo, J.L.; Revelo-Fuelagan, E.J.; Ospina-Aguirre, C.; Olivard-Tost, G.	This work presents an approach for modelling cardiac pulse from electrocardiographic signals (ECG). We explore the use of the Bonhoeffer-van der Pol (BVP) model-being a generalized version of the van der Pol oscillator - which, under proper parameters, is able to describe action potentials, and it can be then adapted to modelling normal cardiac pulse. Using basics of non-linear dynamics and some algebra, the BVP system response is estimated. To account for an adaptive response for every single heartbeat, we propose a parameter tuning method based on a heuristic search in order to yield responses that morphologically resemble real ECG. This aspect is important since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are carried out over real ECG from MIT-BIH arrhythmias database. We perform a bifurcation and phase portrait analysis to explore the relationship between non-linear dynamics features and pathology. Preliminary results provided here are promising showing some hints about the ability of non-linear systems modelling ECG to characterize heartbeats and facilitate the classification thereof, being latter very important for diagnosing purposes.	2015	1	http://ieeexplore.ieee.org/xpl/articleDetails.jsp?arnumber=7345211
132	Interactive interface for efficient data visualization via a geometric approach	The Twentieth Symposium on Signal Processing, Images and Computer Vision. STSIVA 2015	D. H. Peluffo-Ordóñez, J. A. Salazar-Castro, Y. C. Rosas-Narváez, A. D. Pantoja, Juan C. Alvarado-Pérez	Dimensionality reduction (DR) methods represent a suitable alternative to visualizing data. Nonetheless, most of them still lack the properties of interactivity and controllability. In this work, we propose a data visualization interface that allows for user interaction within an interactive framework. Specifically, our interface is based on a mathematic geometric model, which combines DR methods through a weighted sum. Interactivity is provided in the sense that weighting factors are given by the user via the selection of points inside a geometric surface. Then, (even non-expert) users can intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results are obtained using artificial and real datasets, demonstrating the usability and applicability of our interface in DR-based data visualization.	2015	1	http://ieeexplore.ieee.org/document/7330397/
134	Multiple Kernel Learning for Spectral Dimensionality Reduction	XX Iberoamerican Congress on Pattern Recognition. CIARP 2014	Diego Hernán Peluffo-Ordóñez, Andrés Eduardo Castro-Ospina, Juan Carlos Alvarado-Pérez, Edgardo Javier Revelo-Fuelagán	This work introduces a multiple kernel learning (MKL) approach for selecting and combining different spectral methods of dimensionality reduction (DR). From a predefined set of kernels representing conventional spectral DR methods, a generalized kernel is calculated by means of a linear combination of kernel matrices. Coefficients are estimated via a variable ranking aimed at quantifying how much each variable contributes to optimize a variance preservation criterion. All considered kernels are tested within a kernel PCA framework. The experiments are carried out over well-known real and artificial data sets. The performance of compared DR approaches is quantified by a scaled version of the average agreement rate between K-ary neighborhoods. Proposed MKL approach exploits the representation ability of every single method to reach a better embedded data for both getting more intelligible visualization and preserving the structure of data.	2015	1	http://link.springer.com/chapter/10.1007/978-3-319-25751-8_75
107	Machine learning for the prediction of preterm pregnancy using EHG signals.	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	A. S. Caipe-Gordillo, J. A. Muñoz-Rosero, D. H. Peluffo-Ordóñez.	The pre-term pregnancy occurs when labor occurs before 37 weeks of gestation, this fact is a major cause of mortality and morbidity in children, at present. Despite that there are several factors that indicate risk a pre-term delivery, it can be produced without the need of a symptom or indication factor. In the world it is estimated that around 15 million premature babies was born each year, this quantity is growing and also has a greater impact in developing countries. That is why several investigations aimed at solving this problem through a study of records of uterine electrical activity, known as electrohisterography, which represents a great hope when detecting a pre-term pregnancy. By using computerized systems based on techniques of machine learning it is possible to determine the probability of pregnancy preterm as from electrohisterography records, however, there is still no definitive methods to characterize and classify these records This article presents a comparison methodology for the diagnosis of pre-term pregnancy occurs using different supervised Pattern recognition techniques such as feature selection, dimensionality reduction and classification. Considered techniques and reach an average error of 18.75%.	2016	1	https://www.researchgate.net/publication/311679756_Machine_Learning_for_the_prediction_of_preterm_pregnancy_using_EHG_signals
127	Artificial and Natural Intelligence Integration	12th International Symposium on Distributed Computing and Artificial Intelligence, Advances in Intelligent Systems and Computing. DCAI 2015	D. H. Peluffo-Ordóñez, Juan C. Alvarado-Pérez	The large amount of data generated by different activities -academic, scientific, business and industrial activities, among others- contains meaningful information that allows developing processes and techniques, which have scientific validity to optimally explore such information. Doing so, we get new knowledge to properly make decisions. Nowadays a new and innovative field is rapidly growing in importance that is Artificial Intelligence, which involves computer processing devices of modern machines and human reasoning. By synergistically combining them –in other words, performing an integration of natural and artificial intelligence-, it is possible to discover knowledge in a more effective way in order to find hidden trends and patterns belonging to the predictive model database. As well, allowing for new observations and considerations from beforehand known data by using data analysis methods as well as the knowledge and skills (of holistic, flexible and parallel type) from human reasoning. This work briefly reviews main basics and recent works on artificial and natural intelligence integration in order to introduce users and researchers on this field integration approaches. As well, key aspects to conceptually compare them are provided.	2015	1	http://link.springer.com/chapter/10.1007%2F978-3-319-19638-1_19
128	On the Spectral Clustering for Dynamic Data	6th International Work-Conference on the Interplay between Natural and Artificial Computation. IWINAC 2015	D. H. Peluffo-Ordóñez, J. C. Alvarado-Pérez, A. E. Castro-Ospina	Spectral clustering has shown to be a powerful technique for grouping and/or rank data as well as a proper alternative for unlabeled problems. Particularly, it is a suitable alternative when dealing with pattern recognition problems involving highly hardly separable classes. Due to its versatility, applicability and feasibility, this clustering technique results appealing for many applications. Nevertheless, conventional spectral clustering approaches lack the ability to process dynamic or time-varying data. Within a spectral framework, this work presents an overview of clustering techniques as well as their extensions to dynamic data analysis.	2015	1	http://link.springer.com/chapter/10.1007/978-3-319-18833-1_16
129	Geometrical homotopy for data visualization	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning. ESANN 2015	D. H. Peluffo-Ordóñez, J C. Alvarado-Perez , J. A. Lee, M. Verleysen	This work presents an approach allowing for an interactive visualization\r\nof dimensionality reduction outcomes, which is based on an extended view of con-\r\nventional homotopy.  The pairwise functional followed from a simple homotopic\r\nfunction can be incorporated within a geometrical framework in order to yield a bi-\r\nparametric approach able to combine several kernel matrices. Therefore, the users\r\ncan establish the mixture of kernels in an intuitive fashion by only varying two\r\nparameters.  Our approach is tested by using kernel alternatives for conventional\r\nmethods of spectral dimensionality reduction such as multidimensional scalling,\r\nlocally linear embedding and laplacian eigenmaps.  The proposed mixture repre-\r\nsents every single dimensionality reduction approach as well as helps users to find\r\na suitable representation of embedded data.	2015	1	https://www.elen.ucl.ac.be/Proceedings/esann/esannpdf/es2015-137.pdf
130	Knowledge discovery in databases from a perspective of intelligent information visualization	The Twentieth Symposium on Signal Processing, Images and Computer Vision. STSIVA 2015	D. H. Peluffo-Ordóñez, Juan C. Alvarado-Pérez, Harold Bolaños-Ramírez, S. Murillo	This paper reviews some recent and classical, relevant works on information visualization with a special focus on those applied to big data. The central idea dealt in this work relies on how to perform data mining tasks in a visual fashion; that is, using graphical correlation and interaction techniques. The scope of this review encompasses visualization techniques, formal visualization systems, and smart information visualization models. As well, newest approaches consisting of visualization and data mining integration process are explained.	2015	1	http://ieeexplore.ieee.org/document/7330438/
131	On the effect of inverse problem weighted solutions for epileptic sources localization	The Twentieth Symposium on Signal Processing, Images and Computer Vision. STSIVA 2015	D. H. Peluffo-Ordóñez, Melissa E. Acosta-Muñoz, Hugo A. Paredes-Argoty, E. Javier Revelo-Fuelagán	Within the context of epileptic sources localization from electroencephalographic signals, this work presents an exploratory study aimed at studying the effect of channel weighting on the estimation of the inverse problem solution. In this study, we consider two weighting approaches followed from a relevance feature analysis based on variance and energy criteria. Such approaches are compared by measuring the difference between the estimated source activity and the true power of the simulated sources in terms of the Earth mover's distance. Experimental results show that the incorporation of proper weighting factors into a LORETA-driven solution, localization may be improved. As well, the physiological phenomenon of the brain activity is more precisely tracked.	2015	1	http://ieeexplore.ieee.org/document/7330448/
135	Quadratic Problem Formulation with Linear Constraints for Normalized Cut Clustering	19th Iberoamerican Congress on Pattern Recognition. CIARP 2014	D. H. Peluffo-Ordóñez, C. Castro-Hoyos, Carlos D. Acosta-Medina, Germán Castellanos-Domínguez	This work describes a novel quadratic formulation for solving the normalized cuts-based clustering problem as an alternative to spectral clustering approaches. Such formulation is done by establishing simple and suitable constraints, which are further relaxed in order to write a quadratic functional with linear constraints. As a meaningful result of this work, we accomplish a deterministic solution instead of using a heuristic search. Our method reaches comparable performance against conventional spectral methods, but spending significantly lower processing time.	2014	1	https://link.springer.com/chapter/10.1007%2F978-3-319-12568-8_50
136	Short review of dimensionality reduction methods based on stochastic neighbour embedding	10th Workshop on Self-Organizing Maps	D. H. Peluffo-Ordóñez, J. A. Lee, M. Verleysen	Dimensionality reduction methods aimed at preserving the data topology have shown to be suitable for reaching high-quality embedded data. In particular, those based on divergences such as stochastic neighbour embedding (SNE). The big advantage of SNE and its variants is that the neighbor preservation is done by optimizing the similarities in both high- and low-dimensional space. This work presents a brief review of SNE-based methods. Also, a comparative analysis of the considered methods is provided, which is done on important aspects such as algorithm implementation, relationship between methods, and performance. The aim of this paper is to investigate recent alternatives to SNE as well as to provide substantial results and discussion to compare them.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-07695-9_6
137	Unsupervised relevance analysis for feature extraction and selection: A distance-based approach for feature relevance	3rd International Conference on Pattern Recognition Applications and Methods	D. H. Peluffo-Ordóñez, J. A. Lee, M. Verleysen, J.L. Rodríguez, G. Castellanos-Domínguez	The aim of this paper is to propose a new generalized formulation for feature extraction based on distances from a feature relevance point of view.  This is done within an unsupervised framework.  To do so, it is first outlined the formal concept of feature relevance. Then, a novel feature extraction approach is introduced. Such an approach employs the M-norm as a distance measure.  It is de\r\nmonstrated that under some conditions, thismethod can readily explain literature methods.  As another contribution of this paper, we propose an elegant feature ranking approach for feature selection followed from the spectral analysis of the data variability. Also, we provide a weighted PCA scheme revealing the relationship between feature extraction and feature selection. To assess the behavior of the studied methods within a pattern recognition system, a clustering stage is carried\r\nout.  Normalized mutual information is used to quantify the quality of resultant clusters.  Proposed methods reach comparable results with respect to literature methods.	2013	1	https://sites.uclouvain.be/DRedVis/Unsupervised_relevance_ICPRAM2013.pdf
138	Recent methods for dimensionality reduction:A brief comparative analysis	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning. ESANN 2014	D. H. Peluffo-Ordóñez, J. A. Lee, M. Verleysen	Dimensionality reduction is a key stage for both the design of a pattern recognition system or data visualization.  Recently, there has been a increasing interest in those methods aimed at preserving the data topology.  Among them, Laplacian eigenmaps (LE) and stochastic neighbour embedding (SNE) are the most representative.   In this work,  we present  a brief  comparative  among  very recent methods being alternatives to LE and SNE. Comparisons are done mainly on two aspects: algorithm implementation, and complexity. Also, relations between methods are depicted.  The goal of this work is providing researches on this field with some discussion as well as criteria decision to choose a method according to the user’s needs and/or  keeping  a good  trade-off between performance  and required\r\nprocessing time.	2014	1	https://www.elen.ucl.ac.be/Proceedings/esann/esannpdf/es2014-170.pdf
139	A multi-class extension for multi-labeler support vector machines	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning. ESANN 2014	D. H. Peluffo-Ordóñez, S. Murillo-Rendón, J. D. Arias-Londoño, G. Castellanos-Domínguez	In recent years, there has been an increasing interest in the design of pattern recognition systems able to deal with labels coming from multiple sources. To avoid bias during the learning process, in some applications it is strongly recommended to learn from a set of panelists or experts instead of only one. In particular, two aspects are of interest, namely:  discriminating between confident and unconfident labelers, and determining the suitable ground truth.  This work presents an extension of a previous work, which consists of a generalization of the two class case via a modified one-against-all approach.  This approach uses modified classifiers able to learn from multi-labeler settings.  This is done within a soft-margin support vector machine framework.  Proposed method provides ranking values for\r\npanelist as well as an estimate of the ground truth.	2014	1	https://www.elen.ucl.ac.be/Proceedings/esann/esannpdf/es2014-169.pdf
140	Optimal Data Projection for Kernel Spectral Clustering	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning. ESANN 2014	D. H. Peluffo-Ordóñez, C. Alzate, J. A. K. Suykens, and G. Castellanos-Dominguez	Spectral clustering has taken an important place in the context of pattern\r\nrecognition, being a good alternative to solve problems with non-linearly separable\r\ngroups.  Because of its unsupervised nature, clustering methods are often paramet-\r\nric, requiring then some initial parameters. Thus, clustering performance is greatly\r\ndependent on the selection of those initial parameters.  Furthermore, tuning such\r\nparameters is not an easy task when the initial data representation is not adequate.\r\nHere, we propose a new projection for input data to improve the cluster identifi-\r\ncation within a kernel spectral clustering framework.  The proposed projection is\r\ndone from a feature extraction formulation, in which a generalized distance involv-\r\ning the kernel matrix is used. Data projection shows to be useful for improving the\r\nperformance of kernel spectral clustering.	2014	1	https://www.elen.ucl.ac.be/Proceedings/esann/esannpdf/es2014-163.pdf
302	On the spectral clustering for dynamic data	International Work-Conference on the Interplay Between Natural and Artificial Computation	Diego Hernán Peluffo-Ordóñez, Juan C Alvarado-Pérez, Andrés Eduardo Castro-Ospina	Spectral clustering has shown to be a powerful technique for grouping and/or rank data as well as a proper alternative for unlabeled problems. Particularly, it is a suitable alternative when dealing with pattern recognition problems involving highly hardly separable classes. Due to its versatility, applicability and feasibility, this clustering technique results appealing for many applications. Nevertheless, conventional spectral clustering approaches lack the ability to process dynamic or time-varying data. Within a spectral framework, this work presents an overview of clustering techniques as well as their extensions to dynamic data analysis.	2015	10	https://link.springer.com/chapter/10.1007/978-3-319-18833-1_16
141	Multiscale stochastic neighbor embedding: Towards parameter-free dimensionality reduction	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning. ESANN 2014	D. H. Peluffo-Ordóñez, J. A. Lee, M. Verleysen	Stochastic neighbor embedding (SNE) is a method of dimen-sionality reduction that involves softmax similarities measured between all pairs of data points. To build a suitable embedding, SNE tries to repro-duce in a low-dimensional space the similarities that are observed in the high-dimensional data space. Previous work has investigated the immu-nity of such similarities to norm concentration, as well as enhanced cost functions. This paper proposes an additional refinement, in the form of multiscale similarities, namely averages of softmax ratios with decreasing bandwidths. The objective is to maximize the embedding quality at all scales, with a better preservation of both local and global neighborhoods, and also to exempt the user from having to fix a scale arbitrarily. Ex-periments on several data sets show that this multiscale version of SNE, combined with an appropriate cost function (sum of Jensen-Shannon di-vergences), outperforms all previous variants of SNE.	2014	1	http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.640.331
142	Effectiveness of morphological and spectral heartbeat characterization on arrhythmia clustering for Holter recordings	10th International Seminar on Medical Information Processing and Analysis. SIPAIM 2014	D. H. Peluffo-Ordóñez, C. Castro-Hoyos, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Heartbeat characterization is an important issue in cardiac assistance diagnosis systems. In particular, wide sets of features are commonly used in long term electrocardiographic signals. Then, if such a feature space does not represent properly the arrhythmias to be grouped, classification or clustering process may fail. In this work a suitable feature set for different heartbeat types is studied, involving morphology, representation and time-frequency features. To determine what kind of features generate better clusters, feature selection procedure is used and assessed by means clustering validity measures. Then the feature subset is shown to produce fine clustering that yields into high sensitivity and specificity values for a broad range of heartbeat types.	2014	1	http://spie.org/Publications/Proceedings/Paper/10.1117/12.2070686
143	Segment Clustering Methodology for Unsupervised Holter Recordings Analysis	10th International Seminar on Medical Information Processing and Analysis. SIPAIM 2014	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Cardiac arrhythmia analysis on Holter recordings is an important issue in clinical settings, however such issue implicitly involves attending other problems related to the large amount of unlabelled data which means a high computational cost. In this work an unsupervised methodology based in a segment framework is presented, which consists of dividing the raw data into a balanced number of segments in order to identify fiducial points, characterize and cluster the heartbeats in each segment separately. The resulting clusters are merged or split according to an assumed criterion of homogeneity. This framework compensates the high computational cost employed in Holter analysis, being possible its implementation for further real time applications. The performance of the method is measure over the records from the MIT/BIH arrhythmia database and achieves high values of sensibility and specificity, taking advantage of database labels, for a broad kind of heartbeats types recommended by the AAMI.	2014	1	http://spie.org/Publications/Proceedings/Paper/10.1117/12.2073882
144	Novel spectral characteristics of the electrical current waveform to quantifying power quality on LED lamps	XIX Symposium on Image, Signal Processing and Artificial Vision. STSIVA 2014	Peluffo-Ordonez, D.H. ; Revelo-Fuelagan, E.J.	LED lamps are widely used in household, nonetheless they are still non-linear. Therefore, LEDs need a power supply system to correcting their operation, which introduces nonlinearities into the electrical grid and distortions on waveform. Then analysis and quantification of electrical signals is becoming a key issue. This work presents a spectral analysis of analysis of electric current signal in LEDs lamps which yields a novel collection of characteristics and measures to quantify the waveform quality. In particular, periodogram and Fourier transform are considered. For experiments, two circuits are considered: one that corresponds to the commercial LEDs lamp connected to AC source and another one incorporating a power factor corrector. Experimentally, the usefulness and applicability of proposed characteristics is proved.	2014	1	http://ieeexplore.ieee.org/xpl/articleDetails.jsp?reload=true&arnumber=7010182
145	Análisis de Características del Perfil de Usuario para un Sistema de Recomendación de Objetos de Aprendizaje	IX Conferencia Latinoamericana de Objetos y Tecnologías de Aprendizaje. LACLO 2014	Paula Andrea Rodríguez, Néstor Darío Duque, Demetrio Arturo Ovalle, Diego Peluffo, Oscar Mauricio Salazar	Los Objetos de Aprendizaje (OA), como unidades de contenido educativo y como recursos reutilizables permiten disponer de la información para ser utilizada en ambientes virtuales de aprendizaje y para acceder a ellos se debe contar con mecanismos de recuperación y selección permitiendo el apoyo al proceso de enseñanza-aprendizaje de un estudiante en particular. Los Sistemas de Recomendación (SR) son herramientas que apoyan al usuario a obtener información de acuerdo a sus necesidades y preferencias. Para el uso de SR en ambientes educativos, se debe contar con la caracterización de los estudiantes a través de perfiles de usuario con el fin de entregar OA adaptados. Pero no todas las características son relevantes en el proceso de recomendación, por ello en este trabajo se hace un primer acercamiento al análisis de las variables asociadas al estudiante con el fin de seleccionar aquellas que más puedan aportar al proceso de personalización. \r\n\r\nAnálisis de Características del Perfil de... (PDF Download Available). Available from: https://www.researchgate.net/publication/303723307_Analisis_de_Caracteristicas_del_Perfil_de_Usuario_para_un_Sistema_de_Recomendacion_de_Objetos_de_Aprendizaje [accessed Jun 03 2018].	2014	1	https://www.researchgate.net/publication/303723307_Analisis_de_Caracteristicas_del_Perfil_de_Usuario_para_un_Sistema_de_Recomendacion_de_Objetos_de_Aprendizaje
146	Generalized kernel framework for unsupervised spectral methods of dimensionality reduction	2014 IEEE Symposium Series on Computational Intelligence. SSCI 2014	Peluffo-Ordonez, D.H. ; Aldo Lee, J. ; Verleysen, M.	This work introduces a generalized kernel perspective for spectral dimensionality reduction approaches. Firstly, an elegant matrix view of kernel principal component analysis (PCA) is described. We show the relationship between kernel PCA, and conventional PCA using a parametric distance. Secondly, we introduce a weighted kernel PCA framework followed from least-squares support vector machines (LS-SVM). This approach starts with a latent variable that allows to write a relaxed LS-SVM problem. Such a problem is addressed by a primal-dual formulation. As a result, we provide kernel alternatives to spectral methods for dimensionality reduction such as multidimensional scaling, locally linear embedding, and laplacian eigenmaps; as well as a versatile framework to explain weighted PCA approaches. Experimentally, we prove that the incorporation of a SVM model improves the performance of kernel PCA.	2014	1	http://ieeexplore.ieee.org/xpl/articleDetails.jsp?arnumber=7008664
147	Kernel Spectral Clustering for dynamic data using Multiple Kernel Learning	IEEE World Congress on Computational Intelligence/The 2013 International Joint Conference on Neural Networks	D. H. Peluffo-Ordóñez, S. García-Vega, R. Langone, J. A. K. Suykens, G. Castellanos-Domínguez	In this paper we propose a kernel spectral clustering-based technique to catch the different regimes experienced by a time-varying system. Our method is based on a multiple kernel learning approach, which is a linear combination of kernels. The calculation of the linear combination coefficients is done by determining a ranking vector that quantifies the overall dynamical behavior of the analyzed data sequence over-time. This vector can be calculated from the eigenvectors provided by the the solution of the kernel spectral clustering problem. We apply the proposed technique to a trial from the Graphics Lab Motion Capture Database from Carnegie Mellon University, as well as to a synthetic example, namely three moving Gaussian clouds. For comparison purposes, some conventional spectral clustering techniques are also considered, namely, kernel k-means and min-cuts. Also, standard k-means. The normalized mutual information and adjusted random index metrics are used to quantify the clustering performance. Results show the usefulness of proposed technique to track dynamic data, even being able to detect hidden objects.	2013	1	http://ieeexplore.ieee.org/xpl/articleDetails.jsp?arnumber=6706858
148	Spectral analysis of electric current in LEDs lamps	VII Simposio Internacional sobre la Calidad de la Energía Eléctrica. SICEL 2013	D. H. Peluffo-Ordóñez, Edgardo Javier Revelo F	LED lamps are widely used in household, nonetheless they are still non-linear. Therefore, LEDs need a power supply system to correcting their operation, which introduces nonlinearities into the electrical grid and distortions on waveform. Then analysis and quantification of electrical signals is becoming a key issue. This work presents a spectral analysis of analysis of electric current signal in LEDs lamps which yields a novel collection of characteristics and measures to quantify the waveform quality. In particular, periodogram and Fourier transform are considered. For experiments, two circuits are considered: one that corresponds to the commercial LEDs lamp connected to AC source and another one incorporating a power factor corrector. Experimentally, the usefulness and applicability of proposed characteristics is proved.	2013	1	http://ieeexplore.ieee.org/document/7010182/
149	Normalized Cuts Clustering with Prior Knowledge and a Pre-clustering Stage	21st European Symposium on Artificial Neural Networks. ESANN 2013	D. H. Peluffo-Ordóñez, A. E. Castro-Ospina, D. Chavez-Chamorro, C. D. Acosta-Medina, and G. Castellanos-Domínguez	Clustering is of  interest  in cases when  data are not  labeled  enough\r\nand a prior training stage is unfeasible.  In particular, spectral clustering based on\r\ngraph partitioning is of interest to solve problems with highly non-linearly separa-\r\nble classes.  However, spectral methods, such as the well-known normalized cuts,\r\ninvolve the computation  of eigenvectors that is a highly time-consuming task in\r\ncase of large data.  In this work, we propose an alternative to solve the normalized\r\ncuts problem for clustering, achieving same results as conventional spectral meth-\r\nods but spending less processing time. Our method consists of a heuristic search to\r\nfind the best cluster binary indicator matrix, in such a way that each pair of nodes\r\nwith greater similarity value are first grouped and the remaining nodes are clustered\r\nfollowing a heuristic algorithm to search into the similarity-based representation\r\nspace. The proposed method is tested over a public domain image data set. Results\r\nshow that our method reaches comparable results with a lower computational cost.	2013	1	https://www.elen.ucl.ac.be/Proceedings/esann/esannpdf/es2013-90.pdf
150	Kernel Spectral Clustering for Motion Tracking: A first approach	5th International Work-Conference on the Interplay between Natural and Artificial Computation. IWINAC 2013	D. H. Peluffo-Ordóñez, S. García-Vega, G. Castellanos-Domínguez	This work introduces a first approach to track moving-samples or frames matching each sample to a single meaningful value. This is done by combining the kernel spectral clustering with a feature relevance procedure that is extended to rank the frames in order to track the dynamic behavior along a frame sequence. We pose an optimization problem to determine the tracking vector, which is solved by the eigenvectors given by the clustering method. Unsupervised approaches are preferred since, for motion tracking applications, labeling is unavailable in practice. For experiments, two databases are considered: Motion Caption and an artificial three-moving Gaussian in which the mean changes per frame. Proposed clustering is compared with kernel K-means and Min-Cuts by using normalized mutual information and adjusted random index as metrics. Results are promising showing clearly that there exists a direct relationship between the proposed tracking vector and the dynamic behavior.	2013	1	https://link.springer.com/chapter/10.1007/978-3-642-38637-4_27
151	Kernel Spectral Clustering for Dynamic Data	18th Iberoamerican Congress on Pattern Recognition. CIARP 2013	D. H. Peluffo-Ordóñez, S. García-Vega, Andrés Marino Alvarez-Meza, G. Castellanos-Domínguez	This paper introduces a novel spectral clustering approach based on kernels to analyze time-varying data. Our approach is developed within a multiple kernel learning framework, which, in this case is assumed as a linear combination model. To perform such linear combination, weighting factors are estimated by a ranking procedure yielding a vector calculated from the eigenvectors-derived-clustering-method. Particularly, the method named kernel spectral clustering is considered. Proposed method is compared to some conventional spectral clustering techniques, namely, kernel k-means and min-cuts. Standard k-means as well. The clustering performance is quantified by the normalized mutual information and Adjusted Rand Index measures. Experimental results prove that proposed approach is an useful tool for both tracking and clustering dynamic data, being able to manage applications for human motion analysis.	2013	1	https://link.springer.com/chapter/10.1007/978-3-642-41822-8_30
152	Novel Heuristic Search for Ventricular Arrhythmia Detection using Normalized Cut Clustering	The 35th Annual International Conference of the IEEE Engineering in Medicine and Biology Society. EMBC 2013	D. H. Peluffo-Ordóñez, A. E. Castro-Ospina, C. Castro-Hoyos, G. Castellanos-Domínguez	Processing of the long-term ECG Holter recordings for accurate arrhythmia detection is a problem that has been addressed in several approaches. However, there is not an outright method for heartbeat classification able to handle problems such as the large amount of data and highly unbalanced classes. This work introduces a heuristic-search-based clustering to discriminate among ventricular cardiac arrhythmias in Holter recordings. The proposed method is posed under the normalized cut criterion, which iteratively seeks for the nodes to be grouped into the same cluster. Searching procedure is carried out in accordance to the introduced maximum similarity value. Since our approach is unsupervised, a procedure for setting the initial algorithm parameters is proposed by fixing the initial nodes using a kernel density estimator. Results are obtained from MIT/BIH arrhythmia database providing heartbeat labelling. As a result, proposed heuristic-search-based clustering shows an adequate performance, even in the presence of strong unbalanced classes.	2013	1	http://ieeexplore.ieee.org/document/6611188/
153	Support Vector Machine-based approach for multi-labelers problems	21st European Symposium on Artificial Neural Networks. ESANN 2013	D. H. Peluffo-Ordóñez, S.Murillo-Rendón, G. Castellanos-Domínguez	We propose a first approach to quantify the panelist’s labeling general-izing a soft-margin support vector machine classifier to multi-labeler analysis. Our approach consists of formulating a quadratic optimization problem instead of using a heuristic search algorithm. We determine penalty factors for each panelist by in-corporating a linear combination in the primal formulation. Solution is obtained on a dual formulation using quadratic programming. For experiments, the well-known Iris with multiple simulated artificial labels and a multi-label speech database are employed. Obtained penalty factors are compared with both standard supervised and non-supervised measurements. Promising results show that proposed method is able to asses the concordance among panelists considering the structure of data.	2013	1	http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.718.3881
154	Multi-labeler Analysis for Bi-class Problems Based on Soft-Margin Support Vector Machines	5th International Work-Conference on the Interplay between Natural and Artificial Computation. IWINAC 2013	D. H. Peluffo-Ordóñez, J. D. Arias-Londoño, S.Murillo-Rendón, G. Castellanos-Domínguez	This work presents an approach to quantify the quality of panelist’s labeling by means of a soft-margin support vector machine formulation for a bi-class classifier, which is extended to multi-labeler analysis. This approach starts with a formulation of an objective function to determine a suitable hyperplane of decision for classification tasks. Then, this formulation is expressed in a soft-margin form by introducing some slack variables. Finally, we determine penalty factors for each panelist. To this end, a panelist’s effect term is incorporated in the primal soft-margin problem. Such problem is solved by deriving a dual formulation as a quadratic programming problem. For experiments, the well-known Iris database is employed by simulating multiple artificial labels. The obtained penalty factors are compared with standard supervised measures calculated from confusion matrix. The results show that penalty factors are related to the nature of data, allowing to properly quantify the concordance among panelists.	2013	1	https://link.springer.com/chapter/10.1007/978-3-642-38637-4_28
155	An improved multi-class spectral clustering based on normalized cuts	The 17th Iberoamerican Congress on Pattern Recognition. CIARP 2012	D. H. Peluffo-Ordóñez, C. D. Acosta-Medina, G. Castellanos-Domínguez	In this work, we present an improved multi-class spectral clustering (MCSC) that represents an alternative to the standard k-way normalized clustering, avoiding the use of an iterative algorithm for tuning the orthogonal matrix rotation. The performance of proposed method is compared with the conventional MCSC and k-means in terms of different clustering quality indicators. Results are accomplished on commonly used toy data sets with hardly separable classes, as well as on an image segmentation database. In addition, as a clustering indicator, a novel unsupervised measure is introduced to quantify the performance of the proposed method. The proposed method spends lower processing time than conventional spectral clustering approaches.	2012	1	https://link.springer.com/chapter/10.1007/978-3-642-33275-3_16
156	Effect of Latency on Clustering of P300 Recordings for ADHD Discrimination	34th Annual International Conference of the IEEE Engineering in Medicine and Biology Society. EMBC 2012	D. H. Peluffo-Ordóñez, J.D. Martinez-Vargas, G. Castellanos-Domínguez	This paper is focused on testing the latency contribution as regards the quality of formed groups for discriminating between healthy and attention deficit hyperactivity disorder children. To this end, two different cases are considered: nonaligned original recordings and aligned signals according to P300 position. For latter case, a novel approach to conduct time location of P300 component is introduced, which is based on derivative of event-related potential signals. The used database holds event-related potentials registered in auditory and visual oddball paradigm. Several experiments are carried out testing both configurations of considered data matrix. For grouping input data matrices, the k-means clustering technique is employed. To assess the quality of formed clusters and the relevance for clustering of latency-based features, relative values of distances between centroids and data points are computed in order to apprise separability and compactness of estimated clusters. Experimental results show that time localization of P300 component is not a decisive feature in formation of compact and well-defined groups within a discrimination framework for two considered data classes under certain conditions.	2012	1	https://www.ncbi.nlm.nih.gov/pubmed/23367101
157	Numerical Investigation of Low Level OSNR Estimation Based on Gaussian Fitting and NLLS on AAH in Noisy Optical Communication Links	IEEE Colombian Communications Conference. COLCOM 2012	D. H. Peluffo-Ordóñez, Oscar Marino Díaz, Neil Guerrero G, Cristian Castro H	An extended digital estimation approach of optical signal to noise ratio (OSNR) based on statistical analysis of asynchronous amplitude histograms (AAH) of the received optical signal is presented and numerically investigated. Accurate OSNR estimation on highly noisy optical transmission link is achieved. Furthermore, the proposed OSNR estimation approach may be digitally adjusted to any Cartesian modulation format such as multilevel phase shift keying and quadrature amplitude modulated optical signals without degrading estimation accuracy. The OSNR estimation methodology is based on kernel density estimation with Gaussian kernels and non-linear least-squares regression (NLLS). Heuristic searches are no longer needed and the process becomes more reliable and robust. Reported results show accurate OSNR estimation with less than 15% error estimation on the simulated OSNR value for different signal modulation formats, exhibiting a more confident estimation system, with comparable results among formats because of the statistical nature histogram instead of the regular counting bins histogram.	2012	1	http://ieeexplore.ieee.org/abstract/document/6233657/
158	Image Segmentation based on Multi-Kernel Learning and feature relevance analysis	13th Ibero-American Conference on Artificial Intelligence. IBERAMIA 2012	D. H. Peluffo-Ordóñez, S. Molina-Giraldo, A. M. Alvarez-Meza, G. Castellanos-Domínguez	In this paper an automatic image segmentation methodology based on Multiple Kernel Learning (MKL) is proposed. In this regard, we compute some image features for each input pixel, and then combine such features by means of a MKL framework. We automatically fix the weights of the MKL approach based on a relevance analysis over the original input feature space. Moreover, an unsupervised image segmentation measure is used as a tool to establish the employed kernel free parameter. A Kernel Kmeans algorithm is used as spectral clustering method to segment a given image. Experiments are carried out aiming to test the efficiency of the incorporation of weighted feature information into clustering procedure, and to compare the performance against state of the art algorithms, using a supervised image segmentation measure. Attained results show that our approach is able to compute a meaningful segmentations, demonstrating its capability to support further vision computer applications.	2012	1	https://link.springer.com/chapter/10.1007/978-3-642-34654-5_51
159	Constrained affinity matrix for spectral clustering: A basic semi-supervised extension	XVII Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2012	D. H. Peluffo-Ordóñez, G. Castellanos-Domínguez, C. Castro	Spectral clustering has represented a good alternative in digital signal processing and pattern recognition; however a decision concerning the affinity functions among data is still an issue. In this work it is presented an extended version of a traditional multiclass spectral clustering method which employs prior information about the classified data into the affinity matrixes aiming to maintain the background relation that might be lost in the traditional manner, that is using a scaled exponential affinity matrix constrained by weighting the data according to some prior knowledge and via k-way normalized cuts clustering, results in a semi-supervised methodology of traditional spectral clustering. Test was performed over toy data classification and image segmentation and evaluated with and unsupervised performance measures (group coherence, fisher criteria and silhouette).	2012	1	https://www.infona.pl/resource/bwmeta1.element.ieee-art-000006340590
160	Relevance Analysis based on graph theory and spectral analysis	XVII Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2012	D. H. Peluffo-Ordóñez, G. Castellanos-Domínguez, L.M Morales-Villamil, M.C. García-Murillo	Category 1. We present a new method for relevance analysis   based   on  spectral   information,   which  is  done   from a   graph   theory   point   of   view.   This   method   is   carried   out\r\nby  using  Gaussian  Kernels  instead  of  conventional  quadratic forms and then avoiding the need of a linear combination-based representation.  For   this  end,  it  is  implemented  an  extended\r\napproach  for  relevance  analysis  using  alternative  Kernels,  in this  case,  exponential  ones.  For  assessing  the  proposed  method performance,   it   is   applied   a  clustering  algorithm   commonly\r\nused  and  recommended  by  literature:  normalized  cuts  based clustering. Experimental results are obtained from the processing of well known image and toy data bases. Results are comparable\r\nwith those reported  in the literature.	2012	1	http://diegopeluffo.com/publicaciones/STSIVA2012_2.pdf
161	Low level Optical Signal to Noise Ratio measurement using basic statistical data from Asynchronous Amplitude Histogram Gaussian fitting	IBERCHIP XVII	D. H. Peluffo-Ordóñez, J. M. López, O. M. Díaz, N. Guerrero	Optical  Monitoring  Systems  need  to  be  less  expen-\r\nsive  if  we  are  to  create  an  Optical  Packet  Switched  Network.\r\nThe  application  presented  in  this  paper  uses  low  cost  sampling\r\ncircuits and simple Digital Signal Processing in order to acquire\r\ngood approximations of the Optical Signal to Noise Ratio by using\r\nthe exponential relation found between the Variance of one of the\r\npeaks in the AAH and the OSNR. The method works especially\r\nwell  for  PSK  and  QPSK  modulation  schemes,  and  presents  a\r\ngood  representation  for  DPSK  and  DQPSK  systems.\r\nThe results here presented were heuristically obtained, though\r\nsome basic relation between the features used are devisable, and\r\ncould  lead  to  future  analytical  approaches.	2011	1	http://diegopeluffo.com/publicaciones/IBERCHIP2011.pdf
162	Spectral analysis of electric current in compact fluorescent lamps	VI Simposio Internacional sobre Calidad de la Energía Eléctrica. SICEL 2011	D. H. Peluffo-Ordóñez, E. J. Revelo-Fuelagan, G. A. Alarcón-Lancheros, O. M. Díaz-Betancourt	This work presents an analysis of electric current signal in compact fluorescent lamps (CFLs). Electri\r\ncal signals are measured in two circuits, one that corresponds to the CFL shunt connected with the AC source and another one that incorporates a control system into the CFL. Such control system \r\nworks as a power factor correction (PFC) and is designed by employing a boost converter and a current controller. Signals are analyzed in terms of frequency-based representations oriented t\r\no estimate the power spectral density (PSD). In this study, three approaches are employed: Fourier transform, periodogram and a window-based PSD.  The goal of this work is to show that more co\r\nmplex PSD estimation methods can provide useful information for studying the quality energy in electric power systems. Proposed spectral analysis represents an alternative to traditional approaches.	2011	1	http://diegopeluffo.com/publicaciones/SICEL2011.pdf
163	Analysis of the effects of linear and non-linear distortions on QPSK modulated signals for optical channels	11th IEEE International Conference on Computer and Information Technology. CIT 2011	D. H. Peluffo-Ordóñez, N. Guerrero-Gonzales, J. Salazar-Cuellar, M. Vergara-Hidalgo, O. M. Díaz-Betancourt	In this paper, we present some achievements of the degree thesis entitled “Analysis of the effects of linear and  non-linear  distortions  on  QPSK  modulated  signals  for optical  channels”  developed  by  the  two  first  authors.  The pertinence of this work lies in that digital signal processing have currently taken an important place in Communications, in particular, Optical Communications. Current tran\r\nsmission systems are supported by DSP based devices to carry out filtering and equalization tasks. For filtering, the first stage is to  understand  the  distortion  and  establish  a  model (when possible). In this work, we present a brief state of the art of linear  and  non-linear  distortions  in  optical  channels developed  in  the  last  thirteen  years.  Also,  we  present  an useful and specific theoretical background about distortions and  digital  modulation  formats  oriented  to  optical	2011	1	http://diegopeluffo.com/publicaciones/CIT2011.pdf
165	ADHD identification based on a linear projection and clustering	VII Seminario Internacional de Procesamiento y Análisis de Información Médica. SIPAIM 2011	D. H. Peluffo-Ordóñez, F. Restrepo de Mejía, P.A. Castro-Cabrera, G. Castellanos-Domínguez	Event-related potentials (ERPs) are electrical signals from brain generated as a response to an external sensorial stimulus. This kind of signals are widely used to diagnose neurological disorders, such as Attention-deficit hyperactivity disorder (ADHD). In this paper, a novel methodology for ADHD discrimination is proposed, which consist of obtaining a new data representation by means of are characterization of initial feature space. Such re-characterization is done through the distances between data and centroids obtained from k-means algorithm. This methodology also includes pre-clustering and liner projection stages. In addition, this paper explores the use of morphological and\r\nspectral features as descriptive patterns of ERP signal in order to discriminate between normal subjects and ADHD patients. Experimental results show that the morphological features, in contrast with the remaining features considered in this study, are those that more contribute to classification\r\nperformance, reaching 86 % for the original feature set.	2011	1	http://diegopeluffo.com/publicaciones/SIPAIM2011_2.pdf
166	Weighted Time Series Analysis for Electroencephalographic Source Localization	VII Seminario Internacional de Procesamiento y Análisis de Información Médica. SIPAIM 2011	D. H. Peluffo-Ordóñez, E. Giraldo, G. Castellanos-Domínguez	This paper presents a new method to estimate neural activity from electroencephalographic signals using a weighted time series analysis. The method considers a physiologically based linear model that take both spatial and temporal dynamics into account and a weighting stage to modify\r\nthe assumptions of the model from observations. The calculated weighting matrix is included in the cost function used to solve the dynamic inverse problem, and therefore in the Kalman filter formulation. In this way, a weighted Kalman filtering approach is proposed including a preponderance\r\nmatrix. The filter’s performance (in terms of localization error) is analyzedfor several SNRs. The optimal performance is achieved using the linear model with a weighting matrix computed by an inner product method.	2011	1	http://diegopeluffo.com/publicaciones/SIPAIM2011_1.pdf
167	On the groups number estimation for unsupervised clustering	XVI Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2011	D. H. Peluffo-Ordóñez, C. Castro, A. E. Castro, G. Castellanos-Domínguez	Clustering  techniques  usually  requires manually   set   parameters   so   the   classification   task   may   be correctly carried out, one of the most common being the number of groups or clusters in which data should be separated, yet this relies  in  a  prior  knowledge  of  the  data  nature.  In  this  work  a comparison  among different approaches for finding the number of groups is shown, such as singular value decomposition (SVD), analysis  of  the  multiplicity  of  the  greatest  eigenvalues  fr\r\nom  the affinity matrix, and the percentage of the cumulative sum of the singular values of the affinity matrix. The spectral nature of the estimation  process  as  well  as  the  different  datasets  used,  infers that  the  results  rely  only  in  the  internal  information  of  data matrixes.  Results  exhibits  both  limitations  and  advantages  for each method, weather directly related with the nature of the\r\ndata, or  limited  by  the  process  structure  and  definition.  Nonetheless these  guidelines  will  be  helpful  for  deciding  which  estimation technique best  applies for  clustering data  regardless its o\r\nrigin.	2011	1	http://diegopeluffo.com/publicaciones/STSIVA2011_2.pdf
168	A Comparative Study of Weighting Factors for WPCA Based on a Generalized Distance Measure	XVI Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2011	D. H. Peluffo-Ordóñez, J. S. Castaño-Candamil, S. García-Vega, G. Castellanos-Domínguez	This work presents a comparative analysis between different weighting factors for PCA, obtained from a  generalized  distance  measure.  By  employing  such  generalized distance,  an  optimization  problem  is  established  whose  solution provides relevance values for each feature. Relevance values are used  both  for  weighting  data  in  a  WPCA  scheme  to  carry  out a  feature  extraction  and  also  for  selecting  relevant  features. Their   performance   and   suitability   are   assessed   in   terms   of\r\ndimensionality reduction and classification performance achieved\r\nby   applying   both   supervised   and   unsupervised   classification\r\ntechniques  over  real  datasets.	2011	1	http://citeseerx.ist.psu.edu/viewdoc/download?doi=10.1.1.718.2081&rep=rep1&type=pdf
169	Affinity matrix selection for spectral clustering	XV Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2010	D. H. Peluffo-Ordóñez, D. F. López, J. L. Rodríguez, G. Castellanos-Domínguez	This work presents a comparative study of different affinity measures applied in spectral clustering algorithms commonly used and recommended by literature. Spectral algorithms for clustering are known to be useful in different areas of science and engineering such as image segmentation, load balance for intensive computing, circuits design, among others. In particular they have been proved to be effective in classification tasks where the classes are not linearly separable. Typically, spectral clustering involves calculating an affinity matrix from the data to be processed, which usually can be done by different standard approaches or adjusted to the requirements for the specific algorithm or classification task. Experiments results are carried out using an image database and clustering performance is measured by means supervised and unsupervised indices based on cluster coherence and objective function value. Results show a general idea of the effects of the affinity matrix selection in grouping process in terms of convergence time and accuracy.	2010	1	https://www.researchgate.net/publication/303722436_Affinity_matrix_selection_for_spectral_clustering
170	Region of interest extraction using redundant wavelet transform and unsupervised techniques on thermal imaging	10th International Conference on Quantitative InfraRed Thermography	D. H. Peluffo-Ordóñez, B. Ortiz-Jaramillo, J. Garcia-Alvarez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Most applications in the analysis of thermal images can detect changes in patterns [1]. Thus, thermal patterns provide sufficient\r\ninformation of the structure for a particular device, giving the opportunity to alert and perform some preventive action in the process.\r\nThe wavelet transform is useful to characterize this kind of change, because the localized of the scale information gives the nature\r\nof the representation. Thereafter, relevant details are preserved when scale is changed in the representation space, excluding other\r\ndetails that not provide information about regions of interest [2]. On the other hand, the patterns obtained in the characterization phase\r\ncan be clustered by using unsupervised techniques. Those patterns are measured with an adequate metric to determine the principal\r\ncluster of the dataset. Then, additional criteria can be employed to initialize the centroids of the cluster to obtain a better outcome.\r\nThis criteria is supported by no homogeneous representation of the cluster, justified by the nature of the thermal distribution: its\r\ndistribution has smooth changes in the image, making difficult the automatic detection of those regions. In this way, a change in the\r\nrepresentation space is necessary to make easy the clustering process. Thus, changes in the initial groups can be detected, when the\r\ncluster is initially identified in normal condition of the devices and the image representation space is wavelet. A pattern change is\r\ndefined as the change in the number of clusters or in the size of some cluster. It represents a fault candidate in the device, making\r\npossible to take decision about the actual state of the device.	2010	1	http://www.qirt.org/archives/qirt2010/papers/QIRT%202010-103.pdf
171	Weighted-PCA for unsupervised classification of cardiac arrhythmias	32nd Annual International Conference of the IEEE Engineering in Medicine and Biology Society. EMBC 2010	JL Rodríguez-Sotelo, E Delgado-Trejos, D Peluffo-Ordóñez, D Cuesta-Frau, G Castellanos-Domínguez	A method that improves the feature selection stage for non-supervised analysis of Holter ECG signals is presented. The method corresponds to WPCA approach developed mainly in two stages. First, the weighting of the feature set through a weight vector based on M-inner product as distance measure and a quadratic optimization function. The second one is the linear projection of weighted data using principal components. In the clustering stage, some procedures are considered: estimation of the number of groups, initialization of centroids and grouping by means a soft clustering algorithm. In order to decrease the procedure computational cost, segment analysis, grouping contiguous segments and establishing union and exclusion criteria per each cluster, is carried out. This work is focused to classify cardiac arrhythmias into 5 groups, according to the standard of the AAMI (ANSI/AAMI EC57:1998/ 2003). To validate the method, some recordings from MIT/BIH arrhythmia database are used. By employing the labels of each recording, the performance is assessed with supervised measures (Se = 90.1%, Sp = 98.9% y Cp = 97.4%), enhancing other works in the literature that do not take into account all heartbeat types.	2010	1	http://ieeexplore.ieee.org/xpl/articleDetails.jsp?arnumber=5627321
172	Unsupervised feature selection in cardiac arrhythmias analysis	2009 Annual International Conference of the IEEE Engineering in Medicine and Biology Society	D. H. Peluffo-Ordóñez, D. Cuesta-Frau, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	The problem of detecting clinical events related to cardiac arrhythmias in long term electrocardiograms is a difficult one due to the large amount of irrelevant information that hides such events. This problem has been addressed in the literature by means of clustering or classification algorithms that create data partitions according to a cost function based on heartbeat features dissimilarity measures. However, studies about the type or number of heartbeat features is lacking. Usually, the feature sets used are relevant but redundant, which degrades algorithm performance. This paper describes a method for automatic selection of heartbeat features. This method is assessed using real signals from the MIT database and common features used in previous works.	2009	1	http://ieeexplore.ieee.org/document/5335284/
173	Nonparametric Density-Based Clustering for Cardiac Arrhythmia Analysis	36th Annual Computers in Cardiology Conference. CinC - IEEE - 2009	D. H. Peluffo-Ordóñez, C. Ospina,D Cuesta-Frau, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	In this work, a nonsupervised algorithm for feature selection and a non-parametric density-based clustering algorithm are presented, whose density estimation is performed by Parzen's window approach; this algorithm solves the problem that individual components of the mixture should be Gaussian. The method is applied to a set of recordings from MIT/BIH's arrhythmia database with five groups of arrhythmias recommended by the AAMI. The heartbeats are characterized using prematurity indices, morphological and representation features, which are selected with the Q-a algorithm. The results are assessed by means supervised (Se, Sp, Sel) and nonsupervised indices for each arrhythmia. The proposed system presents comparable results than other unsupervised methods of literature.	2009	1	http://ieeexplore.ieee.org/document/5445342/
174	Unsupervised classification of cardiac arrhythmias using partitional clustering	Encuentro Nacional de Investigación en Posgrados ENIP 2009	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	This work describes a method to classify cardiac arrhythmias in Holter records using unsupervised classification. Unsupervised analysis is preferred in this work because detecting a specific heartbeat in Holter records requires analyzing every heartbeat taking into account several factors such as: variability, signal length, EMG noise, artifacts and different dynamic behavior and morphology. ECG signals are extracted from MIT-BIH arrhythmia database. The proposed method includes pre-processing, feature selection and unsupervised classification. Features are obtained from heartbeat morphology, time related and representation features. For feature selection, we apply the unsupervised Q − α algorithm obtained from spectral and graph-based analysis. The classification stage is based on partitional clustering using the general iterative model. In order to improve the algorithm convergence, clustering incorporates a center initialization based on J-means criterion. The method shows good average performance, namely sensitivity 98.9%, specificity 99.8 % and clustering performance 99.6%.	2009	1	https://www.researchgate.net/publication/282611997_Unsupervised_classification_of_cardiac_arrhythmias_using_partitional_clustering
175	Clasificación de arritmias en registros Holter empleando análisis no supervisado de tipo particional y espectral	V Seminario Internacional de Procesamiento y Análisis de Imágenes Médicas. SIPAIM 2009	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Resumen Se propone una metodología para el análisis no supervisado de patrones descrip-tivos de latidos en señales ECG de registros Holter, con el fin de clasificar arritmias y mostrar la aplicabilidad y versatilidad de las técnicas de análisis no supervisado. El sistema propuesto incluye etapas de caracterización, selección de características, criterios de inicialización, es-timación del número de grupos y clustering, desarrolladas con técnicas de tipo particional y espectral. Los experimentos se realizan con la bases de de datos MIT/BIH.	2009	1	https://www.researchgate.net/publication/303722155_Clasificacion_de_arritmias_en_registros_Holter_empleando_analisis_no_supervisado_de_tipo_particional_y_espectral
176	Caracterización de señales ECG empleando un modelo del pulso cardíaco y dinámica no lineal: Una prueba piloto	VI Semana Técnica de Ingenierías Eléctrica y Electrónica Universidad Nacional de Colombia,Sede Manizales	D. H. Peluffo-Ordóñez, C. Ospina, G. Olivard-Tost, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	En este trabajo se presenta una prueba piloto de una nueva técnica de caracterización de señales ECG empleando un modelo de pulso cardíaco y técnicas de análisis de sistemas no lineales. Las señales empleadas en este estudio son extraídas de la base de datos de arritmias del MIT (MIT-BIH). La caracterización se hace a partir de la sintonización secuencial de los parámetros del modelo por cada latido. Para esto se desarrolla una etapa de reproceso para eliminar las ondas P y T de cada latido, de forma que la señal sea, morfológicamente, comparable con la respuesta del modelo. La comparación se realiza estimando el grado de disimilitud de las señales a través del algoritmo DTW. Adicionalmente se realiza un análisis de bifurcaciones del modelo para estudiar la correlación de la respuesta del modelo con la presencia del alguna patología o falla en el sistema de adquisición de la señal.	2009	1	http://diegopeluffo.com/publicaciones/STIEE2009.pdf
177	Clasificación de arritmias ventriculares empleando clustering particional y características morfológicas del QRS	XIV Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2009	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	En este trabajo se desarrolla una metodología para la clasificación de arritmias ventriculares de tipo extrasístole ventricular y bloqueo de rama izquierda y derecha con respecto a latidos normales de la base de datos de arritmias MIT-BIH, empleando características morfológicas del complejo QRS y clasificación no supervisada de tipo particional. El sistema propuesto incluye etapas de preproceso, extracción de características y clasificación no supervisada. El preproceso consiste en centrar y normalizar todas las señales. La extracción de características se realiza utilizando la reconstrucción de la señal a través del modelo paramétrico de Hermite con parámetros óptimos y características morfológicas. En la etapa de clustering se aplican los algoritmos H-means y K-harmonics deducidos del clustering iterativo (genérico) basado en centroides. Además, se realiza una modificación del algoritmo en el sentido de su inicialización utilizando el criterio max-min para garantizar y mejorar la convergencia. El desempeño del sistema para registros de la base de datos MIT/BIH, en promedio es de Se = 97,53 %, Sp = 93,7 %, siendo comparable con resultados publicados en la literatura.	2009	1	https://www.researchgate.net/publication/303722074_Clasificacion_de_arritmias_ventriculares_empleando_clustering_particional_y_caracteristicas_morfologicas_del_QRS
178	Metodología para la reconstrucción y extracción de características del complejo QRS empleando el modelo paramétrico de Hermite	V Semana Técnica de Ingenierías Eléctrica y Electrónica. Universidad Nacional de Colombia, sede Manizales	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	En este trabajo se desarrolla una metodología para la reconstrucción y caracterización de los complejos QRS empleando el modelo paramétrico de Hermite. Los complejos son extraídos de la base de datos MIT-BIH. La reconstrucción se realiza empleando el valoróptimovalor´valoróptimo del parámetro de escala de las bases de Hermite obtenido mediante la minimización de la disimilitud de la señalse˜señal original y la reconstruida. Se emplea DTW como medida de disimilitud. Adicionalmente, se presenta un método para obtener la cantidad mínima de bases que generan una reconstrucción con alta confiabilidad basado en la comparación de los espectros de frecuencia en el rango de 1 − 20 Hz. La evaluación de la caracterización se realiza mediante el algoritmo de clustering K-means Max-Min.	2008	1	https://www.researchgate.net/publication/303721985_Metodologia_para_la_reconstruccion_y_extraccion_de_caracateristicas_del_complejo_QRS_basada_en_el_modelo_parmetrico_de_Hermite
179	Optimización del algoritmo DTW basada en la Naturaleza Estadística de las Disimilitudes	XIII Simposio de Tratamiento de Señales, Imágenes y Visión Artificial. STSIVA 2008	D. H. Peluffo-Ordóñez, E. Delgado, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Se presenta un método para la optimización de la DTW en aplicaciones de clustering basado en restricciones globales que se obtienen mediante un estudio de la naturaleza de los momentos estadísticos de las disimilitudes. El estudio se realiza extrayendo vectores representativos que corresponden a latidos de 16 tipos de arritmia de los diferentes registros de la base de datos MIT – BIH. El método presenta una diferencia promedio de las disimilitudes de la diagonal principal de 1.78*10-4 y reduce considerablemente el tiempo de procesamiento para el cálculo de la disimilitud. Este método resulta útil para procesos de clustering porque reduce el costo computacional sin alterar el valor de las disimilitudes.	2008	1	https://www.researchgate.net/publication/303722228_Optimizacion_de_la_DTW_basada_en_la_naturaleza_estadistica_de_las_disimilitudes
180	Detección de Arritmias de tipo Bloqueo de Rama mediante Análisis no Supervisado y Morfología del QRS	III Congreso de Bioingeniería e Ingeniería Biomédica	D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo, G. Castellanos-Domínguez	Se presenta un método para clasificar arritmias ventriculares de tipo bloqueo de rama izquierda (L) y derecha (R) con respecto a latidos normales (N) de la base de datos de arritmias de la MIT-BIH utilizando clasificación no supervisada debido principalmente a la variabilidad morfológica entre registros. Se desarrolla una etapa de extracción de características basada en la morfología del latido y una etapa de clustering que utiliza el algoritmo de búsqueda heurística k-means modificado en el sentido de su inicialización utilizando el criterio max-min. El sistema presenta resultados comparables con los reportados en la literatura. ABSTRACT This work describes a method to classify left (L) and right (R) bundle block branch beats as well as normal (N) beats from MIT-BIH arrhythmia database. Un-supervised classification is preferred in our approach due to factors that add variability, such as: signal length and different dynamic behaviour and morphology (different patient physiology and/or pathology). Features are obtained from heartbeat morphology. The classification algorithm is a k-means clustering, incorporating an initial partition stage based on max-min criterion. The proposed method shows comparable results to those reported in literature.	2008	1	https://www.researchgate.net/publication/282611786_DETECCION_DE_ARRITMIAS_DE_TIPO_BLOQUEO_DE_RAMA_MEDIANTE_ANALISIS_NO_SUPERVISADO_Y_MORFOLOGIA_DEL_QRS
164	Identification of cardiac arrhythmias by means of Wavelet Packet-based features	VII Seminario Internacional de Procesamiento y Análisis de Información Médica. SIPAIM 2011	D. H. Peluffo-Ordóñez, C. Castro-Hoyos,F. J. Martínez-Tabares, G. Castellanos-Domínguez	Cardiac arrhythmias are important indicators of heart diseases, they refer to electrical conduction problems and therefore their diagnosis is of high clinical interest. However, timely detection is difficult due to factors such as computational cost, large amount of heartbeats per record, morphology variability, infrequency and irregularity of pathological heartbeats. In this work, wavelet transform computed through wavelet packets is applied over electrocardiographic (ECG) signals as a method to characterize and identify normal ECG signals and some arrhythmias such as atrial fibrilation (AF) and life threaded arrhythmias, drawn from MIT databases.	2011	1	https://www.researchgate.net/publication/303722554_Identification_of_cardiac_arrhythmias_by_means_of_Wavelet_Packet-based_features
304	Automatic graph building approach for spectral clustering	Iberoamerican Congress on Pattern Recognition	Andrés Eduardo Castro-Ospina, Andrés Marino Álvarez-Meza, César Germán Castellanos-Domínguez	Spectral clustering techniques have shown their capability to identify the data relationships using graph analysis, achieving better accuracy than traditional algorithms as k-means. Here, we propose a methodology to build automatically a graph representation over the input data for spectral clustering based approaches by taking into account the local and global sample structure. Regarding this, both the Euclidean and the geodesic distances are used to identify the main relationships between a given point and neighboring samples around it. Then, given the information about the local data structure, we estimate an affinity matrix by means of Gaussian kernel. Synthetic and real-world datasets are tested. Attained results show how our approach outperforms, in most of the cases, benchmark methods.	2013	10	https://link.springer.com/chapter/10.1007/978-3-642-41822-8_24
181	Analysis of the effects of linear and non-linear distortions on QPSK modulated signals for optical channels	11th IEEE International Conference on Computer and Information Technology. CIT 2011	D. H. Peluffo-Ordóñez, N. Guerrero-Gonzales, J. Salazar-Cuellar, M. Vergara-Hidalgo, O. M. Díaz-Betancourt	In this paper, we present some achievements of the degree thesis entitled “Analysis of the effects of linear and non-linear distortions on QPSK modulated signals for optical channels” developed by the two first authors. The pertinence of this work lies in that digital signal processing have currently taken an important place in Communications, in particular, Optical Communications. Current tran smission systems are supported by DSP based devices to carry out filtering and equalization tasks. For filtering, the first stage is to understand the distortion and establish a model (when possible). In this work, we present a brief state of the art of linear and non-linear distortions in optical channels developed in the last thirteen years. Also, we present an useful and specific theoretical background about distortions and digital modulation formats oriented to optical	2011	22	http://diegopeluffo.com/publicaciones/CIT2011.pdf
182	Fingertips Segmentation of Thermal Images and Its Potential Use in Hand Thermoregulation Analysis	HAIS: International Conference on Hybrid Artificial Intelligence Systems	A. E. Castro-Ospina, A. M. Correa-Mira, I. D. Herrera-Granda, D. H. Peluffo-Ordóñez, H. A. Fandiño-Toro	Thermoregulation refers to the physiological processes that maintain stable the body temperatures. Infrared thermography is a non-invasive technique useful for visualizing these temperatures. Previous works suggest it is important to analyze thermoregulation in peripheral regions, such as the fingertips, because some disabling pathologies affect particularly the thermoregulation of these regions. This work proposes an algorithm for fingertip segmentation in thermal images of the hand. By using a supervised index, the results are compared against segmentations provided by humans. The results are outstanding even when the analyzed images are highly resized.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_38
183	Optimization of the University Transportation by Contraction Hierarchies Method and Clustering Algorithms	HAIS: International Conference on Hybrid Artificial Intelligence Systems	Israel D. Herrera-GrandaLeandro, L. Lorente-Leyva, Diego H. Peluffo-Ordóñez, Robert M. Valencia-Chapi, Yakcleem Montero-Santos, Jorge L. Chicaiza-Vaca, Andrés E. Castro-Ospina	This research work focuses on the study of different models of solution reflected in the literature, which treat the optimization of the routing of vehicles by nodes and the optimal route for the university transport service. With the recent expansion of the facilities of a university institution, the allocation of the routes for the transport of its students, became more complex. As a result, geographic information systems (GIS) tools and operations research methodologies are applied, such as graph theory and vehicular routing problems, to facilitate mobilization and improve the students transport service, as well as optimizing the transfer time and utilization of the available transport units. An optimal route management procedure has been implemented to maximize the level of service of student transport using the K-means clustering algorithm and the method of node contraction hierarchies, with low cost due to the use of free software.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_9
184	Fingertips Segmentation of Thermal Images and Its Potential Use in Hand Thermoregulation Analysis	HAIS: International Conference on Hybrid Artificial Intelligence Systems	A. E. Castro-Ospina, A. M. Correa-Mira, I. D. Herrera-Granda, D. H. Peluffo-Ordóñez, H. A. Fandiño-Toro	Thermoregulation refers to the physiological processes that maintain stable the body temperatures. Infrared thermography is a non-invasive technique useful for visualizing these temperatures. Previous works suggest it is important to analyze thermoregulation in peripheral regions, such as the fingertips, because some disabling pathologies affect particularly the thermoregulation of these regions. This work proposes an algorithm for fingertip segmentation in thermal images of the hand. By using a supervised index, the results are compared against segmentations provided by humans. The results are outstanding even when the analyzed images are highly resized.	2018	23	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_38
185	Optimization of the University Transportation by Contraction Hierarchies Method and Clustering Algorithms	HAIS: International Conference on Hybrid Artificial Intelligence Systems	Israel D. Herrera-GrandaLeandro, L. Lorente-Leyva, Diego H. Peluffo-Ordóñez, Robert M. Valencia-Chapi, Yakcleem Montero-Santos, Jorge L. Chicaiza-Vaca, Andrés E. Castro-Ospina	This research work focuses on the study of different models of solution reflected in the literature, which treat the optimization of the routing of vehicles by nodes and the optimal route for the university transport service. With the recent expansion of the facilities of a university institution, the allocation of the routes for the transport of its students, became more complex. As a result, geographic information systems (GIS) tools and operations research methodologies are applied, such as graph theory and vehicular routing problems, to facilitate mobilization and improve the students transport service, as well as optimizing the transfer time and utilization of the available transport units. An optimal route management procedure has been implemented to maximize the level of service of student transport using the K-means clustering algorithm and the method of node contraction hierarchies, with low cost due to the use of free software.	2018	23	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_9
186	Advances in Homotopy Applied to Object Deformation	IWBBIO International Conference on Bioinformatics and Biomedical Engineering	José Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A. Becerra-Botero, Diego Hernán Peluffo-Ordóñez, César Germán Castellanos-Domínguez.	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	2	https://link.springer.com/chapter/10.1007%2F978-3-319-78759-6_22
187	Wearable Textil for Accident Prevention for Babies in Crawl Phase	Information Systems and Computer Science (INCISCOS)	Javier Chico Morales, Sandra Karina Narváez Pupiales, Ana Cristina Umaquinga Criollo, Paúl David Rosero Montalvo.	In the present investigation an electronic safety system is developed for babies in the stage of crawling, in order to alert a possible accident to the people who are in charge of their care in areas considered risky. The intelligent textile is integrated in a garment type harness that is connected to a crawling knee pads containing Magnetic Reed sensors, these are responsible for detecting the magnetic tapes previously placed in sites considered dangerous. These areas are chosen by quantifying the distance of the baby relative to its crawling speed; if the infant is in a possible accident zone, the system sends alert messages via an IoT platform. As a result of the system there is an average reaction time of 7.6 seconds with an average current consumption of 90 mA every approximately 12 seconds.	2017	2	https://ieeexplore.ieee.org/document/8328087/
188	Neighborhood Criterion Analysis for Prototype Selection Applied in WSN Data	Information Systems and Computer Science (INCISCOS)	P.D. Rosero-Montalvo, A.C. Umaquinga-Criollo, S. Flores, L. Suarez, J. Pijal, K.L. Ponce-Guevara, D. Nejer, A. Guzman, D. Lugo, K. Moncayo	The present work presents an analysis of the neighborhood criterion for the prototype selection (PS) in supervised machine learning classification algorithms. To do this, we use the condensed neighbor algorithm CNN to eliminate redundant data with the normalization of the distance to the centroid of each data subset criterion. This is done, in order to obtain the training matrix of the most optimal model. A selection of neighborhood criterion has been created from the quantification of the balance between the performance of the classification and the reduction of data set (CER). As proof of the test, we performed: (i) CER and (ii) real-time tests with the implementation of the algorithm within the WSN. The result is a data reduction of up to 88 % and a performance of the kNN classifier of 75%. It is concluded that the criterion of neighborhood with normalized distance must be less than or equal to 0.2 and the implementation of kNN with k = 1 obtains the best CER.	2017	2	https://ieeexplore.ieee.org/document/8328096/
189	Prototype reduction algorithms comparison in nearest neighbor classification for sensor data: Empirical study	2017 IEEE Second Ecuador Technical Chapters Meeting (ETCM)	Paul Rosero-Montalvo; Diego H. Peluffo-Ordóñez; Ana Umaquinga; Andrés Anaya; Jorge Serrano; Edwin Rosero; Carlos Vásquez; Luis Suaréz-Zambrano	This work presents a comparative study of prototype selection (PS) algorithms. Such a study is done over data-from-sensor acquired by an embedded system. Particularly, five flexometers are used as sensors, which are located inside a glove aimed to read sign language. Measures were taken to quantify the balance between classification performance and reduction training set data (QCR) with k neighbors equal to 3 and 1 to force the classifier (kNN) to the maximum. Two tests were used: (a)the QCR performance and (b) the embedded system decision in real proves. As result the Random Mutation Hill Climbing (RMHC) algorithm is considered the best option to choose in this data type with removed instances at 87% and classification performance at 82% in software tests, also the classifier kNN must be with k=3 to improve the classification performance. In a real situation, with the algorithm implemented. The system makes correct decisions at 81% with 5 persons doing sign language in real time.	2017	2	https://ieeexplore.ieee.org/document/8247530/?reload=true
190	“Automatización de una máquina de construcción nacional madejadora de hilos para la Empresa IMBATEX”. Automation of a national construction machine winding machine for the IMBATEX Company	V congreso ecuatoriano de tecnologías de información y comunicación Tic.ec2017	Fernando Ortega Loza, Ana Umaquinga Criollo, Omar Oña Rocha, Jorge Terán Benalcázar, Cosme Mejía Echeverría.	The research presented in this paper intends the potentializing of Ecuadorian manufactured handicraft machinery, so that the production standards required by the companies are complied, in the specific case of a reeling machine made by the Imbatex Company, which produces yarn skein. The objectives of the investigation are: To define the machine state in function of weight error and yarn breakage and reduce the maximal error in the skein (at most 5%) as well as the yarn breaks (less than 0.1 per process). Particularly, a PLC, a three-phase frequency inverter and a HMI touch screen connected by modbus RS485 and Delta Q Link protocol were used. As well, indirect measurement is used along with an encoder sensor. A skein weight control system and a yarn breakage prevention system by means of velocity tests for different yarn types (predetermined by the company) are implemented. The proposed automation reaches a successful performance on reducing the average error in weight skein from 17.47% to 0.8%, and reducing the number of yarn breaks per process from 4.17 to 0.05.	2017	2	https://publicaciones.ucuenca.edu.ec/ojs/index.php/maskana/article/view/1460
216	PROPUESTA DE ANALISIS DE DATOS EN BIG DATA USANDO REDUCCION DE DIMENSIONALIDAD	CONGRESO JORNADAS FICA	A. C. Umaquinga-Criollo,D. H. Peluffo-Ordóñez,P. D. Rosero-Montalvo,M. V. Cabrera-Álvarez,J. C. Alvarado-Pérez, A. J. Anaya-Isaza	Today, the volume of available data is experiencing an exponential growing, introducing an emergent are so-called Big Data. Along with the data growing, the demand of tools, techniques and devices to store, transmit and process high-dimensional data (HD) is increased. Most available methodologies to process HD output abstract outcomes and user is not involved in the selection or parameter tuning processes of data analysis techniques. In this work, we propose a visual analysis methodology following principles of interactivity and controllability. Doing so, users (even non-expert ones) can intuitively select a dimensionality reduction method to generate intelligible representations for human beings.	2016	7	https://www.researchgate.net/publication/316056310_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva_Proposal_for_visual_analysis_of_Big_Data_using_interactive_dimensionality_reduction
191	“Evolución de los textiles inteligentes: revisión de literature”	Tecnologías Aplicadas a la Ingeniería. Capítulo 9 página 93-99. ISBN 978-9942-984-17-3	Rosero Edwin, Rosero Paul, Pamba Quishpe Lisseth, Chamba Evelyn, Umaquinga Ana.	Los generos textiles han sufrido grandes cambios a una velocidad impresionante, dando como re- sultado a la aparicio ́n de los textiles inteligentes; la primera generacio ́n de los textiles inteligentes solamente pueden detectar las condiciones medioambientales o est ́ımulos del mismo, la segunda generacio ́n son los textiles que tienen la capacidad de detectar y actuar frente a una determinada situacio ́n y los textiles ultra inteligentes son la tercera generacio ́n, mismos que pueden detectar, reaccionar y adaptarse a las condiciones y est ́ımulos del medio. Un textil ultra inteligente esencialmente consiste en una unidad, la cual trabaja como cerebro, con capa- cidad cognitiva, que razona y reacciona, siendo la unio ́n de diferentes a ́reas de conocimiento para su desarrollo y conocidos como Smart clothes. En el futuro los textiles inteligentes se presentan como la pro ́xima generacio ́n de fibras, tejidos y productos que se producira ́n gracias a sus enormes posibilidades y funcionalidades.	2016	2	https://www.researchgate.net/publication/316439057_EVOLUCIONEVOLUCI_EVOLUCION_DE_LOS_TEXTILES_INTELIGENTES_REVISION_DE_LITERATURA
192	Base  Legal  o  legitimidad  en  la  aplicación  de  la  Responsabilidad  Social  en  las  empresas  ecuatorianas	Revista  de  Administración  y  Finanzas  Volumen  4  Número  13  -  Octubre  -  Diciembre  2017,  ISSN  2410-342X	Saltos  Tatyana,  Umaquinga  Ana	This research was conducted in order to know the\r\nperception of students in the last semesters of racing\r\nDegree in Business This research aims to analyze\r\nCorporate Social Responsibility (CSR) from the areas of\r\nlegality and legitimacy. The aim is to contribute with\r\nvalue criteria to the debate on legitimate actions that go\r\nbeyond legal aspects, strengthen the position and\r\ncompetitiveness of companies in front of its stakeholders.\r\nFor this, a case study of 2 companies that are part of the\r\nranking of the best companies in Ecuador listed in the\r\nEkos Magazine during 2016 is carried out. The results\r\nsuggest that there is an institutionalized commitment of\r\ncompanies to improve the conditions of the stakeholders.	2017	2	http://www.ecorfan.org/bolivia/researchjournals/Administracion_y_Finanzas/vol4num13/Revista_de%20_Administraci%C3%B3n_y_Finanzas_V4_N13.pdf
193	"Dispositivo  de  seguridad  para  motos  utilizando  SMS  y  GPRS"	Safety  device  for  motorcycles  using  SMS  and  GPRS	Omar  Ricardo  Oña-Rocha,  Julio  Rogelio  Tamayo-Morocho,  Ana  Cristina  Umaquinga-Criollo,  Fabián  Geovanny  Cuzme-Rodríguez,  Carlos  Hernán  Pupiales-Yépez,  Diego  Hernán  Peluffo-Ordoñez	This  research  article  addresses  aspects  based  on  the \r\ndesign,\r\nconstruction and implementation of a security device to be \r\nused in a motor bike as a strategy to prevent stealing or recover it \r\ncase  it  was  stolen.  To  this  end,  It  is  used  mobile  devices  under \r\nAndroid systems, SMS and GPRS transmission. The device allows \r\nfor monitoring and tracking of the stolen motor bikes in real time \r\nby sending an alert via SMS and current geographic position to a \r\nmobile phone as well as a web server. Moreover, it is important to \r\nhighlight how the integration of current technologies in \r\nelectronics \r\nand communications under the concept of Internet of Things (IoT) \r\nfacilitates     communication \r\nbetween \r\nmobile \r\ndevices     and \r\ntransportation  vehicles  such  as  motorcycles  and  cars.  It  was \r\nnecessary  to  analyze  the  working  principles  and  limitations  of \r\nsi\r\nmilar devices available in the market to establish the baseline for \r\ndesigning and implementing the proposed system.	2017	2	http://fcii.ute.edu.ec/inciscos/2017/assets/Memorias.pdf
231	Face Detection and Classification Using Eigenfaces and Principal Component Analysis: Preliminary Results	INCISCOS 2017	Richard Mejía-Campos, Diego Néjer-Haro, Santiago Recalde-Avincho, Paul Rosero-Montalvo, Diego Peluffo-Ordóñez	This work is a Scientific Track paper corresponding to the area of Intelligent Systems. This paper presents a facial recognition approach based on the Eigenfaces method as well as Principal Component Analysis (PCA) as algorithm of processing and cleaning images, respectively. The classification was performed by using the Euclidean distance between the facial characters stored in a database and new images captured in an interface with similarly coded developed in MatLab. As main results, we obtained: (i) 68.9% of classification accuracy when using different components of stored faces, (ii) 91.43% of classification performance when storing 3 components for each face and evaluating more users for training model in seven controlled experiments.	2017	7	https://ieeexplore.ieee.org/document/8328124/
232	Wearable Textil for Accident Prevention for Babies in Crawl Phase	INCISCOS 2017	Inti Javier Chico Morales, Sandra Karina Narváez Pupiales, Ana Cristina Umaquinga Criollo, Paúl David Rosero Montalvo	In the present investigation an electronic safety system is developed for babies in the stage of crawling, in order to alert a possible accident to the people who are in charge of their care in areas considered risky. The intelligent textile is integrated in a garment type harness that is connected to a crawling knee pads containing Magnetic Reed sensors, these are responsible for detecting the magnetic tapes previously placed in sites considered dangerous. These areas are chosen by quantifying the distance of the baby relative to its crawling speed; if the infant is in a possible accident zone, the system sends alert messages via an IoT platform. As a result of the system there is an average reaction time of 7.6 seconds with an average current consumption of 90 mA every approximately 12 seconds.	2017	7	https://ieeexplore.ieee.org/document/8328087/
255	On the relationship between dimensionality reduction and spectral clustering from a kernel viewpoint	Distributed Computing and Artificial Intelligence, 13th International Conference	Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina, X Blanco-Valencia, Juan C Alvarado-Pérez, Roberto Therón, A Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	9	https://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
