196	Implementation a HERIC inverter prototype connected to the grid controlled by SOGI-FLL	Power Electronics and Power Quality Applications (PEPQA), 2015 IEEE Workshop on	David Gámez Patiño, Edison Guaina Erira, Javier Revelo Fuelagän, Edisson Escobar Rosero	This paper presents a feasible implementation of a single phase inverter prototype via a Highly Efficient and Reliable Inverter Concept (HERIC) topology, which is connected to the grid through a phase and frequency synchronization system by means of a Second Order Generalized Integrator - Frequency Locked Loop (SOGI-FLL). The chosen topology for the inverter design-unlike a full H-bridge (FB) inverter-incorporates two transistors in the output aimed at preventing reactive power transfer between the output filter and input capacitor when zero-crossing. Furthermore, proposed inverter implementation presents low leakage currents, and increases HERIC system efficiency. Moreover, the SOGI-FLL chosen for connecting the HERIC inverter to the grid provides - even under harmonic distortion - a fast and accurate frequency tracking. The prototype implementation can be divided into two parts: First, the power inverter HERIC is implemented, which holds four transistors MOSFET IRF730 (400V-10A) in a FB topology, as well as two IGBT transistors GP10NC60KD (600V-10A). In addition, in order to protect all the devices and ensure a well transistor conmmuation, four diodes type SF54 (200V-5A) are located between emisor and collector from all transistors. Second, the synchronization system is implemented on an Arduino Due digital platform.	2015	31	https://ieeexplore.ieee.org/abstract/document/7168209/
197	An estimation method of state of charge and lifetime for lead-acid batteries in smart grid scenario	Innovative Smart Grid Technologies Latin America (ISGT LATAM), 2015 IEEE PES	Danny Montenegro, Simón Rodríguez, Javier Revelo Fuelagán, John Barco Jiménez	This work presents mathematical model of batteries AGM lead acid type that form part of a photovoltaic generating system. The proposed model allows estimation of the voltage of the battery and the state of charge with the objective of designing a controller to create greater duration, efficiency and autonomy of the system. Additionally, we present a mathematical model to estimate the useful life of the battery degraded due to corrosion, cycle, and the state of charge that permits evaluation of the loss of storage capacity in a general distribution scenario. Finally, experimental results and simulations obtained from the monitoring of a bank of batteries in a photovoltaic system are analyzed to validate the proposed model of state of charge. Furthermore, we will present the results of the evaluation of the useful life of the battery in two case studies in the framework of smart grid considering the functioning of a photovoltaic generator under different configurations.	2015	31	https://ieeexplore.ieee.org/abstract/document/7381216/
198	SOGI-FLL for synchronization and fault detection in an inverter connected to the grid	Innovative Smart Grid Technologies Latin America (ISGT LATAM), 2015 IEEE PES	David Gamez Patiño, Edison Geovanny Guamá Erira, Edisson Escobar Rosero, Javier Revelo Fuelagán	This paper presents a theoretical analysis and simulation for the design and implementation of a Second Order Generalized Integrator - Frequency Locked Loop (SOGI-FLL) aimed at synchronization and fault detection when connecting an inverter to the utility grid. Such an inverter is implemented in a Highly-Efficient-and-Reliable- Inverter-Concept (HERIC) topology. The two main aims of this work are: First, the frequency and phase synchronization of the HERIC power inverter with the grid through the SOGI-FLL. Second, the detection of abnormal conditions that may occur in the coupling point system by analyzing changes in frequency, phase shifts and amplitude variations. This is done by complying with the IEEE 1547 standard for disconnecting generation systems to the grid in case of failure. Finally, from the experimental results, it can be concluded that the SOGI-FLL system is an appropriate alternative for controlling the injection of energy process into the grid, as well as for detecting possible grid faults.	2015	31	https://ieeexplore.ieee.org/abstract/document/7381264/
199	Multiple kernel learning for spectral dimensionality reduction	Iberoamerican Congress on Pattern Recognition	Diego Hernán Peluffo-Ordóñez, Andrés Eduardo Castro-Ospina, Juan Carlos Alvarado-Pérez, Edgardo Javier Revelo-Fuelagán	This work introduces a multiple kernel learning (MKL) approach for selecting and combining different spectral methods of dimensionality reduction (DR). From a predefined set of kernels representing conventional spectral DR methods, a generalized kernel is calculated by means of a linear combination of kernel matrices. Coefficients are estimated via a variable ranking aimed at quantifying how much each variable contributes to optimize a variance preservation criterion. All considered kernels are tested within a kernel PCA framework. The experiments are carried out over well-known real and artificial data sets. The performance of compared DR approaches is quantified by a scaled version of the average agreement rate between K-ary neighborhoods. Proposed MKL approach exploits the representation ability of every single method to reach a better embedded data for both getting more intelligible visualization and preserving the structure of data.	2015	31	https://link.springer.com/chapter/10.1007/978-3-319-25751-8_75
200	Implementation of an HB-LED driver with PFC and output power control	Power Electronics and Power Quality Applications (PEPQA), 2015 IEEE Workshop on	Jorge Andrés Chamorro Martínez, Mario Hernán Arciniegas Mejía, Javier Revelo Fuelagán	This work presents a novel HB-LEDs driver designed to solve some of the problems found in commercial LED lamp drivers. This driver includes dimming capability designed for intelligent lightning applications and incorporates a power factor correction method (PFC) to prevent negative effects of current distortion over the mains circuit. The circuit is composed by two main sections: power section and control section. The power section consists on a multi level electronic power converter where the first stage has a boost topology with a current controller performing the PFC function, based on hysteresis comparison. The second stage has a buck topology and it is designed to regulate the power delivered to the LED strings. Both stages are coupled with a digital controller which additionally serves to establish and track a power reference for the LED strings in order to vary the light intensity. A prototype was built based on the design for evaluation. The design implementation provided data that was analysed in terms of efficiency, harmonic distortion and power factor according to regulatory standards. The results were compared with commercial LED lamp drivers characteristics, obtaining significative improvement in energy quality indicators.	2015	31	https://ieeexplore.ieee.org/abstract/document/7168210/
201	Novel spectral characteristics of the electrical current waveform to quantifying power quality on LED lamps	Image, Signal Processing and Artificial Vision (STSIVA), 2014 XIX Symposium on, vol., no	Diego Hernán Peluffo-Ordónez, Edgardo Javier Revelo-Fuelagán	LED lamps are widely used in household, nonetheless\r\nthey are still non-linear. Therefore, LEDs need a power\r\nsupply system to correcting their operation, which introduces\r\nnonlinearities into the electrical grid and distortions on waveform.\r\nThen analysis and quantification of electrical signals is\r\nbecoming a key issue. This work presents a spectral analysis of\r\nanalysis of electric current signal in LEDs lamps which yields\r\na novel collection of characteristics and measures to quantify\r\nthe waveform quality. In particular, periodogram and Fourier\r\ntransform are considered. For experiments, two circuits are\r\nconsidered: one that corresponds to the commercial LEDs lamp\r\nconnected to AC source and another one incorporating a power\r\nfactor corrector. . Experimentally, the usefulness and applicability\r\nof proposed characteristics is proved.	2014	31	https://www.researchgate.net/profile/Diego_Peluffo/publication/286926800_Novel_spectral_characteristics_of_the_electrical_current_waveform_to_quantifying_power_quality_on_LED_lamps/links/56702b3308ae5252e6f1d472.pdf
202	Análisis no supervisado aplicado a la detección de arritmias cardiacas	Enfoque UTE	Mónica Moreno-Revelo, Sandra Patascoy-Botina, Andrés Pantoja-Buchelli, Javier Revelo Fuelagán, José Rodríguez-Sotelo, Santiago Murillo-Rendón, Diego Peluffo-Ordoñez	Una arritmia es una patología que consiste en la alteración de los latidos del corazón. A pesar de que el electrocardiograma de 12 derivaciones permite evaluar el comportamiento eléctrico del corazón para determinar ciertas patologías, existen algunas arritmias que son de difícil detección con este tipo de electrocardiografía. Por tanto, es necesario recurrir al uso del monitor Holter, debido a que facilita el registro de la actividad eléctrica del corazón durante largos periodos de tiempo, por lo general de 24 a 48 horas. Debido a la extensión de los registros proporcionados por el monitor, es común acudir al uso de sistemas computacionales para evaluar características diagnósticas y morfológicas de los latidos con el fin de determinar si existe algún tipo de anormalidad. Estos sistemas computacionales pueden basarse en técnicas supervisadas o no supervisadas de reconocimiento de patrones, pero teniendo en cuenta que en la primera opción el realizar una inspección visual de la gran cantidad de latidos presentes en un registro Holter, resulta ser una ardua tarea, además de implicar costos monetarios, en este trabajo se presenta el diseño de un sistema completo para la identificación de arritmias en registros Holter usando técnicas no supervisadas de reconocimiento de patrones. El sistema propuesto involucra etapas de pre-procesamiento de la señal, segmentación y caracterización de latidos, además de selección de características y agrupamiento. En este caso, la técnica utilizada es k-medias. Dichas etapas se aplican dentro del marco de una metodología basada en segmentos que mejora la detección de clases minoritarias. Asimismo, se considera criterios de inicialización que permiten mejorar las medidas de desempeño, en especial, la sensibilidad. Como resultado, se determina que usar k-medias con el criterio de inicialización máx-mín y un número de grupos igual a 12, permite obtener los mejores resultados, siendo: 99,36 %, 91,31 % y 99,16 % para exactitud, sensibilidad y especificidad, respectivamente.	2017	31	http://www.ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/125
204	On the effect of inverse problem weighted solutions for epileptic sources localization	Symposium on Signal Processing, Images and Computer Vision (STSIVA)	Melissa E Acosta-Muñoz, Hugo A Paredes-Argoty, E Javier Revelo-Fuelagán, Diego H Peluffo-Ordóñez	Within the context of epileptic sources localization from electroencephalographic signals, this work presents an exploratory study aimed at studying the effect of channel weighting on the estimation of the inverse problem solution. In this study, we consider two weighting approaches followed from a relevance feature analysis based on variance and energy criteria. Such approaches are compared by measuring the difference between the estimated source activity and the true power of the simulated sources in terms of the Earth mover's distance. Experimental results show that the incorporation of proper weighting factors into a LORETA-driven solution, localization may be improved. As well, the physiological phenomenon of the brain activity is more precisely tracked.	2015	31	https://ieeexplore.ieee.org/abstract/document/7330448/
205	Spectral analysis of electric current in LEDs Lamps	Simposio Internacional sobre la Calidad de la Energía Eléctrica - SICEL	Diego Hernán Peluffo Ordoñez, Edgardo Javier Revelo Fuelagán	This work presents an analysis of electric current signal in LEDs lamps. Electrical signals are measured in two circuits, one that corresponds to the commercial LEDs lamp connected to AC source and another one incorporating a control system into the LEDs lamp. Such control system works as a power factor correction (PFC) and is designed by using a boost converter and a current controller. Signals are analyzed in terms of frequency-based representations oriented to estimate the power spectral density (PSD). In this study, two approaches are used: Discrete Fourier transform and periodogram. The goal of this work is to show that more complex PSD estimation methods can provide useful information for studying the quality energy in electric power systems, which is comparable with that provided by traditional approaches. In particular, periodogram shows to be a suitable alternative exhibiting meaningful changes along its spectral power plotting when analyzing the circuit without applying PFC. As a result of this work, a set of LEDs lamps characteristics is introduced, including a novel periodicity factor.	2013	31	https://revistas.unal.edu.co/index.php/SICEL/article/view/38955
206	Spectral analysis of electric current in compact fluorescent lamps	SICEL in Asunción, Paraguay, November 2-4, 2011.	D. H. Peluffo-Ordóñez, E. J. Revelo-Fuelagan, G. A. Alarcón-Lancheros, O. M. Diaz-Betancourt	This work presents an analysis of electric current\r\nsignal in compact fluorescent lamps (CFLs). Electrical signals are\r\nmeasured in two circuits, one that corresponds to the CFL shunt\r\nconnected with the AC source and another one that incorporates\r\na control system into the CFL. Such control system works as a\r\npower factor correction (PFC) and is designed by employing a\r\nboost converter and a current controller. Signals are analyzed in\r\nterms of frequency-based representations oriented to estimate the\r\npower spectral density (PSD). In this study, three approaches are\r\nemployed: Fourier transform, periodogram and a window-based\r\nPSD. The goal of this work is to show that more complex PSD\r\nestimation methods can provide useful information for studying\r\nthe quality energy in electric power systems. Proposed spectral\r\nanalysis represents an alternative to traditional approaches.	2011	31	http://diegopeluffo.com/publicaciones/SICEL2011.pdf
207	Diseño de una técnica de control con banda de histéresis adaptativa para corrección del factor de potencia = [Design of a control technique with hysteresis band  Adaptive Power Factor Correction]	Tesis de Maestría	Revelo Fuelagán, Edgardo Javier	This document shows the theoretical, analytical and experimental studies, developed in the master thesis. The work focuses on modeling and designing a control technique for a Boost converter, so that it functions as power factor corrector and also regulates the output voltage.\r\n For this variable structure system, the control technique is based on adaptive hysteresis band, characterized by the presence of several parameters, of which some are fixed and others are adapted depending on the load to be connected.\r\n The system is modeled in the states space, we obtain the numerical solution for the electronic converter using an algorithm based on events, because it requires a high precision at the moment of describing the evolution of the system signals when they collide with the hysteresis band boundaries. The conditions and ranges of operation are characterized in continuous conduction mode, both the components values of the Boost converter as the parameters values of the hysteresis band, in such a way that fulfills the control objectives and it can perform a physical implementation.\r\n The theoretical and simulation results are validated with an experimental prototype design of the Boost electronic converter, by comparing the levels of the input current harmonics with the limits set by the European international standard IEC 61000-3-2.	2009	31	http://www.bdigital.unal.edu.co/4418/
208	Comparación entre TCP y UDP para Redes de Sensores Aplicado a Internet de las Cosas	XI CONGRESO DE CIENCIA Y TECNOLOGIA ESPE 2016	Rosero Paul, Rosero Edwin	Electronic systems with technological advancement tend to connect to data networks to provide better services to people, Internet of Things is the way of remotely communicating devices that previously couldn't, communication M2M (machine to machine) should be most reliable way to ensure data transfer, TCP and UDP are protocols transport layer TCP / IP model to implement a sensor network with a view to applications Internet of Things, free platforms like Intel Galileo Gen 2 allow prototypes a quick and effective way to present solutions with high and optimal processing of information that give way to network connectivity. TCP enables reliable delivery of high data rates to the network that influences the response time of the processor and network, while UDP is light computational load, but does not reveal whether the data has reached its destination.	2016	7	https://www.researchgate.net/publication/315680066_Comparacion_entre_TCP_y_UDP_para_Redes_de_Sensores_Aplicado_a_Internet_de_las_Cosas
209	Mejoramiento de las Capacidades Tecnológicas en los Sectores rurales de la Provincia de Imbabura	REVISTA CIENCIA ESPE	Stefany Flores Armas, Paul Rosero Montalvo, Edgar Maya Olalla, Diego Peluffo\r\nÓrdoñez	The engineering degree program in Electronics and Communication\r\nNetworks from Universidad Técnica del Norte, with the aim of strengthening the\r\nsociety service processes, has created a project that benefits the population of the\r\nrural areas of the province of Imbabura. Such a project has as a main goal to\r\nreduce the digital divide in high schools by providing access to information and\r\ncommunication technologies to Imabura’s rural population. To execute the\r\nimproving technological capabilities project, it is considered as a population of\r\ninterest, individuals (men and women) older than 12 from different social levels,\r\ncultures and ethnic backgrounds. Methodologically, training programs based on a\r\nneeds' assessment are formulated, which are subsequently evaluated with the aim\r\nof reducing the digital illiteracy level in the population of interest. In turn, improving\r\nits technological deficiencies and its quality of life. Strategically, the Community\r\nInfocentros and school labs are considered, since they are reference points for\r\nreaching communities. Along with them, project executors are able to making\r\ntraining on basic office tools, basics on communication networks, Internet,\r\ncomputer maintenance, and men and women management of web pages.\r\nFollowing the training, it was observed that, in the fields of action, participants met\r\ntheir expectations, abilities and skills acquired technology issues. In this paper, the\r\nmethodological aspects and main results of the project are presented.	2017	7	https://ia601608.us.archive.org/0/items/Articulo11_201705/Arti%CC%81culo%2011.pdf
210	Human-Sitting-Pose Detection Using Data Classification and Dimensionality Reduction	Ecuador Electrical Chapters Meeting	Paul Rosero-Montalvo, Santiago Nuñez-Godoy, Vanessa Alvear-Puertas, Staling Realpe-Godoy, Edwin Pujota-Cuascota, Henry Farinango-Endara, Iván Navarrete-Insuasti, Franklin Vaca-Chapi, Diego H. Peluffo	The research area of sitting-pose analysis allows for preventing a range of physical health problems mainly physical. Despite that different systems have been proposed for sitting-pose detection, some open issues are still to be dealt with, such as: Cost, computational load, accuracy, portability, and among others. In this work, we present an alternative approach based on a sensor network to acquire the position-related variables and machine learning techniques, namely dimensionality reduction (DR) and classification. Since the information acquired by sensors is high-dimensional and therefore it might not be saved into embedded system memory, a DR stage based on principal component analysis (PCA) is performed. Subsequently, the automatic posed detection is carried out by the k-nearest neighbors (KNN) classifier. As a result, regarding using the whole data set, the computational cost is decreased by 33 % as well as the data reading is reduced by 10 ms. Then, sitting-pose detection task takes 26 ms, and reaches 75% of accuracy in a 4-trial experiment.	2016	7	http://ieeexplore.ieee.org/document/7750822/
211	Different perspectives for kernel spectral clustering: A theoretical study	2016 IEEE Ecuador Technical Chapters Meeting (ETCM)	D. H. Peluffo-Ordóñez, P. D. Rosero, C. H. Pupiales, L. E. Suárez, E. D. Jaramillo, E. A. Maya, J. R. Michilena, C. A. Vásquez	Spectral clustering is a suitable technique to deal with problems involving unlabeled clusters and having a complex structure, being kernel-based approaches the most recommended ones. This work aims at demonstrating the relationship between a widely-recommended method, so-named kernel spectral clustering (KSC) and other well-known approaches, namely normalized cut clustering and kernel k-means. Such demonstrations are done by following a primal-dual scheme. Also, we mathematically and experimentally prove the usability of using LS-SVM formulations with a model. Experiments are conducted to assess the clustering performance of KSC and the other considered methods on image segmentation tasks.	2016	7	http://ieeexplore.ieee.org/document/7750849/
212	ARQUITECTURA, SERVICIOS Y APLICACIONES DE Business Intelligence: Revisión de literatura	INCISCOS 2016	Paul Rosero, Edwin Rosero, Luis Beltran, Diego Peluffo and Carlos Pupiales	Business Intelligence (BI) es el conjunto de\r\nestrategias y herramientas para analizar gran cantidad de volúmenes\r\nde datos con el fin de encontrar patrones o tendencias de consumo\r\nde las personas y establecer estrategias de negocio, para lograr este\r\nobjetivo es necesario contar con servicios y aplicaciones como\r\nRealTime BI, Social BI, Cloud BI, BI 3.0, Business Analitics y\r\nMobile BI. Todo el proceso de BI es soportado por diferentes análisis\r\nque implementan algoritmos de machine learning en grandes\r\nvolúmenes y diferentes fuentes de datos, considerado como Big Data.\r\nEn este trabajo se hace relación a las funcionalidades y los\r\nrequerimientos necesarios de BI desde un concepto inicial hasta\r\nconceptos específicos y herramientas para su implementación.	2016	7	http://diegopeluffo.com/publicaciones/2016_INCISCOS_ArquiteturasBI.pdf
213	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA	INCISCOS 2016	A. J. Anaya-Isaza, D. H. Peluffo-Ordóñez, J. C. Alvarado-Pérez, J. Ivan-Rios, J. A. Castro-Silva, P. D. Rosero-Montalvo, D. F. Peña-Unigarro, J. A. Salazar-Castro, A. C. Umaquinga-Criollo.	Este trabajo presenta un estudio comparativo con métodos de reducción de la dimensión lineal, tales como: Análisis de Componentes Principales & Análisis Discriminante Lineal. El estudio pretende determinar, bajo criterios de objetividad, cuál de estas técnicas obtiene el mejor resultado de separabilidad entre clases. Para la validación experimental se utilizan dos bases de datos, del repositorio científico (UC Irvine Machine Learning Repository), para dar tratamiento a los atributos del data-set en función de confirmar visualmente la calidad de los resultados obtenidos. Las inmersiones obtenidas son analizadas, para realizar una comparación de resultados del embedimiento representados con RNX(K), que permite evaluar el área bajo la curva, del cual asume una mejor representación en una topología global o local que posteriormente genera los gráficos de visualización en un espacio de menor dimensión, para observar la separabilidad entre clases conservando la estructura global de los datos. Palabras clave— Análisis de componentes principales, Análisis discriminante lineal, Aprendizaje de máquina, Clasificación lineal, Clasificación supervisada, Métodos de reducción de la dimensión. Abstract— This paper presents a comparative study with methods of reducing the linear dimension, such as Principal Component Analysis & linear discriminant analysis. The study aims to determine, based on criteria of objectivity, which of these techniques get the best result of separability between classes. For experimental validation two databases, scientific repository (UC Irvine Machine Learning Repository) are used to provide treatment to the attributes of the data-set according to visually confirm the quality of the results. The dives obtained are analyzed, for comparison of results embedimiento represented with RNX (K), which evaluates the area under the curve, which assumes better representation in a local global topology or subsequently generates graphics display a space of smaller dimension, to observe the class separability preserving the overall structure of the data. Estudio comparativo de métodos... (PDF Download Available). Available from: https://www.researchgate.net/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA [accessed Jun 03 2018].	2016	7	https://www.researchgate.net/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA
214	Internet de las Cosas y Visión Artificial, Funcionamiento y Aplicaciones: Revisión de Literatura	ENFOQUE UTE	V. Alvear-Puertas, P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, J. Pijal-Rojas.	Internet of Things (or also known as IoT) is one of the technologies most named today because of the ability it envisages to connect all kinds of devices to the Internet. If to the potentialities of IoT we add another technology of high impact as It is the Artificial Vision we have a wide field of innovative applications, where the processing of images and video in real time allow the visualization of large amounts of data on the Internet. The main applications developed with IoT and Artificial Vision can be implemented in education, medicine, intelligent buildings, surveillance systems of people and vehicles, among others.This type of applications improves the quality of life of users, however, for their development an infrastructure is required that allows the convergence of different protocols and devices, but in a special way that can handle the different phases of the acquisition of images. In this work, a review of the beginnings, concepts, technologies and applications related to the Artificial Vision with the Internet of Things has been carried out to be able to understand in a precise way the impact of its application in daily life.	2016	7	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/121/127
215	EVOLUCION DE LOS TEXTILES INTELIGENTES: REVISION DE LITERATURA	CONGRESO JORNADAS FICA	Rosero Edwin, Rosero Paul, Pamba Quishpe Lisseth, Chamba Evelyn, Umaquinga Ana.	Los generos textiles han sufrido grandes cambios a una velocidad impresionante, dando como resultado a la aparicioón de los textiles inteligentes; la primera generación de los textiles inteligentes solamente pueden detectar las condiciones medioambientales o estímulos del mismo, la segunda generación son los textiles que tienen la capacidad de detectar y actuar frente a una determinada situación y los textiles ultra inteligentes son la tercera generación, mismos que pueden detectar, reaccionar y adaptarse a las condiciones y estímulos del medio. Un textil ultra inteligente esencialmente consiste en una unidad, la cual trabaja como cerebro, con capacidad cognitiva, que razona y reacciona, siendo la unión de diferentes áreas de conocimiento para su desarrollo y conocidos como Smart clothes. En el futuro los textiles inteligentes se presentan como la próxima generación de fibras, tejidos y productos que se producirán gracias a sus enormes posibilidades y funcionalidades.	2017	7	https://www.researchgate.net/publication/316439057_EVOLUCION_DE_LOS_TEXTILES_INTELIGENTES_REVISION_DE_LITERATURA
315	Case-Based Reasoning Systems for Medical Applications with Improved Adaptation and Recovery Stages	International Conference on Bioinformatics and Biomedical Engineering	X Blanco Valencia, D Bastidas Torres, C Piñeros Rodriguez, DH Peluffo-Ordóñez, MA Becerra, AE Castro-Ospina	Case-Based Reasoning Systems (CBR) are in constant evolution, as a result, this article proposes improving the retrieve and adaption stages through a different approach. A series of experiments were made, divided in three sections: a proper pre-processing technique, a cascade classification, and a probability estimation procedure. Every stage offers an improvement, a better data representation, a more efficient classification, and a more precise probability estimation provided by a Support Vector Machine (SVM) estimator regarding more common approaches. Concluding, more complex techniques for classification and probability estimation are possible, improving CBR systems performance due to lower classification error in general cases.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_3
194	Versión extendida: Propuesta de análisis visual de datos en Big Data usando reducción de dimensión interactiva. Proposal for visual analysis of Big Data using interactive dimensionality reduction"	III  JORNADAS  ACADÉMICAS  INTERNACIONALES  CISIC  2017	A.  C.  Umaquinga-Criollo,  D.  H.  Peluffo-Ordóñez,  P.  D.  Rosero-Montalvo,  M.  V.  Cabrera-Álvarez,  J.  C.  Alvarado-Pérez,  A.  J.  Anaya-Isaza	Today, the volumen of available data is experiencing an exponential growing, introducing an emergent are so-called Big Data. Along with the data growing, the demand of tools, techniques and devices to store, transmit and process high-dimensional data (HD) is increased. Most available methodologies to process HD output abstract outcomes and user is not involved in the selection or parameter tuning processes of data analysis techniques. In this work, we propose a visual analysis methodology following principles of interactivity and controlability. Doing so, users (even non-expert ones) can inuitively select a dimensionality reduction method to generate inteligible representations for human beings.	2016	2	https://www.researchgate.net/publication/316056310_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva_Proposal_for_visual_analysis_of_Big_Data_using_interactive_dimensionality_reduction
30	Big Data Analytics (BDA) en la Toma de Decisiones Empresariales. Big Data Analytics (BDA) in Business Decision Making	III Jornadas Académicas Internacionales CISIC 2017	MacArthur Cosme Ortega-Bustamante Ana Cristina Umaquinga-Criollo, Sandra Karina Narvaez-Pupiales, Diego Hernán Peluffo-Ordoñez	Ante el crecimiento exponencial y vertiginoso del volumen de los datos de diferente tipo: estructurados, semiestructurados y no estructurados provenientes de una variedad de fuentes entre ellas: la web, redes sociales, bases de datos, archivos de audio/video, datos transaccionales, sensores, comunicación máquina a máquina (denominado M2M). El área de Big Data pretende dar respuesta a los desafíos del tratamiento de la información. Es por ello, que el proceso de análisis de grandes volúmenes de datos Big Data Analytics (denominado BDA) facilita el descubrimiento de patrones, predicciones, fraudes, tendencias de mercado, comportamientos y preferencias de los clientes e información de utilidad, que no sería posible con las herramientas convencionales. BDA se convierte en una de las herramientas de soporte para la toma de decisiones empresariales y ventaja competitiva en tiempo real o en el menor tiempo posible frente a sus competidores, ofreciendo nuevos niveles de competitividad, procesos, modelos de negocio basados en datos y reducción del riesgo para conservar, fidelizar y captar una mayor cantidad de clientes generando un aumento en las fuentes de ingreso de las empresas. El presente artículo es de tipo exploratorio, descriptivo y documental. Se realiza un estudio descriptivo del impacto de Big Data Analytics (BDA) en el campo empresarial, así como un breve recorrido por sus tendencias, oportunidades, dificultades y retos. Este estudio pretende contribuir a la comunidad de investigadores, así como al personal de las empresas y a quienes se inician en el conocimiento de Big Data Analytics para una mejor comprensión en este campo. Abstract: By the exponential and vertiginous growth of the volume of data of different types: structured, semi-structured and unstructured from a variety of sources including: the web, social networks, databases, audio / video files, transactional data, sensors, machine-to-machine communication (denominated M2M). The Big-Data-area is intended to address the challenges of information processing. Therefore, the Big Data Analytics (BDA) process of large volumes of data facilitates the discovery of patterns, predictions, fraud, market trends, customer behaviours and preferences and useful information that would not be possible with conventional tools. BDA becomes one of the tools to support business decision-making and competitive advantage in real time or in the shortest possible time in relation its competitors, offering new levels of competitiveness, processes, business models based in data and risk reduction, to conserve, retain and attract a greater number of customers generating an increase in the sources of income of companies. This article is exploratory, descriptive and documentary. A descriptive study of the impact of Big Data Analytics (BDA) in the business field, as well as a brief tour of its tendencies, opportunities, difficulties and challenges. This study aims to contribute to the research community, as well as the staff of the companies and those who are introduced to the knowledge of Big Data Analytics for a better understanding in this field.	2017	2	https://www.researchgate.net/publication/318586255_BIG_DATA_ANALYTICS_BDA_EN_LA_TOMA_DE_DECISIONES_EMPRESARIALES_BIG_DATA_ANALYTICS_BDA_IN_BUSINESS_DECISION_MAKING
31	Portal Cautivo y Seguridad en la Implementación de un Sistema de Publicidad Multimedia Para Dispositivos Móviles en Centros Comerciales.	III JORNADAS ACADÉMICAS INTERNACIONALES CISIC 2017	Jaramillo Edgar Suárez Luis, Umaquinga Ana,Romo Nelson	En la actualidad los nuevos canales para difusión publicitaria han evolucionado de tal manera que es posible usando dispositivos móviles interconectados acceder a ella en cualquier lugar. La publicidad digital, posee muchas ventajas en comparación con la publicidad impresa tradicional, siendo su impacto mayor hacia los usuarios y su efecto sobre el ambiente es positivo, pues ayuda a reducir el uso de papel, los costos de publicidad e impresión, contribuye con la reutilización, mejora la organización de material publicitario, la disponibilidad para difusión a multidispositivo, entre otros, con el fin de incrementar la atención del cliente sobre el producto, servicio y lograr que lo utilice. En centros comerciales u otros lugares de masiva afluencia de personas, disponer de soluciones que regule el acceso a la red e internet a los usuarios y visitantes y además brinde seguridad en la conexión es algo muy importante. El presente trabajo de investigación se enfoca al diseño de un portal cautivo y establecimiento de políticas de seguridad aplicados a la publicidad digital hacia dispositivos móviles en el centro comercial Laguna Mall de la ciudad de Ibarra. Un gran porcentaje de locales de este centro comercial utilizan por una parte publicidad impresa que supone requerir de recurso humano para su difusión. El estudio propone utilizar un sistema de publicidad multimedia orientado a dispositivos móviles cuyo control de acceso de usuarios esté dado a través de un portal cautivo, con el fin de optimizar el uso del ancho de banda tanto para locales comerciales como para usuarios externos y a la vez como mecanismo de seguridad para la red inalámbrica del centro comercial. Palabras clave: portal cautivo, publicidad digital, publicidad en dispositivos móviles, publicidad multimedia, seguridad. .	2017	2	https://www.researchgate.net/publication/318509442_PORTAL_CAUTIVO_Y_SEGURIDAD_EN_LA_IMPLEMENTACION_DE_UN_SISTEMA_DE_PUBLICIDAD_MULTIMEDIA_PARA_DISPOSITIVOS_MOVILES_EN_CENTROS_COMERCIALES
217	Interactive data visualization using dimensionality reduction and similarity-based representations	CIARP 2016	D. F. Peña-Unigarro, P. Rosero-Montalvo, J. Revelo-Fuelagán, J. A. Castro-Silva, J. C. Alvarado-Pérez, R. Therón, C. M. Ortega-Bustamante, D. H. Peluffo-Ordóñez.	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2016	7	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
218	Dimensionality reduction for interactive data visualization via a Geo-Desic approach	LACCI 2016	Jose A. Salazar-Castro, Diego Peña-Unigarro, Diego H. Peluffo-Ordóñez, Paul D. Rosero-Montalvo, H. Mauricio Domínguez-Limaico, Juan C. Alvarado-Pérez, Roberto Therón	This work presents a dimensionality reduction (DR) framework that enables users to perform either the selection or mixture of DR methods by means of an interactive model, here named Geo-Desic approach. Such a model consists of linear combination of kernel-based representations of DR methods, wherein the corresponding coefficients are related to coordinated latitude and longitude inside of the world map. By incorporating the Geo-Desic approach within an interface, the combination may be made easily and intuitively by users -even non-expert ones- fulfilling their criteria and needs, by just picking up points from the map. Experimental results demonstrates the usability and ability of DR methods representation of proposed approach.	2016	7	https://ieeexplore.ieee.org/document/7885740/
219	Interactive Visualization Methodology of High-Dimensional Data with a Color-Based Model for Dimensionality reduction	STSIVA 2016	Diego F. Peña-ünigarro, Jose A. Salazar-Castro, Diego H. Peluffo-Ordóñez, Paul D. Rosero-Montalvo, Omar R. Oña-Rocha, Andres A. Isaza, Juan C. Alvarado-Perez, Roberto Theron	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	7	https://ieeexplore.ieee.org/document/7743318/
316	Efficient Hyperparameter Optimization in Convolutional Neural Networks by Learning Curves Prediction	Iberoamerican Congress on Pattern Recognition	Andrés F Cardona-Escobar, Andrés F Giraldo-Forero, Andrés E Castro-Ospina, Jorge A Jaramillo-Garzón	In this work, we present an automatic framework for hyperparameter selection in Convolutional Neural Networks. In order to achieve fast evaluation of several hyperparameter combinations, prediction of learning curves using non-parametric regression models is applied. Considering that “trend” is the most important feature in any learning curve, our prediction method is focused on trend detection. Results show that our forecasting method is able to catch a complete behavior of future iterations in the learning process.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-75193-1_18
220	Internet de las Cosas y Redes de Sensores Inalambricos: Review	ICES 2017	Paul Rosero, Santiago Núñez, Stalin Realpe, Christian Rosado	La evolución de Internet ha tenido un alto impacto para la población mundial, aunque en sus inicios solo se consideró como una red de computadores ha pasado a convertirse en la base del desarrollo de la mayoría de aspectos de la vida diaria de todas las personas. La relación entre dispositivos conectados y el número de usuarios que se ha establecido en los últimos años indica que existen más sistemas electrónicos conectados a Internet que habitantes a nivel mundial. El Internet de las Cosas (IoT) se origina por la necesidad de estar conectados entre todos, esto incluye a personas y cosas, de tal manera que cada individuo pueda gestionar de forma remota a cualquier objeto que tenga una conexión a Internet. Esto ha requerido emplear diversas tecnologías, la que mayor éxito ha tenido son las redes de sensores inalámbricos, debido a que permiten recoger diferentes tipos de datos para luego poder ser monitorizados y gestionados. Varias organizaciones a nivel mundial se han encargado de trabajar en la arquitectura y los protocolos que se deben tomar en cuenta para desarrollar aplicaciones de IoT con el fin de que exista compatibilidad entre dispositivos. Una revisión del estado del arte de IoT y WSN permite tener una visión más amplia del alcance, arquitectura, aplicaciones y limitaciones de estas tecnologías, especialmente enfocados al manejo de seguridad de la información y Big Data.	2017	7	https://www.researchgate.net/publication/316438631_INTERNET_DE_LAS_COSAS_Y_REDES_DE_SENSORES_INALAMBRICOS_REVIEW
221	Theorical developments for interpreting kernel spectral clustering from alternative view points	REVISTA ASTES	Diego Peluffo-Ordóñez, Paul Rosero-Montalvo, Ana Umaquinga-Criollo, Luis Suárez-Zambrano, Hernan Domínguez-Limaico, Omar Oña-Rocha, Stefany Flores-Armas, Edgar Maya-Olalla	To perform an exploration process over complex structured data within unsupervised settings, the so-called kernel spectral clustering (KSC) is one of the most recommended and appealing approaches, given its versatility and elegant formulation. In this work, we explore the relationship between (KSC) and other well-known approaches, namely normalized cut clustering and kernel k-means. To do so, we first deduce a generic KSC model from a primal-dual formulation based on least-squares support-vector machines (LS-SVM). For experiments, KSC as well as other consider methods are assessed on image segmentation tasks to prove their usability.	2017	7	https://astesj.com/v02/i03/p208/
222	Human Sit Down Position Detection Using Data Classification and Dimensionality Reduction	REVISTA ASTES	Paul Rosero-Montalvo, Daniel Jaramillo, Stefany Flores, Diego Peluffo, Vanessa Alvear, Milton Lopez	The analysis of human sit down position is a research area allows for preventing health physical problems in the back. Many works have proposed systems that detect the sitting position, some open issues are still to be dealt with, such as: Cost, computational load, accuracy, portability, and among others. In this work, we present an alternative approach based on an embedded system to acquire the position-related variables and machine learning techniques, namely dimensionality reduction (DR) and classification. Since the information acquired by sensors is high-dimensional and therefore it might not be saved into embedded system memory, for this reason the system has a DR stage based on principal component analysis (PCA) is performed. Subsequently, the posed detection is carried out by the k-nearest neighbors (KNN) classifier between the matrix stored in the system and new data acquired by pressure and distance sensors. Thus, regarding using the whole data set, the computational cost is decreased by 33 % as well as the data reading is reduced by 10 ms. Then, sitting-pose detection task takes 26 ms, and reaches 75% of accuracy in a 4-trial experiment.	2017	7	https://astesj.com/v02/i03/p95/
223	GreenFarm-DM: A tool for analyzing vegetable crops data from greeenhouse using data mining techniques	Ecuador Electrical Chapters Meeting 2017	K. L. Ponce-Guevara, J. A. Palacios-Echeverría, E. Maya-Olalla, H. M. Domínguez-Limaico, L. E. Suárez-Zambrano, P. D. Rosero-Montalvo, D. H. Peluffo-Ordóñez, J. C. Alvarado-Pérez	This work shows the use of Big Data and Data Mining techniques on vegetable crops data from a greenhouse by implementing the first version of a software tool, so called GreenFarm-DM. Such a tool is aimed at analyzing the factors that influence the growth of the crops, and determine a predictive model of soil moisture. Within a greenhouse, the variables that affect crop growth are: relative humidity, soil moisture, ambient temperature, and levels of illumination and CO2. These parameters are essential for photosynthesis, i.e. during processes where plants acquire the most nutrients, and therefore, if performing a good control on these parameters, plants might grow healthier and produce better fruits. The process of analysis of such factors in a data mining context requires designing an analysis system and establishing an objective variable to be predicted by the system. In this case, in order to optimize water resource expenditure, soil moisture has been chosen as the target variable. The proposed analysis system is developed in a user interface implemented in Java and NetBeans IDE 8.2, and consists mainly of two stages. One of them is the classification through algorithm C4.5 (chosen for the first trial), which uses a decision tree based on the data entropy, and allows to visualize the results graphically. The second main stage is the prediction, in which, from the classification results obtained in the previous stage, the target variable is predicted from information of a new set of data. In other words, the interface builds a predictive model to determine the behavior of soil moisture.	2017	7	https://ieeexplore.ieee.org/document/8247519/
224	Elderly Fall Detection Using Data Classification on a Portable Embeddedd System	Ecuador Electrical Chapters Meeting 2017	P.D. Rosero-Montalvo, D.H. Peluffo-Ordóñez, Pamela Godoy, K. Ponce, E.A. Rosero, C.A. Vásquez, F. Cuzme, S.C Flores, Z. A. Mera	The area of research on the detection of falls in the elderly allows to prevent major ailments to a person and not receiving timely medical attention. Although different systems have been proposed for the detection of falls, there are some open problems such as: cost, computational load, precision, portability, among others. This paper presents an alternative approach based on the acquisition of speed variation of the person on the X, Y and Z axes using an accelerometer and machine learning techniques. Since the information acquired by the sensor is very variant, with noise and high volume of data, a prototype selection stage is carried out using confidence intervals and techniques of Leaving-One-Out. Subsequently, automatic detection is performed using the K-nearest neighbors (K-NN) classifier. As a result of fall detection 95% accuracy is achieved in experiments from 5 trials and already used in reality by an older adult, the system has a time of 30 ms for position selection and the detection of drop is maintained in a 92% right.	2017	7	https://ieeexplore.ieee.org/document/8247529/
225	Prototype Selection Algorithms  Comparision in Nearest Neighbor Classification for Sensor Data: Empirical Study	Ecuador Electrical Chapters Meeting 2017	Paul Rosero-Montalvo, Diego H. Peluffo-Ordóñez, Ana Umaquinga, Andrés Anaya, Jorge Serrano, Edwin Rosero, Carlos Vásquez, Luis Suaréz	This work presents a comparative study of prototype selection (PS) algorithms. Such a study is done over data-from-sensor acquired by an embedded system. Particularly, five flexometers are used as sensors, which are located inside a glove aimed to read sign language. Measures were taken to quantify the balance between classification performance and reduction training set data (QCR) with k neighbors equal to 3 and 1 to force the classifier (kNN) to the maximum. Two tests were used: (a)the QCR performance and (b) the embedded system decision in real proves. As result the Random Mutation Hill Climbing (RMHC) algorithm is considered the best option to choose in this data type with removed instances at 87% and classification performance at 82% in software tests, also the classifier kNN must be with k=3 to improve the classification performance. In a real situation, with the algorithm implemented. The system makes correct decisions at 81% with 5 persons doing sign language in real time.	2017	7	http://ieeexplore.ieee.org/document/8247530/
226	Interactive Data Visualization Using Dimensionality Reduction and Dissimilarity-Based Representations	Ecuador Electrical Chapters Meeting 2017	P. Rosero-MontalvoE. J. Revelo-FuelagánJ. A. Castro-SilvaJ. C. Alvarado-PérezR. TherónC. M. Ortega-BustamanteD. H. Peluffo-Ordóñez, D. F. Peña-Unigarro	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	7	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
227	Two Novel Clustering Performance Measures Based on Coherence and Relative Assignments of Clusters	Colombian Conference on Computing	P. Rosero-MontalvoD. H. Peluffo-OrdóñezJ. L. Rodríguez-SoteloM. A. Becerra-Botero, H. J. Areiza-LaverdeA. E. Castro-Ospina	This work proposes two novel alternatives for dealing with the highly important issue of the clustering performance estimation. One of the measures is the cluster coherence aimed to quantifying the normalized ratio of cuts within a graph-partitioning framework, and therefore it uses a graph-driven approach to explore the nature of data regarding the cluster assignment. The another one is the probability-based-performance quantifier, which calculates a probability value for each cluster through relative frequencies. Proposed measures are tested on some clustering representative techniques applied to real and artificial data sets. Experimental results probe the readability and robustness to noisy labels of our measures.	2017	7	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_56
228	Data visualization using interactive dimensionality reduction and improved color based interaction model	IWINAC (International Work-Conference on the Interplay Between Natural and Artificial Computation) 2017	D. F. Peña-UnigarroD. H. PeluffoJ. A. Castro-SilvaA. UmaquingaE. A. Rosero-Rosero, P. D. Rosero-Montalvo	This work presents an improved interactive data visualization interface based on a mixture of the outcomes of dimensionality reduction (DR) methods. Broadly, it works as follows: The user can input the mixture weighting factors through a visual and intuitive interface with a primary-light-colors-based model (Red, Green, and Blue). By design, such a mixture is a weighted sum of the color tone. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to simultaneously be drawn over the scatter plot. Our interface enables the user to interactively combine DR methods by the human perception of color, while providing information about the structure of original data. Then, it makes the selection of a DR scheme more intuitive -even for non-expert users.	2017	7	https://link.springer.com/chapter/10.1007/978-3-319-59773-7_30
229	Automatic Motion Segmentation via Cumulate Kernel Representation and Spectral Clustering	IDEAL (International Conference on Intelligent Data Engineering and Automated Learning)  2017	D. F. Peña-UnigarroD. H. PeluffoJ. A. Castro-SilvaA. UmaquingaE. A. Rosero-Rosero, P. D. Rosero-Montalvo	This work presents an improved interactive data visualization interface based on a mixture of the outcomes of dimensionality reduction (DR) methods. Broadly, it works as follows: The user can input the mixture weighting factors through a visual and intuitive interface with a primary-light-colors-based model (Red, Green, and Blue). By design, such a mixture is a weighted sum of the color tone. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to simultaneously be drawn over the scatter plot. Our interface enables the user to interactively combine DR methods by the human perception of color, while providing information about the structure of original data. Then, it makes the selection of a DR scheme more intuitive -even for non-expert users.	2017	7	https://link.springer.com/chapter/10.1007/978-3-319-59773-7_30
230	Cardiac Pulse Modeling Using a Modified van der Pol Oscillator and Genetic Algorithms	IWBBIO 2018 (6th International Work-Conference on Bioinformatics and Biomedical Engineering)	Fabián M. Lopez-ChamorroAndrés F. Arciniegas-MejiaDavid Esteban Imbajoa-RuizPaul D. Rosero-MontalvoPedro GarcíaAndrés Eduardo Castro-Ospina, Antonio AcostaDiego Hernán Peluffo-Ordóñez	This paper proposes an approach for modeling cardiac pulses from electrocardiographic signals (ECG). A modified van der Pol oscillator model (mvP) is analyzed, which, under a proper configuration, is capable of describing action potentials, and, therefore, it can be adapted for modeling a normal cardiac pulse. Adequate parameters of the mvP system response are estimated using non-linear dynamics methods, like dynamic time warping (DTW). In order to represent an adaptive response for each individual heartbeat, a parameter tuning optimization method is applied which is based on a genetic algorithm that generates responses that morphologically resemble real ECG. This feature is particularly relevant since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are performed over real ECG from MIT-BIH arrhythmias database. The application of the optimization process shows that the mvP oscillator can be used properly to model the ideal cardiac rate pulse.	2018	7	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_8
233	Neighborhood Criterion Analysis for Prototype Selection Applied in WSN Data	INCISCOS 2017	P.D. Rosero-Montalvo, A.C. Umaquinga-Criollo, S. Flores, L. Suarez, J. Pijal, K.L. Ponce-Guevara, D. Nejer, A. Guzman, D. Lugo, K. Moncayo	The present work presents an analysis of the neighborhood criterion for the prototype selection (PS) in supervised machine learning classification algorithms. To do this, we use the condensed neighbor algorithm CNN to eliminate redundant data with the normalization of the distance to the centroid of each data subset criterion. This is done, in order to obtain the training matrix of the most optimal model. A selection of neighborhood criterion has been created from the quantification of the balance between the performance of the classification and the reduction of data set (CER). As proof of the test, we performed: (i) CER and (ii) real-time tests with the implementation of the algorithm within the WSN. The result is a data reduction of up to 88 % and a performance of the kNN classifier of 75%. It is concluded that the criterion of neighborhood with normalized distance must be less than or equal to 0.2 and the implementation of kNN with k = 1 obtains the best CER.	2017	7	https://ieeexplore.ieee.org/document/8328096/
234	Forecasting of Energy Consumption Based on Gaussian Mixture Model and Classification Techniques	IX Simposio Internacional sobre Calidad de la Energía Eléctrica (SICEL 2017)	D. Imbajoa, A. Arciniegas, J. Revelo, D. H. Peluffo-Ordóñez, P. D. Rosero-Montalvo	The estimation of energy demand is not always straightforward or reliable, as one or several classes may fail in the prediction. In this study, a novel methodology of load forecasting is proposed. Three different configurations\r\nof Artificial Neural Networks perform a supervised classification of energy consumption data, each one providing\r\nan output vector of unreliable predicted data. Under the clustering method k-means, multiple patterns are\r\nidentified, and then processed by the Gaussian Mixture Model in order to provide higher relevance to the more\r\naccurate predicted samples of data. The accuracy of the prediction is evaluated with the several error rate\r\nmeasurements. Finally, a mixture of the generated forecasts by the methods is performed, showing a lower error\r\nrate compared to the inputs predictions, therefore, a more reliable forecast.	2017	7	https://www.researchgate.net/profile/David_Imbajoa/publication/320853691_Forecasting_of_Energy_Consumption_Based_on_Gaussian_Mixture_Model_and_Classification_Techniques/links/59fe4a400f7e9b9968c3cfe6/Forecasting-of-Energy-Consumption-Based-on-Gaussian-Mixture-Model-and-Classification-Techniques.pdf
235	Sistema embebido orientado a bebés en etapa de gateo para prevención de accidentes aplicado en un textil inteligente	REVISTA ENFOQUE	Chico Morales, I., Narváez Pupiales, S., Umaquinga Criollo, A., & Rosero Montalvo, P.	El gateo de los bebés es la forma de descubrir y aprender sus funciones motoras, cognitivas, sociales, emocionales, entre otros. Debido a esto, los infantes se exponen a diferentes peligros como: caídas, quemaduras, lesiones corporales entre las más comunes, donde el hogar es el lugar de mayores incidentes. Debido a lo antes expuesto, la presente investigación se enfoca en el desarrollo de un sistema embebido dentro de un textil inteligente que permita advertir y prevenir accidentes. El sistema se encuentra en una prenda de vestir en forma de arnés que cuentan con una conexión con rodilleras de gateo con sensores magnéticos. Estos elementos son los encargados de detectar cintas de seguridad magnéticas colocadas previamente en lugares de mayor peligro en el hogar. Como resultado, el sistema emite una alerta con un tiempo de reacción de 7,6 segundos, después de ser activado el sistema.	2018	7	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/281
236	A novel color-based data visualization approach using a circular interaction model and dimensionality reduction	ISNN 2018 Advances in Neural Networks	Jose Alejandro Salazar-Castro, Paul D. Rosero-Montalvo, Diego Fernando Peña-Unigarro, Ana Cristina Umaquinga-Criollo, Zenaida Castillo-Marrero, Edgardo Javier Revelo-Fuelagán, Diego Hernán Peluffo-Ordóñez, César Germán Castellanos-Domínguez	Dimensionality reduction (DR) methods are able to produce low-dimensional representations of an input data sets which may become intelligible for human perception. Nonetheless, most existing DR approaches lack the ability to naturally provide the users with the faculty of controlability and interactivity. In this connection, data visualization (DataVis) results in an ideal complement. This work presents an integration of DR and DataVis through a new approach for data visualization based on a mixture of DR resultant representations while using visualization principle. Particularly, the mixture is done through a weighted sum, whose weighting factors are defined by the user through a novel interface. The interface’s concept relies on the combination of the color-based and geometrical perception in a circular framework so that the users may have a at hand several indicators (shape, color, surface size) to make a decision on a specific data representation. Besides, pairwise similarities are plotted as a non-weighted graph to include a graphic notion of the structure of input data. Therefore, the proposed visualization approach enables the user to interactively combine DR methods, while providing information about the structure of original data, making then the selection of a DR scheme more intuitive.	2018	7	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_64
237	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	ISNN 2018 Advances in Neural Networks	Leandro Leonardo Lorente-Leyva, Israel David Herrera-Granda, Paul D. Rosero-Montalvo, Karina L. Ponce-Guevara, Andrés Eduardo Castro-Ospina, Miguel A. Becerra, Diego Hernán Peluffo-Ordóñez, José Luis Rodríguez-Sotelo	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	7	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_37
317	Deforming objects via exponential homotopy: A first approach	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium on	Luis O Alpala, Diego H Peluffo-Ordóñez, Catalina González-Castaño, Fredy A Guasmayan	This work presents a novel alternative to conventional linear homotopy with suboptimal settings for applications on object deformation. Proposed approach extends the linear mapping to exponential representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. As well, we introduce a quality indicator based on the ratio between the coefficients curve of resultant homotopy and those of a non-realistic, reference homotopy. Experimental results are promising and show the applicability of exponential homotopy to interpolating images with soft changes and homotopic geometric objects.	2015	17	https://ieeexplore.ieee.org/abstract/document/7330401/
238	Cardiac Pulse Modeling Using a Modified van der Pol Oscillator and Genetic Algorithms	Bioinformatics and Biomedical Engineering	Fabián M. Lopez-Chamorro, Andrés F. Arciniegas-Mejia, David Esteban Imbajoa-Ruiz, Paul D. Rosero-Montalvo, Pedro García, Andrés Eduardo Castro-Ospina, Antonio Acosta, Diego Hernán Peluffo-Ordóñez	This paper proposes an approach for modeling cardiac pulses from electrocardiographic signals (ECG). A modified van der Pol oscillator model (mvP) is analyzed, which, under a proper configuration, is capable of describing action potentials, and, therefore, it can be adapted for modeling a normal cardiac pulse. Adequate parameters of the mvP system response are estimated using non-linear dynamics methods, like dynamic time warping (DTW). In order to represent an adaptive response for each individual heartbeat, a parameter tuning optimization method is applied which is based on a genetic algorithm that generates responses that morphologically resemble real ECG. This feature is particularly relevant since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are performed over real ECG from MIT-BIH arrhythmias database. The application of the optimization process shows that the mvP oscillator can be used properly to model the ideal cardiac rate pulse.	2018	7	https://link.springer.com/chapter/10.1007%2F978-3-319-78723-7_8
240	Planta satélite de gas natural licuado para el abastecimiento del sector industrial en Cuenca – Ecuador	DELOS	Robert Valencia Chapi, Gerardo Collaguazo Galeano, Leandro Lorente Leyva, Israel Herrera Granda	The object of this paper is the design and construction of an LNG satellite plant to supply the industrial sector of the city of Cuenca in Ecuador. The idea came from to partially replace the consumption of liquefied petroleum gas (LPG) for liquefied natural gas (LNG). One of the main reasons is that the refining process for LPG increasing cost, so a cheaper option arises, and this would be to use LNG. A growing demand for natural gas is expected, so the government is currently implementing a project on extraction and liquefaction of natural gas in the Gulf of Guayaquil, initially the distribution of LNG will be made through the trading of LPG.	2016	23	http://www.eumed.net/rev/delos/27/gas.html
239	Diseño y evaluación de un algoritmo genético para ruteo vehicular que permita optimizar la distribución en una empresa comercializadora de autopartes en quito	Repositorio Dspace	Herrera Granda, Israel David	En el presente proyecto se diseñó y evaluó una metaheurística de algoritmo genético hibridándola con la metaheurística del vecino más cercano para el ruteo de vehículos con el objetivo de optimizar la distribución en una empresa comercializadora de autopartes de nombre ficticio "REPUESTOS S.A." en la ciudad de Quito, para ello se desarrolló una aplicación programada en el lenguaje C# e inspirada a su vez en el enunciado del problema de ruteo vehicular con ventanas de tiempo y capacidad limitada CVRPTW. Una vez desarrollada la aplicación se la evaluó contra un modelo aproximado del VRPTW programado en GAMS con una pequeña cantidad de nodos clientes demostrándose la calidad de las respuestas proporcionadas por la aplicación, luego se pasó a resolver los problemas reales de una empresa distribuidora de autopartes en la ciudad de Quito o DMQ, con una mayor cantidad de clientes en donde se detectó las posibilidades de mejora y la factibilidad de implementarlo en dicha empresa.	2015	23	http://www.dspace.espol.edu.ec/xmlui/handle/123456789/37028
241	Una revisión del estado del arte de la optimización de rutas de recolección de residuos sólidos municipales en países en vías de desarrollo	Tecnologias Aplicadas a la Ingeniería	Herrera I., Collaguazo G., Lorente L., Montero Y. y Valencia R.	El presente trabajo consiste en la revisio ́n de las metodolog ́ıas para la optimizacio ́n de la red de recoleccio ́n y disposicio ́n de Residuos So ́lidos Municipales (RSM) en pa ́ıses en v ́ıas de desarrollo, como parte de un enfoque hol ́ıstico para la adecuada gestio ́n de RSM, dentro del cual se detallan las t ́ecnicas para la optimiza- cio ́n de las rutas recorridas por los camiones recolectores de RSM. Dando cabida al estudio del enrutamiento de los camiones recolectores de residuos so ́lidos municipales (WCVRP). Una extensa revisio ́n del estado del arte de la optimizacio ́n de rutas de recoleccio ́n de RSM demostro ́ la viabilidad y factibilidad de aplicar metodolog ́ıas para el modelamiento de los diferentes WCVRP y los beneficios obtenidos mediante estas implementaciones en distintas localidades, se hace tambi ́en una revisio ́n del software para tratar el WCVRP tanto comercial como tambi ́en de las opciones de acceso libre, a las cuales se les da mayor relevancia. Adicionalmente se presenta una clasificacio ́n esquema ́tica de los diferentes modelos matema ́ticos para el tratamiento del WCVRP y se revisan las aplicaciones que han aportado mayores impactos en t ́erminos de optimizacio ́n de las rutas de reco- leccio ́n de RSM en los u ́ltimos an ̃os, finalmente se revisan las implementaciones sobre esta tem ́atica en Ecuador.	2016	23	https://issuu.com/utnuniversity/docs/ebook-tecnologias-aplicadas-a-la-in
242	Recuperación de destinos turísticos en el Ecuador”, artículo: “Diagnóstico de la situación laboral y social de los entes recicladores de residuos sólidos municipales de Ibarra	MEMORIAS DEL CONGRESO INTERNACIONAL DE MEDIO AMBIENTE Y RECURSOS NATURALES	Israel David Herrera Granda	The  economic  assessment  of  the  natural  resources  constitutes  a  fundamental component   to   promote   processes   of   conservation   of   the   biodiversity, environmental  services  and  cultural  values  associated  to  the  natural  protected spaces, because, integrates to the debate the economic dimension of the natural capital. That ́s why, the present investigation offers information that contributes to  the  handle  of  the  peatland  ecosystem  in  the  Chimborazo  Fauna  Production Reserve. This process consisted in the physical-chemical characterization of the floor of the peatlands, the quantification of the organic carbon stored in the floor and the economic assessment of the organic carbon. The data indicate that the peatlands possess sour floors, not saline, of sandy texture and with high levels of organic matter (7.27%). This reflects in the content of organic carbon total that rises to 97 324 tons in an extension of 519 has. Therefore the total values of  organic  carbon  viabilizan  the  implementation  of  a  model  of  payment  by environmental services through the commercialization of credits of carbon, that of  agreement  to  the  financial  economic  analysis  would  suppose  a  Net  Current Value of $ 323 217 and an Internal Tax of Return of the 128%.	2017	23	https://utneduec-my.sharepoint.com/personal/idherrera_utn_edu_ec/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fidherrera_utn_edu_ec%2FDocuments%2FPUBLICACIONES%20CIENT%C3%8DFICAS%20ISRAEL%20HERRERA%2FCONGRESO%20INTERNACIONAL%20DE%20MEDIO%20AMBIENTE%202017%2FOBRA%20DE%20RELEVANCIA%20%281%29%2Epdf&parent
243	Diseño de sistema de aprovisionamiento para una la línea de repuestos automotores. Caso de estudio	Revista Observatorio de la Economía Latinoamericana	Yakcleem Montero Santos, Israel David Herrera Granda, Carlos Alberto Machado Orges, Erik Orozco Crespo y Leandro Leonardo Lorente Leyva	The research was done for a line of automotive spare parts in the city of Ibarra in Ecuador. With the objective of designing the system of provisioning for the company object of study and thus to satisfy the needs of the clients in time, quantity and specifications. This was achieved through an analysis of historical sales data for 3 years. The ABC classification was performed for a total of 159 articles of type C, 95 type B and 63 type A; this last group of articles, using the statistical software ForecastPro Trac, the sales forecasts of each article were executed. Due to the stable demand that already shows the importance of each article, as well as the value obtained from the coefficient of variability, the EOQ model was applied. The execution of the selected model allowed to obtain lower costs, establishing the optimal quantity of orders, as well as the moment in which the new order is made, considering the security inventory of the products.	2017	23	http://www.eumed.net/cursecon/ecolat/ec/2017/diseno-sistema-automotores.html
