245	Análisis de indicadores de aprovechamiento de bodegas. Caso de estudio ciudad de Ibarra	Revista Observatorio de la Economía Latinoamericana	Yakcleem Montero Santos, Jonatan Estiven Mafla Narvaez, Carlos Alberto Machado Orges, Israel David Herrera Granda y Leandro Leonardo Lorente Leyva	The investigation was carried out with the purpose of evaluating the indicators of exploitation of warehouses, in the city of Ibarra, Ecuador. For this, the procedure designed by (Narvaez J. E., 2017) is chosen. The initial diagnosis (Yakcleem Montero Santos, 2016) states that the use of the area, height and volume of the store were not within the specific ranges to reach an óptimal efficiency index. Therefore, it was decided to apply the aforementioned procedure to make a proposal for improvement to the winery under study. It starts with the ABC analysis of the inventories, then performs the distribution in plant through Corelap 1.0 software and the analysis of the operational method (Towers, 2013), for the new design of the layot, which will allow to raise the technological level of the warehouse.	2018	23	https://www.eumed.net/rev/oel/2018/02/aprovechamiento-bodegas-ecuador.html
246	Estudio de factibilidad para la reutilización, reciclaje y procesamiento de neumáticos fuera de uso	Revista Observatorio de la Economía Latinoamericana	Sebastián Vásquez Pozo, Leandro L. Lorente Leyva, Carlos A. Machado Orges, Yakcleem Montero Santos e Israel D. Herrera Granda	Due to the vital importance of ensuring the permanence of companies in the market over time, the investor must have a high degree of possibility of not failing at the moment of implementing their business, ensuring that it will be economically viable, proceeded to carry out the present investigation with the purpose of knowing the economic feasibility of the opening of a plant of processing of tires out of use inside the city of Ibarra, carrying out a series of steps that start with the bibliographical revision to find a methodology that allows to develop a feasibility study, which determined the completion of a market study as the first point which yielded favorable results in search of a demand to satisfy and that was: for rubber granulation demand in the years 2018, 2019, 2020, 2021 and 2022 will be 284, 509.2, 775.2, 1082.9, 1178.8 ton / year respectively and for recycled steel in 2018, 2019, 2020, 2021 and 2022 of 100, 176, 263.45, 363.3 and 391.3 tons / year, respectively, which allow us to see a positive outlook for developing the product.\r\nAs a second point, a technical study was developed, which allows the search for the appropriate machinery for the fulfillment of the demand, analyzing and proposing the purchase of an out-of-use tire processing line that has a processing capacity of 0.6 ton / hour, which is considered adequate to meet the expectations raised in the market study.\r\nAs a final step, a financial study was proposed that contains a comprehensive analysis of the indicators developed in this section and will allow the conclusion of whether the project is viable or not. For this purpose, the evaluation of the results obtained was: NPV = 364 336.21; R B / C = 2.51; TIR = 27% and PRI = 1.30, and according to the analysis of the evaluation criteria of an investment project, the plant for the processing of out-of-use tires is ready for start-up, since the project is profitable and feasible.	2018	23	https://www.eumed.net/rev/oel/2018/04/reutilizacion-neumaticos.html
247	Diseño de biodigestor a escala de laboratorio para la digestión anaerobia e industrialización energética de los desechos sólidos municipales	Revista DELOS Desarrollo Local Sostenible n.31	Leandro L. Lorente Leyva, Gerardo Collaguazo Galeano, Israel D. Herrera Granda, Ramiro V. Saraguro Piarpuezan, Arlys M. Lastre Aleaga y Alexis Cordovés García	The energy sector is in constant search of new clean sources of energy, both to supplement its production, as well as to reduce dependence on fossil fuels and its gradual replacement based on sustainable development methods. In this context, municipal waste is considered as a renewable energy source, since they have a high biomass content (paper, cardboard, food waste, wood, straw, leaves). A renewable source alternative with great prospects for the future is the use and energetic valuation of municipal solid waste. This research aims at the design of a laboratory-scale biodigester for the energetic industrialization of municipal solid waste, serving as a basis for the construction of a prototype on a pilot scale or a plant for the Anaerobic treatment of these generated wastes. In this way, it will be possible to recover the energy contained in them, in order to reduce the flow of the waste destined to the landfills and to provide a production rate for the obtaining of biogas, taking as fundamental basis for the calculations of design and the Improvement of laboratory-level production, through co-digestion with other types of organic waste and use of alkaline inoculating substances and determination of the most appropriate anaerobic digestion technology for waste treatment Municipal solids.	2018	23	https://www.eumed.net/rev/delos/31/leandro-lorente.html
203	Unsupervised analysis applied to the detection cardiac arrhythmias	Enfoque UTE	Mónica Moreno-Revelo, Sandra Patascoy-Botina, Andrés Pantoja-Buchelli, Javier Revelo Fuelagán, José Rodríguez-Sotelo, Santiago Murillo-Rendón, Diego Peluffo-Ordoñez	An arrhythmia is a pathology that consists on altering the heartbeat. Although, the 12-lead electrocardiogram allows evaluation of the electrical behavior from heart to determine certain pathologies, there are some arrhythmias that are difficult to detect with this type of electrocardiography. In this sense, it is necessary the use of the Holter monitor because it facilitates the records of the heart electrical activity for long periods of time, it is usually 24 up to 48 hours. Due to the extension of the records provided by the monitor, it is common to use computational systems to evaluate diagnostic and morphological features of the beats in order to determine if there is any type of abnormality. These computational systems can be based on supervised or unsupervised pattern recognition techniques, however considering that the first option requires a visual inspection about the large number of beats present in a Holter record, it is an arduous task, as well as it involves monetary costs. Consequently, throughout this paper we present the design of a complete system for the identification of arrhythmias in Holter records using unsupervised pattern recognition techniques. The proposed system involves stages of preprocessing of the signal, segmentation and characterization of beats, as well as feature selection and clustering. In this case, the technique k-means is used. These steps are applied within the framework of a segment-based methodology that improves the detection of minority classes. Additionally, initialization criteria are considered, which allow to enhance quality measures, especially sensitivity. As a result, it is determined that using k-means with the max-min initialization and a number of groups equal to 12, it is possible to obtain the best results, with values of: 99.36%, 91.31% and 99.16% for accuracy, sensitivity and specificity, respectively.	2017	31	https://www.ingentaconnect.com/content/doaj/13906542/2017/00000008/00000001/art00019
248	Dimensionality reduction based on fuzzy rough sets oriented to ischemia detection	Engineering in Medicine and Biology Society (EMBC), 2012 Annual International Conference of the IEEE	Diana A Orrego, Miguel A Becerra, Edilson Delgado-Trejos	This paper presents a dimensionality reduction study based on fuzzy rough sets with the aim of increasing the discriminant capability of the representation of normal ECG beats and those that contain ischemic events. A novel procedure is proposed to obtain the fuzzy equivalence classes based on entropy and neighborhood techniques and a modification of the Quick Reduct Algorithm is used to select the relevant features from a large feature space by a dependency function. The tests were carried out on a feature space made up by 840 wavelet features extracted from 900 ECG normal beats and 900 ECG beats with evidence of ischemia. Results of around 99% classification accuracy are obtained. This methodology provides a reduced feature space with low complexity and high representation capability. Additionally, the discriminant strength of entropy in terms of representing ischemic disorders from time-frequency information in ECG signals is highlighted.	2012	9	https://ieeexplore.ieee.org/abstract/document/6347186/
249	Effect of the electrograms density in detecting and ablating the tip of the rotor during chronic atrial fibrillation: an in silico study	European Society of Cardiology	Juan P Ugarte, Catalina Tobón, Andrés Orozco-Duque, Miguel A Becerra, John Bustamante	Identification in situ of arrhythmogenic mechanisms could improve the rate of ablation success in atrial fibrillation (AF). Our research group reported that rotors could be located through dynamic approximate entropy (DApEn) maps. However, it is unknown how much the spatial resolution of catheter electrodes could affect substrates localization. The present work looked for assessing the electrograms (EGMs) spatial resolution needed to locate the rotor tip using DApEn maps.	2016	9	https://academic.oup.com/europace/article/17/suppl_2/ii97/2802590
250	Heart murmur detection using Ensemble Empirical Mode Decomposition and derivations of the Mel-Frequency Cepstral Coefficients on 4-area phonocardiographic signals	Computing in Cardiology Conference (CinC), 2014	Joe A Jimenez, Miguel A Becerra, Edilson Delgado-Trejos	This paper presents an automatic detection system for the classification of phonocardiographic (PCG) signals using 4 standard auscultation areas (one of each cardiac valve) for heart murmur diagnosis. The database of 4-area PCG records belongs to the National University of Colombia. A set of 50 individuals were labeled as normal, while 98 were labeled as exhibiting cardiac murmurs, caused by valve disorders. With the help of medical experts, 400 representative beats were chosen, 200 normal and 200 with evidence of cardiac murmur from 4 different areas of auscultation. First, the PCG signals were preprocessed; next, four different derivations of Mel Frequency Cepstral Coefficients (MFCC) were extracted. Additionally, statistical moments of Hilbert Huang Transform (HHT) were estimated using different combinations of the signal components by means of Empirical Mode Decomposition (EMD), Ensemble EMD (EEMD) and Complete EEMD with Adaptative Noise (CEEMDAN), independently, where the computational complexity were compared. Finally, stochastic analysis of the feature space was carried out by an ergodic-HMM and the global classification result was around 98% with acceptable sensitivity and specificity scores, using a 30-fold cross-validation procedure (70/30 split).	2015	9	https://ieeexplore.ieee.org/abstract/document/7043087/
251	Adaptive neuro-fuzzy inference system for acoustic analysis of 4-channel phonocardiograms using empirical mode decomposition	Engineering in Medicine and Biology Society (EMBC), 2013 35th Annual International Conference of the IEEE	Miguel A Becerra, Diana A Orrego, Edilson Delgado-Trejos	The heart's mechanical activity can be appraised by auscultation recordings, taken from the 4-Standard Auscultation Areas (4-SAA), one for each cardiac valve, as there are invisible murmurs when a single area is examined. This paper presents an effective approach for cardiac murmur detection based on adaptive neuro-fuzzy inference systems (ANFIS) over acoustic representations derived from Empirical Mode Decomposition (EMD) and Hilbert-Huang Transform (HHT) of 4-channel phonocardiograms (4-PCG). The 4-PCG database belongs to the National University of Colombia. Mel-Frequency Cepstral Coefficients (MFCC) and statistical moments of HHT were estimated on the combination of different intrinsic mode functions (IMFs). A fuzzy-rough feature selection (FRFS) was applied in order to reduce complexity. An ANFIS network was implemented on the feature space, randomly initialized, adjusted using heuristic rules and trained using a hybrid learning algorithm made up by least squares and gradient descent. Global classification for 4-SAA was around 98.9% with satisfactory sensitivity and specificity, using a 50-fold cross-validation procedure (70/30 split). The representation capability of the EMD technique applied to 4-PCG and the neuro-fuzzy inference of acoustic features offered a high performance to detect cardiac murmurs.	2013	9	https://ieeexplore.ieee.org/abstract/document/6609664/
252	Stochastic analysis and classification of 4-area cardiac auscultation signals using Empirical Mode Decomposition and acoustic features	Computing in Cardiology (CinC)	MA Becerra, DA Orrego, Carolina Mejia, Edilson Delgado-Trejos	As cardiac murmurs do not generally appear in every area of auscultation, this paper presents an effective approach for cardiac murmur detection based on stochastic analysis of acoustic features derived from Empirical Mode Decomposition (EMD) and Hilbert-Huang Transform (HHT) of phonocardiographic (PCG) signals made up by the 4-Standard Auscultation Areas (SAA). The 4-SAA PCG database belongs to the National University of Colombia. Mel-Frequency Cepstral Coefficients (MFCC) and statistical moments of HHT were estimated over EMD components. An ergodic HMM was applied on the feature space, randomly initialized and trained by expectation maximization with a convergence at 10e-6 and a maximum iteration number of 1000. Global classification results for 4-SAA were around 98.7% with satisfactory sensitivity and specificity results, using a 30-fold cross-validation procedure (70/30 split). The representation capability of the EMD technique applied to 4-SAA PCG signals and stochastic analysis of acoustic features offered a high performance to detect cardiac murmurs.	2012	9	https://ieeexplore.ieee.org/abstract/document/6420447/
253	Data Fusion Applied to Biometric Identification–A Review	Colombian Conference on Computing	JC Zapata, CM Duque, Y Rojas-Idarraga, ME Gonzalez, JA Guzmán, MA Becerra Botero	There is a growing interest in data fusion oriented to identification and authentication from biometric traits and physiological signals, because of its capacity for combining multiple sources and multimodal analysis allows improving the performance of these systems. Thus, we considered necessary make an analytical review on this domain. This paper summarizes the state of the art of the data fusion oriented to biometric authentication and identification, exploring its techniques, benefits, advantages, disadvantages, and challenges.	2017	9	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_51
254	Complexity of Atrial Fibrillation Electrograms Through Nonlinear Signal Analysis: In Silico Approach	Interpreting Cardiac Electrograms-From Skin to Endocardium	Catalina Tobón, Andrés Orozco‐Duque, Juan P Ugarte, Miguel Becerra, Javier Saiz	Identi cation of atrial  brillation (AF) mechanisms could improve the rate of ablation success. However, the incomplete understanding of those mechanisms makes di cult the decision of targeting sites for ablation. This work is focused on the importance of EGM analysis for detecting and modulating rotors to guide ablation procedures and improve its outcomes. Virtual atrial models are used to show how nonlinear measures can be used to generate electroanatomical maps to detect critical sites in AF. A description of the atrial cell mathematical models, and the procedure of coupling them within two‐dimensional and three‐dimensional virtual atrial models in order to simulate arrhythmogenic mecha‐ nisms, is given. Mathematical modeling of unipolar and bipolar electrogramas (EGM) is introduced. It follows a discussion of EGM signal processing. Nonlinear descriptors, such as approximate entropy and multifractal analysis, are used to study the dynamical behavior of EGM signals, which are not well described by a linear law. Our results evince that nonlinear analysis of EGM can provide information about the dynamics of rotors and other mechanisms of AF. Furthermore, these  brillatory pa erns can be simulated using virtual models. The combination of features using machine learning tools can be used for identifying arrhythmogenic sources of AF.	2017	9	https://www.intechopen.com/books/interpreting-cardiac-electrograms-from-skin-to-endocardium/complexity-of-atrial-fibrillation-electrograms-through-nonlinear-signal-analysis-in-silico-approach
256	Interfaz cerebro computador basado en señales EEG para el control de movimiento de una prótesis de mano usando ANFIS.	Lámpsakos	Alexandra Bedoya Rojas, Jessica Giraldo Leiva, Ingrid Durley Torres Pardo, Miguel A Becerra	A large number of people in the world who have amputated limbs that are usually replaced by mechanical prostheses. Moreover, electromechanical prostheses have been gaining strength and are supported by different types of interfaces as brain interfaces computer that improve the functionality of these, despite show representative results for the control of prostheses, it is still an open field research that seeks to improve its effectiveness and efficiency. In this paper, we present a methodology for classification of electroencephalographic signals (EEG) to control movement of a prosthetic hand, based on the adaptive neurofuzzy inference system (ANFIS) applied to features derived from the wavelet transform is presented (TW ) and the rough fuzzy sets (FRS) to EEG signals obtained in 10-10 system. Thus the performance of the proposed system was measured using cross-validation with 30 repetitions 70-30 obtaining high performance in terms of accuracy, which means that this model has potential as a classifier for the detection of EEG changes for the command generation for the control of hand movement.	2013	9	https://dialnet.unirioja.es/servlet/articulo?codigo=4776223
257	Analysis of motor imaginary BCI within multi-environment scenarios using a mixture of classifiers	Colombian Conference on Computing	M Ortega-Adarme, M Moreno-Revelo, DH Peluffo-Ordoñez, D Marín Castrillon, AE Castro-Ospina, MA Becerra	Brain-computer interface (BCI) is a system that provides communication between human beings and machines through an analysis of human brain neural activity. Several studies on BCI systems have been carried out in controlled environments, however, a functional BCI should be able to achieve an adequate performance in real environments. This paper presents a comparative study on alternative classification options to analyze motor imaginary BCI within multi-environment real scenarios based on mixtures of classifiers. The proposed methodology is as follows: The imaginary movement detection is carried out by means of feature extraction and classification, in the first stage; feature set is obtained from wavelet transform, empirical mode decomposition, entropy, variance and rates between minimum and maximum, in the second stage, where several classifier combinations are applied. The system is validated using a database, which was constructed using the Emotiv Epoc+ with 14 channels of electroencephalography (EEG) signals. These were acquired from three subject in 3 different environments with the presence and absence of disturbances. According to the different effects of the disturbances analyzed in the three environments, the performance of the mixture of classifiers presented better results when compared to the individual classifiers, making it possible to provide guidelines for choosing the appropriate classification algorithm to incorporate into a BCI system.	2017	9	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_37
258	Kernel-based framework for spectral dimensionality reduction and clustering formulation: A theoretical study	ADCAIJ: Advances in Distributed Computing and Artificial Intelligence Journal	Xiomara Patricia Blanco Valencia, MA Becerra, AE Castro Ospina, M Ortega Adarme, D Viveros Melo, DH PELUFFO ORDÓÑEZ	This work outlines a unified formulation to represent spectral approaches for both dimensionality reduction and clustering. Proposed formulation starts with a generic latent variable model in terms of the projected input data matrix.\r\nParticularly, such a projection maps data onto a unknown high-dimensional space. Regarding this model, a generalized optimization problem is stated using quadratic formulations and a least-squares support vector machine.\r\nThe solution of the optimization is addressed through a primal-dual scheme.\r\nOnce latent variables and parameters are determined, the resultant model outputs a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Particularly, proposed\r\nformulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2017	9	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2017613140
259	Data fusion from multiple stations for estimation of PM2. 5 in specific geographical location	Iberoamerican Congress on Pattern Recognition	Miguel A Becerra, Marcela Bedoya Sánchez, Jacobo García Carvajal, Jaime A Guzmán Luna, Diego H Peluffo-Ordóñez, Catalina Tobón	Nowadays, an important decrease in the quality of the air has been observed, due to the presence of contamination levels that can change the natural composition of the air. This fact represents a problem not only for the environment, but also for the public health. Consequently, this paper presents a comparison among approaches based on Adaptive Neural Fuzzy Inference System (ANFIS) and Support Vector Regression (SVR) for the estimation level of PM2.5 (Particle Material 2.5) in specific geographic locations based on nearby stations. The systems were validated using an environmental database that belongs to air quality network of Valle de Aburrá (AMVA) of Medellin Colombia, which has the registration of 5 meteorological variables and 2 pollutants that are from 3 nearby measurement stations. Therefore, this project analyses the relevance of the characteristics obtained in every single station to estimate the levels of PM2.5 in the target station, using four different selectors based on Rough Set Feature Selection (RSFS) algorithms. Additionally, five systems to estimate the PM2.5 were compared: three based on ANFIS, and two based on SVR to obtain an aim and an efficient mechanism to estimate the levels of PM2.5 in specific geographic locations fusing data obtained from the near monitoring stations.	2017	9	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_52
260	Emociones cromáticas: análisis de la percepción de color basado en emociones y su relación con el consumo de moda	Anagramas-Rumbos y sentidos de la comunicación-	Sonia M Peláez Becerra, Paula Gómez Gómez, Miguel A Becerra	The globalization of the marketplace, requires that products are innovative, commercial, functional and highly striking, to wake up as well in the consumer, the sufficient attention and achieve that you give the time of the purchase, with prior identification of your need and the acceptance of the product. Characterize the consumer is complex and different aspects like color and emotions must be analyzed. In this work is established, the relationship between emotion, color and fashion object, identifying variables that motivate the consumer at the time of your purchase. So a survey was applied on a university population in Colombia and Additionally, through database belonging DEAP 4 universities in Europe (Queen Mary University of London, University of Twente, Netherlands, University of Geneva and at the EPFL in Switzerland), that related emotions and videos in a university population of Europe, made an analysis of the color in the background of these and showed the influence of the color using the graph of Genève. The results obtained showed, a strong influence of the color in the attitude of consumption and the color on the emotions, although it was not possible to conclude that emotions affect the time of purchase by the consumer.	2016	9	http://www.scielo.org.co/scielo.php?pid=S1692-25222016000100005&script=sci_abstract&tlng=en
261	Reconstruction of Multi Spatial Resolution Feature Maps on a 2D Model of Atrial Fibrillation: Simulation Study	VI Latin American Congress on Biomedical Engineering CLAIB 2014, Paraná, Argentina 29, 30 & 31 October 2014	Juan Murillo-Escobar, Miguel A Becerra, Esteban A Cardona, Catalina Tobón, Laura C Palacio, BE Valdés, Diana A Orrego	Catheter ablation is a technique used as treatment for atrial fibrillation, this procedure is guided using 3D electro anatomic mapping systems. Ablation is one of the treatments for AF whose effectiveness depend on the location of the rotor tip and this depend of the quality of mapping obtained from a re-duced set of real signals. This paper presents a comparison study between three approaches for reconstruction of features maps of a 2D model of simulated atrial fibrillation. The model was char-acterized using the mean, Shannon entropy and approximate entropy of the electrograms (EGM). The model is made up of 22500 EGM and reductions of 75%, 93.5% and 97.3% in the spatial resolution of the model was conducted. Thereupon a reconstruction of the feature maps was realized using inverse distance weighted (IDW), inverse distance weighted-median filter (IDW-MF) and backpropagation artificial neural networks (BPANN), the performance of the techniques was analyzed using the root mean square error (RMSE) and the peak signal to noise ratio (PSNR). IDW shows a general RSME of 4.2% and a PSNR of 27.5dB, IDW-MF exhibited a RSME of 17.5% and a PSNR of 21.8 dB, finally BPANN shows a RSME of 9% and PSNR of 22.8 dB. IDW shows the best performance at any degree of reduction while IDW-MF represent the best approach for Shannon entropy and mean maps reconstruction and IDW has the best perfor-mance for approximate entropy maps reconstruction.	2014	9	https://link.springer.com/chapter/10.1007/978-3-319-13117-7_159
262	Análisis comparativo de tecnologías de transmisión	Revista QUID	Miguel A Becerra Botero, Oscar A Mejía Gonzales, Darío A Murillo, Sandra M Álvarez	Los sistemas de control de parquet) desempeñan una función clave en el marco de los sistemas inteligentes de transportes, La disponibilidad de las celdas de parqueo es difícil de controlar, por lo que se requiere un sistema de monitoreo que envié at sistema de administración de manera permanente, la disponibilidad de cada una de las celdas y permita una administración del parqueadero más eficiente. Las microondas terrestres son utilizadas en la transmisión inalámbrica de señales, caracterizándose por su bajo consumo de potencia y direccionalidad siendo ideales para la transmisión, en rango reducido, de señales de control basadas en protocolos coma Bluetooth, ZigBee y Wi-Fi. El presente artículo realiza un análisis comparativo de estas tecnologías, con el fin de seleccionar la más apropiada para ser aplicada en la red de sensores requerida para el sistema do control de celdas del parqueadero.	2011	9	http://revistas.proeditio.com/iush/quid/article/view/48
263	Simple ablation guided by ApEn mapping in a 2D model during permanent atrial fibrillation	Computing in Cardiology Conference (CinC), 2014	Catalina Tobón, Laura C Palacio, Juan E Duque, Esteban A Cardona, Juan P Ugarte, Andrés Orozco-Duque, Miguel A Becerra, Javier Saiz, John Bustamante	Atrial fibrillation (AF) is the most common cardiac arrhythmia. Catheter ablation has become the main therapeutic strategy for the treatment of paroxysmal AF, however, results in permanent AF are not completely satisfactory; complex ablation patterns are needed, thus it is of great interest to look for an ideal pattern with a minimum number of lines. Ablation of complex fractionated atrial electrograms (CFAE) has been proposed for the termination of rotors as mechanisms of AF maintenance. The aim of this work is to characterize the CFAE by implementing approximate entropy (ApEn) and to correlate it with the tip of a simulated rotor, in order to apply simple ablation patterns to terminate the rotor activity. For this, a rotor was simulated in a 2D model of human atrial tissue, under permanent AF conditions. Electrograms were recorded and an algorithm to measure ApEn was developed. Three ablation patterns were proposed and evaluated. The ApEn allowed locating the CFAE with high precision and relating them to the tip of the rotor. The ablation pattern that enclosed the rotor tip and that was extended to a conduction boundary was effective in the termination of the rotor. The ApEn could be very effective in identifying target sites for ablation.	2014	9	https://ieeexplore.ieee.org/abstract/document/7043221/
264	Análisis de dependencia usando regresión lineal múltiple y regresión de componentes principales en contaminantes delaire y parámetros meteorológicos caso de estudio	Revista QUID	Daniel Parra, Silvia Quijano, Diana Orrego, Miguel Becerra	La contaminación del aire ha sido un  problema ambiental y de salud en el mundo, se han propuesto varios métodos de regresión lineal multivariable para determinar niveles de asociación y dependencia entre contaminantes del aire y parámetros meteorológicos. Estos parámetros se caracterizan por tener información redundante e irrelevante, que es perjudicial para un modelo de regresión. En este contexto, un análisis de la dependencia mediante Regresión Lineal Múltiple y Regresión de Componentes Principales de los contaminantes del aire y parámetros meteorológicos fue desarrollado, encontrando una fuerte correlación entre el ozono y la temperatura (0.8) para la estación Tlalnepantla, así como un coeficiente de determinación de 82%. El modelo de PCR demostró que parámetros meteorológicos como temperatura y humedad relativa tienen un impacto significativo en la contaminación del aire en la Ciudad de México.	2014	9	http://revistas.proeditio.com/iush/quid/article/view/107
265	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	International Symposium on Neural Networks	Leandro Leonardo Lorente-Leyva, Israel David Herrera-Granda, Paul D Rosero-Montalvo, Karina L Ponce-Guevara, Andrés Eduardo Castro-Ospina, Miguel A Becerra, Diego Hernán Peluffo-Ordóñez, José Luis Rodríguez-Sotelo	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	9	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_37
266	Case-Based Reasoning Systems for Medical Applications with Improved Adaptation and Recovery Stages	International Conference on Bioinformatics and Biomedical Engineering	X Blanco Valencia, D Bastidas Torres, C Piñeros Rodriguez, Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina	Case-Based Reasoning Systems (CBR) are in constant evolution, as a result, this article proposes improving the retrieve and adaption stages through a different approach. A series of experiments were made, divided in three sections: a proper pre-processing technique, a cascade classification, and a probability estimation procedure. Every stage offers an improvement, a better data representation, a more efficient classification, and a more precise probability estimation provided by a Support Vector Machine (SVM) estimator regarding more common approaches. Concluding, more complex techniques for classification and probability estimation are possible, improving CBR systems performance due to lower classification error in general cases.	2018	9	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_3
267	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering	Jose Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A Becerra-Botero, Diego Hernán Peluffo-Ordóñez, Cesar Germán Castellanos-Domínguez	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	9	https://link.springer.com/chapter/10.1007/978-3-319-78759-6_22
268	Case-based reasoning applied to medical diagnosis and treatment	Distributed Computing and Artificial Intelligence	Xiomara Blanco, Sara Rodríguez, Juan M Corchado, Carolina Zato	The Case-Based Reasoning (CBR) is an appropriate methodology to apply in diagnosis and treatment. Research in CBR is growing and there are shortcomings, especially in the adaptation mechanism. In this paper, besides presenting a methodological review of the technology applied to the diagnostics and health sector published in recent years, a new proposal is presented to improve the adaptation stage. This proposal is focused on preparing the data to create association rules that help to reduce the number of cases and facilitate learning adaptation rules.	2013	14	https://link.springer.com/chapter/10.1007/978-3-319-00551-5_17
269	On the relationship between dimensionality reduction and spectral clustering from a kernel viewpoint	Distributed Computing and Artificial Intelligence, 13th International Conference	Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina, X Blanco-Valencia, Juan C Alvarado-Pérez, Roberto Therón, A Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	14	https://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
270	Kernel-based framework for spectral dimensionality reduction and clustering formulation: A theoretical study	ADCAIJ: Advances in Distributed Computing and Artificial Intelligence Journal	Xiomara Patricia Blanco Valencia, MA Becerra, AE Castro Ospina, M Ortega Adarme, D Viveros Melo, DH PELUFFO ORDÓÑEZ	This work outlines a unified formulation to represent spectral approaches for both dimensionality reduction and clustering. Proposed formulation starts with a generic latent variable model in terms of the projected input data matrix.\r\nParticularly, such a projection maps data onto a unknown high-dimensional space. Regarding this model, a generalized optimization problem is stated using quadratic formulations and a least-squares support vector machine.\r\nThe solution of the optimization is addressed through a primal-dual scheme.\r\nOnce latent variables and parameters are determined, the resultant model outputs a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Particularly, proposed\r\nformulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2017	14	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2017613140
272	Razonamiento basado en casos aplicado al diagnóstico médico utilizando clasificadores multi-clase: Un estudio preliminar	Enfoque UTE	D Viveros-Melo, M Ortega-Adarme, X Blanco Valencia, AE Castro-Ospina, S Murillo Rendón, DH Peluffo-Ordóñez	CBR ha demostrado ser apropiado para trabajar con datos de dominios poco estructurados o situaciones donde es difícil la adquisición de conocimiento, como es el caso del diagnóstico médico, donde es posible identificar enfermedades como: cáncer, predicción de epilepsia y diagnóstico de apendicitis. Algunas de las tendencias que se pueden desarrollar para CBR en la ciencia de la salud están orientadas a reducir el número de características en datos de gran dimensión. Una contribución importante puede ser la estimación de probabilidades de pertenencia a cada clase para los nuevos casos. Con el fin de representar adecuadamente la base de datos y evitar los inconvenientes causados por la alta dimensión, ruido y redundancia de los mimos, en este trabajo, se utiliza varios algoritmos en la etapa de pre-procesamiento para realizar una selección de variables y reducción de dimensiones. Además, se realiza una comparación del rendimiento de algunos clasificadores multi-clase representativos para identificar el más eficaz e incluirlo en un esquema CBR. En particular, se emplean cuatro técnicas de clasificación y dos técnicas de reducción para hacer un estudio comparativo de clasificadores multi-clase sobre CBR	2016	14	http://www.ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/141
273	The Colombian Cardiovascular Foundation at the forefront of technology	Revista Colombiana de Cardiología	Xiomara P Blanco, Wilson Gamboa	The Colombian Cardiovascular Foundation is aware of the importance of investing in research, development and innovation in order to incorporate and use scientific and technological advances that may contribute to the socio-economical development of the region and the country. Therefore, it has incremented its strategies to promote both a technological culture in our society, and the development of new local technologies or the adaptation of foreign ones to our needs. To achieve these goals, the Colombian Cardiovascular Foundation has created areas such as the strategic business unit FCV. Soft Software Factory, the bioengineering research group, the pediatric research unit and the unit of computer technology, that demand the integration of processes of technological development and the incorporation of new technologies to the regular clinical practice in a third complexity level institution.	2006	14	http://www.scielo.org.co/scielo.php?script=sci_arttext&pid=S0120-56332006000500005
274	La Fundación Cardiovascular de Colombia a la vanguardia de la tecnología The Colombian Cardiovascular Foundation at the forefront of technology	Revista Colombiana de Cardiologia	Xiomara P Blanco, Wilson Gamboa	Antecedentes: la Fundación Cardiovascular de Colombia es una institución conciente de que la inversión en investigación, desarrollo e innovación, es un elemento fundamental para la incorporación y el aprovechamiento de avances científicos y tecnológicos que contribuyen al desarrollo socio-económico de la región y del país. Por esta razón, ha enfocado sus esfuerzos en la implementación de estrategias que promuevan una cultura tecnológica en nuestra sociedad y fomenten el desarrollo local de nuevas tecnologías o la adaptación de las mismas a nuestras necesidades. Para alcanzar estas metas, la Fundación Cardiovascular de Colombia ha creado áreas como la unidad estratégica de negocios FCV.Soft Software Factory, el grupo de investigación de bioingeniería, el área de investigación en pediatría y el área de tecnología informática que demandan de la institución la integración de los procesos de desarrollo tecnológico y la incorporación de nuevas tecnologías con los procesos asistenciales habituales en una institución clínica de tercer nivel de complejidad. Objetivo: describir la experiencia de la Fundación Cardiovascular de Colombia en la integración de la bioingeniería y sus especialidades a la práctica clínica convencional. Conclusiones: la aplicación de la bioingeniería a la práctica clínica convencional, constituye una fortaleza institucional que favorece la competitividad de las instituciones e impulsa el mejoramiento de la calidad de vida de los pacientes, ya que permite la creación de nuevas herramientas para apoyar la toma de decisiones médicas de una manera eficiente y oportuna.\r\nBackground: the Colombian Cardiovascular Foundation is aware of the importance of investing in research, development and innovation in order to incorporate and use scientific and technological advances that may contribute to the socio-economical development of the region and the country. Therefore, it has incremented its strategies to promote both a technological culture in our society, and the development of new local technologies or the adaptation of foreign ones to our needs. To achieve these goals, the Colombian Cardiovascular Foundation has created areas such as the strategic business unit FCV. Soft Software Factory, the bioengineering research group, the pediatric research unit and the unit of computer technology, that demand the integration of processes of technological development and the incorporation of new technologies to the regular clinical practice in a third complexity level institution. Objective: to describe the experience of the Colombian Cardiovascular Foundation in the integration of bioengineering and its specialties to the conventional clinical practice. Conclusions: the utilization of bioengineering in the conventional clinical practice favors institutional competitivity and motivates the improvement of the patients’ quality of life, as it allows the creation of new tools to support the medical decisions in an efficient and timely way.	2006	14	https://www.ingentaconnect.com/content/doaj/01205633/2006/00000013/00000002/art00006
275	A multi-class extension for case-based reasoning applied to medical problems: A first approach	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	D Viveros-Melo, M Ortega-Adarme, X Blanco Valencia, AE Castro-Ospina, S Murillo Rendón, DH Peluffo-Ordóñez	Case-based reasoning (CBR) is a problem solving approach that uses past experience to tackle current problems. CBR has demonstrated to be appropriate for working with unstructured domains data or difficult knowledge acquisition situations, as it is the case of the diagnosis of many diseases. Some of the trends and opportunities that may be developed for CBR in the health science are oriented to reduce the number of features in highly dimensional data, as well as another important focus on how CBR can associate probabilities and statistics with its results by taking into account the concurrence of several ailments. In this paper, in order to adequately represent the database and to avoid the inconveniences caused by the high dimensionality, a number of algorithms are used in the preprocessing stage for performing both variable selection and dimension reduction procedures. Subsequently, we make a comparative study of multi- class classifiers. Particularly, four classification techniques and two reduction techniques are employed to make a comparative study of multi-class classifiers on CBR.	2015	14	https://www.researchgate.net/profile/Mabel_Ortega/publication/311680679_A_multi-class_extension_for_case-based_reasoning_applied_to_medical_problems_A_first_approach/links/5854407408ae81995eb1d12a/A-multi-class-extension-for-case-based-reasoning-applied-to-medical-problems-A-first-approach.pdf
271	Case-Based Reasoning Systems for Medical Applications with Improved Adaptation and Recovery Stages	International Conference on Bioinformatics and Biomedical Engineering	X Blanco Valencia, D Bastidas Torres, C Piñeros Rodriguez, Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina	Case-Based Reasoning Systems (CBR) are in constant evolution, as a result, this article proposes improving the retrieve and adaption stages through a different approach. A series of experiments were made, divided in three sections: a proper pre-processing technique, a cascade classification, and a probability estimation procedure. Every stage offers an improvement, a better data representation, a more efficient classification, and a more precise probability estimation provided by a Support Vector Machine (SVM) estimator regarding more common approaches. Concluding, more complex techniques for classification and probability estimation are possible, improving CBR systems performance due to lower classification error in general cases.	2018	14	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_3
276	Case based reasoning applied to medical diagnosis using multi-class classifier: A preliminary study	Enfoque UTE	D Viveros-Melo, M Ortega-Adarme, X Blanco Valencia, AE Castro-Ospina, S Murillo Rendón, DH Peluffo-Ordóñez	Case-based reasoning (CBR) is a process used for computer processing that tries to mimic the behavior of a human expert in making decisions regarding a subject and learn from the experience of past cases. CBR has demonstrated to be appropriate for working with unstructured domains data or difficult knowledge acquisition situations, such as medical diagnosis, where it is possible to identify diseases such as: cancer diagnosis, epilepsy prediction and appendicitis diagnosis. Some of the trends that may be developed for CBR in the health science are oriented to reduce the number of features in highly dimensional data. An important contribution may be the estimation of probabilities of belonging to each class for new cases. In this paper, in order to adequately represent the database and to avoid the inconveniences caused by the high dimensionality, noise and redundancy, a number of algorithms are used in the preprocessing stage for performing both variable selection and dimension reduction procedures. Also, a comparison of the performance of some representative multi-class classifiers is carried out to identify the most effective one to include within a CBR scheme. Particularly, four classification techniques and two reduction techniques are employed to make a comparative study of multiclass classifiers on CBR	2017	14	https://www.ingentaconnect.com/content/doaj/13906542/2017/00000008/00000001/art00017
277	Low Data Fusion Framework Oriented to Information Quality for BCI Systems	International Conference on Bioinformatics and Biomedical Engineering 2018	Miguel Alberto Becerra, Karla C. Alvarez-Uribe, Diego Hernán Peluffo Ordoñez.	The evaluation of the data/information fusion systems does not have standard quality criteria making the reuse and optimization of these systems a complex task. In this work, we propose a complete low data fusion (DF) framework based on the Joint Director of Laboratories (JDL) model, which considers contextual information alongside information quality (IQ) and performance evaluation system to optimize the DF process according to the user requirements. A set of IQ criteria was proposed by level. The model was tested with a brain-computer interface (BCI) system multi-environment to prove its functionality. The first level makes the selection and preprocessing of electroencephalographic signals. In level one feature extraction is carried out using discrete wavelet transform (DWT), nonlinear and linear statistical measures, and Fuzzy Rough Set – FRS algorithm for selecting the relevant features; finally, in the same level a classification process was conducted using support vector machine – SVM. A Fuzzy Inference system is used for controlling different processes based on the results given by an IQ evaluation system, which applies quality measures that can be weighted by the users of the system according to their requirements. Besides, the system is optimized based on the results given by the cuckoo search algorithm, which uses the IQ traceability for maximizing the IQ criteria according to user requirements. The test was carried out with different type and levels of noise applied to the signals. The results showed the capability and functionality of the model.	2018	9	https://link.springer.com/chapter/10.1007%2F978-3-319-78759-6_27
278	Interactive data visualization using dimensionality reduction and similarity-based representations	Iberoamerican Congress on Pattern Recognition	P Rosero-Montalvo, P Diaz, JA Salazar-Castro, DF Peña-Unigarro, AJ Anaya-Isaza, Juan C Alvarado-Pérez, Roberto Therón, Diego Hernán Peluffo-Ordóñez	This work presents a new interactive data visualization approach based on mixture of the outcomes of dimensionality reduction (DR) methods. Such a mixture is a weighted sum, whose weighting factors are defined by the user through a visual and intuitive interface. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to be drawn on the scatter plot. Our visualization approach enables the user to interactively combine DR methods while provided information about the structure of original data, making then the selection of a DR scheme more intuitive.	2017	8	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_41
279	Interactive visualization methodology of high-dimensional data with a color-based model for dimensionality reduction	Signal Processing, Images and Artificial Vision (STSIVA), 2016 XXI Symposium on	Diego F Peña-ünigarro, Jose A Salazar-Castro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, Omar R Oña-Rocha, Andres A Isaza, Juan C Alvarado-Perez, Roberto Theron	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	8	https://ieeexplore.ieee.org/abstract/document/7743318/
280	Data Visualization Using Interactive Dimensionality Reduction and Improved Color-Based Interaction Model	International Work-Conference on the Interplay Between Natural and Artificial Computation	PD Rosero-Montalvo, DF Peña-Unigarro, DH Peluffo, JA Castro-Silva, A Umaquinga, EA Rosero-Rosero	This work presents an improved interactive data visualization interface based on a mixture of the outcomes of dimensionality reduction (DR) methods. Broadly, it works as follows: The user can input the mixture weighting factors through a visual and intuitive interface with a primary-light-colors-based model (Red, Green, and Blue). By design, such a mixture is a weighted sum of the color tone. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to simultaneously be drawn over the scatter plot. Our interface enables the user to interactively combine DR methods by the human perception of color, while providing information about the structure of original data. Then, it makes the selection of a DR scheme more intuitive -even for non-expert users.	2017	8	https://link.springer.com/chapter/10.1007/978-3-319-59773-7_30
281	Interactive Data Visualization Using Dimensionality Reduction and Dissimilarity-Based Representations	International Conference on Intelligent Data Engineering and Automated Learning	DF Peña-Unigarro, P Rosero-Montalvo, EJ Revelo-Fuelagán, JA Castro-Silva, JC Alvarado-Pérez, R Therón, CM Ortega-Bustamante, DH Peluffo-Ordóñez	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	8	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
282	Dimensionality reduction for interactive data visualization via a Geo-Desic approach	Computational Intelligence (LA-CCI), 2016 IEEE Latin American Conference on	Jose A Salazar-Castro, Diego Peña-Unigarro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, H Mauricio Domínguez-Limaico, Juan C Alvarado-Pérez, Roberto Therón	This work presents a dimensionality reduction (DR) framework that enables users to perform either the selection or mixture of DR methods by means of an interactive model, here named Geo-Desic approach. Such a model consists of linear combination of kernel-based representations of DR methods, wherein the corresponding coefficients are related to coordinated latitude and longitude inside of the world map. By incorporating the Geo-Desic approach within an interface, the combination may be made easily and intuitively by users -even non-expert ones- fulfilling their criteria and needs, by just picking up points from the map. Experimental results demonstrates the usability and ability of DR methods representation of proposed approach.	2016	8	https://ieeexplore.ieee.org/abstract/document/7885740/
283	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA	INCISCOS 2016, 2017	Andrés J Anaya-Isaza, Diego H Peluffo-Ordoñez, Juan C Alvarado-Pérez, Jorge Ivan-Rios, Juan A Castro-Silva, Paul D Rosero-Montalvo, Diego F Peña-Unigarro, Ana C Umaquinga-Criollo	This paper presents a comparative study with methods of reducing the linear dimension, such as Principal Component Analysis & linear discriminant analysis. The study aims to determine, based on criteria of objectivity, which of these techniques get the best result of separability between classes. For experimental validation two databases, scientific repository (UC Irvine Machine Learning Repository) are used to provide treatment to the attributes of the data-set according to visually confirm the quality of the results. The dives obtained are analyzed, for comparison of results embedimiento represented with RNX (K), which evaluates the area under the curve, which assumes better representation in a local global topology or subsequently generates graphics display a space of smaller dimension, to observe the class separability preserving the overall structure of the data.	2017	8	https://www.researchgate.net/profile/Ana_Umaquinga/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA/links/5846c4e008ae61f75ddfd956.pdf
284	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering	Jose Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A Becerra-Botero, Diego Hernán Peluffo-Ordóñez, Cesar Germán Castellanos-Domínguez	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	4	https://link.springer.com/chapter/10.1007/978-3-319-78759-6_22
285	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	Lecture Notes in Computer Science	Leandro Leonardo Lorente Leyva, Israel Herrera, Paul Rosero, Jose LUIS Rodriguez-Sotelo.	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	15	https://www.researchgate.net/publication/325363575_Developments_on_Solutions_of_the_Normalized-Cut-Clustering_Problem_Without_Eigenvectors
286	ANÁLISIS DE INDICADORES DE APROVECHAMIENTO DE BODEGAS. CASO DE ESTUDIO CIUDAD DE IBARRA	Revista Observatorio de la Economía Latinoamericana	Yakcleem Montero Santos, Jonatan Estiven Mafla Narvaez, Carlos Alberto Machado Orges, Israel David Herrera Granda, Leandro Leonardo Lorente Leyva	La investigación se realizó con el propósito de evaluar los indicadores de explotación de almacenes, en la ciudad de Ibarra, Ecuador. Para esto, se elige el procedimiento diseñado por (Narvaez J. E., 2017). El diagnóstico inicial (Yakcleem Montero Santos, 2016) establece que el uso del área, la altura y el volumen de la tienda no estaban dentro de los rangos específicos para alcanzar un índice de eficiencia óptimo. Por lo tanto, se decidió aplicar el procedimiento antes mencionado para hacer una propuesta de mejora a la bodega en estudio. Inicialmente se comienza con el análisis ABC de los inventarios, luego realiza la distribución en planta a través del software Corelap 1.0 y el análisis del método operativo (Torres, 2013) para el nuevo diseño del layuot, lo que permitirá elevar el nivel tecnológico del almacén.	2018	15	https://www.researchgate.net/publication/323344764_ANALISIS_DE_INDICADORES_DE_APROVECHAMIENTO_DE_BODEGAS_CASO_DE_ESTUDIO_CIUDAD_DE_IBARRA
288	Intelligent Adaptation of Axisymmetric Solid Parts in Machining Process Planning by Case Based Reasoning	International Journal of Intelligent Engineering and Systems	A.C. García, R.S. Lancho, A.M.L. Aleaga, Leandro Leonardo Lorente Leyva	The goal of this paper is the adaptation of plans of manufacturing processes of Axisymmetric Solid Parts under the approach of Case Based Reasoning (CBR). To this end, a data model for feature-based representation has been developed, which contains the geometric, dimensional and technological information required for the preparation of the one-piece process plan. As a result, an algorithm to generate new parts process plans from a similar plan retrieved from the case base is presented, which is based on the specific information of the Primitive Form Features (PFF) and considers the possible interaction between neighboring PFFs. The computer support of the developed algorithm was implemented in AutoLISP as programming language of the CAD system used and the interface was created in OpenDCL.	2017	15	https://www.researchgate.net/publication/317214784_Intelligent_Adaptation_of_Axisymmetric_Solid_Parts_in_Machining_Process_Planning_by_Case_Based_Reasoning
289	Método de Colonia de Hormigas para el Corte de Piezas en Chapas	Décima Quinta Conferencia Iberoamericana en Sistemas	Arlys M. LASTRE ALEAGA, Leonardo L. LORENTE LEYVA, Alexis CORDOVÉS GARCÍA	El presente trabajo comprende la concepción, desarrollo y la implementación de un procedimiento con el empleo del Método de Colonia de Hormigas para el corte de piezas en chapas , que concilia las restricciones del proceso tecnológico empleado y garantiza la obtención de soluciones con la menor trayectoria de corte. La concepción general del sistema propuesto fue implementada en la práctica durante la operación de una la máquina de corte por plasma Merlin 6000GST. Como resultado práctico, se ha obtenido una aplicación soportada sobre AutoCAD, y desarrollada en lenguaje de programación AutoLISP y Opendcl, la cual se integra a un sistema CAD/CAPP obteniéndose una herramienta para la generación de trayectorias para el corte de piezas en chapas.	2016	15	https://www.researchgate.net/publication/318883440_Metodo_de_Colonia_de_Hormigas_para_el_Corte_de_Piezas_en_Chapas
290	USE OF JATROPHA CURCAS PLANT AS RENEWABLE ENERGY FOR ENVIRONMENTAL AND SUSTAINABLE DEVELOPMENT OF A FARM IN GRANMA PROVINCE, CUBA.	RESEARCHGATE	Bárzaga Quesada Joao L., Rodríguez Ponce Yoandro, Mena Mena Euro R., Beltrán Reyna Roberto F.	The present research is based on the renewable energy sources utilization to achieve an environmental and sustainable development of the Antonio Sánchez Días farm and with it decreasing the climatic change that is generated in the world at present. In order to achieve such objective it proposes the planting of the Jatropha Curcas plant for reforestation and decrease of the environmental impact allowing getting oil from his fruits and use residual products and animal wastes to producing biofuels. As a result of the research it can be seen to be able to extract and characterize the plant oil yield values similar to other work according to the rules used the oil can be used as biofuel in power generation and agricultural tractors belonging to the farm, besides were obtained the size of a digester to produce biogas that will generate 40 days of operation a volume of 29 m3 of gas for cooking food.	2015	15	https://www.researchgate.net/publication/308398413_USE_OF_JATROPHA_CURCAS_PLANT_AS_RENEWABLE_ENERGY_FOR_ENVIRONMENTAL_AND_SUSTAINABLE_DEVELOPMENT_OF_A_FARM_IN_GRANMA_PROVINCE_CUBA
300	On the Relationship Between Dimensionality Reduction and Spectral Clustering from a Kernel Viewpoint	Distributed Computing and Artificial Intelligence, 13th International Conference	Diego Hernán Peluffo-Ordóñez, MA Becerra, Andrés Eduardo Castro-Ospina, X Blanco-Valencia, Juan C Alvarado-Pérez, R Therón, A Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	10	https://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
318	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering	Jose Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A Becerra-Botero, Diego Hernán Peluffo-Ordóñez, Cesar Germán Castellanos-Domínguez	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	17	https://link.springer.com/chapter/10.1007/978-3-319-78759-6_22
287	Optimization of the University Transportation by Contraction Hierarchies Method and Clustering Algorithms	HAIS: International Conference on Hybrid Artificial Intelligence Systems	Israel D. Herrera-GrandaLeandro, L. Lorente-Leyva, Diego H. Peluffo-Ordóñez, Robert M. Valencia-Chapi, Yakcleem Montero-	This research work focuses on the study of different models of solution reflected in the literature, which treat the optimization of the routing of vehicles by nodes and the optimal route for the university transport service. With the recent expansion of the facilities of a university institution, the allocation of the routes for the transport of its students, became more complex. As a result, geographic information systems (GIS) tools and operations research methodologies are applied, such as graph theory and vehicular routing problems, to facilitate mobilization and improve the students transport service, as well as optimizing the transfer time and utilization of the available transport units. An optimal route management procedure has been implemented to maximize the level of service of student transport using the K-means clustering algorithm and the method of node contraction hierarchies, with low cost due to the use of free software.	2018	15	https://www.researchgate.net/profile/Israel_Herrera4/publication/325623085_Optimization_of_the_University_Transportation_by_Contraction_Hierarchies_Method_and_Clustering_Algorithms/links/5b3ba3890f7e9b0df5ec469e/Optimization-of-the-University-Transportation-by-Contraction-Hierarchies-Method-and-Clus
291	Diseño de biodigestor a escala de laboratorio para la digestión anaerobia e industrialización energética de los desechos sólidos municipales	Revista DELOS Desarrollo Local Sostenible n.31	Leandro L. Lorente Leyva, Gerardo Collaguazo Galeano, Israel D. Herrera Granda, Ramiro V. Saraguro Piarpuezan, Arlys M. Lastre Aleaga y Alexis Cordovés García	The energy sector is in constant search of new clean sources of energy, both to supplement its production, as well as to reduce dependence on fossil fuels and its gradual replacement based on sustainable development methods. In this context, municipal waste is considered as a renewable energy source, since they have a high biomass content (paper, cardboard, food waste, wood, straw, leaves). A renewable source alternative with great prospects for the future is the use and energetic valuation of municipal solid waste. This research aims at the design of a laboratory-scale biodigester for the energetic industrialization of municipal solid waste, serving as a basis for the construction of a prototype on a pilot scale or a plant for the Anaerobic treatment of these generated wastes. In this way, it will be possible to recover the energy contained in them, in order to reduce the flow of the waste destined to the landfills and to provide a production rate for the obtaining of biogas, taking as fundamental basis for the calculations of design and the Improvement of laboratory-level production, through co-digestion with other types of organic waste and use of alkaline inoculating substances and determination of the most appropriate anaerobic digestion technology for waste treatment Municipal solids.	2018	15	https://www.eumed.net/rev/delos/31/leandro-lorente.html
292	Estudio de factibilidad para la reutilización, reciclaje y procesamiento de neumáticos fuera de uso	Revista Observatorio de la Economía Latinoamericana	Sebastián Vásquez Pozo, Leandro L. Lorente Leyva, Carlos A. Machado Orges, Yakcleem Montero Santos e Israel D. Herrera Granda	Due to the vital importance of ensuring the permanence of companies in the market over time, the investor must have a high degree of possibility of not failing at the moment of implementing their business, ensuring that it will be economically viable, proceeded to carry out the present investigation with the purpose of knowing the economic feasibility of the opening of a plant of processing of tires out of use inside the city of Ibarra, carrying out a series of steps that start with the bibliographical revision to find a methodology that allows to develop a feasibility study, which determined the completion of a market study as the first point which yielded favorable results in search of a demand to satisfy and that was: for rubber granulation demand in the years 2018, 2019, 2020, 2021 and 2022 will be 284, 509.2, 775.2, 1082.9, 1178.8 ton / year respectively and for recycled steel in 2018, 2019, 2020, 2021 and 2022 of 100, 176, 263.45, 363.3 and 391.3 tons / year, respectively, which allow us to see a positive outlook for developing the product. As a second point, a technical study was developed, which allows the search for the appropriate machinery for the fulfillment of the demand, analyzing and proposing the purchase of an out-of-use tire processing line that has a processing capacity of 0.6 ton / hour, which is considered adequate to meet the expectations raised in the market study. As a final step, a financial study was proposed that contains a comprehensive analysis of the indicators developed in this section and will allow the conclusion of whether the project is viable or not. For this purpose, the evaluation of the results obtained was: NPV = 364 336.21; R B / C = 2.51; TIR = 27% and PRI = 1.30, and according to the analysis of the evaluation criteria of an investment project, the plant for the processing of out-of-use tires is ready for start-up, since the project is profitable and feasible.	2018	15	https://www.eumed.net/rev/oel/2018/04/reutilizacion-neumaticos.html
293	Diseño de sistema de aprovisionamiento para una la línea de repuestos automotores. Caso de estudio	Revista Observatorio de la Economía Latinoamericana	Yakcleem Montero Santos, Israel David Herrera Granda, Carlos Alberto Machado Orges, Erik Orozco Crespo y Leandro Leonardo Lorente Leyva	The research was done for a line of automotive spare parts in the city of Ibarra in Ecuador. With the objective of designing the system of provisioning for the company object of study and thus to satisfy the needs of the clients in time, quantity and specifications. This was achieved through an analysis of historical sales data for 3 years. The ABC classification was performed for a total of 159 articles of type C, 95 type B and 63 type A; this last group of articles, using the statistical software ForecastPro Trac, the sales forecasts of each article were executed. Due to the stable demand that already shows the importance of each article, as well as the value obtained from the coefficient of variability, the EOQ model was applied. The execution of the selected model allowed to obtain lower costs, establishing the optimal quantity of orders, as well as the moment in which the new order is made, considering the security inventory of the products.	2017	15	http://www.eumed.net/cursecon/ecolat/ec/2017/diseno-sistema-automotores.html
301	Multiple kernel learning for spectral dimensionality reduction	Iberoamerican Congress on Pattern Recognition	Diego Hernán Peluffo-Ordóñez, Andrés Eduardo Castro-Ospina, Juan Carlos Alvarado-Pérez, Edgardo Javier Revelo-Fuelagán	This work introduces a multiple kernel learning (MKL) approach for selecting and combining different spectral methods of dimensionality reduction (DR). From a predefined set of kernels representing conventional spectral DR methods, a generalized kernel is calculated by means of a linear combination of kernel matrices. Coefficients are estimated via a variable ranking aimed at quantifying how much each variable contributes to optimize a variance preservation criterion. All considered kernels are tested within a kernel PCA framework. The experiments are carried out over well-known real and artificial data sets. The performance of compared DR approaches is quantified by a scaled version of the average agreement rate between K-ary neighborhoods. Proposed MKL approach exploits the representation ability of every single method to reach a better embedded data for both getting more intelligible visualization and preserving the structure of data.	2015	10	https://link.springer.com/chapter/10.1007/978-3-319-25751-8_75
294	Una revisión del estado del arte de la optimización de rutas de recolección de residuos sólidos municipales en países en vías de desarrollo	Tecnologias Aplicadas a la Ingeniería	Herrera I., Collaguazo G., Lorente L., Montero Y. y Valencia R.	El presente trabajo consiste en la revisio ́n de las metodolog ́ıas para la optimizacio ́n de la red de recoleccio ́n y disposicio ́n de Residuos So ́lidos Municipales (RSM) en pa ́ıses en v ́ıas de desarrollo, como parte de un enfoque hol ́ıstico para la adecuada gestio ́n de RSM, dentro del cual se detallan las t ́ecnicas para la optimiza- cio ́n de las rutas recorridas por los camiones recolectores de RSM. Dando cabida al estudio del enrutamiento de los camiones recolectores de residuos so ́lidos municipales (WCVRP). Una extensa revisio ́n del estado del arte de la optimizacio ́n de rutas de recoleccio ́n de RSM demostro ́ la viabilidad y factibilidad de aplicar metodolog ́ıas para el modelamiento de los diferentes WCVRP y los beneficios obtenidos mediante estas implementaciones en distintas localidades, se hace tambi ́en una revisio ́n del software para tratar el WCVRP tanto comercial como tambi ́en de las opciones de acceso libre, a las cuales se les da mayor relevancia. Adicionalmente se presenta una clasificacio ́n esquema ́tica de los diferentes modelos matema ́ticos para el tratamiento del WCVRP y se revisan las aplicaciones que han aportado mayores impactos en t ́erminos de optimizacio ́n de las rutas de reco- leccio ́n de RSM en los u ́ltimos an ̃os, finalmente se revisan las implementaciones sobre esta tem ́atica en Ecuador.	2016	15	https://issuu.com/utnuniversity/docs/ebook-tecnologias-aplicadas-a-la-in
295	Planta satélite de gas natural licuado para el abastecimiento del sector industrial en Cuenca – Ecuador	DELOS	Robert Valencia Chapi, Gerardo Collaguazo Galeano, Leandro Lorente Leyva, Israel Herrera Granda	The object of this paper is the design and construction of an LNG satellite plant to supply the industrial sector of the city of Cuenca in Ecuador. The idea came from to partially replace the consumption of liquefied petroleum gas (LPG) for liquefied natural gas (LNG). One of the main reasons is that the refining process for LPG increasing cost, so a cheaper option arises, and this would be to use LNG. A growing demand for natural gas is expected, so the government is currently implementing a project on extraction and liquefaction of natural gas in the Gulf of Guayaquil, initially the distribution of LNG will be made through the trading of LPG.	2016	15	http://www.eumed.net/rev/delos/27/gas.html
296	A kernel-based representation to support 3d mri unsupervised clustering	22nd International Conference on Pattern Recognition (ICPR)	David Cardenas-Pena, Mauricio Orbes-Arteaga, Andres Castro-Ospina, Andres Alvarez-Meza, Germán Castellanos-Dominguez	A new kernel-based image representation is proposed on this paper aiming to support clustering tasks on 3D magnetic resonances images. The approach establishes an effective way to encode inter-slice similarities, so that the main shape information is kept on a lower dimensional space. Additionally, a spectral clustering technique is employed to estimate a compact embedding space where natural groups are easily detectable. Proposed approach outperforms the conventional voxel-wise sum of squared differences on clustering the gender category. Additionally, a pair of eigenvectors describing accurately the subject age is found.	2014	10	https://www.computer.org/csdl/proceedings/icpr/2014/5209/00/5209d203-abs.html
297	Feature extraction schemes for BCI systems	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium on	L Vega-Escobar, AE Castro-Ospina, L Duque-Muñoz	Brain-computer Interfaces (BCIs) are control and communication systems based on acquisition and processing of brain signals to control a computer or an external device. Usually, BCI is focused in recognizing acquired events by different neuroimage methods, but the most used is the electroencephalography (EEG). Feature extraction over EEG signals for BCI systems is crucial to the classification performance. In this paper a comparison between various methods for feature extraction of EEG signals in BCI systems is presented. Different methodologies were taken into account, both at extracting frequency information from each electrode as for extracting shared information between electrodes.	2015	10	https://ieeexplore.ieee.org/abstract/document/7330455/
298	Novel heuristic search for ventricular arrhythmia detection using normalized cut clustering	Engineering in Medicine and Biology Society (EMBC), 2013 35th Annual International Conference of the IEEE	AE Castro-Ospina, C Castro-Hoyos, D Peluffo-Ordonez, G Castellanos-Dominguez	Processing of the long-term ECG Holter recordings for accurate arrhythmia detection is a problem that has been addressed in several approaches. However, there is not an outright method for heartbeat classification able to handle problems such as the large amount of data and highly unbalanced classes. This work introduces a heuristic-search-based clustering to discriminate among ventricular cardiac arrhythmias in Holter recordings. The proposed method is posed under the normalized cut criterion, which iteratively seeks for the nodes to be grouped into the same cluster. Searching procedure is carried out in accordance to the introduced maximum similarity value. Since our approach is unsupervised, a procedure for setting the initial algorithm parameters is proposed by fixing the initial nodes using a kernel density estimator. Results are obtained from MIT/BIH arrhythmia database providing heartbeat labelling. As a result, proposed heuristic-search-based clustering shows an adequate performance, even in the presence of strong unbalanced classes.	2013	10	https://ieeexplore.ieee.org/abstract/document/6611188/
299	Normalized cuts clustering with prior knowledge and a pre-clustering stage.	ESANN	Diego Hernán Peluffo-Ordóñez, Andrés Eduardo Castro-Ospina, Diego Chavez-Chamorro, Carlos Daniel Acosta-Medina, Germán Castellanos-Domínguez	Clustering is of interest in cases when data are not labeled enough and a prior training stage is unfeasible. In particular, spectral clustering based on graph partitioning is of interest to solve problems with highly non-linearly separa- ble classes. However, spectral methods, such as the well-known normalized cuts, involve the computation of eigenvectors that is a highly time-consuming task in case of large data. In this work, we propose an alternative to solve the normalized cuts problem for clustering, achieving same results as conventional spectral meth- ods but spending less processing time. Our method consists of a heuristic search to find the best cluster binary indicator matrix, in such a way that each pair of nodes with greater similarity value are first grouped and the remaining nodes are clustered following a heuristic algorithm to search into the similarity-based representation space. The proposed method is tested over a public domain image data set. Results show that our method reaches comparable results with a lower computational cost.	2013	10	https://www.researchgate.net/profile/Diego_Peluffo/publication/282295220_Normalized_Cuts_Clustering_with_Prior_Knowledge_and_a_Pre-clustering_Stage/links/560b129e08ae840a08d6851e/Normalized-Cuts-Clustering-with-Prior-Knowledge-and-a-Pre-clustering-Stage.pdf
305	Analysis of Motor Imaginary BCI Within Multi-environment Scenarios Using a Mixture of Classifiers	Colombian Conference on Computing	M Ortega-Adarme, M Moreno-Revelo, DH Peluffo-Ordoñez, D Marín Castrillon, AE Castro-Ospina, MA Becerra	Brain-computer interface (BCI) is a system that provides communication between human beings and machines through an analysis of human brain neural activity. Several studies on BCI systems have been carried out in controlled environments, however, a functional BCI should be able to achieve an adequate performance in real environments. This paper presents a comparative study on alternative classification options to analyze motor imaginary BCI within multi-environment real scenarios based on mixtures of classifiers. The proposed methodology is as follows: The imaginary movement detection is carried out by means of feature extraction and classification, in the first stage; feature set is obtained from wavelet transform, empirical mode decomposition, entropy, variance and rates between minimum and maximum, in the second stage, where several classifier combinations are applied. The system is validated using a database, which was constructed using the Emotiv Epoc+ with 14 channels of electroencephalography (EEG) signals. These were acquired from three subject in 3 different environments with the presence and absence of disturbances. According to the different effects of the disturbances analyzed in the three environments, the performance of the mixture of classifiers presented better results when compared to the individual classifiers, making it possible to provide guidelines for choosing the appropriate classification algorithm to incorporate into a BCI system.	2017	10	https://link.springer.com/chapter/10.1007/978-3-319-66562-7_37
306	Kernel-based framework for spectral dimensionality reduction and clustering formulation: A theoretical study	ADCAIJ: ADVANCES IN DISTRIBUTED COMPUTING AND ARTIFICIAL INTELLIGENCE JOURNAL	X Blanco-Valencia, MA Becerra, AE Castro-Ospina, M Ortega-Adarme, D Viveros-Melo, JC Alvarado-Pérez, DH Peluffo-Ordóñez	This work outlines a unified formulation to represent spectral approaches for both dimensionality reduction and clustering. Proposed formulation starts with a generic latent variable model in terms of the projected input data matrix.\r\nParticularly, such a projection maps data onto a unknown high-dimensional space. Regarding this model, a generalized optimization problem is stated using quadratic formulations and a least-squares support vector machine.\r\nThe solution of the optimization is addressed through a primal-dual scheme.\r\nOnce latent variables and parameters are determined, the resultant model outputs a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Particularly, proposed\r\nformulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2017	10	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2017613140
307	Automatic graph pruning based on kernel alignment for spectral clustering	Pattern Recognition Letters	Andrés Marino Álvarez-Meza, Andrés Eduardo Castro-Ospina, Germán Castellanos-Dominguez	Detection of data structures in spectral clustering approaches becomes a difficult task when dealing with complex distributions. Moreover, there is a need of a real user prior knowledge about the influence of the free parameters when building the graph. Here, we introduce a graph pruning approach, termed Kernel Alignment based Graph Pruning (KAGP), within a spectral clustering framework that enhances both the local and global data consistencies for a given input similarity. The KAGP allows revealing hidden data structures by finding relevant pair-wise relationships among samples. So, KAGP estimates the loss of information during the pruning process in terms of a kernel alignment-based cost function. Besides, we encode the sample similarities using a compactly supported kernel function that allows obtaining a sparse data representation to support spectral clustering techniques. Attained results shows that KAGP enhances the clustering performance in most of the cases. In addition, KAGP avoids the need for a comprehensive user knowledge regarding the influence of its free parameters.	2015	10	https://www.sciencedirect.com/science/article/pii/S016786551500392X
308	Spectral Clustering Using Compactly Supported Graph Building	Iberoamerican Congress on Pattern Recognition	Andrés Marino Álvarez-Meza, Andrés Eduardo Castro-Ospina, Germán Castellanos-Dominguez	Clustering techniques demand on suitable models of data structures to infer the main samples patterns. Nonetheless, detection of data structures becomes a difficult task when dealing with nonlinear data relationships and complex distributions. Here, to support clustering tasks, we introduce a new graph building strategy based on a compactly supported kernel technique. Thus, our approach makes relevant pair-wise sample relationships by finding a sparse kernel matrix that codes the main sample connections. Clustering performance is assessed on synthetic and real-world data sets. Obtained results show that the proposed method enhances the data interpretability and separability by revealing relevant data relationships into a graph-based representation.	2014	10	https://link.springer.com/chapter/10.1007/978-3-319-12568-8_40
331	Large scale continuation using a block eigensolver	Universidad Central de Venezuela Facultad de Ciencias	Zenaida Castillo	This paper presents a new algorithm to find and follow particular solutions of para-meterized nonlinear systems. A block eigenvalue solver is embedded in a continuation framework for the computation of some eigenvalues of large Jacobian matrices depending on one parameter. Experiments on several problems show the reliability of the new approach in the accurate detection of critical points. As a byproduct, one obtains information about the stability of the process with no additional cost.	2017	24	https://www.researchgate.net/publication/228454176_Large_scale_continuation_using_a_block_eigensolver
309	Tensor-product kernel-based representation encoding joint MRI view similarity	Engineering in Medicine and Biology Society (EMBC), 2014 36th Annual International Conference of the IEEE	A Álvarez-Meza, D Cárdenas-Peña, AE Castro-Ospina, M Álvarez, G Castellanos-Dominguez	To support 3D magnetic resonance image (MRI) analysis, a marginal image similarity (MIS) matrix holding MR inter-slice relationship along every axis view (Axial, Coronal, and Sagittal) can be estimated. However, mutual inference from MIS view information poses a difficult task since relationships between axes are nonlinear. To overcome this issue, we introduce a Tensor-Product Kernel-based Representation (TKR) that allows encoding brain structure patterns due to patient differences, gathering all MIS matrices into a single joint image similarity framework. The TKR training strategy is carried out into a low dimensional projected space to get less influence of voxel-derived noise. Obtained results for classifying the considered patient categories (gender and age) on real MRI database shows that the proposed TKR training approach outperforms the conventional voxel-wise sum of squared differences. The proposed approach may be useful to support MRI clustering and similarity inference tasks, which are required on template-based image segmentation and atlas construction.	2014	10	https://ieeexplore.ieee.org/abstract/document/6944475/
310	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	International Symposium on Neural Networks	Leandro Leonardo Lorente-Leyva, Israel David Herrera-Granda, Paul D Rosero-Montalvo, Karina L Ponce-Guevara, Andrés Eduardo Castro-Ospina, Miguel A Becerra, Diego Hernán Peluffo-Ordóñez, José Luis Rodríguez-Sotelo	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_37
311	Fingertips Segmentation of Thermal Images and Its Potential Use in Hand Thermoregulation Analysis	International Conference on Hybrid Artificial Intelligence Systems	AE Castro-Ospina, AM Correa-Mira, ID Herrera-Granda, DH Peluffo-Ordóñez, HA Fandiño-Toro	Thermoregulation refers to the physiological processes that maintain stable the body temperatures. Infrared thermography is a non-invasive technique useful for visualizing these temperatures. Previous works suggest it is important to analyze thermoregulation in peripheral regions, such as the fingertips, because some disabling pathologies affect particularly the thermoregulation of these regions. This work proposes an algorithm for fingertip segmentation in thermal images of the hand. By using a supervised index, the results are compared against segmentations provided by humans. The results are outstanding even when the analyzed images are highly resized.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_38
312	Multi-label Learning by Hyperparameters Calibration for Treating Class Imbalance	International Conference on Hybrid Artificial Intelligence Systems	Andrés Felipe Giraldo-Forero, Andrés Felipe Cardona-Escobar, Andrés Eduardo Castro-Ospina	Multi-label learning has been becoming an increasingly active area into the machine learning community due to a wide variety of real world problems. However, only over the past few years class balancing for these kind of problems became a topic of interest. In this paper, we present a novel method named hyperparameter calibration to treat class imbalance in a multi-label problem, to this aim we develop an extensive analysis over four real-world databases and two own synthetic databases exhibiting different ratios of imbalance. The empirical analysis shows that the proposed method is able to improve the classification performance when it is combined with three of the most widely used strategies for treating multi-label classification problems.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-92639-1_27
313	Optimization of the University Transportation by Contraction Hierarchies Method and Clustering Algorithms	International Conference on Hybrid Artificial Intelligence Systems	Israel D Herrera-Granda, Leandro L Lorente-Leyva, Diego H Peluffo-Ordóñez, Robert M Valencia-Chapi, Yakcleem Montero-Santos, Jorge L Chicaiza-Vaca, Andrés E Castro-Ospina	This research work focuses on the study of different models of solution reflected in the literature, which treat the optimization of the routing of vehicles by nodes and the optimal route for the university transport service. With the recent expansion of the facilities of a university institution, the allocation of the routes for the transport of its students, became more complex. As a result, geographic information systems (GIS) tools and operations research methodologies are applied, such as graph theory and vehicular routing problems, to facilitate mobilization and improve the students transport service, as well as optimizing the transfer time and utilization of the available transport units. An optimal route management procedure has been implemented to maximize the level of service of student transport using the K-means clustering algorithm and the method of node contraction hierarchies, with low cost due to the use of free software.	2018	10	https://scholar.google.com/citations?user=tiN96JEAAAAJ&hl=en#d=gs_md_cita-d&p=&u=%2Fcitations%3Fview_op%3Dview_citation%26hl%3Den%26user%3DtiN96JEAAAAJ%26citation_for_view%3DtiN96JEAAAAJ%3A7PzlFSSx8tAC%26tzom%3D300
314	Cardiac Pulse Modeling Using a Modified van der Pol Oscillator and Genetic Algorithms	International Conference on Bioinformatics and Biomedical Engineering	Fabián M Lopez-Chamorro, Andrés F Arciniegas-Mejia, David Esteban Imbajoa-Ruiz, Paul D Rosero-Montalvo, Pedro García, Andrés Eduardo Castro-Ospina, Antonio Acosta, Diego Hernán Peluffo-Ordóñez	This paper proposes an approach for modeling cardiac pulses from electrocardiographic signals (ECG). A modified van der Pol oscillator model (mvP) is analyzed, which, under a proper configuration, is capable of describing action potentials, and, therefore, it can be adapted for modeling a normal cardiac pulse. Adequate parameters of the mvP system response are estimated using non-linear dynamics methods, like dynamic time warping (DTW). In order to represent an adaptive response for each individual heartbeat, a parameter tuning optimization method is applied which is based on a genetic algorithm that generates responses that morphologically resemble real ECG. This feature is particularly relevant since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are performed over real ECG from MIT-BIH arrhythmias database. The application of the optimization process shows that the mvP oscillator can be used properly to model the ideal cardiac rate pulse.	2018	10	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_8
319	Metodología basada en el enfoque modular para el diseño y simulación de instalaciones industriales y sistemas de producción en un contexto de" Industry 4.0".	Repositorio Institucional UPV	LUIS OMAR ALPALA	El presente TFM se centra en una de las decisiones que debe tomar el planificador durante el diseño de la distribución de instalaciones en un contexto de la industria 4.0. Si bien, la forma de concebir una instalación industrial como se la conoce hoy en día, ha ido evolucionando hasta el punto de integrar sistemas tecnológicos avanzados de producción, vale la pena resaltar la importancia de la distribución de instalaciones para la generación de diseños exitosos de layout, basados en ingeniería y arquitectura de forma integrada. En este orden de ideas, se propone una metodología para el problema del diseño de distribución en planta con enfoque modular y contexto de industria 4.0 denominada “Metodología SLP-Sim” la cual incorpora en su estructura el denominado diseño integrado de sistemas (IDS) que permite trabajar con varios tipos de software de diseño, simulación y base de datos de forma colaborativa. Para la propuesta de la metodología SLP-Sim ha sido necesario realizar un estado del arte respecto a metodologías y herramientas existentes para abordar el problema de la distribución de instalaciones, de esto se pudo determinar que la metodología SLP (Systematic layout planning) propuesta por (Muther, 1968), ha sido una de las más aceptadas y la más comúnmente utilizada para la resolución de problemas de diseño y distribución de instalaciones a partir de criterios cualitativos, pese a que fue concebida para el diseño de todo tipo de distribuciones de instalaciones independientemente de su naturaleza. De aquí que la metodología propuesta se basa en algunos pasos de la metodología SLP de Muther.	2016	17	https://scholar.google.es/citations?user=PevPY5sAAAAJ&hl=es#d=gs_md_cita-d&p=&u=%2Fcitations%3Fview_op%3Dview_citation%26hl%3Des%26user%3DPevPY5sAAAAJ%26citation_for_view%3DPevPY5sAAAAJ%3A2osOgNQ5qMEC%26tzom%3D300
320	Analysis and diagnosis of the Computer Science program at the Central University of Venezuela: Towards a competency-based curriculum design	Computing Conference (CLEI)	Maria Villapol, Zenaida Castillo, Alecia Eleonora Acosta, Carlos Acosta	The Central University of Venezuela, as part of its efforts for adapting its academic offer to national and international needs, is conducting a project to review, evaluate and modify the Computer Science program, in order to form the professional required by the country. In this paper we present the results of the first stage of the project: an assessment of the Computer Science program based on the use of various data collection instruments used to determine the professor and student perception of the program as well as deficiencies and potential of our graduates, according to the companies and organizations that hire them. The results show that there exist a gap between the perception of our professors about the program and the opinion of the employers. We also present information about student performance during the last decade, which is an input to the next stage of the program redesign.	2014	24	https://www.researchgate.net/publication/261489257_Analysis_and_diagnosis_of_the_Computer_Science_program_at_the_Central_University_of_Venezuela_Towards_a_competency-based_curriculum_design
321	A Detailed Study of the Computer Science Degree at the Central University of Venezuela: Towards a New Curriculum Design	Universidad Central de Venezuela	Maria Villapol, Zenaida Castillo, Alecia E. Acosta, Carlos Acosta, A. Bottini, Rhadamés Carmona, Harun Juhasz,	The Central University of Venezuela, as part of its efforts for adapting its academic offer to national and international needs, is conducting a project to review, evaluate and modify the Computer Science curriculum, in order to form the professional required by the country. In this paper we present the results of the first stage of the project: an assessment of the Computer Science curriculum based on the use of various data collection instruments used to determine the professor, student and graduates perception of the program as well as deficiencies and potential of our graduates, according to the companies and organizations that hire them. The results show that there exist a gap between the perception of our professors about the program and the opinion of the employers. We also present information about student performance during the last decade, which is an input to the next stage of the program redesign.	2014	24	https://www.researchgate.net/publication/277335973_A_Detailed_Study_of_the_Computer_Science_Degree_at_the_Central_University_of_Venezuela_Towards_a_New_Curriculum_Design
322	Un esquema paralelo para el cálculo del pseudoespectro de matrices de gran magnitud	Revista Internacional de Métodos Numéricos para Cálculo y Diseño en Ingeniería	Beatriz Otero, R. Astudillo, Zenaida Castillo	El pseudoespectro es una gran herramienta para el estudio de sistemas dinámicos asociados a matrices no normales. En las últimas décadas su estudio y aplicación se ha intensificado, por lo que realizar su cálculo de forma eficiente resulta de especial interés para la comunidad científica. Para matrices de grandes dimensiones se han empleado diferentes métodos, entre los cuales destacan los métodos de proyección en espacios de Krylov. En este trabajo se utiliza la idea propuesta por Wright y Trefethen para aproximar el pseudoespectro de la matriz usando una proyección Hm de menor tamaño. Adicionalmente, se propone una descomposición del dominio en subregiones asignando a cada procesador una subregión. Cada procesador calcula el menor valor singular de la matriz (zI − Hm) para todos los valores z = x + yi que representan los puntos de la subregión asignada. Se realizaron diferentes experimentos numéricos cuyos resultados fueron contrastados con los obtenidos en la bibliografía. En todos los casos estudiados el método implementado muestra una reducción del tiempo de ejecución respecto a la versión secuencial del programa desde 41x hasta 101x.	2014	24	https://www.researchgate.net/publication/261917489_Un_esquema_paralelo_para_el_calculo_del_pseudoespectro_de_matrices_de_gran_magnitud
323	Approximating the weighted pseudospectra of large matrices	Mathematical and Computer Modelling	R. Astudillo, Zenaida Castillo	In different applications it is necessary to compute the pseudospectra of matrices in an energy or weighted norm. In this work we develop a practical method to convert an Arnoldi factorization based on the Euclidean inner product into another Arnoldi factorization in a weighted inner product. We also propose how to use this approach to find a portion of the weighted pseudospectra of large matrices. Numerical results on different test problems are presented. (c) 2011 Elsevier Ltd. All rights reserved.	2013	24	https://www.researchgate.net/publication/229352391_Approximating_the_weighted_pseudospectra_of_large_matrices
324	Computing pseudospectra using block implicitly restarted Arnoldi iteration	Mathematical and Computer Modelling	R. Astudillo, Zenaida Castillo	The pseudospectra is a useful tool to study the behavior of systems associated with non-normal matrices. In the past decade, different projection Krylov methods have been used to calculate the pseudospectra of large matrices, rather than earlier approaches which require the application of SVD decomposition at each point of a grid. Inverse Lanczos is a better choice, but still requires previous Schur factorization, which is prohibited in the large scale setting. In this work, we investigate the practical applicability and the performance of a block implicitly restarted Arnoldi method to approximate the pseudospectrum of large matrices, as was suggested by Wright and Trefethen in “Pseudospectra of rectangular matrices” (Wright and Trefethen, 2002 [16]). We present a case study of this idea, using a block version of the Implicitly Restarted Arnoldi Method (IRAM) (Sorensen, 1992 [5]). Numerical results, on several test matrices from the literature, are encouraging and show a reduction in time of this block method compared with its counterpart single version IRAM.	2013	24	https://www.researchgate.net/publication/251601712_Computing_pseudospectra_using_block_implicitly_restarted_Arnoldi_iteration
325	A New Algorithm for Continuation and Bifurcation Analysis of Large Scale Free Surface Flows	RESEARCHGATE	Zenaida Castillo, Danny Sorensen	This thesis presents a new algorithm to find and follow particular solutions of parameterized nonlinear systems. Important applications often arise after spatial discretization of time dependent PDEs. We embed a block eigenvalue solver in a continuation framework for the computation of some specific eigenvalues of large Jacobian matrices that depend on one or more parameters. The new approach is then employed to study the behavior of an industrial process referred to as coating. Stability analysis of the discretized system that models this process is important because it provides alternatives for changing parameters in order to improve the quality of the final product or to increase productivity. Experiments on several problems show the reliability of the new approach in the accurate detection of critical points. Further analysis of two-dimensional coating flow problems reveals that computational results are competitive with those of previous continuation approaches. As a byproduct, one obtains information about the stability of the process with no additional cost. Due to the size and structure of the matrices generated in three-dimensional free surface flow applications, it is necessary to use a general iterative linear solver, such as GMRES. However, GMRES displays a very slow rate of convergence as a consequence of the poor conditioning in the coefficient matrices. To speed up GMRES convergence, we developed and implemented a scalable approximate sparse inverse preconditioner. Numerical experiments demonstrate that this preconditioner greatly improves the convergence of the method. Results illustrate the effectiveness of the preconditioner on very large free surface flow problems with more than million unknowns.	2013	24	https://www.researchgate.net/publication/234815075_A_New_Algorithm_for_Continuation_and_Bifurcation_Analysis_of_Large_Scale_Free_Surface_Flows
326	Evaluación de precondicionadores en bloque en la solución de sistemas de punto de ensilladura	Revista de la Facultad de Ingenieria	Zenaida Castillo, Jean Piero Suárez	This paper presents a new approach to precondition linear systems of the saddle point kind. Specifically we consider block diagonal, block triangular and block indefinite preconditioning techniques on nonsymmetric systems. These preconditioners require the computation of some inverses and we propose to use sparse approximate inverses (SPAI) to construct these approximations. The computation of these inverses involves solving a set of uncoupled least squares problems, which can be easily parallelized on a memory distributed machine. Comparison with other techniques suggests that block diagonal and block triangular preconditioning can be more effective if they are combined with SPAI techniques in the computation of approximate inverses. Results are promising and show the effectiveness of these preconditioners when improving the convergence of Krylov methods such as GMRES, which suggests the application of this approach in the large-scale setting.	2010	24	https://www.researchgate.net/publication/262514264_Evaluacion_de_precondicionadores_en_bloque_en_la_solucion_de_sistemas_de_punto_de_ensilladura
327	Evaluating block preconditioners in the solution of saddle point systems	Revista de la Facultad de Ingenieria	Zenaida Castillo, J.P. Suárez	This paper presents a new approach to precondition linear systems of the saddle point kind. Specifically we consider block diagonal, block triangular and block indefinite preconditioning techniques on nonsymmetric systems. These preconditioners require the computation of some inverses and we propose to use sparse approximate inverses (SPAI) to construct these approximations. The computation of these inverses involves solving a set of uncoupled least squares problems, which can be easily parallelized on a memory distributed machine. Comparison with other techniques suggests that block diagonal and block triangular preconditioning can be more effective if they are combined with SPAI techniques in the computation of approximate inverses. Results are promising and show the effectiveness of these preconditioners when improving the convergence of Krylov methods such as GMRES, which suggests the application of this approach in the large-scale setting.	2010	24	https://www.researchgate.net/publication/288134444_Evaluating_block_preconditioners_in_the_solution_of_saddle_point_systems
328	Parallel solution of large-scale free surface viscoelastic flows via sparse approximate inverse preconditioning	Journal of Non-Newtonian Fluid Mechanics	Xueying Xie, Zenaida Castillo, Matteo Pasquali, Mark Embree	Though computational techniques for two-dimensional viscoelastic free surface flows are well developed, three-dimensional flows continue to present significant computational challenges. Fully coupled free surface flow models lead to nonlinear systems whose steady states can be found via Newton’s method. Each Newton iteration requires the solution of a large, sparse linear system, for which memory and computational demands suggest the application of an iterative method, rather than the sparse direct methods widely used for two dimensional simulations. The Jacobian matrix of this system is often ill-conditioned, resulting in unacceptably slow convergence of the linear solver; hence preconditioning is essential. We propose a variant sparse approximate inverse preconditioner for the Jacobian matrix that allows for the solution of problems involving more than a million degrees of freedom in challenging parameter regimes. Construction of this preconditioner requires the solution of small least squares problems that can be simply parallelized on a distributed memory machine. The performance and scalability of this preconditioner with the GMRES solver are investigated for two- and three-dimensional free surface flows on both structured and unstructured meshes in the presence and absence of viscoelasticity. The results suggest that this preconditioner is an extremely promising candidate for solving large-scale steady viscoelastic flows with free surfaces.	2009	24	https://www.researchgate.net/publication/247108326_Parallel_solution_of_large-scale_free_surface_viscoelastic_flows_via_sparse_approximate_inverse_preconditioning
329	COMPUTATIONAL TECHNIQUES FOR SADDLE POINT PROBLEMS	Revista Internacional de Métodos Numéricos para Cálculo y Diseño en Ingeniería	Zenaida Castillo, Jean Suarez	In this paper we present a numerical evaluation of block preconditioners for linear systems of the saddle point kind. We consider specifically block diagonal, block triangular and block indefinite preconditioners on nonsymmetric matrices. These preconditioners require the computation of the inverse of some matrices involved and we propose to use sparse inverse approximations (SPAI). Results are promising and show the effectivity of block diagonal and block triangular preconditioners improving the convergence of Krylov methods as GMRES, suggesting the application of this approach in the large scale setting.	2008	24	https://www.researchgate.net/publication/298857321_COMPUTATIONAL_TECHNIQUES_FOR_SADDLE_POINT_PROBLEMS
330	Linear least squares with quadratic constraints	Divulgaciones Matematicas	Zenaida Castillo	This work proposes a method to minimize the function ||Ax - b|| 2, subject to ||Cx - d||2 ≤ Δ, with A ∈ ℝm×n, C ∈ ℝp×n, b ∈ ℝm, and d ∈ ℝp. We use a regularization technique to reformulate the problem, in order to solve a non-linear equation. Preliminary results are encouraging. We present a comparison with traditional approaches.	2007	24	https://www.researchgate.net/publication/264997820_Linear_least_squares_with_quadratic_constraints
332	Mínimos Cuadrados Lineales con Restriccion Cuadratica	Divulgaciones Matemáticas	Zenaida Castillo	This work proposes a method to minimize the function kAx ¡ bk2, subject to kCx ¡ dk2 • ¢, with A 2 R m£n , C 2 R p£n , b 2 R m , and d 2R p . We use a regularization technique to reformulate the problem, in order to solve a non-linear equation. Preliminary results are encour- aging. We present a comparison with traditional approaches.	2007	24	https://www.emis.de/journals/DM/v15-2/art7.pdf
333	Técnicas de precondicionamiento para problemas de punto de silla	Revista Internacional de M ́etodos Num ́ericos para C ́alculo y Disen ̃o en Ingenier ́ıa	Zenaida Castillo, Jean Suárez	En este artículo se presenta una evaluación numérica de precondicionadores por bloques para sistemas lineales de punto de silla, en los cuales la matriz A ∈ R n×n del bloque (1, 1) es no simétrica y la matriz B ∈ R m×n del bloque (2, 1) es de rango completo. Se consideran específicamente precondicionadores diagonales por bloques, triangulares por bloques y de tipo indefinido. Estos precondicionadores requieren para su construcción el cálculo de inversas de algunas matrices, para lo cual se propone utilizar aproximaciones de tipo SPAI. Los resultados ilustran la efectividad de los precondicionadores diagonales y triangulares en la aceleración de la convergencia del método GMRES. Palabras clave: sistemas de punto de silla, precondicionadores por bloques, aproximación dispersa de la inversa de una matriz. Summary In this paper we present a numerical evaluation of block preconditioners for linear systems of the saddle point kind. We consider specifically block diagonal, block triangular and block indefinite preconditioners on nonsymmetric matrices. These preconditioners require the computation of the inverse of some matrices involved and we propose to use sparse inverse approximations (SPAI). Results are promising and show the effectivity of block diagonal and block triangular preconditioners improving the convergence of Krylov methods as GMRES, suggesting the application of this approach in the large scale setting.	2008	24	https://upcommons.upc.edu/bitstream/handle/2099/10444/II%20-%20V24N3.pdf
334	Second and fourth order mimetic finite differences on non-uniform grids	RESEARCHGATE	J Blanco, O Rojas, Zenaida Castillo	Mimetic finite differences (MFD) keep the simple use and computational efficiency of traditional FD but satisfy discrete analog of the divergence theorem and various identities of vector and tensor calculus. In this paper, we apply second-and fourth-order MDF to solve diffusion problems with extreme boundary layers on 1D non-uniform meshes and show numerical convergence in terms of error norms that naturally arise in the discretization process. Experimental convergence of computed solutions agrees with the nominal discretization order and show precise resolution of steep gradients.	2008	24	https://www.researchgate.net/publication/267846710_Second_and_fourth_order_mimetic_finite_differences_on_non-uniform_grids
335	Autonomous Robots and Behavior Initiators	IntechOpen	Oscar Chang	We use an autonomous neural controller (ANC) that handles the mechanical behavior of virtual, multi-joint robots, with many moving parts and sensors distributed through the robot’s body, satisfying basic Newtonian laws. As in living creatures, activities inside the robot include behavior initiators: self-activating networks that burn energy and func- tion without external stimulus. Autonomy is achieved by mimicking the dynamics of biological brains, in resting situations, a default state network (DSN), specialized set of energy burning neurons, assumes control and keeps the robot in a safe condition, where other behaviors can be brought to use. Our ANC contains several kinds of neural nets trained with gradient descent to perform specialized jobs. The  rst group generates mov- ing wave activities in the robot muscles, the second yields basic position/presence predic- tion information about sensors, the third acts as timing masters, empowering sequential tasks. We add a fourth category of self-activating networks that push behavior from the inside. Through evolutive methods, the composed network share clue information along a few connecting weights, producing self-motivated robots, capable of achieving notice- able self-level of competence. We show that this spirited robot interacts with humans and, through appropriate interfaces, learn complex behaviors that satisfy unknown, sub- jacent human expectative.	2018	25	https://www.researchgate.net/publication/326215617_Autonomous_Robots_and_Behavior_Initiators
336	A Deep Learning Algorithm to Forecast Sales of Pharmaceutical Products	DRAFT PAPER	Oscar. Chang, Ivan Naranjo, Christian Guerron	This work proposes a deep neural network (DNN) algorithm that accomplishes consistent sales forecasting for weekly data of pharmaceutical products. The resultant time series is used to train with backpropagation, step by step, a DNN, where shallow nets face selected scenarios, with different space-time data considerations. In each step, by using a sum of square differences and a peak search procedure, a reasonable quality in the obtained abstract representations is pursued. First an autoencoder is trained as to develop in its hidden layer neural data abstractions about a random moving window. Thereafter the autoencoder abstractions are used to train a second shallow net which operates in a restricted area and specializes in one week ahead predictions. Lastly by using the abstraction of this second net plus recently captured information, a third shallow net is trained to produce its own one week ahead estimates, using new timing and data procedures. After training, the whole stacked system can produce stable weekly forecasting with up to 91%_ 55 % hit rate, for assorted products and periods. The system has been tested in real time with real data.	2017	25	https://www.researchgate.net/publication/319041996_A_Deep_Learning_Algorithm_to_Forecast_Sales_of_Pharmaceutical_Products
337	A Deep Learning Algorithm to Forecast Sales of Pharmaceutical Products	RESEARCHGATE	No Name	This work proposes a deep neural network (DNN) algorithm that accomplishes consistent sales forecasting for weekly data of pharmaceutical products. The resultant time series is used to train with backpropagation, step by step, a DNN, where shallow nets face selected scenarios, with different space-time data considerations. In each step, by using a sum of square differences and a peak search procedure, a reasonable quality in the obtained abstract representations is pursued. First an autoencoder is trained as to develop in its hidden layer neural data abstractions about a random moving window. Thereafter the autoencoder abstractions are used to train a second shallow net which operates in a restricted area and specializes in one week ahead predictions. Lastly by using the abstraction of this second net plus recently captured information, a third shallow net is trained to produce its own one week ahead estimates, using new timing and data procedures. After training, the whole stacked system can produce stable weekly forecasting with up to 91%_ 55 % hit rate, for assorted products and periods. The system has been tested in real time with real data.	2017	25	https://www.researchgate.net/publication/319311063_A_Deep_Learning_Algorithm_to_Forecast_Sales_of_Pharmaceutical_Products
338	Neural networks for optic nerve detection in digital optic fundus images	IEEE International Conference on Automatica (ICA-ACCA)	Patricia Nataly Constante, Andres Gordon, Oscar. Chang, Ivón Escobar	This paper presents a method used for detection of optic nerve in fundus digital images; for this purpose, initially there is a preprocessing and segmentation of digital images of fundus taken from databases Messidor and Stare in order to stand out the veins and blood vessels of ocular region. The processed image is used in an artificial neural network which has three layers; an input layer with 10000 neurons that belong to the vectorized and processed image, a hidden layer with 100 neurons and an output layer with 42 neurons, which define the pixel deviation between the center of the ROI and the original image. For the training of the Artificial Neural Network, is used an arrangement of fifteen selected images from databases and scaled to a suitable size, so it can fit inside the ROI; this training was performed using backpropagation. At the end of the training, there were two types of experiments for result's validation; the first one was the detection of optic discs in known databases with an error of 0%, the second one was the detection of optic discs in unknown databases, with an error of 5% during the tracking of optic nerve, thus it concludes that the presented method is efficient for the detection of optic disc in fundus digital images.	2016	25	https://www.researchgate.net/publication/311610304_Neural_networks_for_optic_nerve_detection_in_digital_optic_fundus_images
339	Implementation of a WirelessHART Training System for Upgrading Industrial	IEEE Latin America Transactions	Ivón Escobar, Edwin Pruna, Oscar. Chang, Galo Avila	The rapid advance of technology has caused for engineers who graduate a few years ago to have a definite shortcomings in the use, design and maintenance of modern industrial control systems. Such is the case of the wireless technology WirelessHART, which by their high performance and flexibility of use, is increasingly common in todays industry. To correct this growing situation this work has developed a WirelessHART, wireless educative module which is being used in the Continuing Education Unit of the University of the Armed Forces ESPE. The final objective is to develop open and institutional courses where characteristics identical to a real WirelessHART industrial application can be handled. The system includes a LabVIEW designed HMI which makes possible to remotely monitor interest variables.	2016	25	https://www.researchgate.net/publication/307440877_Implementation_of_a_WirelessHART_Training_System_for_Upgrading_Industrial
340	Artificial Vision Techniques to Optimize Strawberry's Industrial Classification	IEEE Latin America Transactions	Patricia Nataly Constante, Andres Gordon, Oscar. Chang, Ivón Escobar	This research presents novel artificial vision techniques applied to the detection of features for strawberries used in the food industry. For this purpose, a computer vision system based in arti#64257;cial neural networks is used, organized as a deep architecture and trained with noise compensated learning. This combination originates a strong network-object relations which makes possible the recognition of complex strawberry features under changing conditions of lightning, size and orientation. The programming uses OpenCV libraries and fruits databases captured with a webcam. The images used to train the Articial Neural Network are dened with canny edge detection and a moving region of interest (ROI). After training, the network recognizes important features such as shape, color and anomalies. The system has been tested in real time with real images.	2016	25	https://www.researchgate.net/publication/307442845_Artificial_Vision_Techniques_to_Optimize_Strawberry%27s_Industrial_Classification
341	Implementación de una herramienta didáctica para el diagnóstico de válvulas de control	IEEE Biennial Congress of Argentina (ARGENCON)	Edwin Pruna, Jenny Calvopina, Estefania Serna, Oscar. Chang	This paper presents the implementation of a tool of low cost for the diagnosis of control valves, aimed at the identification and analysis of the performance of such elements and used them for the education in Engineering. It was implanted a HART network that allows the communication with the positioner of the valve, and it was also built a display interface made in Labview in order to obtain information key data of the control valves, including diagnosis in line and off line.	2016	25	https://www.researchgate.net/publication/309338662_Implementacion_de_una_herramienta_didactica_para_el_diagnostico_de_valvulas_de_control
342	A Novel Deep Neural Network that Uses Space-Time Features for Tracking and Recognizing a Moving Object	Journal of Artificial Intelligence and Soft Computing Research	Oscar. Chang, Patricia Nataly Constante, Andres Gordon, Marco Singaña	This work proposes a deep neural network (DNN) that accomplishes the reliable visual recognition of a chosen object captured with a webcam and moving in a 3D space. Auto encoding and substitutional reality are used to train a shallow net until it achieves zero tracking error in a discrete ambient. This trained individual is set to work in a real world closed loop system where images coming from a webcam produce displacement information for a moving region of interest (ROI) inside the own image. This loop gives rise to an emergent tracking behavior which creates a self-maintain flow of compressed space-time data. Next, short term memory elements are set to play a key role by creating new representations in terms of a space-time matrix. The obtained representations are delivery as input to a second shallow network which acts as “recognizer”. A noise balanced learning method is used to fast train the recognizer with real-world images, giving rise to a simple and yet powerful robotic eye, with a slender neural processor that vigorously tracks and recognizes the chosen object. The system has been tested with real images in real time.	2016	25	https://www.researchgate.net/publication/303498175_A_Novel_Deep_Neural_Network_that_Uses_Space-Time_Features_for_Tracking_and_Recognizing_a_Moving_Object
343	Building a training module for modern control	CHILEAN Conference on Electrical, Electronics Engineering, Information and Communication Technologies (CHILECON)	Andres Gordon, Oscar. Chang, Patricia Nataly Constante, Edwin Pruna, Ivón Escobar, Diego Jimenez, Pérez A., Ávila Galo	Engineering students majoring in instrumentation and control require training modules to realize practices in industrial processes and automatic control. Usually these modules are expensive and most are designed to control a single variable. In the present work we design and built a low-cost training module, which makes possible to realize labs practices in the industrial process control area, with up to two independent simultaneous variables, and by using modern elements. The system is easy to use, robust and has proved to be a useful tool for evaluating the different control modes required in the existent industrial world.	2015	25	https://www.researchgate.net/publication/295256866_Building_a_training_module_for_modern_control
344	A Deep Architecture for Visually Analyze Pap Cells	IEEE CCAC 2015	Oscar. Chang, Patricia Nataly Constante, Fausto Acuna, Andres Gordon	This work proposes a deep ANN architecture which accomplishes the reliable visual classification of abnormal Pap smear cell. The system is driven by independent agents where the first agent consists of a three layer ANN pretrained to closely track a reticle pattern. This net participates in a local close loop that oscillates and produces unique time-space versions of the visual data. This information is stabilized and sparsed in order to obtain compact data representations, with implicit space time content. The obtained representations are delivered to second level agents, formed by independent three layers ANNs dedicated to learning and recognition activities. To train the system a noise-balanced algorithm is employed, where the training set is composed by pap cells and white noise. This combination operating on finite databases and in a self controlled learning loop, auto develops enough cell recognition knowledge as to classify whole classes of Pap smear cells. The system has been tested in real time utilizing documented data bases.	2015	25	https://www.researchgate.net/publication/283264419_A_Deep_Architecture_for_Visually_Analyze_Pap_Cells
345	Calibration of residential water meters by using computer vision	CHILEAN Conference on Electrical, Electronics Engineering, Information and Communication Technologies (CHILECON)	Oscar. Chang, Edwin Pruna, Marco Pilatasig, L. Mena	We present an artificial vision based system that quickly and semi-automatically calibrates water meters. The system operates with an artificial neural net architecture which is able to visually read analog needles and dynamically track the float position of a lab rotameter. By using a closed water flow circuit powered by a low power centrifugal pump, the computer reads through a web camera the water meter needles position, measuring the time required for a full turn and calculating the associated water flow. Simultaneously a second camera tracks the float of a rotameter connected to the water circuit and digitalizes the indicated flow. The two amounts are compared by using column indicators, telling the operator to correct the water meter by excess or defect if necessary. The system has been tested in real time and with real instruments.	2015	25	https://www.researchgate.net/publication/304408631_Calibration_of_residential_water_meters_by_using_computer_vision
346	Visión Artificial para Reconocer Fielmente Células Biológicas	JIFI 2014, Universidad Central de Venezuela, At Caracas	Oscar. Chang	Presentamos un sistema de visión artificial el cual utiliza principios operativos detectados en el cerebro de los insectos; particularmente la comunicación con código depurado entre el Lóbulo Antenal (AL) y el Cuerpo de Mushroom (MB). El sistema mira al mundo a través de imágenes tomadas de cámaras web o de bases de datos. Rutinas OpenCV canny (detección de bordes) transforman este flujo masivo de información y lo entregan a agentes neurales auto-regulados, que simulan el comportamiento del AL y producen código depurado para el MB simulado. En el MB una población de agentes neurales realiza actividades cognitivas y se entrena aisladamente mediante recompensas selectivas, lo cual potencia el reconocimiento visual de objetos. Los agentes son agrupados en cadenas cognitivas que memorizan imágenes complejas, distribuyendo automáticamente los recursos de aprendizaje disponibles. Estas cadenas llegan memorizar y reconocer acuciosamente diferentes tipos de células, pudiéndolas distinguir individualmente entre ellas y entre otros innumerables elementos. El acucioso reconocimiento celular obtenido tendría aplicaciones en la detección de enfermedades. El sistema ha sido probado en tiempo real con imágenes del mundo real. Palabras clave— Visión Artificial, Diagnostico por computadora, Reconocimiento de células vivas.	2014	25	https://www.researchgate.net/publication/269166194_Vision_Artificial_para_Reconocer_Fielmente_Celulas_Biologicas
347	Robot Bio-inspirado con percepción visual de oportunidades de uso (Affordances)	Second Workshop on Affordances. ECCV 2014).	Oscar. Chang	Presentamos un robot visual cuyo controlador neural asociado desarrolla una percepción realista de “Affordances” u “Oportunidades de uso”. El controlador aplica principios detectados en el cerebro de los insectos; particularmente la comunicación usando código estabilizado-esparcido entre el Lóbulo Antenal (AL) y el Cuerpo de Mushroom (MB). El robot percibe el mundo a través de una cámara web y rutinas de detección de bordes (canny) de OpenCV. Agentes neurales auto-controlados procesan este flujo masivo de datos y producen una versión estabilizada en el tiempo y esparcida, donde se codifica en forma implícita relaciones espacio-tiempo. Esta información pre-procesada es transmitida a una población de agentes neurales establecidos en nuestro modelo de MB, especializados en actividades cognitivas y entrenados bajo condiciones autocriticas aisladas. El aislamiento induce un comportamiento emergente que facilita el reconocimiento visual e invariante de objetos. Esta última capacidad se ensambla dentro de cadenas cognitivas que incorporan la activación prolongada y automática de los recursos de aprendizaje. Las cadenas cognitivas usadas durante un periodo de aprendizaje extendido permiten finalmente al robot desarrollar percepción de oportunidades de uso para elementos específicos. El sistema ha sido probado en tiempo real con elementos del mundo real. Index Terms— Percepcion de “Affordance”, Vision Robotica, Agentes Neurales Cooperativos	2014	25	https://www.researchgate.net/publication/269166414_Robot_Bio-inspirado_con_percepcion_visual_de_oportunidades_de_uso_Affordances
348	A Bio-Inspired Robot with Visual Perception of Affordances	European Conference on Computer Vision	Oscar. Chang	We present a visual robot whose associated neural controller develops a realistic perception of affordances. The controller uses known insect brain principles; particularly the time stabilized sparse code communication between the Antennal Lobe and the Mushroom Body. The robot perceives the world through a webcam and canny border openCV routines. Self-controlled neural agents process this massive raw data and produce a time stabilized sparse version, where implicit time-space information is encoded. Preprocessed information is relayed to a population of neural agents specialized in cognitive activities and trained under self-critical isolated conditions. Isolation induces an emergent behavior which makes possible the invariant visual recognition of objects. This later capacity is assembled into cognitive strings which incorporate time-elapse learning resources activation. By using this assembled capacity during an extended learning period the robot finally achieves perception of affordances. The system has been tested in real time with real world elements.	2014	25	https://www.researchgate.net/publication/301982818_A_Bio-Inspired_Robot_with_Visual_Perception_of_Affordances
349	Reliable Object Recognition by Using Cooperative Neural Agents	WCCI 2014, At Beijing, China	Oscar. Chang	An artificial vision system based upon known insect brain structures is presented. It reliably recognizes real world objects visualized through a web cam or read from databases, and utilizes neural agents that communicate through time stabilized sparse code. A three layer ANN is trained to track one reticle pattern. Once trained the net becomes a proactive agent by participating in a local, close loop control system which oscillates, shows a sturdy emergent tracking behavior and produces a continuous flow of space-time related unstable code. This flow is time stabilized, converted to sparse form and relayed to a population of other isolated neural agents, whose response can be tuned to complex visual stimulus. Finally a novel noise-balanced training method is used to tune agents' response in and secluded environment, where only the images of a chosen object and noise exist. Isolation creates a strong agent-object association that boosts object recognition. The found solutions sustain sparse code, visual invariance and concentrate their decision into a single neuron. These might represents good start up conditions for modeling concept cells. The system has been tested using real time real world images and data bases.	2014	25	https://www.researchgate.net/publication/264310917_Reliable_Object_Recognition_by_Using_Cooperative_Neural_Agents
350	Evolving cooperative neural agents for controlling vision guided mobile robots	Cybernetic Intelligent Systems (CIS), 2010 IEEE 9th International Conference	Oscar. Chang	We have studied and developed the behavior of two specific neural processes, used for vehicle driving and path planning, in order to control mobile robots. Each processor is an independent agent defined by a neural network trained for a defined task. Through simulated evolution fully trained agents are encouraged to socialize by opening low bandwidth, asynchronous channels between them. Under evolutive pressure agents spontaneously develop communication skills (protolan-guage) that take advantages of interchanged information, even under noisy conditions. The emerged cooperative behavior raises the level of competence of vision guided mobile robots and allows a convenient autonomous exploration of the environment. The system has been tested in a simulated location and shows a robust performance.	2010	25	https://www.researchgate.net/publication/224242620_Evolving_cooperative_neural_agents_for_controlling_vision_guided_mobile_robots
351	A robotic eye controller based on cooperative neural agents	Neural Networks (IJCNN), The 2010 International Joint Conference	Oscar. Chang, Pascual Campoy, Carol Viviana Martínez, Miguel Angel Olivares-Mendez	A neural behavior initiating agent (BIA) is proposed to integrate relevant compressed image information coming from others cooperating and specialized neural agents. Using this arrangement the problem of tracking and recognizing a moving icon has been solved by partitioning it into three simpler and separated tasks. Neural modules associated to those tasks proved to be easier to train and show a good general performance. The obtained neural controller can handle spurious images and solve an acute image related task in a dynamical environment. Under prolonged dead-lock conditions the controller shows traces of genuine spontaneity. The overall performance has been tested using a pan and tilt camera platform and real images taken from several objects, showing the good tracking results discussed in the paper.	2010	25	https://www.researchgate.net/publication/224181484_A_robotic_eye_controller_based_on_cooperative_neural_agents
352	Propuesta de implementación y simulación de modelos basados en sinapsis dinámica	Universidad, Ciencia y Tecnología	Alvaro Olmedo, Oscar. Chang	Some problems in the field of non-stationary and highly non-lineal sign processing, such as voice recognition, have not been solved by traditional neural network. This proposal for implementation and simulation of a dynamic sinapse is offered to have a background for the biological neuron, specifically depression and facilitation phenomena ocurred in the sinaptic knot as a product of pulse neuronal feedback giving these cells the capacity of self modulating, that is, changing the pulse sequence that excite this biological structure and also giving man the ability to recognize things. To test the model, some timedepending sequences like Spanish spoken words were experimented. They were processed through a Double Delta modulation to emulate the impulses that excite human cells. This study shows the model efficiency to answer with a different pulse sequence to each input sequence. It was verified that the answers are similar for equal sequences (words) no matter who pronunces them. This is the most important fact and there is no doubt it will contribuye to develop classification and recognition systems in future studies.	2016	25	https://www.researchgate.net/publication/262656213_Propuesta_de_implementacion_y_simulacion_de_modelos_basados_en_sinapsis_dinamica
353	Synthesis of linear array using Schelkunoff's method and genetic algorithms	Conference: Antennas and Propagation Society International Symposium	Diogenes Marcano, M. Jiminez, Oscar. Chang	The synthesis of radiation patterns of linear arrays using the Schelkunoff method and genetic algorithms (GAs) is presented. GAs permit the location of the roots on the complex w plane until the desired pattern is obtained. This technique is a powerful tool in the synthesis of complex radiation patterns.	1996	25	https://www.researchgate.net/publication/3645299_Synthesis_of_linear_array_using_Schelkunoff%27s_method_and_genetic_algorithms
354	Synthesis of antenna arrays using genetic algorithms	Conference: Devices, Circuits and Systems, 1995. Proceedings of the 1995 First IEEE International Caracas Conference on	Diogenes Marcano, M. Jimenez, Filinto Duran, Oscar. Chang	The synthesis of the radiation pattern of linear antenna arrays is an interesting problem in radiating systems. When the synthesis of antennas is subject to many restrictions the problem is very complex and becomes difficult to solve by classical optimization techniques because they are vulnerable to local minima problems. One relatively novel technique which could be used for the antenna synthesis is the use of Genetic Algorithms (GAs). In this article two methods for the synthesis of the radiation pattern of a linear array antenna based on GAs are presented. With these techniques it is possible to synthesize a radiation pattern specified by shaped beams and nulls in given directions. Results for different cases are presented.	1996	25	https://www.researchgate.net/publication/3629919_Synthesis_of_antenna_arrays_using_genetic_algorithms
355	Synthesis of multiple beam linear antenna arrays using genetic algorithms	Antennas and Propagation Society International Symposium, 1995. AP-S. Digest, Volume: 2	Diogenes Marcano, Filinto Duran, Oscar. Chang	Genetic algorithms are used to synthesize the radiation pattern of a linear array subject to many restrictions. In particular, a dual beam radiation pattern with low sidelobes is presented. The results show that genetic algorithms are robust and can solve complex antenna problems.	1995	25	https://www.researchgate.net/publication/3653060_Synthesis_of_multiple_beam_linear_antenna_arrays_using_genetic_algorithms
356	Applying vowel sounds to command support systems for motor-impaired people	Medical & Biological Engineering & Computing	N Mendez, Fernando Mora, scar. Chang, Gianfranco Passariello	A novel approach to low-cost microprocessor-based speech analysis and processing has been developed. Real-time Spanish vowel recognition accuracy of 98-76 per cent with an average time response of 200 ms in a noisy room is possible with very simple hardware and software. The voice-recognition method can be implemented in any commercially available 8-bit microprocessors. Also, the adjustment of the system to match other users vocal characteristics is easily performed. The voicerecognition system has been applied to the design of assistive devices for high-level quadriplegics, to provide a more natural method of man-machine communication. Voice is used to command a low-cost personal computer that serves as a support system for a motor-impaired person. By choosing proper sequences of vowel sounds, the patient can control his environment, dial a telephone, handle a telephone directory, play games etc. The extent of possible tasks is limited by the software available.	1987	25	https://www.researchgate.net/publication/20190041_Applying_vowel_sounds_to_command_support_systems_for_motor-impaired_people
357	Design of a Dynamically Programmable Logic Gate	IEEE Transactions on Computers	Ricardo E. Suarez, Oscar. Chang, Vladimir Adam	An eight-transistor static logic gate has been designed, which generates the functions OR, NOR, and, nand, xor, and XNOR of two logic variables, under the dynamic control of two programming variables. In addition to its versatility as a building block, the dynamic programmability of the gate makes it a powerful tool for the efficient design of complex digital networks.	1981	25	https://www.researchgate.net/publication/220331296_Design_of_a_Dynamically_Programmable_Logic_Gate
358	Comments on “revision of the buffer length derivation for a modified Ek/D/1 system by Maritsas and Hartley”	IEEE Transactions on Computers	R.E. Suarez, Oscar. Chang, V. Adam	An eight-transistor static logic gate has been designed, which generates the functions OR, NOR, AND, NAND, XOR, and XNOR of two logic variables, under the dynamic control of two programming variables. In addition to its versatility as a building block, the dynamic programmability of the gate makes it a powerful tool for the efficient design of complex digital networks.	1981	25	https://www.researchgate.net/publication/260585592_Comments_on_revision_of_the_buffer_length_derivation_for_a_modified_EkD1_system_by_Maritsas_and_Hartley
359	Interactive interface for efficient data visualization via a geometric approach	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium	JA Salazar-Castro, YC Rosas-Narváez, AD Pantoja, Juan C Alvarado-Pérez, Diego H Peluffo-Ordóñez	Dimensionality reduction (DR) methods represent a suitable alternative to visualizing data. Nonetheless, most of them still lack the properties of interactivity and controllability. In this work, we propose a data visualization interface that allows for user interaction within an interactive framework. Specifically, our interface is based on a mathematic geometric model, which combines DR methods through a weighted sum. Interactivity is provided in the sense that weighting factors are given by the user via the selection of points inside a geometric surface. Then,(even non-expert) users can intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results are obtained using artificial and real datasets, demonstrating the usability and applicability of our interface in DR-based data visualization.	2015	6	https://ieeexplore.ieee.org/abstract/document/7330397/
360	Interactive data visualization using dimensionality reduction and similarity-based representations	IberoAmerican Congress on Pattern Recognition	P Rosero-Montalvo, P Diaz, Jose Alejandro Salazar-Castro, DF Pena-Unigarro, AJ Anaya-Isaza, Juan C Alvarado-Pérez, Roberto Therón, Diego Hernán Peluffo-Ordóñez	This work presents a new interactive data visualization approach based on mixture of the outcomes of dimensionality reduction (DR) methods. Such a mixture is a weighted sum, whose weighting factors are defined by the user through a visual and intuitive interface. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to be drawn on the scatter plot. Our visualization approach enables the user to interactively combine DR methods while provided information about the structure of original data, making then the selection of a DR scheme more intuitive.	2016	6	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_41
361	Interactive visualization methodology of high-dimensional data with a color-based model for dimensionality reduction	Signal Processing, Images and Artificial Vision (STSIVA), 2016 XXI Symposium	Diego F Peña-ünigarro, Jose A Salazar-Castro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, Omar R Oña-Rocha, Andres A Isaza, Juan C Alvarado-Perez, Roberto Theron	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	6	https://ieeexplore.ieee.org/abstract/document/7743318/
362	Dimensionality reduction for interactive data visualization via a Geo-Desic approach	Computational Intelligence (LA-CCI), 2016 IEEE Latin American Conference	Jose A Salazar-Castro, Diego Peña-Unigarro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, H Mauricio Domínguez-Limaico, Juan C Alvarado-Pérez, Roberto Therón	This work presents a dimensionality reduction (DR) framework that enables users to perform either the selection or mixture of DR methods by means of an interactive model, here named Geo-Desic approach. Such a model consists of linear combination of kernel-based representations of DR methods, wherein the corresponding coefficients are related to coordinated latitude and longitude inside of the world map. By incorporating the Geo-Desic approach within an interface, the combination may be made easily and intuitively by users-even non-expert ones-fulfilling their criteria and needs, by just picking up points from the map. Experimental results demonstrates the usability and ability of DR methods representation of proposed approach.	2016	6	https://ieeexplore.ieee.org/abstract/document/7885740/
363	A Novel Color-Based Data Visualization Approach Using a Circular Interaction Model and Dimensionality Reduction	International Symposium on Neural Networks	Jose Alejandro Salazar-Castro, Paul D Rosero-Montalvo, Diego Fernando Peña-Unigarro, Ana Cristina Umaquinga-Criollo, Zenaida Castillo-Marrero, Edgardo Javier Revelo-Fuelagán, Diego Hernán Peluffo-Ordóñez, César Germán Castellanos-Domínguez	Dimensionality reduction (DR) methods are able to produce low-dimensional representations of an input data sets which may become intelligible for human perception. Nonetheless, most existing DR approaches lack the ability to naturally provide the users with the faculty of controlability and interactivity. In this connection, data visualization (DataVis) results in an ideal complement. This work presents an integration of DR and DataVis through a new approach for data visualization based on a mixture of DR resultant representations while using visualization principle. Particularly, the mixture is done through a weighted sum, whose weighting factors are defined by the user through a novel interface. The interface’s concept relies on the combination of the color-based and geometrical perception in a circular framework so that the users may have a at hand several indicators (shape, color, surface size) to make a decision on a specific data representation. Besides, pairwise similarities are plotted as a non-weighted graph to include a graphic notion of the structure of input data. Therefore, the proposed visualization approach enables the user to interactively combine DR methods, while providing information about the structure of original data, making then the selection of a DR scheme more intuitive.	2018	6	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_64
364	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering	Jose Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A Becerra-Botero, Diego Hernán Peluffo-Ordóñez, Cesar Germán Castellanos-Domínguez	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	6	https://link.springer.com/chapter/10.1007/978-3-319-78759-6_22
365	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA	NCISCOS 2016	Andrés J Anaya-Isaza, Diego H Peluffo-Ordoñez, Juan C Alvarado-Pérez, Jorge Ivan-Rios, Juan A Castro-Silva, Paul D Rosero-Montalvo, Diego F Peña-Unigarro, Ana C Umaquinga-Criollo	Este trabajo presenta un estudio comparativo con métodos de reducción de la dimensión lineal, tales como: Análisis de Componentes Principales & Análisis Discriminante Lineal. El estudio pretende determinar, bajo criterios de objetividad, cuál de estas técnicas obtiene el mejor resultado de separabilidad entre clases. Para la validación experimental se utilizan dos bases de datos, del repositorio científico (UC Irvine Machine Learning Repository), para dar tratamiento a los atributos del data-set en función de confirmar visualmente la calidad de los resultados obtenidos. Las inmersiones obtenidas son analizadas, para realizar una comparación de resultados del embedimiento representados con RNX(K), que permite evaluar el área bajo la curva, del cual asume una mejor representación en una topología global o local que posteriormente genera los gráficos de visualización en un espacio de menor dimensión, para observar la separabilidad entre clases conservando la estructura global de los datos.	2017	6	https://www.researchgate.net/profile/Ana_Umaquinga/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA/links/5846c4e008ae61f75ddfd956.pdf
366	2016 21st Symposium on Signal Processing, Images and Artificial Vision, STSIVA 2016	STSIVA 2016	Pena-Unigarro, D. F., Salazar-Castro, J. A., Peluffo-Ordonez, D. H., Rosero-Montalvo, P. D., Ona-Rocha, O. R., Isaza, A. A., ... Theron, R. (2016)	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	6	https://colciencias.pure.elsevier.com/en/publications/2016-21st-symposium-on-signal-processing-images-and-artificial-vi-4
367	2015 20th Symposium on Signal Processing, Images and Computer Vision, STSIVA 2015-Conference Proceedings	STSIVA 2015	Arias-Mora, L., López-Ríos, L., Céspedes-Villar, Y., Velasquez-Martinez, L. F., Alvarez-Meza, A. M., & Castellanos-Dominguez, G.	Brain Computer Interface (BCI) has become one of the most interesting alternatives to support automatic systems able to interpret brain functions. Recently, the Motor Imagery (MI) paradigm is a widely topic of interest as a tool to develop BCI-based systems. Here, we present a relevant feature extraction methodology, termed MI discrimination using kernel relevance analysis (MIDKRA), to support MI classification in BCI systems. For such a purpose, a similarity criterion to rank the contribution of EEG features for classifying an MI paradigm is employed. The introduced approach includes the supervised information regarding the MI paradigm to find out a relevant set of features encoding discriminative information. We model the EEG recordings by considering both time and time-frequency representations. Moreover, a k nearest-neighbor classifier is carried out to validate the proposed feature relevance approach. Experimental results carried out on two different BCI databases, a well-known public MI data and an Emotiv-based dataset built by us, demonstrate that MIDKRA outperforms state of the art methods and it is a suitable alternative to support straightforward BCI systems.	2015	6	https://colciencias.pure.elsevier.com/es/publications/2015-20th-symposium-on-signal-processing-images-and-computer-visi-13
368	A Low Cost Portable Prototype for Support of Bio-Feedback Therapies in Psychophysiological Disorders	RESEARCHGATE	Jose A Salazar-Castro, Diego H Peluffo-Ordóñez, Sergio Cano, Ángela Ruano, EJ Revelo-Fuelagán, Juan F Salazar-Castro, Hugo Campaña, Carlos R Ramírez-Saavedra	This work presents the design and implementation of a low cost and portable electronic device, it is based on the estimation of the mechanical activity of the heart by plethysmographic techniques. The proposed device is composed of four stages understood among the signal acquisition through photoplethysmography, its adequacy by analogic filters, the signal processing and heart rate estimation through an algorithm developed in an Arduino platform, and the human-device interface whit allows to make the a process of visual and hearing feedback. Testing and experimental results shows the applicability of the device while it maintaining its low cost and portability. Resumen—Este trabajo presenta el diseño y la implementación de un dispositivo electrónico de bajo costo y portable, basado en la estimación de la actividad mecánica del corazón mediante técnicas pletismográficas. El dispositivo propuesto está compuesto por cuatro etapas comprendidas entre la adquisición de la señal mediante fotopletismografía, su adecuación mediante filtros analógicos, el procesamiento de la señal y estimación del ritmo cardiaco mediante un algoritmo implementado en una tarjeta arduino y la interfaz hombre-dispositivo con la que se realiza un proceso de realimentación visual y auditiva. Las pruebas y los resultados experimentales muestran la aplicabilidad del dispositivo manteniendo su bajo costo y portabilidad.	2016	6	https://www.researchgate.net/profile/Jose_Salazar_Castro/publication/311644945_A_Low_Cost_Portable_Prototype_for_Support_of_Bio-_Feedback_Therapies_in_Psychophysiological_Disorders/links/5851bcd508ae7d33e0181b95/A-Low-Cost-Portable-Prototype-for-Support-of-Bio-Feedback-Therapies-in-Psychophysiologic
369	Propuesta Para El Diseño Del Control Automático De Una Planta De Producción De Biodiesel A Partir De Aceite Usado De Cocina	Jornadas Internacionales FICA 2016.	Yesid C Rosas-Narváez, Jose A Salazar-Castro, Diego H Peluffo-Ordóñez, Carlos A Ramírez	La eliminación desordenada de aceite por parte de hogares y restaurantes, así como el desaprovechamiento del aceite usado de cocinas se han convertido en causas transcendentales de contaminación. Asimismo, si no se recicla adecuadamente el aceite usado, la demanda de diésel fósil seguirá prevaleciendo. Esto obedece, entre otras razones, al desconocimiento de las posibilidades y beneficios de la transformación industrial del aceite para la generación de biodiesel. Una etapa determinante de la generación de biodiesel es la transesterificación, proceso que se desarrolla, tradicionalmente, de forma manual y heurística, razón por la cual está propenso a errores humanos. Esta investigación presenta el diseño de un prototipo para la automatización del proceso de transesterificación a través de un control automático de pH y temperatura.	2016	6	https://www.researchgate.net/publication/311648484_Propuesta_Para_El_Diseno_Del_Control_Automatico_De_Una_Planta_De_Produccion_De_Biodiesel_A_Partir_De_Aceite_Usado_De_Cocina
80	Segment Clustering for Holter Recordings Analysis	International Work-Conference on the Interplay Between Natural and Artificial Computation.  IWINAC 2017.	J. L. Rodriguez-Sotelo, D. H. Peluffo-Ordóñez, D. López-Londoño, A. Castro-Ospina.	In this work, an efficient non-supervised algorithm for clustering of ECG signals is presented. The method is assessed over a set of records from MIT/BIH arrhythmia database with different types of heartbeats, including normal (N) heartbeats, as well as the arrhythmia heartbeats recommended by the AAMI, usually found in Holter recordings: ventricular extra systoles (VE), left and right branch bundles blocks (LBBB and RBBB) and atrial premature beats (APB). The results are assessed by means the sensitivity and specificity measures, taking advantage of the database labels. Also, unsupervised performance measures are used. Finally, the performance of the algorithm is in average 95%, improving results reported by previous works of the literature.	2017	1	https://link.springer.com/chapter/10.1007/978-3-319-59740-9_45
115	Propuesta Para El Diseño Del Control Automático De Una Planta De Producción De Biodiesel A Partir De Aceite Usado De Cocina.	Jornadas Internacionales FICA 2016.	Yesid C. Rosas-Narváez, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez, C. A. Ramírez.	La eliminación desordenada de aceite por parte de hogares y restaurantes, así como el desaprovechamiento del aceite usado de cocinas se han convertido en causas transcendentales de contaminación. Asimismo, si no se recicla adecuadamente el aceite usado, la demanda de diésel fósil seguirá prevaleciendo. Esto obedece, entre otras razones, al desconocimiento de las posibilidades y beneficios de la transformación industrial del aceite para la generación de biodiesel. Una etapa determinante de la generación de biodiesel es la transesterificación, proceso que se desarrolla, tradicionalmente, de forma manual y heurística, razón por la cual está propenso a errores humanos. Esta investigación presenta el diseño de un prototipo para la automatización del proceso de transesterificación a través de un control automático de pH y temperatura.	2016	1	https://www.researchgate.net/publication/311648484_Propuesta_Para_El_Diseno_Del_Control_Automatico_De_Una_Planta_De_Produccion_De_Biodiesel_A_Partir_De_Aceite_Usado_De_Cocina
370	JUEGOS CON INTERFAZ NATURAL DE USUARIO PARA EL APOYO A LA ORIENTACIÓN ESPACIAL EN NIÑOS CON CAPACIDADES ESPECIALES	CIIEE 2017	Daysi Elizabeth Imbaquingo Esparza, Amarilis Loor, José Jácome, MacArthur Ortega Bustamante, Hugo Imbaquingo	Para el desarrollo de aprendizaje de los niños, los ejercicios y juegos han sido una herramienta de educación en la cultura humana, una de las habilidades básicas es la orientación espacial, que depende de la lateralización y el desarrollo psicomotor. Este estudio tuvo como objetivo implementar una aplicación basada en la tecnología Kinect denominada ViAm para apoyar al desarrollo de la orientación espacial en niños con capacidades especiales del Instituto Angélica Flores Zambrano, la cual permitirá a los niños realizar actividades de orientación espacial por medio de movimientos del cuerpo, Kinect es en la actualidad uno de los productos comerciales más usados para investigación en proyectos tecnológicos que requieren de interacción con usuarios de forma atractiva, y lúdica. La metodología utilizada fue cuantitativa se realizó pruebas en los prototipos desarrollados previamente por cada SDK a medir, se obtiene un valor por la posición de cada articulación en los frames de muestra (30/seg), a estos datos se le aplicó la fórmula de desviación estándar para determinar cuándo se mueve en relación a la media de posición, y cuan estable es el seguimiento del esqueleto humano.	2017	20	https://congresos.ups.edu.ec/index.php/ciiee/ciiee/paper/view/157
371	Planeación estratégica de TI-Gobernanza de TI	INNOVACIÓN TECNOLÓGICA	Daisy E Imbaquingo, José G Jácome, Hugo S MacArthur Ortega, Landeta Pablo Imbaquingo	El presente artículo hace un balance del estado del arte sobre los conceptos que corresponden al gobierno de TI además de tomar énfasis en el tema concerniente a la planeación estratégica de TI. Se hace una investigación histórica de la evolución de los marcos de referencia y las normas asociadas hasta llegar a la actualidad. La planeación estratégica institucional se la puede definir como el diseño de objetivos institucionales y las estrategias a utilizar para la consecución de estos objetivos. En particular, la planeación estratégica de tecnologías de la información, consiste en la definición de objetivos y las estrategias de TI necesarias para alcanzarlos. Hablamos entonces del alineamiento entre las estrategias de TI con los objetivos corporativos.	2016	20	https://scholar.google.com/scholar?oi=bibs&cluster=8666202575424516302&btnI=1&hl=es
372	Interactive Data Visualization Using Dimensionality Reduction and Dissimilarity-Based Representations	Intelligent Data Engineering and Automated Learning – IDEAL 2017. IDEAL 2017.	D. F. Peña-Unigarro, P. Rosero-Montalvo, J. Revelo-Fuelagán, J. A. Castro-Silva, J. C. Alvarado-Pérez, R. Therón, C. M. Ortega-Bustamante, D. H. Peluffo-Ordóñez.	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	20	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
373	Analysis of functionality between two Java EE enterprise service buses	INCISCOS 2016	Mauricio Rea, Daisy Imbaquingo, Fabricio Huera, Macarthur Ortega Bustamante, José Jácome, Marco R. Pusdá	This paper presents a comparison of two Enterprise Service Buses identified as reference implementations of free software for ESB: OpenESB and Mule ESB. The first uses JBI and the second its own integration engine based in interfaces and connectors. Both built on the JavaEE architecture but its internal structure is different, there lies the importance of confronting their architectures, strategies, technologies and implement a case of comparison of both ESB. A comparative analysis is used through a checklist to identify the features and functionality; and methodology of the test-mistake to evaluate the performance of ESB, for which an application to quantify transactions per second was implemented. With these comparisons it is determined that the OpenESB bus provides better performance and operability.	2016	20	https://www.researchgate.net/publication/313852826_Analysis_of_functionality_between_two_Java_EE_enterprise_service_buses
374	Creatividad e innovación: competencias genéricas o transversales en la formación profesional	Revista Virtual Universidad Católica del Norte	Isabel Hernández Arteaga, Juan Carlos Alvarado Pérez, Sara María Luna	La finalidad de este texto es presentar una revisión bibliográfica de estudios en la última década sobre creatividad e innovación en la educación, particularmente, como competencias genéricas en la formación de profesionales. Es un tema de mucha relevancia puesto que la creatividad y la innovación se constituyen en competencias clave para obtener ventajas competitivas en todos los campos del conocimiento y en todos los sectores de la sociedad. La política pública sobre Universidad-Empresa-Estado, unida a la de ciencia, tecnología e innovación, llaman la atención de la universidad sobre la necesidad de profesionales creativos e innovadores responsables de la transformación de la sociedad; acción que demanda la asimilación de estas competencias en la cultura, en el contexto educativo y en el sector empresarial, estimulando el cambio de paradigma y dando paso a modelos pedagógicos cuyas bases se centran en la solución de problemas y la toma de decisiones.	2015	16	http://revistavirtual.ucn.edu.co/index.php/RevistaUCN/article/view/620
375	Bridging the gap between human knowledge and machine learning	ADCAIJ: Advances in Distributed Computing and Artificial Intelligence Journal	Juan Carlos Alvarado-Pérez, Diego H Peluffo-Ordónez, Roberto Therón	Nowadays, great amount of data is being created by several sources from academic, scientific, business and industrial activities. Such data intrinsically contains meaningful information allowing for developing techniques, and have scientific validity to explore the information thereof. In this connection, the aim of artificial intelligence (AI) is getting new knowledge to make decisions properly. AI has taken an important place in scientific and technology development communities, and recently develops computer-based processing devices for modern machines. Under the premise, the premise that the feedback provided by human reasoning-which is holistic, flexible and parallel-may enhance the data analysis, the need for the integration of natural and artificial intelligence has emerged. Such an integration makes the process of knowledge discovery more effective, providing the ability to easily find hidden trends and patterns belonging to the database predictive model. As well, allowing for new observations and considerations from beforehand known data by using both data analysis methods and knowledge and skills from human reasoning. In this work, we review main basics and recent works on artificial and natural intelligence integration in order to introduce users and researchers on this emergent field. As well, key aspects to conceptually compare them are provided.	2015	16	http://revistas.usal.es/~revistas_trabajo/index.php/2255-2863/article/view/ADCAIJ2015415464
376	Geometrical homotopy for data visualization	European Symposium on Artificial Neural Networks, Computational Intelligence and Machine Learning (ESANN 2015)	Diego H Peluffo-Ordónez, Juan C Alvarado-Pérez, John A Lee, Michel Verleysen	This work presents an approach allowing for an interactive visualization of dimensionality reduction outcomes, which is based on an extended view of conventional homotopy. The pairwise functional followed from a simple homotopic function can be incorporated within a geometrical framework in order to yield a bi-parametric approach able to combine several kernel matrices. Therefore, the users can establish the mixture of kernels in an intuitive fashion by only varying two parameters. Our approach is tested by using kernel alternatives for conventional methods of spectral dimensional reduction such as multidimensional scalling, locally linear embedding and laplacian eigenmaps. Provided mixture represents every single dimensional reduction approach as well as helps users to find a suitable representation of embedded data.	2015	16	https://scholar.google.es/scholar?oi=bibs&cluster=13542050440249360610&btnI=1&hl=es
377	Responsabilidad social en la relación universidad-empresa-Estado	Educación y Educadores	Rosario Isabel Hernández-Arteaga, Juan Carlos Alvarado-Pérez, José Alberto Luna	Este artigo de revisão é o resultado de pesquisa sobre a responsabilidade social, particularmente a que deve cumprir a universidade do século XXI. Evidencia a importância da relação universidade-empresa-Estado como estratégia para propiciar o desenvolvimento de pesquisa e inovação, mediante a inter-relação dos setores educativo, empresarial e governamental, a partir da qual se propende pela geração de capacidade competitiva para o avanço da ciência, da tecnologia e dos processos produtivos, que visam aumentar a produtividade para impactar o avanço da sociedade. É dividido em cinco partes: na primeira, conceitualiza-se sobre a responsabilidade social como elemento fundamental na relação empresa-sociedade; na segunda, apresenta-se a responsabilidade da universidade perante a sociedade, e assinala-se que, além de formar profissionais, tem a missão de criar e recriar conhecimento pertinente para a região; na terceira, analisa-se a responsabilidade da empresa como organização que assume processos de inovação e competitividade a partir da relação com a academia; na quarta, identifica-se a responsabilidade da universidade diante de processos de mudança com relação ao setor produtivo; em quinto lugar, descreve-se o estabelecimento das relações universidade-empresa-Estado como estratégia para instaurar cenários de confiança entre os três setores. O estudo conclui que a responsabilidade social da universidade no século XXI assume-se a partir da pertinência de suas funções substantivas com o contexto social; portanto, deve ser integrada aos âmbitos econômico, político, social, cultural e ambiental, participando deforma significativa no desenvolvimento da região e do país.	2015	16	http://www.scielo.org.co/scielo.php?pid=S0123-12942015000100006&script=sci_abstract&tlng=pt
378	Interactive interface for efficient data visualization via a geometric approach	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium	JA Salazar-Castro, YC Rosas-Narváez, AD Pantoja, Juan C Alvarado-Pérez, Diego H Peluffo-Ordóñez	Dimensionality reduction (DR) methods represent a suitable alternative to visualizing data. Nonetheless, most of them still lack the properties of interactivity and controllability. In this work, we propose a data visualization interface that allows for user interaction within an interactive framework. Specifically, our interface is based on a mathematic geometric model, which combines DR methods through a weighted sum. Interactivity is provided in the sense that weighting factors are given by the user via the selection of points inside a geometric surface. Then,(even non-expert) users can intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results are obtained using artificial and real datasets, demonstrating the usability and applicability of our interface in DR-based data visualization.	2015	16	https://ieeexplore.ieee.org/abstract/document/7330397/
379	Interactive data visualization using dimensionality reduction and similarity-based representations	IberoAmerican Congress on Pattern Recognition	P Rosero-Montalvo, P Diaz, Jose Alejandro Salazar-Castro, DF Pena-Unigarro, AJ Anaya-Isaza, Juan C Alvarado-Pérez, Roberto Therón, Diego Hernán Peluffo-Ordóñez	This work presents a new interactive data visualization approach based on mixture of the outcomes of dimensionality reduction (DR) methods. Such a mixture is a weighted sum, whose weighting factors are defined by the user through a visual and intuitive interface. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to be drawn on the scatter plot. Our visualization approach enables the user to interactively combine DR methods while provided information about the structure of original data, making then the selection of a DR scheme more intuitive.	2016	16	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_41
380	On the relationship between dimensionality reduction and spectral clustering from a kernel viewpoint	Distributed Computing and Artificial Intelligence, 13th International Conference	Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina, X Blanco-Valencia, Juan C Alvarado-Pérez, Roberto Therón, A Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	16	https://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
381	Multiple kernel learning for spectral dimensionality reduction	Iberoamerican Congress on Pattern Recognition	Diego Hernán Peluffo-Ordóñez, Andrés Eduardo Castro-Ospina, Juan Carlos Alvarado-Pérez, Edgardo Javier Revelo-Fuelagán	This work introduces a multiple kernel learning (MKL) approach for selecting and combining different spectral methods of dimensionality reduction (DR). From a predefined set of kernels representing conventional spectral DR methods, a generalized kernel is calculated by means of a linear combination of kernel matrices. Coefficients are estimated via a variable ranking aimed at quantifying how much each variable contributes to optimize a variance preservation criterion. All considered kernels are tested within a kernel PCA framework. The experiments are carried out over well-known real and artificial data sets. The performance of compared DR approaches is quantified by a scaled version of the average agreement rate between K-ary neighborhoods. Proposed MKL approach exploits the representation ability of every single method to reach a better embedded data for both getting more intelligible visualization and preserving the structure of data.	2015	16	https://link.springer.com/chapter/10.1007/978-3-319-25751-8_75
382	Knowledge discovery in databases from a perspective of intelligent information visualization	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium	Juan C Alvarado-Pérez, Harold Bolaños-Ramírez, Diego H Peluffo-Ordóñez, S Murillo	This paper reviews some recent and classical, relevant works on information visualization with a special focus on those applied to big data. The central idea dealt in this work relies on how to perform data mining tasks in a visual fashion; that is, using graphical correlation and interaction techniques. The scope of this review encompasses visualization techniques, formal visualization systems, and smart information visualization models. As well, newest approaches consisting of visualization and data mining integration process are explained.	2015	16	https://ieeexplore.ieee.org/abstract/document/7330438/
383	On the spectral clustering for dynamic data	International Work-Conference on the Interplay Between Natural and Artificial Computation	Diego Hernán Peluffo-Ordóñez, Juan C Alvarado-Pérez, Andrés Eduardo Castro-Ospina	Spectral clustering has shown to be a powerful technique for grouping and/or rank data as well as a proper alternative for unlabeled problems. Particularly, it is a suitable alternative when dealing with pattern recognition problems involving highly hardly separable classes. Due to its versatility, applicability and feasibility, this clustering technique results appealing for many applications. Nevertheless, conventional spectral clustering approaches lack the ability to process dynamic or time-varying data. Within a spectral framework, this work presents an overview of clustering techniques as well as their extensions to dynamic data analysis.	2015	16	https://link.springer.com/chapter/10.1007/978-3-319-18833-1_16
384	Interactive data visualization using dimensionality reduction and dissimilarity-based representations	International Conference on Intelligent Data Engineering and Automated Learning	DF Peña-Unigarro, P Rosero-Montalvo, Edgardo Javier Revelo-Fuelagán, JA Castro-Silva, Juan C Alvarado-Pérez, Roberto Therón, CM Ortega-Bustamante, Diego Hernán Peluffo-Ordóñez	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive color-based interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	16	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_50
385	Kernel-based framework for spectral dimensionality reduction and clustering formulation: A theoretical study	ADCAIJ: Advances in Distributed Computing and Artificial Intelligence Journal	Xiomara Patricia Blanco Valencia, MA Becerra, AE Castro Ospina, M Ortega Adarme, D Viveros Melo, DH PELUFFO ORDÓÑEZ	This work outlines a unified formulation to represent spectral approaches for both dimensionality reduction and clustering. Proposed formulation starts with a generic latent variable model in terms of the projected input data matrix.\r\nParticularly, such a projection maps data onto a unknown high-dimensional space. Regarding this model, a generalized optimization problem is stated using quadratic formulations and a least-squares support vector machine.\r\nThe solution of the optimization is addressed through a primal-dual scheme.\r\nOnce latent variables and parameters are determined, the resultant model outputs a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Particularly, proposed\r\nformulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2017	16	http://revistas.usal.es/index.php/2255-2863/article/view/ADCAIJ2017613140
386	Dimensionality reduction for interactive data visualization via a Geo-Desic approach	Computational Intelligence (LA-CCI), 2016 IEEE Latin American Conference	Jose A Salazar-Castro, Diego Peña-Unigarro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, H Mauricio Domínguez-Limaico, Juan C Alvarado-Pérez, Roberto Therón	This work presents a dimensionality reduction (DR) framework that enables users to perform either the selection or mixture of DR methods by means of an interactive model, here named Geo-Desic approach. Such a model consists of linear combination of kernel-based representations of DR methods, wherein the corresponding coefficients are related to coordinated latitude and longitude inside of the world map. By incorporating the Geo-Desic approach within an interface, the combination may be made easily and intuitively by users-even non-expert ones-fulfilling their criteria and needs, by just picking up points from the map. Experimental results demonstrates the usability and ability of DR methods representation of proposed approach.	2016	16	https://ieeexplore.ieee.org/abstract/document/7885740/
387	De Paz, Francisco 21 De Paz, Juan F. 63 de SL Cuadro, Marco Antonio 211 Djenouri, Youcef 47	Distributed Computing and Artificial Intelligence, 12th International Conference	Ngoc Anh Dung Do, Giner Alor-Hernández, Juan C Alvarado-Pérez, Victor Alves, Rogério Passos Pereira Amaral, Javier Bajo, Amar Balla, Z Banaszak, M Bedia, Karima Benatchba, Ahcene Bendjoudi, Ghassan Beydoun, G Bocewicz, Adel Boukhadra, Oleg Bukhvalov, L Castillo, Pablo Chamoso, Ali Chekima, Xia Chen, Luis Omar Colombo-Mendoza, Juan M Corchado, Catarina Costa, Stefania Costantini, Jamal Ahmad Dargham, Gustavo Maia de Almeida, Giovanni De Gasperis, Fernando De la Prieta, Raffaele Dell’Aversana, J Fdez-Glez, F Fdez-Riverola, Kiyohito Fukuda, Edoardo Gaffeo, Lucio Gobbi, Arkadiusz Gola, Vladimir Gorodetsky, David Griol, Katarzyna Grzybowska, Gutiérrez Guadalupe, Rebeca Cordero Gutiérrez, Zineb Habbas, Nurzeatul Hamimah Abdul Hamid, Samer Hassan, Patrycja Hoffa, Jinzhong Hou, Arazi Idrus, Omar Abdullatif Jassim, Bo Nørregaard Jørgensen, Canúl-Reich Juana, Ponce Julio, R Laza, Carlos Ley-Bosch, Tiancheng Li	The 12th International Symposium on Distributed Computing and Artificial Intelligence 2015 (DCAI 2015) is a forum to present applications of innovative techniques for studying and solving complex problems. The exchange of ideas between scientists and technicians from both the academic and industrial sector is essential to facilitate the development of systems that can meet the ever-increasing demands of today’s society. The present edition brings together past experience, current work and promising future trends associated with distributed computing, artificial intelligence and their application in order to provide efficient solutions to real problems.	2015	16	https://link.springer.com/book/10.1007%2F978-3-319-19638-1#page=417
388	El big data en la complejidad del sistema Universidad-Empresa-Estado	Universidad-Empresa-Estado: hacia la cultura de la investigación y la innovación	Juan Carlos Alvarado-Pérez	Big data es un nuevo concepto que emerge en respuesta a los actuales avances electrónicos e informáticos, los que han contribuido a formar montañas de datos generadas a un acelerado ritmo y que han alcanzado dimensiones exorbitantes, superando la capacidad de las herramientas convencionales para ser capturados, gestionados y procesados en un tiempo razonable. Además, dichos datos están dispersos y proceden de diversas fuentes, las cuales tienen la capacidad potencial de combinarse, propiciando composiciones inconsistentes e impredecibles. Los sistemas complejos, como la Universidad, la Empresa y el Estado, enfrentan diversos problemas, sobre los que existen gran cantidad de datos pero escasa información, lo que hace necesario dar un sentido a todo este caos, encontrando relaciones significantes para generar nuevo conocimiento. Por esta razón, las herramientas deben evolucionar paralelamente al crecimiento de los datos, haciendo emerger novedosas técnicas que utilicen las potencialidades de los recursos computacionales, como la minería de datos, y los integren de manera sinérgica con otras técnicas que se adapten a las cualidades de análisis e interpretación humana como la analítica visual, es decir, la suma de la inteligencia artificial y la inteligencia natural como un equipo idóneo para descubrir conocimiento y concebir una visión holística del mundo.	2013	16	https://www.researchgate.net/profile/C_Y_Rosero-Galindo/publication/271764595_Research_as_the_Coordinating_Axis_in_the_University-Company-State_Relationship_Carol_Yovanna_Rosero-Galindo_y_Juan_Pablo_Garcia-Lopez/links/54d0ea730cf20323c21a1212.pdf#page=126
389	Visualización y métodos kernel: Integrando inteligencia natural y artificial	Universidad Politécnica Estatal del Carchi (UPEC)-Ecuador	Juan C Alvarado-Pérez, Diego H Peluffo-Ordóñez, Roberto Theron	Los enormes volúmenes de datos, generados por la actividad académica, científica, empresarial e industrial, entre muchas más, contienen información muy valiosa, lo que hace necesario desarrollar procesos y técnicas robustas, de validez científica que permitan explorar esas grandes cantidades de datos de manera óptima, con el propósito de obtener información relevante para la generación de nuevo conocimiento y toma de decisiones acertadas. La robustez y altas capacidades de procesamiento computacional de las maquinas modernas son aprovechadas por áreas como la inteligencia artificial que si se integra de forma holística con la inteligencia natural, es decir, si se combina sinérgicamente los métodos sofisticados de análisis de datos con los conocimientos, habilidades y flexibilidad de la razón humana, es posible generar conocimiento de forma más eficaz. La visualización de información propone formas eficientes de llevar los resultados generados por los algoritmos a la comprensión humana, la cual permite encontrar tendencias y patrones ocultos de forma visual, los cuales pueden formar la base de modelos predictivos que permitan a los analistas producir nuevas observaciones y consideraciones a partir de los datos existentes, mejorando el desempeño de los sistemas de aprendizaje automático, haciendo más inteligibles los resultados y mejorando la interactividad y controlabilidad por parte del usuario.	2016	16	http://congresoingenierias.upec.edu.ec/images/IICONGRESO/MEMORIAS_IICONGRESO.pdf#page=14
390	Interactive Data Visualization Using Dimensionality Reduction and Dissimilarity-Based Representations	Intelligent Data Engineering and Automated Learning–IDEAL 2017: 18th International Conference, Guilin, China, October 30–November 1, 2017, Proceedings	JA Castro-Silva, JC Alvarado-Pérez, R Therón, CM Ortega-Bustamante, DH Peluffo-Ordónez	This work describes a new model for interactive data visualization followed from a dimensionality-reduction (DR)-based approach. Particularly, the mixture of the resulting spaces of DR methods is considered, which is carried out by a weighted sum. For the sake of user interaction, corresponding weighting factors are given via an intuitive colorbased interface. Also, to depict the DR outcomes while showing information about the input high-dimensional data space, the low-dimensional representations reached by the mixture is conveyed using scatter plots enhanced with an interactive data-driven visualization. In this connection, a constrained dissimilarity approach define the graph to be drawn on the scatter plot.	2017	16	https://books.google.es/books?hl=es&lr=&id=3f06DwAAQBAJ&oi=fnd&pg=PA461&ots=3jrESW4Feo&sig=zm2MaOERNCTBFGYuoFJPQir9h9M#v=onepage&q&f=false
391	Knowledge discovery in databases from a perspective of intelligent information visualization	20th Symposium on Signal Processing, Images and Computer Vision (STSIVA)	Juan C. Alvarado-Pérez , Harold Bolaños-Ramírez , Diego H. Peluffo-Ordóñez , S. Murillo	This paper reviews some recent and classical, relevant works on information visualization with a special focus on those applied to big data. The central idea dealt in this work relies on how to perform data mining tasks in a visual fashion; that is, using graphical correlation and interaction techniques. The scope of this review encompasses visualization techniques, formal visualization systems, and smart information visualization models. As well, newest approaches consisting of visualization and data mining integration process are explained.	2015	34	https://ieeexplore.ieee.org/document/7330438/
392	Automatic Motion Segmentation via a Cumulative Kernel Representation and Spectral Clustering	Lecture Notes in Computer Science	O. R. Oña-Rocha, O. T. Sánchez-Manosalvas, A. C. Umaquinga-Criollo, P. D. Rosero-Montalvo, L. E. Suárez-Zambrano, J. L. Rodríguez-Sotelo, D. H. Peluffo-Ordóñez	Dynamic or time-varying data analysis is of great interest in emerging and challenging research on automation and machine learning topics. In particular, motion segmentation is a key stage in the design of dynamic data analysis systems. Despite several studies have addressed this issue, there still does not exist a final solution highly compatible with subsequent clustering/classification tasks. In this work, we propose a motion segmentation compatible with kernel spectral clustering (KSC), here termed KSC-MS, which is based on multiple kernel learning and variable ranking approaches. Proposed KSC-MS is able to automatically segment movements within a dynamic framework while providing robustness to noisy environments.	2017	35	https://link.springer.com/chapter/10.1007/978-3-319-68935-7_44
393	Case-Based Reasoning Systems for Medical Applications with Improved Adaptation and Recovery Stages	Lecture Notes in Computer Science	X. Blanco Valencia, D. Bastidas Torres, C. Piñeros Rodriguez, D. H. Peluffo-Ordóñez, M. A. Becerra, A. E. Castro-Ospina	Case-Based Reasoning Systems (CBR) are in constant evolution, as a result, this article proposes improving the retrieve and adaption stages through a different approach. A series of experiments were made, divided in three sections: a proper pre-processing technique, a cascade classification, and a probability estimation procedure. Every stage offers an improvement, a better data representation, a more efficient classification, and a more precise probability estimation provided by a Support Vector Machine (SVM) estimator regarding more common approaches. Concluding, more complex techniques for classification and probability estimation are possible, improving CBR systems performance due to lower classification error in general cases.	2018	26	https://link.springer.com/chapter/10.1007%2F978-3-319-78723-7_3
394	Multi-labeler Classification Using Kernel Representations and Mixture of Classifiers	Lecture Notes in Computer Science	D. E. Imbajoa-Ruiz, I. D. Gustin, M. Bolaños-LedezmaA. F. Arciniegas-MejíaF. A. Guasmayan-GuasmayanM. J. Bravo-MontenegroA. E. Castro-OspinaD. H. Peluffo-Ordóñez	This work introduces a multi-labeler kernel novel approach for data classification learning from multiple labelers. The learning process is done by training support-vector machine classifiers using the set of labelers (one labeler per classifier). The objective functions representing the boundary decision of each classifier are mixed by means of a linear combination. Followed from a variable relevance, the weighting factors are calculated regarding kernel matrices representing each labeler. To do so, a so-called supervised kernel function is also introduced, which is used to construct kernel matrices. Our multi-labeler method reaches very good results being a suitable alternative to conventional approaches.	2017	13	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_42
395	Cardiac Pulse Modeling Using a Modified van der Pol Oscillator and Genetic Algorithms	Lecture Notes in Computer Science	Fabián M. Lopez-Chamorro, Andrés F. Arciniegas-Mejia, David Esteban Imbajoa-Ruiz, Paul D. Rosero-Montalvo, Pedro García, Andrés Eduardo Castro-Ospina, Antonio Acosta, Diego Hernán Peluffo-Ordóñez	This paper proposes an approach for modeling cardiac pulses from electrocardiographic signals (ECG). A modified van der Pol oscillator model (mvP) is analyzed, which, under a proper configuration, is capable of describing action potentials, and, therefore, it can be adapted for modeling a normal cardiac pulse. Adequate parameters of the mvP system response are estimated using non-linear dynamics methods, like dynamic time warping (DTW). In order to represent an adaptive response for each individual heartbeat, a parameter tuning optimization method is applied which is based on a genetic algorithm that generates responses that morphologically resemble real ECG. This feature is particularly relevant since heartbeats have intrinsically strong variability in terms of both shape and length. Experiments are performed over real ECG from MIT-BIH arrhythmias database. The application of the optimization process shows that the mvP oscillator can be used properly to model the ideal cardiac rate pulse.	2018	13	https://link.springer.com/chapter/10.1007/978-3-319-78723-7_8
396	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	Lecture Notes in Computer Science	Leandro Leonardo Lorente-LeyvaIs, rael David Herrera-Granda, Paul D. Rosero-Montalvo, Karina L. Ponce-Guevara, Andrés Eduardo Castro-Ospina, Miguel A. Becerra, Diego Hernán Peluffo-Ordóñez	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	18	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_37
397	GreenFarm-DM: A tool for analyzing vegetable crops data from a greenhouse using data mining techniques (First trial)	Second Ecuador Technical Chapters Meeting (ETCM)	K. L. Ponce-Guevara, J. A. Palacios-Echeverría, E. Maya-Olalla, H. M. Domínguez-Limaico, L. E. Suárez-Zambrano, P. D. Rosero-Montalvo, D. H. Peluffo-Ordóñez, J. C. Alvarado-Pérez	This work shows the use of Big Data and Data Mining techniques on vegetable crops data from a greenhouse by implementing the first version of a software tool, so called GreenFarm-DM. Such a tool is aimed at analyzing the factors that influence the growth of the crops, and determine a predictive model of soil moisture. Within a greenhouse, the variables that affect crop growth are: relative humidity, soil moisture, ambient temperature, and levels of illumination and CO2. These parameters are essential for photosynthesis, i.e. during processes where plants acquire the most nutrients, and therefore, if performing a good control on these parameters, plants might grow healthier and produce better fruits. The process of analysis of such factors in a data mining context requires designing an analysis system and establishing an objective variable to be predicted by the system. In this case, in order to optimize water resource expenditure, soil moisture has been chosen as the target variable. The proposed analysis system is developed in a user interface implemented in Java and NetBeans IDE 8.2, and consists mainly of two stages. One of them is the classification through algorithm C4.5 (chosen for the first trial), which uses a decision tree based on the data entropy, and allows to visualize the results graphically. The second main stage is the prediction, in which, from the classification results obtained in the previous stage, the target variable is predicted from information of a new set of data. In other words, the interface builds a predictive model to determine the behavior of soil moisture.	2017	18	https://ieeexplore.ieee.org/document/8247519/
398	Face Detection and Classification Using Eigenfaces and Principal Component Analysis: Preliminary Results	International Conference on Information Systems and Computer Science (INCISCOS)	Richard Mejía-Campos, Diego Néjer-Haro, Santiago Recalde-Avincho, Paul Rosero-Montalvo, Diego Peluffo-Ordóñez	This work is a Scientific Track paper corresponding to the area of Intelligent Systems. This paper presents a facial recognition approach based on the Eigenfaces method as well as Principal Component Analysis (PCA) as algorithm of processing and cleaning images, respectively. The classification was performed by using the Euclidean distance between the facial characters stored in a database and new images captured in an interface with similarly coded developed in MatLab. As main results, we obtained: (i) 68.9% of classification accuracy when using different components of stored faces, (ii) 91.43% of classification performance when storing 3 components for each face and evaluating more users for training model in seven controlled experiments.	2018	11	https://ieeexplore.ieee.org/document/8328124/
399	Razonamiento basado en casos aplicado al diagnóstico médico utilizando clasificadores multi-clase: Un estudio preliminar	Enfoque UTE	D. Viveros-Melo, M. Ortega-Adarme, X. Valencia, A. E. Castro-Ospina, S. Murillo-Rendón, D. H. Peluffo-Ordóñez.	Case-based reasoning (CBR)is a process used for computer processingthat tries to mimic the behavior of a human expert in making decisions regarding a subject and learn from the experience of past cases.CBR has demonstrated to be appropriate for working with unstructured domains dataor difficult knowledge acquisition situations,such as medical diagnosis, where it is possible to  identify  diseases  such  as:cancer  diagnosis,  epilepsy  prediction  and  appendicitis  diagnosis. Someof the trendsthat may be developed for CBR in the health science are oriented to reduce the  number  of  features  in  highly dimensional  data.An  important  contribution  may  be  the estimation  of  probabilities  of  belonging  to  each  class  for  new  cases.In  this  paper,  in  order  to adequately  represent  the  database  and  to avoid  the  inconveniences  caused  by  the  high dimensionality,  noise  and  redundancy,  a  number  of  algorithms  are  used  in  the  preprocessing stage  for  performing  both  variable  selection  and  dimension  reduction  procedures. Also,a comparison  of  the  performance  ofsome representative multi-classclassifiers  is  carried  out  to identify  the  most effective  oneto  includewithin  a  CBR  scheme. Particularly,  four  classification techniques and  two reduction  techniques are  employed to make a comparative study  of multi-classclassifiers on CBR.	2017	3	http://ingenieria.ute.edu.ec/enfoqueute/index.php/revista/article/view/141/148
400	Comparative Evaluation of Background Subtraction Algorithms for High Performance Embedded Systems	RESEARCHGATE	Lorena de los Angeles Guachi Guachi, Giuseppe Cocorullo, Pasquale Corsonello, Fabio Frustaci, Stefania Perri	Background Subtraction technique is widely used in surveillance systems to identify moving objects. Although color features have been extensively used in several background subtraction algorithms, demonstrating high efficiency and performances, in actual real-time applications the background subtraction performance is still a challenge due to high computational requirements. In this paper, two approaches and their optimized versions are evaluated to implement highperformance background subtraction algorithms for real-time applications. Gaussian Mixture Model and the Multimodal Background Subtraction are characterized by two different color descriptors: Gray scale and H color invariant combined with Gray scale information respectively. Different experimental analysis allows evaluating the efficiency in terms of computational complexity and accuracy for outdoor and indoor environments. Experimental tests demonstrated that the Multimodal Background Subtraction approach with its variants is established as affordable for real-time applications and particularly suitable on hardware platforms with onboard memory and limited computational resources.	2017	40	https://www.researchgate.net/publication/321025123_Comparative_Evaluation_of_Background_Subtraction_Algorithms_for_High_Performance_Embedded_Systems
401	Multimodal background subtraction for high-performance embedded systems	Journal of Real-Time Image Processing	Giuseppe Cocorullo, Pasquale Corsonello, Fabio Frustaci, Lorena de los Angeles Guachi Guachi, Stefania Perri	In many computer vision systems, background subtraction algorithms have a crucial importance to extract information about moving objects. Although color features have been extensively used in several background subtraction algorithms, demonstrating high efficiency and performances, in actual applications the background subtraction accuracy is still a challenge due to the dynamic, diverse and complex background types. In this paper, a novel method for the background subtraction is proposed to achieve low computational cost and high accuracy in real-time applications. The proposed approach computes the background model using a limited number of historical frames, thus resulting suitable for a real-time embedded implementation. To compute the background model as proposed here, pixels grayscale information and color invariant H are jointly exploited. Differently from state-of-the-art competitors, the background model is updated by analyzing the percentage changes of current pixels with respect to corresponding pixels within the modeled background and historical frames. The comparison with several traditional and real-time state-of-the-art background subtraction algorithms demonstrates that the proposed approach is able to manage several challenges, such as the presence of dynamic background and the absence of frames free from foreground objects, without undermining the accuracy achieved. Different hardware designs have been implemented, for several images resolutions, within an Avnet ZedBoard containing an xc7z020 Zynq FPGA device. Post-place and route characterization results demonstrate that the proposed approach is suitable for the integration in low-cost high-definition embedded video systems and smart cameras. In fact, the presented system uses 32 MB of external memory, 6 internal Block RAM, less than 16,000 Slices FFs, a little more than 20,000 Slices LUTs and it processes Full HD RGB video sequences with a frame rate of about 74 fps.	2016	40	https://www.researchgate.net/publication/309815461_Multimodal_background_subtraction_for_high-performance_embedded_systems
402	Color Invariant Study for Background Subtraction	Conference: CENICS 2016 : The Ninth International Conference on Advances in Circuits, Electronics and Micro-electronics, At Niza Francia	Lorena de los Angeles Guachi Guachi, Giuseppe Cocorullo, Pasquale Corsonello, Fabio Frustaci, Stefania Perri	Effectiveness detection to extract objects of interest is a fundamental step in many computer vision systems. In real solutions, the accurate Background Subtraction (BS) is a challenge due to diverse and complex background types. Being the color widely used as descriptor to improve accuracy in several BS algorithms, in this paper we analyze four Color Invariants (CIs) based on the Kubelka-Munk theory combined with Gray scale. The capability of several CIs combinations in segmenting foreground is evaluated referring to five video sequences. This experimental study provides a point-of-view to choose the best color combination considering accuracy and the channel numbers which can be applied for image segmentation. The results demonstrate that the combination of the color invariant H with Gray scale achieves higher performance for foreground segmentation for both indoor and outdoor video sequences. Furthermore, it uses the minimum number of color channels.	2016	40	https://www.researchgate.net/publication/321441592_Color_Invariant_Study_for_Background_Subtraction
403	Embedded surveillance system using background subtraction and Raspberry Pi	AEIT International Annual Conference (AEIT)	Giuseppe Cocorullo, Pasquale Corsonello, Fabio Frustaci, Lorena de los Angeles Guachi Guachi, Stefania Perri	One of the most challenging problems in computer vision is the ability of understanding video sequences to automatically detect and recognize moving objects. This work presents the development and the inexpensive implementation of an efficient algorithm based on the background subtraction technique adequate for low-cost embedded video surveillance systems. The proposed algorithm exploits the combination of few historical frames with the use of two channels based on the invariant color H and the grayscale level information to achieve high performance and good quality also within the Raspberry-Pi platform. Experimental results show that the implemented algorithm is robust against noises typically occurring in both indoor and outdoor environments.	2015	40	https://www.researchgate.net/publication/304409961_Embedded_surveillance_system_using_background_subtraction_and_Raspberry_Pi
404	A novel background subtraction method based on color invariants and grayscale levels	International Carnahan Conference on Security	Fabio Frustaci, Lorena de los Angeles Guachi Guachi, Giuseppe Cocorullo, Corsonello Pasquale, Stefania Perri	This paper presents a new method for background subtraction which takes advantages of using the color invariants combined with gray color. The proposed method works robustly reducing misclassified foreground objects. Gaussian mixtures are exploited for each pixel through two channels: the color invariants, which are derived from a physical model, and the gray colors obtained as a descriptor of the image. The background models update is performed using a random process selected considering that in many practical situations it is not necessary to update each background pixel model for each new frame. The novel algorithm has been compared to three state-of-the-art methods. Experimental results demonstrate the proposed method achieves a higher robustness, is less sensitive to noise and increases the number of pixel correctly classified as foreground for both indoor and outdoor video sequences.	2014	40	https://www.researchgate.net/publication/270157853_A_novel_background_subtraction_method_based_on_color_invariants_and_grayscale_levels
405	Interactive data visualization using dimensionality reduction and similarity-based representations	IberoAmerican Congress on Pattern Recognition	P Rosero-Montalvo, P Diaz, Jose Alejandro Salazar-Castro, DF Pena-Unigarro, AJ Anaya-Isaza, Juan C Alvarado-Pérez, Roberto Therón, Diego Hernán Peluffo-Ordóñez	This work presents a new interactive data visualization approach based on mixture of the outcomes of dimensionality reduction (DR) methods. Such a mixture is a weighted sum, whose weighting factors are defined by the user through a visual and intuitive interface. Additionally, the low-dimensional representation space produced by DR methods are graphically depicted using scatter plots powered via an interactive data-driven visualization. To do so, pairwise similarities are calculated and employed to define the graph to be drawn on the scatter plot. Our visualization approach enables the user to interactively combine DR methods while provided information about the structure of original data, making then the selection of a DR scheme more intuitive.	2017	12	https://link.springer.com/chapter/10.1007/978-3-319-52277-7_41
411	Propuesta de análisis visual de datos en Big Data usando reducción de dimensión interactiva Proposal for visual analysis of Big Data using interactive dimensionality reduction	Tecnologías Aplicadas a la Ingeniería	AC Umaquinga-Criollo, DH Peluffo-Ordónez, PD Rosero-Montalvo, MV Cabrera-Álvarez, JC Alvarado-Perez, AJ Anaya-Isaza	Today, the volume of available data is experiencing an exponential growing, introducing an emergent are so-called Big Data. Along with the data growing, the demand of tools, techniques and devices to store, transmit and process high-dimensional data (HD) is increased. Most available methodologies to process HD output abstract outcomes and user is not involved in the selection or parameter tuning processes of data analysis techniques. In this work, we propose a visual analysis methodology following principles of interactivity and controllability. Doing so, users (even non-expert ones) can intuitively select a dimensionality reduction method to generate intelligible representations for human beings.	2017	12	https://www.researchgate.net/profile/Ana_Umaquinga/publication/316056310_Propuesta_de_analisis_visual_de_datos_en_Big_Data_usando_reduccion_de_dimension_interactiva_Proposal_for_visual_analysis_of_Big_Data_using_interactive_dimensionality_reduction/links/58ee5d63aca2724f0a28a36f/Propuesta-de-analisi
406	Interactive visualization methodology of high-dimensional data with a color-based model for dimensionality reduction	Signal Processing, Images and Artificial Vision (STSIVA), 2016 XXI Symposium	Diego F Peña-ünigarro, Jose A Salazar-Castro, Diego H Peluffo-Ordóñez, Paul D Rosero-Montalvo, Omar R Oña-Rocha, Andres A Isaza, Juan C Alvarado-Perez, Roberto Theron	Nowadays, a consequence of data overload is that world's technology capacity to collect, communicate, and store large volumes of data is increasing faster than human analysis skills. Such an issue has motivated the development of graphic ways to visually represent and analyze high-dimensional data. Particularly, in this work, we propose a graphical interface that allow the combination of dimensionality reduction (DR) methods using a chromatic model to make data visualization more intelligible for humans. This interface is designed for an easy and interactive use, so that input parameters are given by the user via the selection of RGB values inside a given surface. Proposed interface enables (even non-expert) users to intuitively either select a concrete DR method or carry out a mixture of methods. Experimental results proves the usability of our interface making the selection or configuration of a DR-based visualization an intuitive and interactive task for the user.	2016	12	https://ieeexplore.ieee.org/abstract/document/7743318/
407	On the relationship between dimensionality reduction and spectral clustering from a kernel viewpoint	Distributed Computing and Artificial Intelligence, 13th International Conference	Diego Hernán Peluffo-Ordóñez, Miguel A Becerra, Andrés Eduardo Castro-Ospina, X Blanco-Valencia, Juan C Alvarado-Pérez, Roberto Therón, A Anaya-Isaza	This paper presents the development of a unified view of spectral clustering and unsupervised dimensionality reduction approaches within a generalized kernel framework. To do so, the authors propose a multipurpose latent variable model in terms of a high-dimensional representation of the input data matrix, which is incorporated into a least-squares support vector machine to yield a generalized optimization problem. After solving it via a primal-dual procedure, the final model results in a versatile projected matrix able to represent data in a low-dimensional space, as well as to provide information about clusters. Specifically, our formulation yields solutions for kernel spectral clustering and weighted-kernel principal component analysis.	2016	12	https://link.springer.com/chapter/10.1007/978-3-319-40162-1_28
408	Sistema de Riego Basado En La Internet De Las Cosas (IoT)	International Conference on Information Systems and Computer Science 2016 (INCISCOS).	A Anaya-Isaza, Diego H Peluffo-Ordoñez, Jorge Ivan-Rios, Juan A Castro-Silva, Diego A Carvajal Ruiz, Luis H Espinosa Llanos	The application of technology in all the society’s fields has increased since the 90’s decade, and in the agriculture has brought many benefits enabling increase quality and productivity in crops. The inefficiency and ineffectiveness of traditional methods of control and monitoring used in agriculture, produce extra time and cost loss for farmers. This paper describes the design, elaboration and implementation of an irrigation system using open hardware and open software, Wireless Sensor Network (WSN), actuators, Wireless Communication Devices and ICT tools, to create an environment where Internet of Things (IoT) and precision agriculture give users better control of irrigation over crops based on evapotranspiration.	2016	12	https://www.researchgate.net/profile/Diego_Peluffo/publication/315793360_Sistema_de_Riego_Basado_En_La_Internet_De_Las_Cosas_IoT/links/58f4dd6ba6fdcc11e569fa8a/Sistema-de-Riego-Basado-En-La-Internet-De-Las-Cosas-IoT.pdf
409	Prototype reduction algorithms comparison in nearest neighbor classification for sensor data: Empirical study	Ecuador Technical Chapters Meeting (ETCM), 2017 IEEE	Paul Rosero-Montalvo, Diego H Peluffo-Ordóñez, Ana Umaquinga, Andrés Anaya, Jorge Serrano, Edwin Rosero, Carlos Vásquez, Luis Suaréz	This work presents a comparative study of prototype selection (PS) algorithms. Such a study is done over data-from-sensor acquired by an embedded system. Particularly, five flexometers are used as sensors, which are located inside a glove aimed to read sign language. Measures were taken to quantify the balance between classification performance and reduction training set data (QCR) with k neighbors equal to 3 and 1 to force the classifier (kNN) to the maximum. Two tests were used: (a)the QCR performance and (b) the embedded system decision in real proves. As result the Random Mutation Hill Climbing (RMHC) algorithm is considered the best option to choose in this data type with removed instances at 87% and classification performance at 82% in software tests, also the classifier kNN must be with k=3 to improve the classification performance. In a real situation, with the algorithm implemented. The system makes correct decisions at 81% with 5 persons doing sign language in real time.	2017	12	https://ieeexplore.ieee.org/abstract/document/8247530/
410	Estudio comparativo de métodos espectrales para reducción de la dimensionalidad: LDA versus PCA	INCISCOS 2016	Andrés J Anaya-Isaza, Diego H Peluffo-Ordoñez, Juan C Alvarado-Pérez, Jorge Ivan-Rios, Juan A Castro-Silva, Paul D Rosero-Montalvo, Diego F Peña-Unigarro, Ana C Umaquinga-Criollo	This paper presents a comparative study with methods of reducing the linear dimension, such as Principal Component Analysis & linear discriminant analysis. The study aims to determine, based on criteria of objectivity, which of these techniques get the best result of separability between classes. For experimental validation two databases, scientific repository (UC Irvine Machine Learning Repository) are used to provide treatment to the attributes of the data-set according to visually confirm the quality of the results. The dives obtained are analyzed, for comparison of results embedimiento represented with RNX (K), which evaluates the area under the curve, which assumes better representation in a local global topology or subsequently generates graphics display a space of smaller dimension, to\r\nobserve the class separability preserving the overall structure of the data.	2016	12	https://www.researchgate.net/profile/Ana_Umaquinga/publication/311450410_Estudio_comparativo_de_metodos_espectrales_para_reduccion_de_la_dimensionalidad_LDA_versus_PCA_Comparative_study_between_spectral_methods_for_dimension_reduction_LDA_versus_PCA/links/5846c4e008ae61f75ddfd956.pdf
412	Propuesta de análisis visual de datos en Big Data usando reducción de dimensión interactiva Visual Big Data analysis proposal using interactive dimensionality reduction	Tecnologías aplicadas a la Ingeniería FICA-UTN 2016	AC Umaquinga-Criollo, DH Peluffo-Ordóñez, MV Cabrera-Álvarez, JC Alvarado-Pérez, AJ Anaya-Isaza	Today, the volumen of available data is experiencing an exponential growing, introducing an emergent are so-called Big Data. Along with the data growing, the demand of tools, techniques and devices to store, transmit and process high-dimensional data (HD) is increased. Most available methodologies to process HD output abstract outcomes and user is not involved in the selection or parameter tuning processes of data analysis techniques. In this work, we propose a visual analysis methodology following principles of interactivity and controlability. Doing so, users (even non-expert ones) can inuitively select a dimensionality reduction method to generate inteligible representations for human beings.	2016	12	http://diegopeluffo.com/publicaciones/2016_JornadasFica_BigData.pdf
413	Diseño e implementación de un Sistema de Medición Inteligente para AMI de la microrred de la Universidad de Nariño	DOI: 10.29019/enfoqueute.v8n1.136	Andrés Fernando Arciniegas Mejía, David Imbajoa, Javier Revelo F.	Este proyecto describe la propuesta de un Sistema de Gestión de Medida desde el proceso de diseño hasta la implementación de un prototipo de medidor inteligente, para operación en la microrred de la Universidad de Nariño. Este dispositivo se caracteriza por el constante registro de medidas con resolución de 24 bits, suficiente para realizar análisis de calidad de la potencia. Además, se integra al sistema SCADA, a través de los protocolos abiertos MODBUS, DNP3 e IEC 61850 con técnicas de ciberseguridad programada. De igual manera, se diseña varias plataformas de gestión para el monitoreo de variables eléctricas y el control del flujo de corriente a las cargas. Finalmente, dos casos de estudios muestran la aplicación en la microrred, del Sistema de Gestión de Medida implementado.	2017	42	https://www.researchgate.net/publication/320993048_Diseno_e_implementacion_de_un_Sistema_de_Medicion_Inteligente_para_AMI_de_la_microrred_de_la_Universidad_de_Narino
414	Multi-Labeller classification Method based on Mixture of Classifiers and Genetic Algorithm Optimization	INCISCOS	Andrés Fernando Arciniegas Mejía, David Imbajoa, Iván Gustin, Mauricio Bolaños, Dario F. Fajardo F., Fredy Guasmayan, María JANETH Bravo Montenegro, Diego Peluffo	This work presents a new method proposal applied to Multi-Labelers scenarios. This is a situation where labelling individuals in a set of data based on certain characteristics in the process of determining labels to individuals in a set of data based on certain characteristics. Our approach consists in processing a Support Vector Machine classifier to each labelers substantiated on his answers. We formulate a genetic algorithm optimization to obtain a set of weights according to their opinion, in order to penalize each panelist. Finally, their resulting mappings are mixed, and a final classifier is generated, showing to be better than majority vote. For experiments, the well-known Iris database is handled, with multiple simulated artificial labels. The proposed method reaches very good results compared to conventional multi-labeler methods, able to assess the concordance among panelists considering the structure data.	2016	42	https://www.researchgate.net/publication/311668355_Multi-Labeller_classification_Method_based_on_Mixture_of_Classifiers_and_Genetic_Algorithm_Optimization
415	Multi-labeler Classification Using Kernel Representations and Mixture of Classifiers	Progress in Pattern Recognition, Image Analysis, Computer Vision, and Applications: 21st Iberoamerican Congress, CIARP 2016, Lima, Peru, November 8–11, 2016, Proceedings	David Imbajoa, Iván Gustin, Mauricio Bolaños, Andrés Fernando Arciniegas Mejía, Fredy Guasmayan, María JANETH Bravo Montenegro, A. E. Castro-Ospina, Diego Peluffo	This work introduces a multi-labeler kernel a novel approach for data classification learning from multiple labelers. The learning process is done by training support-vector machine classifiers using the set of labelers (one labeler per classifier). The objective functions representing the boundary decision of each classifier are mixed by means of a linear combination. Followed from a variable relevance, the weighting factors are calculated regarding kernel matrices representing each labeler. To do so, a so-called supervised kernel function is also introduced , which is used to construct kernel matrices. Our multi-labeler method reach very good results being a suitable alternative to conventional approaches.2	2016	42	https://www.researchgate.net/publication/311668348_Multi-labeler_Classification_Using_Kernel_Representations_and_Mixture_of_Classifiers
418	Modelo de horno de arco eléctrico para estudios del efecto flicker y su solución con métodos de compensación	International Conference on Bioinformatics and Biomedical Engineering	Catalina Gonzalez Castaño	Objective: The aim of this paper is to evaluate voltage fluctuations or flicker of two electric arc furnace models through comparison with real data.\r\n\r\nMethod: The first proposed model is founded on the energy conservation principle, which generates a non-linear differential equation modelling the electric arc voltage - current characteristics. Voltage fluctuations are generated using a chaotic circuit that modulates the amplitude of arc voltage. The second model is based on the empirical relationship between the arc diameter or length as well as voltage and electrical current on the arc. Voltage fluctuations are considered adding a random signal in the arc length. Both models are implemented in PSCADTM.\r\n\r\nResults: The results of both models are compared with real data taken at the most critical stage of the operation of the furnace, and they show that the model based on energy conservation has a lower average mean square error in the voltages and currents 5.6 V and 1.7 kA against 27,2 V y 3.38 kA obtained with the second model.\r\n\r\nConclusions: Both models consider the nonlinearity and random behavior present in this type of load, validating their inclusion in computer models of electric power systems.	2013	5	http://revistas.udistrital.edu.co/ojs/index.php/Tecnura/article/view/10545/11906
419	Deforming objects via exponential homotopy: A first approach	Signal Processing, Images and Computer Vision (STSIVA), 2015 20th Symposium	Luis O Alpala, Diego H Peluffo-Ordóñez, Catalina González-Castaño, Fredy A Guasmayan	This work presents a novel alternative to conventional linear homotopy with suboptimal settings for applications on object deformation. Proposed approach extends the linear mapping to exponential representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. As well, we introduce a quality indicator based on the ratio between the coefficients curve of resultant homotopy and those of a non-realistic, reference homotopy. Experimental results are promising and show the applicability of exponential homotopy to interpolating images with soft changes and homotopic geometric objects.	2015	5	https://ieeexplore.ieee.org/abstract/document/7330401/
425	Comparative Analysis Between Embedded-Spaces-Based and Kernel-Based Approaches for Interactive Data Representation	Colombian Conference on Computing - CCC 2018	C. K. Basante-Villota, C. M. Ortega-Castillo, D. F. Peña-Unigarro, J. E. Revelo-Fuelagán, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez	This work presents a comparative analysis between the linear combination of em-bedded spaces resulting from two approaches: (1) The application of dimensional reduction methods (DR) in their standard implementations, and (2) Their corresponding kernel-based approximations. Namely, considered DR methods are: CMDS (Classical Multi- Dimensional Scaling), LE (Laplacian Eigenmaps) and LLE (Locally Linear Embedding). This study aims at determining -through objective criteria- what approach obtains the best performance of DR task for data visualization. The experimental validation was performed using four databases from the UC Irvine Machine Learning Repository. The quality of the obtained embedded spaces is evaluated regarding the RNX(K) criterion. The RNX(K) allows for evaluating the area under the curve, which indicates the performance of the technique in a global or local topology. Additionally, we measure the computational cost for every comparing experiment. A main contribution of this work is the provided discussion on the selection of an interactivity model when mixturing DR methods, which is a crucial aspect for information visualization purposes.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_3
420	Modelos de horno de arco eléctrico para estudios del efecto flicker	Tecnura	Catalina González Castaño, Alfonso Alzate Gómez, Jesser James Marulanda Durango	Objetivo:\r\nEl objetivo de este artículo es evaluar las fluctuaciones de voltaje o flicker de dos modelos de un horno de arco eléctrico a través de la comparación con datos reales.\r\nMétodo:\r\nEl primer modelo se fundamenta a partir del principio de conservación de la energía, de la cual se obtiene una ecuación diferencial no lineal que captura la característica voltaje–corriente del arco eléctrico. Las fluctuaciones de voltaje se generan con un circuito de caos que modula la amplitud del voltaje del arco eléctrico. El segundo modelo está basado en las relaciones empíricas entre la longitud de arco, la tensión y la corriente a través del arco. Las fluctuaciones de voltaje se obtienen agregando una señal aleatoria a la longitud del arco eléctrico. Ambos modelos son implementados en PSCAD TM.\r\nResultados:\r\nLos resultados de ambos modelos son comparados con mediciones reales tomadas en la etapa más crítica de la operación del horno, y muestran que el modelo basado en la conservación de la potencia presenta un menor error medio cuadrático promedio en los voltajes y corrientes de 5, 6 V y 1.7 kA frente a 27, 2 V y 3.38 kA obtenidos con el segundo modelo.\r\nConclusiones:\r\nAmbos modelos consideran la no linealidad y comportamiento aleatorio que exhibe este tipo de carga, validando su inclusión en modelos computacionales de sistemas eléctricos de potencia.	2016	5	http://www.redalyc.org/pdf/2570/257046835002.pdf
421	Design of a bidirectional DC/DC converter with coupled inductor for an electric vehicle application	Industrial Electronics (ISIE), 2017 IEEE 26th International Symposium	Catalina González-Castaño, Enric Vidal-Idiarte, Javier Calvente	The aim of this work is to design and implement a bidirectional buck-boost converter prototype to regulate DC voltage in a powertrain of an electric vehicle. To validate the design of the proposed converter start-up transient experiments are realized in open loop for the buck and boost mode. The activation signals of MOSFETS switch are generated using a transition method by hysteresis and are implemented in micro-controller. Experimental results show its works properly in both modes, keeping the criteria design parameters.	2017	5	https://ieeexplore.ieee.org/abstract/document/8001329/
422	Advances in Homotopy Applied to Object Deformation	International Conference on Bioinformatics and Biomedical Engineering	Jose Alejandro Salazar-Castro, Ana Cristina Umaquinga-Criollo, Lilian Dayana Cruz-Cruz, Luis Omar Alpala-Alpala, Catalina González-Castaño, Miguel A Becerra-Botero, Diego Hernán Peluffo-Ordóñez, Cesar Germán Castellanos-Domínguez	This work explores novel alternatives to conventional linear homotopy to enhance the quality of resulting transitions from object deformation applications. Studied/introduced approaches extend the linear mapping to other representations that provides smooth transitions when deforming objects while homotopy conditions are fulfilled. Such homotopy approaches are based on transcendental functions (TFH) in both simple and parametric versions. As well, we propose a variant of an existing quality indicator based on the ratio between the coefficients curve of resultant homotopy and that of a less-realistic, reference homotopy. Experimental results depict the effect of proposed TFH approaches regarding its usability and benefit for interpolating images formed by homotopic objects with smooth changes.	2018	5	https://link.springer.com/chapter/10.1007/978-3-319-78759-6_22
423	Voice Pathology Detection Using Artificial Neural Networks and Support Vector Machines Powered by a Multicriteria Optimization Algorithm	Communications in Computer and Information Science	Henry Jhoán Areiza-Laverde, Andrés Eduardo Castro-Ospina, Diego Hernán Peluffo-Ordóñez	Computer-aided diagnosis (CAD) systems have allowed to enhance the performance of conventional, medical diagnosis procedures in different scenarios. Particularly, in the context of voice pathology detection, the use of machine learning algorithms has proved to be a promising and suitable alternative. This work proposes the implementation of two well known classification algorithms, namely artificial neural networks (ANN) and support vector machines (SVM), optimized by particle swarm optimization (PSO) algorithm, aimed at classifying voice signals between healthy and pathologic ones. Three different configurations of the Saarbrucken voice database (SVD) are used. The effect of using balanced and unbalanced versions of this dataset is proved as well as the usefulness of the considered optimization algorithm to improve the final performance outcomes. Also, proposed approach is comparable with state-of-the-art methods.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-00350-0_13
424	Odor Pleasantness Classification from Electroencephalographic Signals and Emotional States	Colombian Conference on Computing - CCC 2018	M. A. Becerra, E. Londoño-Delgado, S. M. Pelaez-Becerra, L. Serna-Guarín, A. E. Castro-Ospina, D. Marin-Castrillón, D. H. Peluffo-Ordóñez	Odor identification refers to the capability of the olfactory sense for discerning odors. The interest in this sense has grown over multiple fields and applications such as multimedia, virtual reality, marketing, among others. Therefore, objective identification of pleasant and unpleasant odors is an open research field. Some studies have been carried out based on electroencephalographic signals (EEG). Nevertheless, these can be considered insufficient due to the levels of accuracy achieved so far. The main objective of this study was to investigate the capability of the classifiers systems for identification pleasant and unpleasant odors from EEG signals. The methodology applied was carried out in three stages. First, an odor database was collected using the signals recorded with an Emotiv Epoc+ with 14 channels of electroencephalography (EEG) and using a survey for establishing the emotion levels based on valence and arousal considering that the odor induces emotions. The registers were acquired from three subjects, each was subjected to 10 different odor stimuli two times. The second stage was the feature extraction which was carried out on 5 sub-bands δ, θ, α, β, γ of EEG signals using discrete wavelet transform, statistical measures, and other measures such as area, energy, and entropy. Then, feature selection was applied based on Rough Set algorithms. Finally, in the third stage was applied a Support vector machine (SVM) classifier, which was tested with five different kernels. The performance of classifiers was compared using k-fold cross-validation. The best result of 99.9% was achieved using the linear kernel. The more relevant features were obtained from sub-bands ββ and αα . Finally, relations among emotion, EEG, and odors were demonstrated.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_10
426	Physiological Signals Fusion Oriented to Diagnosis - A Review	Colombian Conference on Computing - CCC 2018	Y. F. Uribe, K. C. Alvarez-Uribe, D. H. Peluffo-Ordoñez, M. A. Becerra	The analysis of physiological signals is widely used for the development of diagnosis support tools in medicine, and it is currently an open research field. The use of multiple signals or physiological measures as a whole has been carried out using data fusion techniques commonly known as multimodal fusion, which has demonstrated its ability to improve the accuracy of diagnostic care systems. This paper presents a review of state of the art, putting in relief the main techniques, challenges, gaps, advantages, disadvantages, and practical considerations of data fusion applied to the analysis of physiological signals oriented to diagnosis decision support. Also, physiological signals data fusion architecture oriented to diagnosis is proposed.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_1
427	Exploration of Characterization and Classification Techniques for Movement Identification from EMG Signals: Preliminary Results	Colombian Conference on Computing - CCC 2018	A. Viveros-Melo, L. Lasso-Arciniegas, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez, M. A. Becerra, A. E. Castro-OspinaE. J. Revelo-Fuelagán	Today, human-computer interfaces are increasingly more often used and become necessary for human daily activities. Among some remarkable applications, we find: Wireless-computer controlling through hand movement, wheelchair directing/guiding with finger motions, and rehabilitation. Such applications are possible from the analysis of electromyographic (EMG) signals. Despite some research works have addressed this issue, the movement classification through EMG signals is still an open challenging issue to the scientific community -especially, because the controller performance depends not only on classifier but other aspects, namely: used features, movements to be classified, the considered feature-selection methods, and collected data. In this work, we propose an exploratory work on the characterization and classification techniques to identifying movements through EMG signals. We compare the performance of three classifiers (KNN, Parzen-density-based classifier and ANN) using spectral (Wavelets) and time-domain-based (statistical and morphological descriptors) features. Also, a methodology for movement selection is proposed. Results are comparable with those reported in literature, reaching classification errors of 5.18% (KNN), 14.7407% (ANN) and 5.17% (Parzen-density-based classifier).	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_11
428	Comparative Analysis Between Embedded-Spaces-Based and Kernel-Based Approaches for Interactive Data Representation	Colombian Conference on Computing - CCC 2018	C. K. Basante-Villota, C. M. Ortega-Castillo, D. F. Peña-Unigarro, J. E. Revelo-Fuelagán, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez	This work presents a comparative analysis between the linear combination of em-bedded spaces resulting from two approaches: (1) The application of dimensional reduction methods (DR) in their standard implementations, and (2) Their corresponding kernel-based approximations. Namely, considered DR methods are: CMDS (Classical Multi- Dimensional Scaling), LE (Laplacian Eigenmaps) and LLE (Locally Linear Embedding). This study aims at determining -through objective criteria- what approach obtains the best performance of DR task for data visualization. The experimental validation was performed using four databases from the UC Irvine Machine Learning Repository. The quality of the obtained embedded spaces is evaluated regarding the RNX(K) criterion. The RNX(K) allows for evaluating the area under the curve, which indicates the performance of the technique in a global or local topology. Additionally, we measure the computational cost for every comparing experiment. A main contribution of this work is the provided discussion on the selection of an interactivity model when mixturing DR methods, which is a crucial aspect for information visualization purposes.	2018	44	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_3
429	Exploration of Characterization and Classification Techniques for Movement Identification from EMG Signals: Preliminary Results.	Communications in Computer and Information Science	A. Viveros-Melo, Laura Lasso- Arciniegas, Jose Alejandro Salazar Castro, Javier Revelo, Miguel A Becerra, Andrés Eduardo Castro-Ospina	Today, human-computer interfaces are increasingly more often used and become necessary for human daily activities. Among some remarkable applications, we find: Wireless-computer controlling through hand movement, wheelchair directing/guiding with finger motions, and rehabilitation. Such applications are possible from the analysis of electromyographic (EMG) signals. Despite some research works have addressed this issue, the movement classification through EMG signals is still an open challenging issue to the scientific community -especially, because the controller performance depends not only on classifier but other aspects, namely: used features, movements to be classified, the considered feature-selection methods, and collected data. In this work, we propose an exploratory work on the characterization and classification techniques to identifying movements through EMG signals. We compare the performance of three classifiers (KNN, Parzen-density-based classifier and ANN) using spectral (Wavelets) and time-domain-based (statistical and morphological descriptors) features. Also, a methodology for movement selection is proposed. Results are comparable with those reported in literature, reaching classification errors of 5.18% (KNN), 14.7407% (ANN) and 5.17% (Parzen-density-based classifier).	2018	37	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_11
430	Exploration of Characterization and Classification Techniques for Movement Identification from EMG Signals: Preliminary Results.	Communications in Computer and Information Science	A. Viveros-Melo, Laura Lasso- Arciniegas, Jose Alejandro Salazar Castro, Javier Revelo, Miguel A Becerra, Andrés Eduardo Castro-Ospina	Today, human-computer interfaces are increasingly more often used and become necessary for human daily activities. Among some remarkable applications, we find: Wireless-computer controlling through hand movement, wheelchair directing/guiding with finger motions, and rehabilitation. Such applications are possible from the analysis of electromyographic (EMG) signals. Despite some research works have addressed this issue, the movement classification through EMG signals is still an open challenging issue to the scientific community -especially, because the controller performance depends not only on classifier but other aspects, namely: used features, movements to be classified, the considered feature-selection methods, and collected data. In this work, we propose an exploratory work on the characterization and classification techniques to identifying movements through EMG signals. We compare the performance of three classifiers (KNN, Parzen-density-based classifier and ANN) using spectral (Wavelets) and time-domain-based (statistical and morphological descriptors) features. Also, a methodology for movement selection is proposed. Results are comparable with those reported in literature, reaching classification errors of 5.18% (KNN), 14.7407% (ANN) and 5.17% (Parzen-density-based classifier).	2018	41	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_11
431	Comparative Analysis Between Embedded-Spaces-Based and Kernel-Based Approaches for Interactive Data Representation	Colombian Conference on Computing - CCC 2018	C. K. Basante-Villota, C. M. Ortega-Castillo, D. F. Peña-Unigarro, J. E. Revelo-Fuelagán, J. A. Salazar-Castro, D. H. Peluffo-Ordóñez	This work presents a comparative analysis between the linear combination of em-bedded spaces resulting from two approaches: (1) The application of dimensional reduction methods (DR) in their standard implementations, and (2) Their corresponding kernel-based approximations. Namely, considered DR methods are: CMDS (Classical Multi- Dimensional Scaling), LE (Laplacian Eigenmaps) and LLE (Locally Linear Embedding). This study aims at determining -through objective criteria- what approach obtains the best performance of DR task for data visualization. The experimental validation was performed using four databases from the UC Irvine Machine Learning Repository. The quality of the obtained embedded spaces is evaluated regarding the RNX(K) criterion. The RNX(K) allows for evaluating the area under the curve, which indicates the performance of the technique in a global or local topology. Additionally, we measure the computational cost for every comparing experiment. A main contribution of this work is the provided discussion on the selection of an interactivity model when mixturing DR methods, which is a crucial aspect for information visualization purposes.	2018	45	https://link.springer.com/chapter/10.1007/978-3-319-98998-3_3
433	Movement Identification in EMG Signals Using Machine Learning: A Comparative Study	International Workshop on Artificial Intelligence and Pattern Recognition: IWAIPR 2018	L. Lasso-Arciniegas, A. Viveros-Melo, J. A. Salazar-Castro, M. A. Becerra, A. E. Castro-Ospina, E. J. Revelo-Fuelagán, D. H. Peluffo-Ordóñez	The analysis of electromyographic (EMG) signals enables the development of important technologies for industry and medical environments, due mainly to the design of EMG-based human-computer interfaces. There exists a wide range of applications encompassing: Wireless-computer controlling, rehabilitation, wheelchair guiding, and among others. The semantic interpretation of EMG analysis is typically conducted by machine learning algorithms, and mainly involves stages for signal characterization and classification. This work presents a methodology for comparing a set of state-of-the-art approaches of EMG signal characterization and classification within a movement identification framework. We compare the performance of three classifiers (KNN, Parzen-density-based classifier and ANN) using spectral (Wavelets) and time-domain-based (statistical and morphological descriptors) features. Also, a methodology for movement selection is proposed. Results are comparable with those reported in literature, reaching classification performance of (90.89 ± 1.12)% (KNN), (93.92 ± 0.34)% (ANN) and 91.09 ± 0.93 (Parzen-density-based classifier) with 12 movements.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-01132-1_42
434	Angle-Based Model for Interactive Dimensionality Reduction and Data Visualization	International Workshop on Artificial Intelligence and Pattern Recognition: IWAIPR 2018	C. K. Basante-Villota, C. M. Ortega-Castillo, D. F. Peña-Unigarro, E. J. Revelo-Fuelagán, J. A. Salazar-Castro, M. Ortega-Bustamante, P. Rosero-Montalvo, L. S. Vega-Escobar, D. H. Peluffo-Ordóñez	In recent times, an undeniable fact is that the amount of data available has increased dramatically due mainly to the advance of new technologies allowing for storage and communication of enormous volumes of information. In consequence, there is an important need for finding the relevant information within the raw data through the application of novel data visualization techniques that permit the correct manipulation of data. This issue has motivated the development of graphic forms for visually representing and analyzing high-dimensional data. Particularly, in this work, we propose a graphical approach, which, allows the combination of dimensionality reduction (DR) methods using an angle-based model, making the data visualization more intelligible. Such approach is designed for a readily use, so that the input parameters are interactively given by the user within a user-friendly environment. The proposed approach enables users (even those being non-experts) to intuitively select a particular DR method or perform a mixture of methods. The experimental results prove that the interactive manipulation enabled by the here-proposed model-due to its ability of displaying a variety of embedded spaces-makes the task of selecting a embedded space simpler and more adequately fitted for a specific need.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-01132-1_17
440	Intelligent System for Identification of Wheelchair User’s Posture using Machine Learning Techniques	IEEE Sensors	P. Rosero-Montalvo, D. H. Peluffo-Ordóñez, V. F. López-Batista, J. Serrano, E. Rosero.	This work presents an intelligent system aimed at detecting a person’s posture when sit a wheelchair. The main use of the proposed system is to warn an improper posture to preventing major health issues. A network of sensors is used to collect data that are analyzed through a scheme involving the following stages: Selection of prototypes using Condensed Nearest Neighborhood rule (CNN), data balancing with the Kennard- Stone (KS) algorithm, and reduction of dimensionality through Principal Component Analysis (PCA). In doing so, acquired data can be both stored and processed into a micro controller. Finally, to carry out the posture classification over balanced, pre-processed data, the K-Nearest Neighbors (k-NN) algorithm is used. It turns to be an intelligent system reaching a good tradeoff between the necessary amount of data and performance is accomplished. As a remarkable result, the amount of required data for training is significantly reduced while an admissible classification performance is achieved being a suitable tradegiven the device conditions.	2018	1	https://ieeexplore.ieee.org/document/8565996
432	Electroencephalographic Signals and Emotional States for Tactile Pleasantness Classification	International Workshop on Artificial Intelligence and Pattern Recognition: IWAIPR 2018	M. A. Becerra, E. Londoño-Delgado, S. M. Pelaez-Becerra, A. E. Castro-Ospina, C. Mejia-Arboleda, J. Durango, D. H. Peluffo-Ordóñez	Haptic textures are alterations of any surface that are perceived and identified using the sense of touch, and such perception affects individuals. Therefore, it has high interest in different applications such as multimedia, medicine, marketing, systems based on human-computer interface among others. Some studies have been carried out using electroencephalographic signals; nevertheless, this can be considered few. Therefore this is an open research field. In this study, an analysis of tactile stimuli and emotion effects was performed from EEG signals to identify pleasantness and unpleasantness sensations using classifier systems. The EEG signals were acquired using Emotiv Epoc+ of 14 channels following a protocol for presenting ten different tactile stimuli two times. Besides, three surveys (Becks depression, emotion test, and tactile stimuli pleasant level) were applied to three volunteers for establishing their emotional state, depression, anxiety and the pleasantness level to characterize each subject. Then, the results of the surveys were computed and the signals preprocessed. Besides, the registers were labeled as pleasant and unpleasant. Feature extraction was applied from Short Time Fourier Transform and discrete wavelet transform calculated to each sub-bands (δ, θ, α, β, and γ) of EEG signals. Then, Rough Set algorithm was applied to identify the most relevant features. Also, this technique was employed to establish relations among stimuli and emotional states. Finally, five classifiers based on the support vector machine were tested using 10-fold cross-validation achieving results upper to 99% of accuracy. Also, dependences among emotions and pleasant and unpleasant tactile stimuli were identified.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-01132-1_35
67	Computer Vision-Based Method for Automatic Detection of Crop Rows in Potato Fields.	International Conference on Information Technology & System (ICITS 2018)	I. Garcia-Santillan, D. H. Peluffo-Ordóñez, V. Caranqui, M. Pusda, F. Garrido, P. Granda.	This work presents an adaptation and validation of a method for automatic crop row detection from images captured in potato fields (Solanum tuberosum) for initial growth stages based on the micro-ROI concept. The crop row detection is a crucial aspect for autonomous guidance of agricultural vehicles and site-specific treatments application. The images were obtained using a color camera installed in the front of a tractor under perspective projection. There are some issues that can affect the quality of the images and the detection procedure, among them: uncontrolled illumination in outdoor agricultural environments, different plant densities, presence of weeds and gaps in the crop rows. The adapted approach was designed to address these adverse situations and it consists of three linked phases. The main contribution is the ability to detect straight and curved crop rows in potato crops. The performance was quantitatively compared against two existing methods, achieving acceptable results in terms of accuracy and processing time.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-73450-7_34
435	Building a Nasa Yuwe Language Corpus and Tagging with a Metaheuristic Approach	Computación y Sistemas	L. M. Sierra-Martinez, C. A. Cobos, J. C. Corrales-Muñoz, T. Rojas Curieux, E. Herrera-Viedman, D. H. Peluffo-Ordóñez.	Nasa Yuwe is the language of the Nasa indigenous community in Colombia. It is currently threatened with extinction. In this regard, a range of computer science solutions have been developed to the teaching and revitalization of the language. One of the most suitable approaches is the construction of a Part-Of-Speech Tagging (POST), which encourages the analysis and advanced processing of the language. Nevertheless, for Nasa Yuwe no tagged corpus exists, neither is there a POS Tagger and no related works have been reported. This paper therefore concentrates on building a linguistic corpus tagged for the Nasa Yuwe language and generating the first tagging application for Nasa Yuwe. The main results and findings are 1) the process of building the Nasa Yuwe corpus, 2) the tagsets and tagged sentences, as well as the statistics associated with the corpus, 3) results of two experiments to evaluate several POS Taggers (a Random tagger, three versions of HSTAGger, a tagger based on the harmony search metaheuristic, and three versions of a memetic algorithm GBHS Tagger, based on Global-Best Harmony Search (GBHS), Hill Climbing and an explicit Tabu memory, which obtained the best results in contrast with the other methods considered over the Nasa Yuwe language corpus.	2018	1	http://www.cys.cic.ipn.mx/ojs/index.php/CyS/article/view/3018
436	Intelligence in Embedded Systems: Overview and Applications	FTC 2018: Future Technologies Conference.	P. D. Rosero-Montalvo, V. F. López Batista, E. A. Rosero, E. D. Jaramillo, J. A. Caraguay, J. Pijal-Rojas, D. H. Peluffo-Ordóñez.	The use of electronic systems and devices has become widely spread and is reaching several fields as well as indispensable for many daily activities. Such systems and devices (here termed embedded systems) are aiming at improving human beings’ quality of life. To do so, they typically acquire users’ data to adjust themselves to different needs and environments in an adequate fashion. Consequently, they are connected to data networks to share this information and find elements that allow them to make the appropriate decisions. Then, for practical usage, their computational capabilities should be optimized to avoid issues such as: resources saturation (mainly memory and battery). In this line, machine learning offers a wide range of techniques and tools to incorporate “intelligence” into embedded systems, enabling them to make decisions by themselves. This paper reviews different data storage techniques along with machine learning algorithms for embedded systems. Its main focus is on techniques and applications (with special interest in Internet of Things) reported in literature about data analysis criteria to make decisions.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-02686-8_65
62	Developments on Solutions of the Normalized-Cut-Clustering Problem Without Eigenvectors	15th International Symposium on Neural Networks (ISNN 2018)	L. L. Lorente-Leyva, I. D. Herrera-Granda, P. D. Rosero-Montalvo, K. L. Ponce-Guevara, A. E. Castro-Ospina, M. A. Becerra, D. H. Peluffo-Ordóñez, J. L. Rodríguez-Sotelo.	Normalized-cut clustering (NCC) is a benchmark graph-based approach for unsupervised data analysis. Since its traditional formulation is a quadratic form subject to orthogonality conditions, it is often solved within an eigenvector-based framework. Nonetheless, in some cases the calculation of eigenvectors is prohibitive or unfeasible due to the involved computational cost – for instance, when dealing with high dimensional data. In this work, we present an overview of recent developments on approaches to solve the NCC problem with no requiring the calculation of eigenvectors. Particularly, heuristic-search and quadratic-formulation-based approaches are studied. Such approaches are elegantly deduced and explained, as well as simple ways to implement them are provided.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_37
61	A Novel Color-Based Data Visualization Approach Using a Circular Interaction Model and Dimensionality Reduction	15th International Symposium on Neural Networks (ISNN 2018)	J. A. Salazar-Castro, P. D. Rosero-Montalvo, D. F. Peña-Unigarro, A. C. Umaquinga-Criollo, Z. Castillo-Marrero, E. J. Revelo-Fuelagán, D. H. Peluffo-Ordóñez, C. G. Castellanos-Domínguez.	Dimensionality reduction (DR) methods are able to produce low-dimensional representations of an input data sets which may become intelligible for human perception. Nonetheless, most existing DR approaches lack the ability to naturally provide the users with the faculty of controlability and interactivity. In this connection, data visualization (DataVis) results in an ideal complement. This work presents an integration of DR and DataVis through a new approach for data visualization based on a mixture of DR resultant representations while using visualization principle. Particularly, the mixture is done through a weighted sum, whose weighting factors are defined by the user through a novel interface. The interface’s concept relies on the combination of the color-based and geometrical perception in a circular framework so that the users may have a at hand several indicators (shape, color, surface size) to make a decision on a specific data representation. Besides, pairwise similarities are plotted as a non-weighted graph to include a graphic notion of the structure of input data. Therefore, the proposed visualization approach enables the user to interactively combine DR methods, while providing information about the structure of original data, making then the selection of a DR scheme more intuitive.	2018	1	https://link.springer.com/chapter/10.1007/978-3-319-92537-0_64
437	Generalized Low-Computational Cost Laplacian Eigenmaps	Lecture Notes in Computer Science	J. A. Salazar-Castro, D. F. Peña, C. Basante, C. Ortega, L. Cruz-Cruz, J. Revelo-Fuelagán, X. P. Blanco-Valencia, G. Castellanos-Domínguez, D. H. Peluffo-Ordóñez.	Dimensionality reduction (DR) is a methodology used in many fields linked to data processing, and may represent a preprocessing stage or be an essential element for the representation and classification of data. The main objective of DR is to obtain a new representation of the original data in a space of smaller dimension, such that more refined information is produced, as well as the time of the subsequent processing is decreased and/or visual representations more intelligible for human beings are generated. The spectral DR methods involve the calculation of an eigenvalue and eigenvector decomposition, which is usually high-computational-cost demanding, and, therefore, the task of obtaining a more dynamic and interactive user-machine integration is difficult. Therefore, for the design of an interactive IV system based on DR spectral methods, it is necessary to propose a strategy to reduce the computational cost required in the calculation of eigenvectors and eigenvalues. For this purpose, it is proposed to use locally linear submatrices and spectral embedding. This allows integrating natural intelligence with computational intelligence for the representation of data interactively, dynamically and at low computational cost. Additionally, an interactive model is proposed that allows the user to dynamically visualize the data through a weighted mixture.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-03493-1_69
438	Exploratory Study of the Effects of Cardiac Murmurs on Electrocardiographic-Signal-Based Biometric Systems	Lecture Notes in Computer Science	M. A. Becerra, C. Duque-Mejía, C. Zapata-Hernández, D. H. Peluffo-Ordóñez, L. Serna-Guarín, Edilson Delgado-Trejos, E. J. Revelo-Fuelagán, X. P. Blanco Valencia.	The process of distinguishing among human beings through the inspection of acquired data from physical or behavioral traits is known as biometric identification. Mostly, fingerprint- and iris-based biometric techniques are used. Nowadays, since such techniques are highly susceptible to be counterfeited, new biometric alternatives are explored mainly based on physiological signals and behavioral traits -which are useful not only for biometric identification purposes, but may also play a role as a vital signal indicator. In this connection, the electrocardiographic (ECG) signals have shown to be a suitable approach. Nonetheless, their informative components (morphology, rhythm, polarization, and among others) can be affected by the presence of a cardiac pathology. Even more, some other cardiac diseases cannot directly be detected by the ECG signal inspection but still have an effect on their waveform, that is the case of cardiac murmurs. Therefore, for biometric purposes, such signals should be analyzed submitted to the effects of pathologies. This paper presents a exploratory study aimed at assessing the influence of the presence of a pathology when analyzing ECG signals for implementing a biometric system. For experiments, a data base holding 20 healthy subjects and 20 pathological subjects (diagnosed with different types of cardiac murmurs) are considered. The proposed signal analysis consists of preprocessing, characterization (using wavelet features), feature selection and classification (five classifiers as well as a mixture of them are tested). As a result, through the performed comparison of the classification rates when testing pathological and normal ECG signals, the cardiac murmurs’ undesired effect on the identification mechanism performance is clearly unveiled.	2018	1	https://link.springer.com/chapter/10.1007/978-3-030-03493-1_43
439	Methodology for the design and simulation of industrial facilities and production systems based on a modular approach in an "industry 4.0" context	DYNA	L. O. Alpala, M. E. Alemany, D. H. Peluffo-Ordoñez, F. Bolaños, A. M. Rosero, J. C. Torres.	The design of the industrial facilities distribution is one of the most important decisions to be made, as it will condition the operation thereof. The concept of industrial installation as it is known today has evolved to the point that it integrates automation and information systems. Indeed, such evolution has given rise to the so-called intelligent factory. At present, in order to produce customized mass products according to customers' requirements, it is become an important issue the distribution of facilities with the generation of successful layout designs, based on the flexibility, modularity and easy configuration of production systems.This paper proposes a methodology to solve the problem of plant distribution design and redesign based upon a novel modular approach within an industry 4.0context. Proposed methodology is an adaptation of the "SLP" Methodology (Systematic Layout Planning-Simulation) so-called SLP Modulary 4.0 (systematic planning of the Layout based on a modular vision under a context of Industry 4.0); this methodology incorporates in its structure an integrated design system (IDS) into its structure, which allows collaborative work with different CAD design and simulation tools. For the validation of the proposed methodology, a case study of a coffee processing plant is considered. The distribution design results obtained from the case study prove the benefit and usefulness of the proposed methodology.	2018	1	https://revistas.unal.edu.co/index.php/dyna/article/view/68545/68851
441	Air Quality Monitoring Intelligent System Using Machine Learning Techniques	INCISCOS 2018	P. D. Rosero-Montalvo, J. A. Caraguay-Procel, E. D. Jaramillo, J. M. Michilena-Calderón, A. C. Umaquinga-Criollo, M. Mediavilla-Valverde, M. A. Ruiz, L. A. Beltrán, D. H. Peluffo-Ordóñez	Environment monitoring is so important because it is based on the first right of people, life and health. For this reason, this system monitoring air quality with different sensor nodes in the Ibarra that evaluate the parameters of CO2, NOx, UV Light, Temperature and Humidity. The data analysis through machine learning algorithms allow the system to classify autonomously if a certain geographical location is exceeding the established emission limits of gases. As a result, the k-Nearest Neighbor algorithm presented a great classification performance when selecting the most contaminated sectors.	2018	1	https://ieeexplore.ieee.org/document/8564511
